def _cleanup_loky_on_startup() -> None:
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
            logger.debug("🧹 Loky-Executor beim Start bereinigt")
    except ImportError:
        pass
    except Exception as e:
        logger.debug(f"⚠️ Loky-Start-Cleanup fehlgeschlagen: {e}")


def _cleanup_loky_atexit() -> None:
    """
    Führt die Bereinigung beim Programmende durch – nur einmal.
    """
    # ── Idempotenz ────────────────────────────────────────────────
    if hasattr(_cleanup_loky_atexit, "_done"):
        return
    _cleanup_loky_atexit._done = True

    start_time = time.perf_counter()
    logger.info("🧹 Loky‑Cleanup‑Handler wird ausgeführt (ultimative Version v11)...")

    # ── 1. Resource‑Tracker zuerst stoppen (verhindert KeyError) ──
    try:
        import multiprocessing.resource_tracker as rt
        if hasattr(rt, "_resource_tracker"):
            tracker = rt._resource_tracker
            if hasattr(tracker, "stop"):
                tracker.stop()
                logger.debug("✅ Resource‑Tracker gestoppt (explizit)")
            # Zusätzlich Semaphore‑Cache leeren
            if hasattr(tracker, "_semaphores"):
                tracker._semaphores.clear()
                logger.debug("✅ Semaphore‑Cache geleert")
    except ImportError:
        logger.debug("ℹ️ multiprocessing.resource_tracker nicht verfügbar")
    except Exception as e:
        logger.warning(f"⚠️ Resource‑Tracker‑Stop fehlgeschlagen: {e}")

    # ── 2. Resource‑Tracker‑Thread sicher beenden ──────────────────
    try:
        for t in threading.enumerate():
            if t.name == "resource_tracker" and t.is_alive():
                t.join(timeout=1.0)
                if t.is_alive():
                    t.daemon = True
                    logger.debug("✅ resource_tracker-Thread als Daemon markiert")
                else:
                    logger.debug("✅ resource_tracker-Thread beendet")
    except Exception as e:
        logger.debug(f"Resource‑Tracker‑Thread‑Beendigung fehlgeschlagen: {e}")

    # ── 3. Loky‑Executor herunterfahren (asynchron, mit Timeout) ──
    try:
        from loky import get_reusable_executor
        executor = get_reusable_executor()
        if executor is not None:
            # Zuerst alle ausstehenden Futures abbrechen
            try:
                if hasattr(executor, "_pending_work_items"):
                    pending = list(executor._pending_work_items.keys())
                    for future in pending:
                        if not future.done():
                            future.cancel()
                    if pending:
                        logger.debug(f"✅ {len(pending)} ausstehende Future(s) abgebrochen")
            except Exception as e:
                logger.debug(f"Fehler beim Abbrechen von Futures: {e}")

            shutdown_done = threading.Event()
            shutdown_error = None

            def _shutdown_task():
                nonlocal shutdown_error
                try:
                    safe_shutdown_executor(executor, wait=True, cancel_futures=True)
                except TypeError:
                    executor.shutdown(wait=True)
                except Exception as e:
                    shutdown_error = e
                finally:
                    shutdown_done.set()

            t = threading.Thread(target=_shutdown_task, daemon=True)
            t.start()
            # Max. 5 Sekunden warten, dann abbrechen
            if not shutdown_done.wait(timeout=5.0):
                logger.warning("⏰ Loky‑Executor‑Shutdown timeout – erzwinge Abbruch")
                try:
                    safe_shutdown_executor(executor, wait=False, cancel_futures=True)
                except Exception:
                    pass
                # Verbleibende Threads als Daemon markieren
                for th in threading.enumerate():
                    if th.name.startswith("loky") and th.is_alive():
                        try:
                            th.daemon = True
                        except RuntimeError:
                            pass
            else:
                if shutdown_error:
                    logger.warning(f"⚠️ Loky‑Executor‑Shutdown Fehler: {shutdown_error}")
                else:
                    logger.debug("✅ Loky‑Executor sicher heruntergefahren")
        else:
            logger.debug("ℹ️ Kein loky‑Executor aktiv")
    except ImportError:
        logger.debug("ℹ️ Loky nicht installiert – überspringe")
    except Exception as e:
        logger.warning(f"⚠️ Loky‑Executor‑Shutdown fehlgeschlagen: {e}")

    # ── 4. Joblib‑Parallel‑Backend bereinigen ─────────────────────
    try:
        import joblib
        backend = getattr(joblib, "_parallel_backend", None)
        if backend is not None:
            if hasattr(backend, "terminate"):
                backend.terminate()
                logger.debug("✅ Joblib‑Parallel‑Backend terminiert")
            elif hasattr(backend, "shutdown"):
                backend.shutdown()
                logger.debug("✅ Joblib‑Parallel‑Backend heruntergefahren")
    except ImportError:
        pass
    except Exception as e:
        logger.debug(f"Joblib‑Cleanup fehlgeschlagen (ignoriert): {e}")

    # ── 5. Multiprocessing‑Kinderprozesse hart beenden ──────────
    try:
        import multiprocessing
        active = multiprocessing.active_children()
        if active:
            logger.info(f"🧹 Terminiere {len(active)} verbleibende Multiprocessing‑Prozesse...")
            deadline = time.monotonic() + 2.0
            for p in active:
                if time.monotonic() >= deadline:
                    logger.warning("⏰ Zeitlimit für Prozess‑Terminierung erreicht")
                    break
                try:
                    p.terminate()
                    p.join(timeout=0.5)
                except Exception:
                    pass
            # Verbleibende Prozesse hart killen (falls nötig)
            for p in active:
                if p.is_alive():
                    try:
                        p.kill()
                        p.join(timeout=0.3)
                    except Exception:
                        pass
    except Exception as e:
        logger.debug(f"Multiprocessing‑Cleanup fehlgeschlagen: {e}")

    # ── 6. Nicht‑Daemon‑Threads als Daemon markieren ──────────────
    main_thread = threading.main_thread()
    daemon_marked = 0
    for t in threading.enumerate():
        if t is not main_thread and not t.daemon and t.is_alive():
            try:
                t.daemon = True
                daemon_marked += 1
            except RuntimeError:
                pass
    if daemon_marked > 0:
        logger.info(f"✅ {daemon_marked} Thread(s) als Daemon markiert")

    # ── 7. Garbage‑Collection zweimal durchführen ────────────────
    try:
        gc.collect()
        gc.collect()  # zweiter Durchlauf für zirkuläre Referenzen
        logger.debug("✅ Garbage‑Collection (2x) durchgeführt")
    except Exception as e:
        logger.debug(f"GC fehlgeschlagen: {e}")

    # ── 8. Abschließende Logausgabe mit Zeitmessung ──────────────
    elapsed_ms = (time.perf_counter() - start_time) * 1000
    logger.info(f"✅ Loky‑Cleanup abgeschlossen in {elapsed_ms:.2f} ms")


_cleanup_loky_on_startup()
atexit.register(_cleanup_loky_atexit)

