def _safe_log_debug(
    component_or_msg: str, msg: Optional[str] = None, *args: Any, **kwargs: Any
) -> None:
    if msg is None:
        component = "default"
        message = component_or_msg
    else:
        component = component_or_msg
        message = msg
    impl = _get_log_debug_impl()
    if impl is not None:
        impl(component, message, *args, **kwargs)
        return
    try:
        debug_level = globals().get("DEBUG_LEVEL", 0)
        debug_components = globals().get("DEBUG_COMPONENTS", [])
    except Exception:
        debug_level = 0
        debug_components = []
    if debug_level >= 3 or component in debug_components:
        logger.debug(message, *args, extra={"component": component}, **kwargs)


def _safe_log_exception(
    component_or_msg: str,
    msg: Optional[str] = None,
    exc: Optional[Exception] = None,
    level: str = "error",
    **kwargs: Any,
) -> None:
    if msg is None:
        if exc is not None:
            component = "default"
            message = component_or_msg
        else:
            component = "default"
            message = component_or_msg
            exc = None
    else:
        component = component_or_msg
        message = msg
    impl = _get_log_exception_impl()
    if impl is not None:
        impl(component, message, exc, level, **kwargs)
        return
    level_lower = level.lower() if isinstance(level, str) else "error"
    log_msg = f"[{component}] {message}"
    if level_lower == "error":
        logger.error(log_msg, exc_info=exc, extra={"component": component}, **kwargs)
    elif level_lower == "warning":
        logger.warning(log_msg, exc_info=exc, extra={"component": component}, **kwargs)
    else:
        logger.debug(log_msg, exc_info=exc, extra={"component": component}, **kwargs)


