# 12. NAMEDHTTPADAPTER (NUR WENN REQUESTS VERFÜGBAR)
# ============================================================================
if requests is not None:
    from requests.adapters import HTTPAdapter

    class NamedHTTPAdapter(HTTPAdapter):
        def __init__(self, pool_name: str = "DW-Requests", *args, **kwargs) -> None:
            self.pool_name = pool_name
            kwargs.pop("pool_name", None)
            super().__init__(*args, **kwargs)

        def init_poolmanager(self, *args, **kwargs) -> None:
            kwargs.pop("key_threadpool", None)
            max_workers = kwargs.get("num_pools", 10)
            threadpool = ThreadPoolExecutor(
                max_workers=max_workers, thread_name_prefix=self.pool_name
            )
            kwargs["threadpool"] = threadpool
            try:
                super().init_poolmanager(*args, **kwargs)
            except TypeError as e:
                if "threadpool" in str(e):
                    kwargs.pop("threadpool", None)
                    super().init_poolmanager(*args, **kwargs)
                else:
                    raise

        def proxy_manager_for(self, *args, **kwargs) -> Any:
            kwargs.pop("key_threadpool", None)
            max_workers = kwargs.get("num_pools", 10)
            threadpool = ThreadPoolExecutor(
                max_workers=max_workers, thread_name_prefix=f"{self.pool_name}-Proxy"
            )
            kwargs["threadpool"] = threadpool
            try:
                return super().proxy_manager_for(*args, **kwargs)
            except TypeError as e:
                if "threadpool" in str(e):
                    kwargs.pop("threadpool", None)
                    return super().proxy_manager_for(*args, **kwargs)
                else:
                    raise

# 13. URLLIB3‑MONKEY‑PATCH (BEHEBT TYPEFEHLER IN URLLIB3 >= 2.0)
_original_pool_init: Optional[Callable] = None
_original_proxy_init: Optional[Callable] = None
_original_poolkey_new: Optional[Callable] = None
_original_poolkey_init: Optional[Callable] = None
