_ASIAN_NAMES: Optional[List[str]] = None
_OTHER_NAMES: Optional[List[str]] = None


def get_common_language_names() -> List[str]:
    """Gibt die lesbaren Namen der häufigsten Sprachen zurück (mit Caching)."""
    global _COMMON_NAMES
    if _COMMON_NAMES is None:
        _COMMON_NAMES = [
            BASE_LANGUAGES[code]
            for code in COMMON_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _COMMON_NAMES.copy()


def get_asian_language_names() -> List[str]:
    """Gibt die lesbaren Namen asiatischer / nahöstlicher Sprachen zurück (mit Caching)."""
    global _ASIAN_NAMES
    if _ASIAN_NAMES is None:
        _ASIAN_NAMES = [
            BASE_LANGUAGES[code]
            for code in ASIAN_LANGUAGE_CODES
            if code in BASE_LANGUAGES
        ]
    return _ASIAN_NAMES.copy()


def get_other_language_names() -> List[str]:
    """
    Gibt alle übrigen lesbaren Sprachnamen zurück, die nicht in den
    vordefinierten Gruppen sind (mit Caching).
    """
    global _OTHER_NAMES
    if _OTHER_NAMES is None:
        excluded = set(COMMON_LANGUAGE_CODES + ASIAN_LANGUAGE_CODES)
        _OTHER_NAMES = [
            name
            for name, code in SORTED_LANGUAGES
            if code not in excluded and code != "auto"
        ]
    return _OTHER_NAMES.copy()


class EventBus:
    """
    Zentraler, thread‑sicherer Event‑Bus mit exakten und Pattern‑Abonnements,
    automatischem Fehler‑Logging, optionalem Weak‑Referenz‑Modus, einmaligen
    Subscriptions (``once``) und konfigurierbarem Rate‑Limiting.
    """

    def __init__(
        self,
        debug: bool = False,
        scheduler: Optional[Callable[..., None]] = None,
        use_weakref: bool = False,
    ) -> None:
        """
        Initialisiert den EventBus.
        """
        self._lock = threading.RLock()
        self._exact: Dict[str, List[Callable]] = defaultdict(list)
        self._patterns: List[Tuple[str, Callable]] = []
        self._debug = debug
        self._metrics_enabled = debug
        self._metrics: Dict[str, Any] = {
            "total_events": 0,
            "events_per_type": defaultdict(int),
            "errors": 0,
            "start_time": time.time(),
        }
        self._scheduler = scheduler
        self._use_weakref = use_weakref
        self._pattern_match_cache: Dict[str, Dict[str, bool]] = {}
        self._pattern_cache_lock = threading.RLock()

        self._rate_limit: Optional[float] = None
        self._rate_limit_buckets: Dict[str, float] = {}
        self._rate_limit_lock = threading.RLock()

        if debug:
            logger.debug("EventBus initialisiert (debug=True, weakref=%s)", use_weakref)

    # ── Scheduler ──────────────────────────────────────────────
    def set_scheduler(self, scheduler: Callable[[Callable, int], None]) -> None:
        with self._lock:
            self._scheduler = scheduler
        if self._debug:
            log_debug("eventbus", "Scheduler gesetzt")

    # ── Abonnements ───────────────────────────────────────────
    def _store_callback(self, callback: Callable) -> Callable:
        if self._use_weakref:
            if hasattr(callback, "__self__") and hasattr(callback, "__func__"):
                return weakref.WeakMethod(callback)
            else:
                return weakref.ref(callback)
        return callback

    def _call_stored(self, stored: Any) -> Optional[Callable]:
        if self._use_weakref:
            if isinstance(stored, weakref.ref):
                cb = stored()
                return cb
            elif isinstance(stored, weakref.WeakMethod):
                cb = stored()
                return cb
        return stored

    def subscribe(self, event_type: str, callback: Callable[[Any], None]) -> None:
        with self._lock:
            stored = self._store_callback(callback)
            self._exact[event_type].append(stored)
        if self._debug:
            log_debug("eventbus", "Subscribed exact '%s'", event_type)

    def subscribe_pattern(self, pattern: str, callback: Callable[[Any], None]) -> None:
        with self._lock:
            stored = self._store_callback(callback)
            self._patterns.append((pattern, stored))
        if self._debug:
            log_debug("eventbus", "Subscribed pattern '%s'", pattern)

    def subscribe_once(self, event_type: str, callback: Callable[[Any], None]) -> None:
        def _once_wrapper(data: Any, _cb=callback, _ev=event_type, _self=self):
            try:
                _cb(data)
            finally:
                _self.unsubscribe(_ev, _once_wrapper)

        self.subscribe(event_type, _once_wrapper)

    def unsubscribe(self, event_type: str, callback: Callable) -> bool:
        with self._lock:
            if event_type not in self._exact:
                return False
            to_remove = []
            for stored in self._exact[event_type]:
                cb = self._call_stored(stored)
                if cb is callback:
                    to_remove.append(stored)
            for item in to_remove:
                self._exact[event_type].remove(item)
            if not self._exact[event_type]:
                del self._exact[event_type]
            if to_remove:
                if self._debug:
                    log_debug(
                        "eventbus",
                        "Unsubscribed exact '%s' (%d removed)",
                        event_type,
                        len(to_remove),
                    )
                return True
            return False

    def unsubscribe_pattern(self, pattern: str, callback: Callable) -> bool:
        with self._lock:
            to_remove = []
            for p, stored in self._patterns:
                cb = self._call_stored(stored)
                if p == pattern and cb is callback:
                    to_remove.append((p, stored))
            for item in to_remove:
                self._patterns.remove(item)
            if to_remove:
                if self._debug:
                    log_debug("eventbus", "Unsubscribed pattern '%s'", pattern)
                return True
            return False

    def unsubscribe_all(self, event_type: Optional[str] = None) -> None:
        with self._lock:
            if event_type is None:
                self._exact.clear()
                self._patterns.clear()
                if self._debug:
                    log_debug("eventbus", "Alle Subscriptions entfernt")
            else:
                if event_type in self._exact:
                    del self._exact[event_type]
                    if self._debug:
                        log_debug(
                            "eventbus",
                            "Alle exact‑Subscriptions für '%s' entfernt",
                            event_type,
                        )

    # ── Event‑Emission ──────────────────────────────────────────
    def _matches_pattern(self, pattern: str, event_type: str) -> bool:
        with self._pattern_cache_lock:
            if pattern not in self._pattern_match_cache:
                self._pattern_match_cache[pattern] = {}
            cache = self._pattern_match_cache[pattern]
            if event_type not in cache:
                cache[event_type] = fnmatch.fnmatch(event_type, pattern)
            return cache[event_type]

    def _check_rate_limit(self, event_type: str) -> bool:
        if self._rate_limit is None:
            return True
        with self._rate_limit_lock:
            now = time.monotonic()
            last = self._rate_limit_buckets.get(event_type, 0.0)
            if now - last >= 1.0 / self._rate_limit:
                self._rate_limit_buckets[event_type] = now
                return True
            return False

    def set_rate_limit(self, events_per_second: Optional[float]) -> None:
        with self._rate_limit_lock:
            self._rate_limit = events_per_second
            if events_per_second is None:
                self._rate_limit_buckets.clear()

    def emit(self, event_type: str, data: Any = None) -> None:
        if self._metrics_enabled:
            with self._lock:
                self._metrics["total_events"] += 1
                self._metrics["events_per_type"][event_type] += 1

        if not self._check_rate_limit(event_type):
            if self._debug:
                log_debug(
                    "eventbus",
                    "Rate‑Limit für '%s' erreicht – Event unterdrückt",
                    event_type,
                )
            return

        if self._debug:
            log_debug("eventbus", "Emitting '%s'", event_type)

        with self._lock:
            exact_callbacks = [
                self._call_stored(s) for s in self._exact.get(event_type, [])
            ]
            exact_callbacks = [cb for cb in exact_callbacks if cb is not None]

            pattern_callbacks = []
            for pattern, stored in self._patterns:
                if self._matches_pattern(pattern, event_type):
                    cb = self._call_stored(stored)
                    if cb is not None:
                        pattern_callbacks.append(cb)

        all_callbacks = exact_callbacks + pattern_callbacks

        for cb in all_callbacks:
            try:
                if self._scheduler is not None:
                    try:
                        self._scheduler(0, cb, data)
                    except Exception:
                        cb(data)
                else:
                    cb(data)
            except Exception as e:
                logger.error(
                    "EventBus callback error for '%s': %s", event_type, e, exc_info=True
                )
                if self._metrics_enabled:
                    with self._lock:
                        self._metrics["errors"] += 1

        if self._metrics_enabled and self._metrics["total_events"] % 1000 == 0:
            self._prune_pattern_cache()

    def _prune_pattern_cache(self) -> None:
        """
        Entfernt die ältesten Einträge aus dem Pattern‑Match‑Cache, wenn die
        maximale Größe überschritten wird.
        """
        MAX_CACHE_SIZE = 1000
        PRUNE_TARGET = 500
        AGGRESSIVE_THRESHOLD = 2000

        with self._pattern_cache_lock:
            current_size = len(self._pattern_match_cache)

            if current_size <= MAX_CACHE_SIZE:
                return

            if current_size > AGGRESSIVE_THRESHOLD:
                target_size = max(PRUNE_TARGET, current_size // 2)
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "eventbus",
                        "⚠️ Pattern‑Cache übermäßig groß (%d Einträge) – aggressive Bereinigung auf %d",
                        current_size,
                        target_size,
                    )
                to_remove = current_size - target_size
            else:
                to_remove = current_size - PRUNE_TARGET

            if to_remove <= 0:
                return

            removed = 0
            try:
                for _ in range(to_remove):
                    self._pattern_match_cache.popitem(last=False)
                    removed += 1
            except KeyError:
                pass

            if len(self._pattern_match_cache) > MAX_CACHE_SIZE:
                second_target = max(PRUNE_TARGET, len(self._pattern_match_cache) // 2)
                second_remove = len(self._pattern_match_cache) - second_target
                for _ in range(second_remove):
                    try:
                        self._pattern_match_cache.popitem(last=False)
                        removed += 1
                    except KeyError:
                        break

            if DEBUG_LEVEL >= 3 and removed > 0:
                log_debug(
                    "eventbus",
                    "Pattern‑Cache bereinigt: %d Einträge entfernt (war %d, jetzt %d)",
                    removed,
                    current_size,
                    len(self._pattern_match_cache),
                )
            elif DEBUG_LEVEL >= 2 and removed > 0:
                logger.debug(
                    "EventBus: Pattern cache pruned: removed %d entries (size %d → %d)",
                    removed,
                    current_size,
                    len(self._pattern_match_cache),
                )

    # ── Kontextmanager ───────────────────────────────────────────
    @contextmanager
    def subscription_context(self, event_type: str, callback: Callable[[Any], None]):
        self.subscribe(event_type, callback)
        try:
            yield
        finally:
            self.unsubscribe(event_type, callback)

    @contextmanager
    def pattern_subscription_context(
        self, pattern: str, callback: Callable[[Any], None]
    ):
        self.subscribe_pattern(pattern, callback)
        try:
            yield
        finally:
            self.unsubscribe_pattern(pattern, callback)

    # ── Verwaltung ─────────────────────────────────────────────
    def clear(self) -> None:
        with self._lock:
            self._exact.clear()
            self._patterns.clear()
        if self._debug:
            log_debug("eventbus", "All subscriptions cleared")

    # ── Metriken ─────────────────────────────────────────────────
    def get_metrics(self) -> Dict[str, Any]:
        if not self._metrics_enabled:
            return {}
        with self._lock:
            metrics = self._metrics.copy()
            metrics["uptime"] = time.time() - metrics["start_time"]
            metrics["events_per_type"] = dict(metrics["events_per_type"])
            return metrics

    def get_debug_info(self) -> Dict[str, Any]:
        if not self._debug:
            return {"debug_enabled": False}
        with self._lock:
            return {
                "debug_enabled": True,
                "exact_subscriptions": {k: len(v) for k, v in self._exact.items()},
                "pattern_subscriptions": len(self._patterns),
                "has_scheduler": self._scheduler is not None,
                "metrics": self.get_metrics(),
            }

    def __repr__(self) -> str:
        with self._lock:
            exact_count = sum(len(v) for v in self._exact.values())
            pattern_count = len(self._patterns)
        return (
            f"<EventBus exact={exact_count} patterns={pattern_count} "
            f"scheduler={self._scheduler is not None}>"
        )


class PeriodicTaskMixin:
    """
    Mixin zum Ausführen einer periodischen Hintergrundaufgabe in einem eigenen Thread.
    """

    __slots__ = (
        "_interval",
        "_task",
        "_task_args",
        "_task_kwargs",
        "_max_errors",
        "_on_error",
        "_error_count",
        "_stop_event",
        "_thread",
        "_initial_delay",
    )

    def __init__(
        self,
        interval: float,
        task: Callable[..., Any],
        *args: Any,
        thread_name: Optional[str] = None,
        initial_delay: float = 0.0,
        max_errors: int = 0,
        on_error: Optional[Callable[[Exception], None]] = None,
        **kwargs: Any,
    ) -> None:
        """
        Args:
            interval: Wartezeit in Sekunden zwischen zwei Ausführungen.
            task: Aufzurufende Funktion.
            *args: Positionsargumente für die Funktion.
            thread_name: Name des Threads (optional).
            initial_delay: Verzögerung vor dem ersten Aufruf (Sekunden).
            max_errors: Maximale Anzahl aufeinanderfolgender Fehler, bevor der Thread stoppt.
                        0 = niemals stoppen.
            on_error: Callback bei Fehlern (optional).
            **kwargs: Schlüsselwortargumente für die Funktion.
        """
        self._interval = interval
        self._task = task
        self._task_args = args
        self._task_kwargs = kwargs
        self._max_errors = max_errors
        self._on_error = on_error
        self._error_count = 0
        self._stop_event = threading.Event()
        self._thread = threading.Thread(
            target=self._run,
            daemon=True,
            name=thread_name or f"Periodic-{id(self)}",
        )
        self._initial_delay = initial_delay
        self._thread.start()

    def _run(self) -> None:
        """
        Wird in einem eigenen Thread ausgeführt. Führt die Aufgabe periodisch aus,
        mit optionaler Startverzögerung und Fehlerbehandlung.
        """
        if self._initial_delay > 0:
            self._sleep_with_stop(self._initial_delay)
            if self._stop_event.is_set():
                return

        while not self._stop_event.is_set():
            self._sleep_with_stop(self._interval)
            if self._stop_event.is_set():
                break

            try:
                self._task(*self._task_args, **self._task_kwargs)
                self._error_count = 0
            except Exception as e:
                logger.error(f"Periodic task error: {e}")
                if self._on_error:
                    self._on_error(e)
                self._error_count += 1
                if self._max_errors > 0 and self._error_count >= self._max_errors:
                    logger.error(
                        f"Max errors ({self._max_errors}) reached, stopping periodic task."
                    )
                    break

    def _sleep_with_stop(self, duration: float) -> None:
        """
        Schläft in 0,5‑Sekunden‑Schritten, prüft dabei das _stop_event.
        Dadurch kann der Thread zeitnah beendet werden.
        """
        chunk = 0.5
        while duration > 0 and not self._stop_event.is_set():
            sleep_time = min(chunk, duration)
            time.sleep(sleep_time)
            duration -= sleep_time

    def wait_for_stop(self, timeout: float = 2.0) -> bool:
        """
        Wartet auf das Ende des Threads. Gibt True zurück, wenn der Thread
        innerhalb des Timeouts gestoppt wurde, sonst False.
        """
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)
            return not self._thread.is_alive()
        return True

    def stop_periodic_task(self, timeout: float = 2.0) -> None:
        """
        Setzt das Stop‑Event und wartet bis zum Timeout auf das Ende des Threads.
        """
        self._stop_event.set()
        if self._thread.is_alive():
            self._thread.join(timeout=timeout)


class BaseDialog:
    """
    Ultimative Basisklasse für alle modalen Dialoge in Dragon Whisperer.
    """

    def __init__(
        self,
        parent: Union[tk.Widget, tk.Tk],
        title: str,
        width: int = 600,
        height: int = 400,
        timeout: Optional[int] = None,
        modal: bool = True,
        close_on_escape: bool = True,
        resizable: bool = False,
        on_close_callback: Optional[Callable[[], None]] = None,
    ) -> None:
        """
        Initialisiert den Dialog.
        """
        # ── Parameter speichern ─────────────────────────────────────────
        self.parent = parent
        self.title = title
        try:
            self.width = int(width)
        except (TypeError, ValueError):
            self.width = 600
        try:
            self.height = int(height)
        except (TypeError, ValueError):
            self.height = 400
        self.timeout = timeout
        self.modal = modal
        self.close_on_escape = close_on_escape
        self.resizable = resizable
        self.on_close_callback = on_close_callback

        # ── Interner Zustand ───────────────────────────────────────────
        self._closed = False
        self._timeout_id: Optional[str] = None
        self._theme = self._get_theme_safe()
        self.dialog: Optional[tk.Toplevel] = None
        self.main: Optional[tk.Frame] = None

        # ── Dialog erstellen ───────────────────────────────────────────
        self.dialog = self._create_dialog()
        if self.dialog is None:
            raise RuntimeError("Dialogfenster konnte nicht erstellt werden")

        # ── Hauptcontainer ─────────────────────────────────────────────
        self.main = tk.Frame(self.dialog, bg=self._theme.BG_PRIMARY, padx=15, pady=15)
        self.main.pack(fill="both", expand=True)

        # ── Registrierung in Parent – für globale Theme‑Updates ─────────
        self._register_in_parent()

        # ── Zentrierung ────────────────────────────────────────────────
        self._center_dialog()

        # ── Escape‑Taste ───────────────────────────────────────────────
        if self.close_on_escape:
            self.dialog.bind("<Escape>", lambda e: self.close())

        # ── Timeout ────────────────────────────────────────────────────
        if timeout is not None and timeout > 0:
            self._timeout_id = self._safe_after(
                int(timeout * 1000), self._timeout_close
            )

        # ── Modalität ──────────────────────────────────────────────────
        if modal:
            self._make_modal()

        # ── Resizing ───────────────────────────────────────────────────
        self.dialog.resizable(resizable, resizable)

        # ── UI durch Unterklasse ───────────────────────────────────────
        self.build_ui()

    @property
    def is_closed(self) -> bool:
        """Gibt zurück, ob der Dialog bereits geschlossen wurde."""
        return self._closed

    @property
    def is_visible(self) -> bool:
        """Gibt zurück, ob der Dialog sichtbar ist (nicht geschlossen)."""
        return (
            not self._closed and self.dialog is not None and self.dialog.winfo_exists()
        )

    @staticmethod
    def _get_theme_safe() -> Any:
        """Liefert ein gültiges Theme‑Objekt (niemals None)."""
        try:
            return CURRENT_THEME
        except NameError:
            try:
                from dragon_whisperer import DarkTheme

                return DarkTheme()
            except ImportError:
                # Inline‑Fallback
                class _FallbackTheme:
                    BG_PRIMARY = "#0f1419"
                    BG_SECONDARY = "#1a2129"
                    BG_TERTIARY = "#242d38"
                    BG_HOVER = "#2a3645"
                    TEXT_PRIMARY = "#e6edf3"
                    TEXT_SECONDARY = "#8b949e"
                    TEXT_ACCENT = "#58a6ff"
                    ERROR = "#f85149"
                    SUCCESS = "#238636"
                    WARNING = "#d29922"
                    COMBO_SELECTION = "#1f6feb"
                    SCROLLBAR = "#1f6feb"
                    SCROLLBAR_HOVER = "#58a6ff"
                    INPUT_BG = "#161b22"

                return _FallbackTheme()

    def _get_safe_parent(self) -> tk.Widget:
        """Ermittelt ein garantiert existierendes Eltern‑Widget."""
        try:
            if self.parent.winfo_exists():
                return self.parent
        except (tk.TclError, AttributeError):
            pass
        root = tk._default_root
        if root and root.winfo_exists():
            return root
        raise RuntimeError("Kein gültiges Eltern‑Fenster verfügbar")

    def _create_dialog(self) -> Optional[tk.Toplevel]:
        """Erstellt das Toplevel‑Fenster mit robuster Parent‑Prüfung."""
        try:
            parent_widget = self._get_safe_parent()
            dlg = tk.Toplevel(parent_widget)
            display_title = (
                f"🐉 {self.title}" if not self.title.startswith("🐉") else self.title
            )
            dlg.title(display_title)
            dlg.configure(bg=self._theme.BG_PRIMARY)
            dlg.geometry(f"{self.width}x{self.height}")
            dlg.protocol("WM_DELETE_WINDOW", self.close)
            return dlg
        except (tk.TclError, RuntimeError) as e:
            log_debug("dialog", f"Fehler beim Erstellen des Dialogs: {e}")
            return None

    def _register_in_parent(self) -> None:
        """Registriert den Dialog in der Parent‑Liste (falls vorhanden)."""
        try:
            if (
                hasattr(self.parent, "_open_dialogs")
                and self.dialog not in self.parent._open_dialogs
            ):
                self.parent._open_dialogs.append(self.dialog)
        except (tk.TclError, AttributeError):
            pass

    def _unregister_from_parent(self) -> None:
        """Entfernt den Dialog aus der Parent‑Liste."""
        try:
            if (
                hasattr(self.parent, "_open_dialogs")
                and self.dialog in self.parent._open_dialogs
            ):
                self.parent._open_dialogs.remove(self.dialog)
        except (tk.TclError, AttributeError, ValueError):
            pass

    # ------------------------------------------------------------------
    # Zentrierung (robust)
    # ------------------------------------------------------------------
    def _center_dialog(self) -> None:
        """Zentriert den Dialog relativ zum Parent (oder Bildschirm)."""
        if not self.dialog or not self.dialog.winfo_exists():
            return
        try:
            self.dialog.update_idletasks()
            dlg_w = self.dialog.winfo_width()
            dlg_h = self.dialog.winfo_height()
            if dlg_w <= 1 or dlg_h <= 1:
                dlg_w = self.width
                dlg_h = self.height

            x, y = None, None
            try:
                if self.parent.winfo_exists():
                    parent_x = self.parent.winfo_rootx()
                    parent_y = self.parent.winfo_rooty()
                    parent_w = self.parent.winfo_width()
                    parent_h = self.parent.winfo_height()
                    x = parent_x + (parent_w - dlg_w) // 2
                    y = parent_y + (parent_h - dlg_h) // 2
            except (tk.TclError, AttributeError):
                pass

            if x is None or y is None:
                screen_w = self.dialog.winfo_screenwidth()
                screen_h = self.dialog.winfo_screenheight()
                x = (screen_w - dlg_w) // 2
                y = (screen_h - dlg_h) // 2
            else:
                screen_w = self.dialog.winfo_screenwidth()
                screen_h = self.dialog.winfo_screenheight()
                x = max(0, min(x, screen_w - dlg_w))
                y = max(0, min(y, screen_h - dlg_h))

            self.dialog.geometry(f"+{x}+{y}")
            self.dialog.lift()
        except (tk.TclError, RuntimeError):
            pass

    # ------------------------------------------------------------------
    # Modalität
    # ------------------------------------------------------------------
    def _make_modal(self) -> None:
        """Macht den Dialog modal (grab_set, transient)."""
        if not self.dialog or not self.dialog.winfo_exists():
            return
        try:
            self.dialog.transient(self.parent)
            self.dialog.grab_set()
            self.dialog.focus_force()
        except (tk.TclError, AttributeError):
            pass

    def _release_modal(self) -> None:
        """Gibt den modal‑Grab frei (wird beim Schließen aufgerufen)."""
        if not self.dialog or not self.dialog.winfo_exists():
            return
        try:
            self.dialog.grab_release()
        except (tk.TclError, AttributeError):
            pass

    # ------------------------------------------------------------------
    # Sichere after‑Aufrufe
    # ------------------------------------------------------------------
    def _safe_after(
        self, delay_ms: int, callback: Callable, *args, **kwargs
    ) -> Optional[str]:
        """Führt callback nach delay_ms aus, falls Dialog noch existiert."""
        if not self.dialog or not self.dialog.winfo_exists():
            return None
        try:
            return self.dialog.after(delay_ms, callback, *args, **kwargs)
        except tk.TclError:
            return None

    def _safe_after_cancel(self, after_id: Optional[str]) -> None:
        """Bricht einen `after`‑Aufruf ab, falls möglich."""
        if after_id is not None and self.dialog and self.dialog.winfo_exists():
            try:
                self.dialog.after_cancel(after_id)
            except (tk.TclError, ValueError):
                pass

    def _timeout_close(self) -> None:
        """Wird nach Timeout aufgerufen – schließt den Dialog."""
        if self.dialog and self.dialog.winfo_exists() and not self._closed:
            log_debug(
                "dialog",
                f"Dialog '{self.title}' nach {self.timeout}s automatisch geschlossen",
            )
            self.close()

    def build_ui(self) -> None:
        """
        Muss von Unterklassen überschrieben werden, um die GUI aufzubauen.
        Diese Basisimplementierung tut nichts.
        """

    def apply_theme(self) -> None:
        """
        Wendet das aktuelle Theme rekursiv auf alle tk‑Widgets im Dialog an.
        Überspringt ttk‑Widgets (die haben eigene Styles).
        """
        if not self.dialog or not self.dialog.winfo_exists():
            return
        try:
            theme = self._get_theme_safe()
            PlatformUtils.apply_theme_to_widget_tree(self.dialog, theme)
            self._theme = theme  # Aktualisieren für zukünftige Aufrufe
        except (tk.TclError, NameError, AttributeError):
            pass

    def reset(self) -> None:
        """
        Setzt den Dialog zurück, damit er nach close() erneut geöffnet werden kann.
        Normalerweise nicht nötig – besser neue Instanz erzeugen.
        """
        if self._closed and self.dialog is None:
            self._closed = False
            self.dialog = self._create_dialog()
            if self.dialog is None:
                raise RuntimeError(
                    "Reset fehlgeschlagen: Dialog konnte nicht neu erstellt werden"
                )
            self.main = tk.Frame(
                self.dialog, bg=self._theme.BG_PRIMARY, padx=15, pady=15
            )
            self.main.pack(fill="both", expand=True)
            self._register_in_parent()
            self._center_dialog()
            if self.modal:
                self._make_modal()
            self.build_ui()
        else:
            raise RuntimeError("Reset nur auf geschlossenem Dialog möglich")

    def update_status(self, message: str) -> None:
        """
        Kann von Unterklassen überschrieben werden, um Statusmeldungen anzuzeigen.
        Standard: nichts tun.
        """

    def close(self) -> None:
        """Schließt den Dialog und räumt Ressourcen auf (idempotent)."""
        if self._closed:
            return
        self._closed = True

        # Timeout abbrechen
        if self._timeout_id is not None:
            self._safe_after_cancel(self._timeout_id)
            self._timeout_id = None

        # Modal‑Grab freigeben
        if self.modal:
            self._release_modal()

        # Aus Parent‑Liste entfernen
        self._unregister_from_parent()

        # Dialog zerstören
        if self.dialog and self.dialog.winfo_exists():
            try:
                self.dialog.destroy()
            except tk.TclError:
                pass
        self.dialog = None
        self.main = None

        # Callback ausführen (im Hauptthread)
        if self.on_close_callback:
            try:
                self.on_close_callback()
            except Exception as e:
                log_debug("dialog", f"Fehler im on_close_callback: {e}")

    def focus(self) -> None:
        """Setzt den Fokus auf den Dialog (falls sichtbar)."""
        if self.dialog and self.dialog.winfo_exists():
            try:
                self.dialog.focus_force()
            except tk.TclError:
                pass

    @contextmanager
    def temporary_subscription(
        self, event_bus: "EventBus", event_type: str, callback: Callable
    ):
        """Kontextmanager für temporäre Event‑Bus‑Abonnements."""
        event_bus.subscribe(event_type, callback)
        try:
            yield
        finally:
            event_bus.unsubscribe(event_type, callback)

    def __repr__(self) -> str:
        return f"<BaseDialog title='{self.title}' closed={self._closed} visible={self.is_visible}>"


class ContextMenuMixin:
    """Einheitliches Kontextmenü für Text- und Entry-Widgets mit:"""

    def __init__(
        self,
        widget: Union[tk.Text, tk.Entry, ttk.Entry],
        use_copy_cut_paste: bool = True,
    ):
        """
        Initialisiert das Kontextmenü.
        """
        self.widget = widget
        self._debug = DEBUG_LEVEL >= 3
        self._widget_type = self._get_widget_type()
        self.menu = tk.Menu(
            widget,
            tearoff=0,
            bg=CURRENT_THEME.BG_TERTIARY,
            fg=CURRENT_THEME.TEXT_PRIMARY,
            activebackground=CURRENT_THEME.BG_HOVER,
            activeforeground=CURRENT_THEME.TEXT_ACCENT,
            borderwidth=1,
            relief="solid",
        )
        if use_copy_cut_paste:
            if self._widget_type == "text":
                self.menu.add_command(
                    label="Undo", command=self.undo, accelerator="Ctrl+Z"
                )
                self.menu.add_command(
                    label="Redo", command=self.redo, accelerator="Ctrl+Y"
                )
                self.menu.add_separator()

            self.menu.add_command(label="Cut", command=self.cut, accelerator="Ctrl+X")
            self.menu.add_command(label="Copy", command=self.copy, accelerator="Ctrl+C")
            self.menu.add_command(
                label="Paste", command=self.paste, accelerator="Ctrl+V"
            )
            self.menu.add_separator()

        self.menu.add_command(
            label="Select All", command=self.select_all, accelerator="Ctrl+A"
        )
        if self._widget_type == "text":
            self.menu.add_command(label="Delete", command=self.clear)

        self.menu.bind("<Escape>", lambda e: self.menu.unpost())
        widget.bind("<Button-3>", self.show_menu)

        if self._debug:
            log_debug(
                "gui",
                f"ContextMenuMixin initialized for {self._widget_type} widget: {widget}",
            )

    def _get_widget_type(self) -> str:
        """Ermittelt den Widget-Typ (text, entry, unknown)."""
        if isinstance(self.widget, tk.Text):
            return "text"
        if isinstance(self.widget, (tk.Entry, ttk.Entry)):
            return "entry"
        return "unknown"

    def _has_selection(self) -> bool:
        """Prüft, ob im Widget Text ausgewählt ist (robust)."""
        try:
            if self._widget_type == "text":
                return bool(self.widget.tag_ranges(tk.SEL))
            else:
                return self.widget.selection_present()
        except tk.TclError:
            return False

    def _get_selected_text(self) -> str:
        """Gibt den selektierten Text zurück oder leeren String."""
        try:
            if self._widget_type == "text":
                if self.widget.tag_ranges(tk.SEL):
                    return self.widget.get(tk.SEL_FIRST, tk.SEL_LAST)
            else:
                if self.widget.selection_present():
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    return self.widget.get()[start:end]
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Error getting selected text: {e}")
        return ""

    def show_menu(self, event):
        """Zeigt das Kontextmenü an der Mausposition an."""
        try:
            self.menu.tk_popup(event.x_root, event.y_root)
            if self._debug:
                log_debug(
                    "gui", f"Context menu shown at ({event.x_root}, {event.y_root})"
                )
        except Exception as e:
            if self._debug:
                log_debug("gui", f"Failed to show context menu: {e}")
        finally:
            self.menu.grab_release()
        return "break"

    def copy(self):
        """Kopiert den selektierten Text in die Zwischenablage."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Copy called but no selection")
                return

        text = self._get_selected_text()
        if not text:
            return

        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            if self._debug:
                log_debug("gui", f"Copied {len(text)} chars to clipboard")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Copy failed: {e}")

    def cut(self):
        """Ausschneiden: Kopieren und Löschen."""
        if not self._has_selection():
            if self._debug:
                log_debug("gui", "Cut called but no selection")
                return
        text = self._get_selected_text()
        if not text:
            return
        try:
            self.widget.clipboard_clear()
            self.widget.clipboard_append(text)
            if self._widget_type == "text":
                self.widget.delete(tk.SEL_FIRST, tk.SEL_LAST)
            else:
                start = self.widget.index(tk.SEL_FIRST)
                end = self.widget.index(tk.SEL_LAST)
                self.widget.delete(start, end)
            if self._debug:
                log_debug("gui", f"Cut {len(text)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Cut failed: {e}")

    def paste(self):
        """Fügt Text aus der Zwischenablage ein."""
        try:
            clipboard = self.widget.clipboard_get()
            if not clipboard:
                return

            if self._widget_type == "text":
                self.widget.insert(tk.INSERT, clipboard)
            else:
                if self._has_selection():
                    start = self.widget.index(tk.SEL_FIRST)
                    end = self.widget.index(tk.SEL_LAST)
                    self.widget.delete(start, end)
                self.widget.insert(tk.INSERT, clipboard)

            if self._debug:
                log_debug("gui", f"Pasted {len(clipboard)} chars")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Paste failed: {e}")

    def select_all(self):
        """Markiert den gesamten Text im Widget."""
        try:
            if self._widget_type == "text":
                self.widget.tag_add(tk.SEL, "1.0", tk.END)
                self.widget.mark_set(tk.INSERT, "1.0")
            else:
                self.widget.select_range(0, tk.END)
                self.widget.icursor(tk.END)
            if self._debug:
                log_debug("gui", "Select all executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Select all failed: {e}")

    def clear(self):
        """Löscht den gesamten Inhalt (nur für Text-Widgets)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.delete("1.0", tk.END)
            if self._debug:
                log_debug("gui", "Cleared text widget")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Clear failed: {e}")

    def undo(self):
        """Macht die letzte Änderung rückgängig (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.edit_undo()
            if self._debug:
                log_debug("gui", "Undo executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Undo failed: {e}")

    def redo(self):
        """Stellt die letzte rückgängig gemachte Änderung wieder her (nur Text)."""
        if self._widget_type != "text":
            return
        try:
            self.widget.edit_redo()
            if self._debug:
                log_debug("gui", "Redo executed")
        except tk.TclError as e:
            if self._debug:
                log_debug("gui", f"Redo failed: {e}")


