class ConfigDefaults:
    """
    Zentrale Konfigurationskonstanten für Dragon Whisperer.

    Alle Werte sind als Klassenattribute (`ClassVar`) deklariert, damit sie
    von abgeleiteten Klassen überschrieben werden können.
    """

    # ── Audio-Grundparameter ─────────────────────────────────────────────
    SAMPLE_RATE: ClassVar[int] = 16000
    """Audio-Samplerate in Hz (16 kHz ist optimal für Whisper)."""

    CHANNELS: ClassVar[int] = 1
    """Anzahl der Audiokanäle (1 = Mono, 2 = Stereo). Mono reicht für Whisper aus."""

    AUDIO_FORMAT: ClassVar[str] = "s16le"
    """Rohaudio-Format (s16le = signed 16-bit little-endian)."""

    BYTES_PER_SAMPLE: ClassVar[int] = 2
    """Bytes pro Sample (bei 16-bit = 2)."""

    # ── Whisper-Parameter ──────────────────────────────────────────────────
    DEFAULT_BEAM_SIZE: ClassVar[int] = 10
    """Standard-Beam-Size für Whisper-Decodierung (höher = genauer, aber langsamer)."""

    DEFAULT_TEMPERATURE: ClassVar[float] = 0.0
    """Temperatur für Whisper (0.0 = deterministisch, >0 = zufälliger)."""

    # ── Speicher- und Performance-Grenzen ────────────────────────────────
    MAX_MEMORY_USAGE: ClassVar[int] = 8 * 1024 * 1024 * 1024
    """Maximaler Arbeitsspeicher in Bytes (8 GB). Wird durch psutil überschrieben, falls verfügbar."""

    MAX_GUI_UPDATES_PER_SECOND: ClassVar[int] = 120
    """Maximale GUI-Updates pro Sekunde (begrenzt die Auslastung des Hauptthreads)."""

    MAX_CACHE_SIZE: ClassVar[int] = 500
    """Maximale Anzahl Einträge im Transkriptions-Cache (LRU)."""

    MAX_TEXT_LINES: ClassVar[int] = 2000
    """Maximale Zeilen in den Text-Widgets (verhindert Speicherüberlauf)."""

    # ── VAD (Voice Activity Detection) ────────────────────────────────────
    ENABLE_VAD_FILTER: ClassVar[bool] = True
    """Voice Activity Detection standardmäßig aktivieren (entfernt Stille vor Transkription)."""

    VAD_THRESHOLD: ClassVar[float] = 0.25
    """VAD-Schwellwert (0.0-1.0, höher = weniger empfindlich)."""

    VAD_MIN_SPEECH_DURATION_MS: ClassVar[int] = 225
    """Minimale Sprachdauer in Millisekunden (kürzere Passagen werden ignoriert)."""

    VAD_MIN_SILENCE_DURATION_MS: ClassVar[int] = 80
    """Minimale Stilledauer in Millisekunden, um einen Satz zu beenden."""

    LANGUAGE_VAD: ClassVar[Dict[str, Dict[str, Any]]] = {
        "ja": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "ko": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "zh": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "th": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "vi": {"threshold": 0.3, "min_speech_ms": 250, "min_silence_ms": 90},
        "ar": {"threshold": 0.35, "min_speech_ms": 280, "min_silence_ms": 100},
        "ru": {"threshold": 0.3, "min_speech_ms": 240, "min_silence_ms": 80},
        "hi": {"threshold": 0.32, "min_speech_ms": 280, "min_silence_ms": 110},
        "tr": {"threshold": 0.32, "min_speech_ms": 260, "min_silence_ms": 95},
        "fa": {"threshold": 0.33, "min_speech_ms": 270, "min_silence_ms": 100},
    }
    """Sprachspezifische VAD-Parameter (überschreiben die globalen Werte für bestimmte Sprachen)."""

    # ── Chunk-Verarbeitung ─────────────────────────────────────────────────
    BASE_CHUNK_DURATION: ClassVar[int] = 20
    """Standard-Chunk-Dauer in Sekunden (20s ist ein guter Kompromiss)."""

    MIN_CHUNK_DURATION: ClassVar[int] = 2
    """Minimale Chunk-Dauer (kürzer = niedrigere Latenz, aber weniger Kontext)."""

    MAX_CHUNK_DURATION: ClassVar[int] = 30
    """Maximale Chunk-Dauer (länger = mehr Kontext, aber höhere Latenz)."""

    CHUNK_OVERLAP: ClassVar[float] = 2.0
    """Überlappung zwischen aufeinanderfolgenden Chunks in Sekunden (verhindert Informationsverlust an den Grenzen)."""

    ADAPTIVE_CHUNK_MIN_SAMPLES: ClassVar[int] = 5
    """Minimale Anzahl von Samples für die adaptive Chunk-Anpassung."""

    ADAPTIVE_CHUNK_SMOOTHING_ALPHA: ClassVar[float] = 0.3
    """Glättungsfaktor für die adaptive Chunk-Anpassung (0.0-1.0)."""

    ADAPTIVE_CHUNK_STABLE_THRESHOLD: ClassVar[int] = 2
    """Anzahl der stabilen Messungen, bevor die Chunk-Dauer geändert wird."""

    # ── Stream- und Netzwerk-Parameter ────────────────────────────────────
    STREAM_TIMEOUT: ClassVar[int] = 25
    """Timeout für Stream-Verbindungen in Sekunden."""

    INITIAL_BUFFER_SECONDS: ClassVar[float] = 2.0
    """Initiale Puffergröße in Sekunden (erlaubt einen flüssigen Start)."""

    MAX_EMPTY_READS: ClassVar[int] = 30
    """Maximale Anzahl aufeinanderfolgender leerer Leseversuche, bevor ein Reconnect ausgelöst wird."""

    RECONNECT_DELAY: ClassVar[int] = 2
    """Verzögerung vor einem Reconnect-Versuch in Sekunden."""

    READ_RETRY_DELAY: ClassVar[float] = 0.1
    """Verzögerung zwischen Leseversuchen bei Timeout in Sekunden."""

    YOUTUBE_TIMEOUT: ClassVar[int] = 10_000_000  # Mikrosekunden
    """YouTube-spezifisches Timeout in Mikrosekunden (10 Sekunden)."""

    NORMAL_TIMEOUT: ClassVar[int] = 30_000_000  # Mikrosekunden
    """Normales Timeout für andere Streams in Mikrosekunden (30 Sekunden)."""

    MAX_STREAM_RECONNECTS: ClassVar[int] = 5
    """Maximale Anzahl von Reconnect-Versuchen pro Stream."""

    STREAM_RECONNECT_DELAY: ClassVar[int] = 2
    """Basisverzögerung zwischen Reconnects in Sekunden."""

    STREAM_RECONNECT_BACKOFF_FACTOR: ClassVar[float] = 2.0
    """Exponentieller Backoff-Faktor für Reconnects."""

    READ_EMPTY_SLEEP_BASE: ClassVar[float] = 0.1
    """Basis-Schlafzeit bei leeren Lesevorgängen."""

    READ_ERROR_BACKOFF_BASE: ClassVar[float] = 0.1
    """Basis-Backoff bei Lese-Fehlern."""

    YOUTUBE_IDLE_TIMEOUT: ClassVar[int] = 25
    """Inaktivitäts-Timeout für YouTube-Streams in Sekunden."""

    YOUTUBE_INITIAL_TIMEOUT: ClassVar[int] = 25
    """Initiales Timeout für YouTube-Verbindungen."""

    YOUTUBE_URL_REFRESH_INTERVAL: ClassVar[int] = 600
    """Intervall für das Aktualisieren der YouTube-Audio-URL in Sekunden (10 Minuten)."""

    YOUTUBE_URL_REFRESH_MAX_ATTEMPTS: ClassVar[int] = 3
    """Maximale Versuche, eine frische YouTube-URL zu holen."""

    YOUTUBE_LOW_QUALITY_MAX_CHUNKS: ClassVar[int] = 5
    """Anzahl der Chunks mit niedriger Qualität, bevor ein Fallback ausgelöst wird."""

    YOUTUBE_INITIAL_WAIT: ClassVar[float] = 3.0
    """Wartezeit nach dem Start eines YouTube-Streams in Sekunden."""

    FFMPEG_START_WAIT: ClassVar[float] = 1.5
    """Wartezeit nach dem Start von FFmpeg, bevor mit dem Lesen begonnen wird."""

    STREAM_TEST_TIMEOUT: ClassVar[int] = 8
    """Timeout für den initialen Stream-Test in Sekunden."""

    YOUTUBE_STREAM_TEST_TIMEOUT: ClassVar[int] = 8
    """YouTube-spezifischer Stream-Test-Timeout."""

    READ_WITH_TIMEOUT_SELECT_INTERVAL: ClassVar[float] = 0.001
    """Intervall für select() bei Lesevorgängen mit Timeout."""

    READ_WITH_TIMEOUT_EMPTY_LOG_INTERVAL: ClassVar[int] = 10
    """Log-Intervall für leere Lesevorgänge (Anzahl der Versuche)."""

    MAX_BACKOFF: ClassVar[int] = 30
    """Maximale Backoff-Zeit in Sekunden."""

    BUFFER_FLUSH_INACTIVITY: ClassVar[float] = 10.0
    """Inaktivitätszeit, nach der der Puffer geleert wird, in Sekunden."""

    BUFFER_FLUSH_TIMEOUT: ClassVar[float] = 30.0
    """Timeout für Puffer-Leerung in Sekunden."""

    PROGRESS_UPDATE_INTERVAL: ClassVar[float] = 0.5
    """Intervall für Fortschritts-Updates in Sekunden."""

    ERRORS_BEFORE_CHUNK_REDUCTION: ClassVar[int] = 3
    """Anzahl der Fehler, bevor die Chunk-Dauer reduziert wird."""

    SUCCESSES_BEFORE_CHUNK_INCREASE: ClassVar[int] = 5
    """Anzahl der Erfolge, bevor die Chunk-Dauer erhöht wird."""

    # ── FFmpeg-spezifische Parameter ──────────────────────────────────────
    FFMPEG_BUFSIZE: ClassVar[str] = "2048k"
    """FFmpeg Puffergröße (2 MB)."""

    FFMPEG_THREADS: ClassVar[int] = 1
    """Anzahl der FFmpeg-Threads (1 = automatisch)."""

    FFMPEG_PROBESIZE: ClassVar[str] = "32"
    """FFmpeg Probesize in MB (kleiner Wert für schnellere Initialisierung)."""

    FFMPEG_ANALYZE_DURATION: ClassVar[str] = "0"
    """FFmpeg Analyze-Duration (0 = automatisch)."""

    # ── Audio-Enhancement ──────────────────────────────────────────────────
    AUDIO_ENHANCEMENT_ENABLED: ClassVar[bool] = True
    """Audio-Enhancement standardmäßig aktivieren."""

    MIN_RMS_THRESHOLD: ClassVar[float] = 0.002
    """Minimaler RMS-Wert, ab dem eine Verstärkung angewendet wird."""

    TARGET_RMS: ClassVar[float] = 0.2
    """Ziel-RMS-Wert für die automatische Verstärkung."""

    MAX_GAIN: ClassVar[float] = 5.0
    """Maximaler Verstärkungsfaktor."""

    CLIPPING_THRESHOLD: ClassVar[float] = 0.9
    """Schwellwert für Clipping-Erkennung (0.9 = 90% des Maximalwerts)."""

    NOISEREDUCE_INTERVAL: ClassVar[int] = 10
    """Intervall (Anzahl der Chunks) für die Anwendung von noisereduce."""

    NOISEREDUCE_MIN_LENGTH: ClassVar[int] = 32000
    """Minimale Audio-Länge in Samples für noisereduce (2 Sekunden bei 16 kHz)."""

    AUDIO_ENHANCEMENT_MIN_LENGTH: ClassVar[int] = 1600
    """Minimale Audio-Länge für Enhancement in Bytes."""

    LOW_QUALITY_CHUNK_THRESHOLD_FACTOR: ClassVar[float] = 0.15
    """Faktor für die Erkennung niedriger Qualität (im Verhältnis zur erwarteten Dauer)."""

    LOW_QUALITY_CHUNK_LOG_LEVEL: ClassVar[int] = 4
    """Log-Level für Low-Quality-Warnungen."""

    LOW_QUALITY_CHUNK_LOG_INTERVAL: ClassVar[int] = 10
    """Intervall für Low-Quality-Logs (Anzahl der Chunks)."""

    # ── Duplikaterkennung ──────────────────────────────────────────────────
    DUPLICATE_CHECK_ENABLED: ClassVar[bool] = False
    """Duplikaterkennung standardmäßig deaktiviert (spart CPU)."""

    RECENT_TRANSCRIPTIONS_SIZE: ClassVar[int] = 10
    """Anzahl der letzten Transkriptionen, die für die Duplikatprüfung gespeichert werden."""

    MIN_TEXT_LENGTH: ClassVar[int] = 3
    """Minimale Textlänge für die Duplikatprüfung (kürzere Texte werden ignoriert)."""

    MIN_UNIQUE_WORDS_RATIO: ClassVar[float] = 0.3
    """Minimaler Anteil einzigartiger Wörter (verhindert Wiederholungen wie 'ja ja ja')."""

    # ── Untertitel / Timed Transcriptions ──────────────────────────────────
    SUBTITLE_BUFFER_SIZE: ClassVar[int] = 1000
    """Maximale Anzahl von Untertitel-Segmenten im Puffer."""

    ENABLE_TIMED_TRANSCRIPTIONS: ClassVar[bool] = True
    """Zeitstempel für Transkriptionen aktivieren (für Untertitel-Modus)."""

    ENABLE_TIMED_TRANSLATIONS: ClassVar[bool] = True
    """Zeitstempel für Übersetzungen aktivieren (für Untertitel-Modus)."""

    # ── Logging ─────────────────────────────────────────────────────────────
    ENABLE_DEBUG_LOGGING: ClassVar[bool] = True
    """Debug-Logging global aktivieren."""

    LOG_CHUNK_PROCESSING: ClassVar[bool] = False
    """Detailliertes Logging für Chunk-Verarbeitung (sehr ausführlich)."""

    LOG_AUDIO_STATS: ClassVar[bool] = True
    """Audio-Statistiken (RMS, Verstärkung) loggen."""

    LOG_PERFORMANCE: ClassVar[bool] = True
    """Performance-Metriken (Verarbeitungszeit, Realtime-Faktor) loggen."""

    LOG_STREAM_EVENTS: ClassVar[bool] = True
    """Stream-Ereignisse (Verbindung, Timeout, Reconnect) loggen."""

    PERFORMANCE_LOG_INTERVAL: ClassVar[int] = 50
    """Intervall für Performance-Logs (Anzahl der Chunks)."""

    # ── Caching ─────────────────────────────────────────────────────────────
    MAX_CACHE_SIZE_MB: ClassVar[int] = 100
    """Maximale Cache-Größe in MB (Überschreibung durch Config möglich)."""

    CACHE_ENABLED: ClassVar[bool] = True
    """Caching global aktivieren."""

    TRANSCRIPTION_CACHE_SIZE: ClassVar[int] = 500
    """Maximale Anzahl Einträge im Transkriptions-Cache."""

    TRANSCRIPTION_CACHE_TTL: ClassVar[int] = 300
    """Lebensdauer von Transkriptions-Cache-Einträgen in Sekunden (5 Minuten)."""

    TRANSLATION_CACHE_SIZE: ClassVar[int] = 1000
    """Maximale Anzahl Einträge im Übersetzungs-Cache."""

    TRANSLATION_CACHE_TTL: ClassVar[int] = 3600
    """Lebensdauer von Übersetzungs-Cache-Einträgen in Sekunden (1 Stunde)."""

    AUDIO_CACHE_SIZE: ClassVar[int] = 256
    """Maximale Anzahl Einträge im Audio-Cache."""

    AUDIO_CACHE_TTL: ClassVar[int] = 1800
    """Lebensdauer von Audio-Cache-Einträgen in Sekunden (30 Minuten)."""

    # ── Fehlertoleranz ──────────────────────────────────────────────────────
    MAX_CONSECUTIVE_ERRORS: ClassVar[int] = 5
    """Maximale aufeinanderfolgende Fehler, bevor der Stream neu gestartet wird."""

    # ── Sicherheit (Dateizugriff) ─────────────────────────────────────────
    ALLOWED_FILE_SCHEME_PREFIX: ClassVar[str] = "file://"
    """Präfix für lokale Dateien."""

    ALLOWED_FILE_BASE_DIRS: ClassVar[List[str]] = [
        str(Path.home().resolve()),
        os.getcwd(),
    ]
    """Standardmäßig erlaubte Basisverzeichnisse für Dateizugriff (Home, CWD)."""

    URL_ALLOWED_CHARS: ClassVar[str] = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
    """Erlaubte Zeichen in URLs (RFC 3986-konform)."""

    # ── YouTube-spezifische Header ─────────────────────────────────────────
    YOUTUBE_HEADERS: ClassVar[Dict[str, str]] = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.0.0 Safari/537.36",
        "Referer": "https://www.youtube.com/",
        "Origin": "https://www.youtube.com",
        "Accept": "*/*",
        "Accept-Language": "en-US,en;q=0.9",
    }
    """HTTP-Header für YouTube-Anfragen (umgeht Blockaden)."""

    # ── Plattformspezifische FFmpeg-Parameter ──────────────────────────────
    PLATFORM_CONFIG: ClassVar[Dict[str, Dict[str, Any]]] = {
        "windows": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_streamed", "1"],
            "process_creation_flags": 0x08000000,
        },
        "macos": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_on_network_error", "1"],
            "start_new_session": True,
        },
        "linux": {
            "ffmpeg_flags": ["-reconnect", "1", "-reconnect_streamed", "1"],
            "start_new_session": True,
        },
    }
    """Plattformspezifische FFmpeg- und Prozess-Parameter."""

    # ── Queue-Größen ────────────────────────────────────────────────────────
    GUI_QUEUE_MAX_SIZE: ClassVar[int] = 200
    """Maximale Größe der GUI-Queue (begrenzt die GUI-Last)."""

    GUI_QUEUE_CLEANUP_TARGET: ClassVar[int] = 100
    """Zielgröße der GUI-Queue nach einer Bereinigung."""

    TEXT_QUEUE_MAX_SIZE: ClassVar[int] = 150
    """Maximale Größe der Text-Queue (Transkriptionen/Übersetzungen)."""

    TEXT_QUEUE_CLEANUP_TARGET: ClassVar[int] = 75
    """Zielgröße der Text-Queue nach einer Bereinigung."""

    # ── Whisper-Modelle ─────────────────────────────────────────────────────
    WHISPER_MODELS: ClassVar[List[str]] = [
        "tiny",
        "tiny.en",
        "base",
        "base.en",
        "small",
        "small.en",
        "medium",
        "large-v2",
        "large-v3",
        "large-v3-turbo",
        "distil-large-v3",
    ]
    """Liste aller von Whisper unterstützten Modelle (für ComboBox und Validierung)."""

    # ── Refresh / Reconnect ─────────────────────────────────────────────────
    MAX_REFRESH_ATTEMPTS: ClassVar[int] = 3
    """Maximale Anzahl von Refresh-Versuchen für Stream-URLs."""

    REFRESH_RETRY_DELAY_BASE: ClassVar[float] = 2.0
    """Basisverzögerung für Refresh-Wiederholungen in Sekunden."""

    REFRESH_RETRY_DELAY_MAX: ClassVar[float] = 10.0
    """Maximale Verzögerung für Refresh-Wiederholungen."""

    STALLED_RECONNECT_LOG_INTERVAL: ClassVar[float] = 10.0
    """Intervall für Logs bei hängenden Reconnects in Sekunden."""

    # ── Statische Validierung ─────────────────────────────────────────────
    @classmethod
    def print_debug_info(cls) -> None:
        """Gibt eine Übersicht aller Konfigurationswerte für Debugging-Zwecke aus."""

        logger.debug("=" * 60)
        logger.debug("ConfigDefaults Debug Information")
        logger.debug("=" * 60)
        for name, value in cls.__dict__.items():
            if not name.startswith("_") and not callable(value):
                if isinstance(value, (list, dict)) and len(str(value)) > 100:
                    value_str = str(value)[:100] + "..."
                else:
                    value_str = str(value)
                logger.debug(f"  {name:35} = {value_str}")
        logger.debug("=" * 60)

    @classmethod
    def validate_constants(cls) -> List[str]:
        """
        Validiert die Konstanten auf Konsistenz und gibt eine Liste von Problemen zurück.
        Wird beim Start aufgerufen, um fehlerhafte Konfigurationen zu erkennen.
        """
        issues = []
        if cls.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            issues.append(
                f"SAMPLE_RATE={cls.SAMPLE_RATE} (erwartet: 8000,16000,22050,44100,48000)"
            )
        if cls.CHANNELS not in (1, 2):
            issues.append(f"CHANNELS={cls.CHANNELS} (erwartet: 1 oder 2)")
        if cls.MIN_CHUNK_DURATION >= cls.MAX_CHUNK_DURATION:
            issues.append(
                f"MIN_CHUNK_DURATION={cls.MIN_CHUNK_DURATION} >= MAX_CHUNK_DURATION={cls.MAX_CHUNK_DURATION}"
            )
        if (
            cls.BASE_CHUNK_DURATION < cls.MIN_CHUNK_DURATION
            or cls.BASE_CHUNK_DURATION > cls.MAX_CHUNK_DURATION
        ):
            issues.append(
                f"BASE_CHUNK_DURATION={cls.BASE_CHUNK_DURATION} außerhalb [{cls.MIN_CHUNK_DURATION}, {cls.MAX_CHUNK_DURATION}]"
            )
        if not cls.WHISPER_MODELS:
            issues.append("WHISPER_MODELS ist leer")
        return issues


# =============================================================================
# 2. Dynamische Config-Klasse (Config)
# =============================================================================
@dataclass
class Config(ConfigDefaults):
    """
    Dynamische Konfiguration für Dragon Whisperer.

    Erbt alle Konstanten von `ConfigDefaults`, überschreibt aber einige
    Werte mit dynamischen Standardwerten. Bietet Properties für Chunk-Größen,
    Bytes pro Sekunde und Hilfsmethoden für Filter, Timeouts und Plattform-Konfig.
    """

    _base_chunk_duration: int = ConfigDefaults.BASE_CHUNK_DURATION
    CHUNK_OVERLAP: float = ConfigDefaults.CHUNK_OVERLAP
    MIN_CHUNK_DURATION: int = ConfigDefaults.MIN_CHUNK_DURATION
    MAX_CHUNK_DURATION: int = ConfigDefaults.MAX_CHUNK_DURATION
    LANGUAGE_VAD: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.LANGUAGE_VAD.copy()
    )
    _actual_chunk_duration: float = field(
        init=False, default=float(ConfigDefaults.BASE_CHUNK_DURATION)
    )

    AUDIO_FILTER: str = "aresample=16000"
    LANGUAGE_FILTERS: Dict[str, str] = field(
        default_factory=lambda: {
            k: "aresample=16000" for k in ConfigDefaults.LANGUAGE_VAD
        }
    )
    FILTER_PROFILES: Dict[str, str] = field(
        default_factory=lambda: {
            "transcription": "aresample=16000",
            "translation": "aresample=16000",
            "realtime": "aresample=16000",
            "noisy": "aresample=16000,volume=2.5,highpass=f=150,lowpass=f=3000",
            "music": "aresample=16000",
            "podcast": "aresample=16000",
        }
    )

    YOUTUBE_HEADERS: Dict[str, str] = field(
        default_factory=lambda: ConfigDefaults.YOUTUBE_HEADERS.copy()
    )
    PLATFORM_CONFIG: Dict[str, Dict[str, Any]] = field(
        default_factory=lambda: ConfigDefaults.PLATFORM_CONFIG.copy()
    )

    AUDIO_ENHANCEMENT_ENABLED: bool = False
    MIN_RMS_THRESHOLD: float = ConfigDefaults.MIN_RMS_THRESHOLD
    TARGET_RMS: float = ConfigDefaults.TARGET_RMS
    MAX_GAIN: float = ConfigDefaults.MAX_GAIN
    CLIPPING_THRESHOLD: float = ConfigDefaults.CLIPPING_THRESHOLD

    DUPLICATE_CHECK_ENABLED: bool = False
    RECENT_TRANSCRIPTIONS_SIZE: int = ConfigDefaults.RECENT_TRANSCRIPTIONS_SIZE
    MIN_TEXT_LENGTH: int = ConfigDefaults.MIN_TEXT_LENGTH
    MIN_UNIQUE_WORDS_RATIO: float = ConfigDefaults.MIN_UNIQUE_WORDS_RATIO

    SUBTITLE_BUFFER_SIZE: int = ConfigDefaults.SUBTITLE_BUFFER_SIZE
    ENABLE_TIMED_TRANSCRIPTIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSCRIPTIONS
    ENABLE_TIMED_TRANSLATIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSLATIONS

    ENABLE_DEBUG_LOGGING: bool = ConfigDefaults.ENABLE_DEBUG_LOGGING
    LOG_CHUNK_PROCESSING: bool = ConfigDefaults.LOG_CHUNK_PROCESSING
    LOG_AUDIO_STATS: bool = ConfigDefaults.LOG_AUDIO_STATS
    LOG_PERFORMANCE: bool = ConfigDefaults.LOG_PERFORMANCE
    LOG_STREAM_EVENTS: bool = ConfigDefaults.LOG_STREAM_EVENTS
    PERFORMANCE_LOG_INTERVAL: int = ConfigDefaults.PERFORMANCE_LOG_INTERVAL

    MAX_CACHE_SIZE_MB: int = ConfigDefaults.MAX_CACHE_SIZE_MB
    CACHE_ENABLED: bool = ConfigDefaults.CACHE_ENABLED

    WHISPER_MODELS: List[str] = field(
        default_factory=lambda: ConfigDefaults.WHISPER_MODELS.copy()
    )

    _cached_bytes_per_second: Optional[int] = field(
        default=None, init=False, repr=False
    )

    # ── Properties ──────────────────────────────────────────────────────────

    @property
    def CHUNK_DURATION(self) -> float:
        """Aktuelle Chunk-Dauer in Sekunden (dynamisch änderbar)."""
        return self._actual_chunk_duration

    @CHUNK_DURATION.setter
    def CHUNK_DURATION(self, value: float) -> None:
        """Setzt die Chunk-Dauer mit Bereichsprüfung und Logging."""
        old = self._actual_chunk_duration
        if self.MIN_CHUNK_DURATION <= value <= self.MAX_CHUNK_DURATION:
            self._actual_chunk_duration = float(value)
            if abs(old - value) > 0.1 and logger.isEnabledFor(logging.DEBUG):
                _safe_log_debug(f"Chunk-Dauer geändert: {old:.1f}s → {value:.1f}s")
        else:
            clamped = max(self.MIN_CHUNK_DURATION, min(value, self.MAX_CHUNK_DURATION))
            logger.warning(
                f"Chunk-Dauer {value}s außerhalb [{self.MIN_CHUNK_DURATION}, {self.MAX_CHUNK_DURATION}] – "
                f"auf {clamped:.1f}s geklammert"
            )
            self._actual_chunk_duration = clamped

    @property
    def CHUNK_SIZE_BYTES(self) -> int:
        """Größe eines Audio-Chunks in Bytes (basierend auf aktueller Chunk-Dauer)."""
        return int(
            self.CHUNK_DURATION
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def OVERLAP_SIZE_BYTES(self) -> int:
        """Überlappungsgröße in Bytes zwischen aufeinanderfolgenden Chunks."""
        return int(
            self.CHUNK_OVERLAP
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def BYTES_PER_SECOND(self) -> int:
        """
        Datenrate in Bytes pro Sekunde (mit Caching für Performance).
        """
        if self._cached_bytes_per_second is None:
            self._cached_bytes_per_second = (
                self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
            )
            if self.ENABLE_DEBUG_LOGGING and getattr(globals(), "DEBUG_LEVEL", 0) >= 4:
                _safe_log_debug(
                    f"Computed BYTES_PER_SECOND = {self._cached_bytes_per_second} "
                    f"(SR={self.SAMPLE_RATE}, CH={self.CHANNELS}, BPS={self.BYTES_PER_SAMPLE})"
                )
        return self._cached_bytes_per_second

    @property
    def MIN_CHUNK_BYTES(self) -> int:
        """Minimale Chunk-Größe in Bytes (entspricht MIN_CHUNK_DURATION)."""
        return int(self.MIN_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def MAX_CHUNK_BYTES(self) -> int:
        """Maximale Chunk-Größe in Bytes (entspricht MAX_CHUNK_DURATION)."""
        return int(self.MAX_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def INITIAL_BUFFER_BYTES(self) -> int:
        """Größe des initialen Audiopuffers in Bytes."""
        return int(self.INITIAL_BUFFER_SECONDS * self.BYTES_PER_SECOND)

    # ── Hilfsmethoden ──────────────────────────────────────────────────────

    def get_timeout_microseconds(self, is_youtube: bool = False) -> int:
        """
        Gibt das passende Timeout in Mikrosekunden zurück.
        """
        return self.YOUTUBE_TIMEOUT if is_youtube else self.NORMAL_TIMEOUT

    def get_audio_filter(
        self, language: Optional[str] = None, profile: Optional[str] = None
    ) -> str:
        """Gibt einen optimierten Audiofilter basierend auf Sprache und Profil zurück."""
        filter_str = self.AUDIO_FILTER

        if profile and profile in self.FILTER_PROFILES:
            filter_str = self.FILTER_PROFILES[profile]

        if language and language in self.LANGUAGE_FILTERS:
            filter_str = self.LANGUAGE_FILTERS[language]

        if self.LOG_AUDIO_STATS and getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
            _safe_log_debug(
                f"Verwende Audiofilter: {filter_str} (profil={profile}, lang={language})"
            )

        return filter_str

    def get_youtube_headers(self, is_manifest: bool = False) -> Dict[str, str]:
        """Gibt die HTTP-Header für YouTube-Anfragen zurück."""
        headers = self.YOUTUBE_HEADERS.copy()
        if is_manifest:
            headers.update(
                {"X-Client-Data": "CI22yQE=", "Content-Type": "application/x-mpegURL"}
            )
        return headers

    def get_platform_config(self, platform: Optional[str] = None) -> Dict[str, Any]:
        """Gibt plattformspezifische Konfiguration für FFmpeg und Prozesse zurück."""
        if not platform:
            platform = getattr(globals(), "SYSTEM", "linux").lower()
        config = self.PLATFORM_CONFIG.get(platform, self.PLATFORM_CONFIG["linux"])
        if self.ENABLE_DEBUG_LOGGING and getattr(globals(), "DEBUG_LEVEL", 0) >= 3:
            _safe_log_debug(f"Plattform-Konfiguration für {platform}: {config}")
        return config

    def __setattr__(self, name: str, value: Any) -> None:
        """
        Invalidiert den BYTES_PER_SECOND‑Cache nur bei tatsächlicher Wertänderung.
        """
        if name in ("SAMPLE_RATE", "CHANNELS", "BYTES_PER_SAMPLE"):
            current = getattr(self, name, None)
            if current != value:
                object.__setattr__(self, "_cached_bytes_per_second", None)
                if (
                    self.ENABLE_DEBUG_LOGGING
                    and getattr(globals(), "DEBUG_LEVEL", 0) >= 4
                ):
                    _safe_log_debug(
                        f"Invalidated BYTES_PER_SECOND cache due to change of {name} "
                        f"({current} → {value})"
                    )
        super().__setattr__(name, value)

    def __post_init__(self) -> None:
        """
        Initialisiert die Config-Instanz nach der Dataclass-Erstellung.
        """
        self._actual_chunk_duration = float(self._base_chunk_duration)
        self._cached_bytes_per_second = (
            self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
        )

        # Validierung und automatische Reparatur
        if not self.validate_config():
            logger.warning(
                "Config-Instanz enthält ungültige Werte. Versuche automatische Korrektur."
            )
            if self.CHUNK_DURATION < self.MIN_CHUNK_DURATION:
                logger.warning(
                    f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s < MIN_CHUNK_DURATION={self.MIN_CHUNK_DURATION}s. "
                    f"Setze auf MIN_CHUNK_DURATION."
                )
                self.CHUNK_DURATION = self.MIN_CHUNK_DURATION
            elif self.CHUNK_DURATION > self.MAX_CHUNK_DURATION:
                logger.warning(
                    f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s > MAX_CHUNK_DURATION={self.MAX_CHUNK_DURATION}s. "
                    f"Setze auf MAX_CHUNK_DURATION."
                )
                self.CHUNK_DURATION = self.MAX_CHUNK_DURATION

            if self.CHUNK_OVERLAP >= self.CHUNK_DURATION:
                new_overlap = max(0.0, self.CHUNK_DURATION * 0.1)
                logger.warning(
                    f"CHUNK_OVERLAP={self.CHUNK_OVERLAP:.1f}s >= CHUNK_DURATION={self.CHUNK_DURATION:.1f}s. "
                    f"Setze auf {new_overlap:.1f}s."
                )
                self.CHUNK_OVERLAP = new_overlap

            if self.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
                logger.warning(
                    f"SAMPLE_RATE={self.SAMPLE_RATE}Hz ist unüblich. "
                    f"Whisper erwartet 16000Hz. Setze auf 16000Hz."
                )
                self.SAMPLE_RATE = 16000

            if self.CHANNELS not in (1, 2):
                logger.warning(
                    f"CHANNELS={self.CHANNELS} ist ungültig. Setze auf 1 (Mono)."
                )
                self.CHANNELS = 1
            self._cached_bytes_per_second = (
                self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
            )

        if self.ENABLE_DEBUG_LOGGING:
            if getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
                _safe_log_debug(
                    f"Config initialisiert: chunk={self.CHUNK_DURATION:.1f}s "
                    f"({self.CHUNK_SIZE_BYTES:,} bytes), "
                    f"sample_rate={self.SAMPLE_RATE}Hz, channels={self.CHANNELS}, "
                    f"overlap={self.CHUNK_OVERLAP:.1f}s ({self.OVERLAP_SIZE_BYTES:,} bytes), "
                    f"bytes_per_sec={self.BYTES_PER_SECOND:,}"
                )
            elif getattr(globals(), "DEBUG_LEVEL", 0) >= 1:
                _safe_log_debug(
                    f"Config: chunk={self.CHUNK_DURATION:.1f}s, "
                    f"sr={self.SAMPLE_RATE}Hz, ch={self.CHANNELS}"
                )

        # Einmalige Validierung der Konstanten (nur beim ersten Mal)
        if not getattr(Config, "_constants_validated", False):
            issues = Config.validate_constants()
            if issues:
                logger.error(
                    f"❌ ConfigDefaults enthält inkonsistente Konstanten: {', '.join(issues)}"
                )
                if getattr(globals(), "DEBUG_LEVEL", 0) >= 3:
                    _safe_log_debug(f"Validation issues details: {issues}")
            else:
                if getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
                    _safe_log_debug("✅ ConfigDefaults validation passed")
            Config._constants_validated = True

        # Warnungen bei fehlenden optionalen Abhängigkeiten
        if self.AUDIO_ENHANCEMENT_ENABLED and not self._is_scipy_available():
            logger.warning(
                "Audio-Enhancement ist aktiviert, aber scipy ist nicht installiert. "
                "Rauschunterdrückung wird nicht funktionieren."
            )

        if self.DUPLICATE_CHECK_ENABLED and not (
            self._is_scipy_available() or self._is_numpy_available()
        ):
            logger.warning(
                "Duplikatprüfung ist aktiviert, aber weder scipy noch numpy sind verfügbar. "
                "Die Ähnlichkeitsberechnung wird langsam sein."
            )

    @staticmethod
    def _is_scipy_available() -> bool:
        try:
            import importlib.util

            return importlib.util.find_spec("scipy") is not None
        except Exception:
            return False

    @staticmethod
    def _is_numpy_available() -> bool:
        try:
            import importlib.util

            return importlib.util.find_spec("numpy") is not None
        except Exception:
            return False

    def calculate_optimal_chunk_duration(
        self,
        model_size: str = "medium",
        is_realtime: bool = False,
        device: Optional[str] = None,
        compute_type: Optional[str] = None,
        use_dynamic: bool = True,
    ) -> float:
        """
        Berechnet die optimale Chunk-Dauer basierend auf Modell, Hardware und Echtzeit-Anforderung.
        """
        if is_realtime:
            min_dur = float(self.MIN_CHUNK_DURATION)
            if device == "cuda" and use_dynamic:
                duration = min(8.0, min_dur * 1.5)
            else:
                duration = min_dur
            if self.ENABLE_DEBUG_LOGGING and getattr(globals(), "DEBUG_LEVEL", 0) >= 3:
                _safe_log_debug(
                    f"Echtzeit-Modus: Chunk-Dauer = {duration:.1f}s (device={device})"
                )
            return duration

        model_lower = model_size.lower()
        base_model = model_lower.replace(".en", "")
        model_base = {
            "tiny": 3.0,
            "base": 4.0,
            "small": 5.0,
            "medium": 6.0,
            "large": 7.0,
            "large-v2": 7.0,
            "large-v3": 7.0,
            "large-v3-turbo": 5.0,
            "distil-large-v3": 4.0,
        }
        duration = model_base.get(base_model, 5.0)

        if use_dynamic:
            compute_factor = 1.0
            if compute_type == "int8":
                compute_factor = 1.2
            elif compute_type == "float16":
                compute_factor = 0.9
            elif compute_type == "float32":
                compute_factor = 0.7
            duration *= compute_factor

            device_factor = 1.0
            if device == "cuda":
                device_factor = 1.3
            elif device == "mps":
                device_factor = 1.1
            elif device == "cpu":
                device_factor = 0.8
            duration *= device_factor

        duration = max(self.MIN_CHUNK_DURATION, min(duration, self.MAX_CHUNK_DURATION))
        duration = round(duration * 2) / 2.0

        if self.ENABLE_DEBUG_LOGGING and getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
            _safe_log_debug(
                f"Optimale Chunk-Dauer für {model_size}: {duration:.1f}s "
                f"(realtime={is_realtime}, device={device}, compute={compute_type})"
            )
        return duration

    @classmethod
    def get_dynamic_max_memory(cls) -> int:
        """
        Ermittelt dynamisch die maximale Arbeitsspeichergrenze (75 % des verfügbaren RAM).

        Returns:
            Maximaler Speicher in Bytes.
        """
        try:
            import psutil

            mem = psutil.virtual_memory()
            limit = int(mem.total * 0.75)
            if getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
                _safe_log_debug(
                    f"Dynamisches Speicherlimit: {limit // (1024**2)} MB "
                    f"(75% von {mem.total // (1024**2)} MB)"
                )
            return limit
        except ImportError:
            if getattr(globals(), "DEBUG_LEVEL", 0) >= 1:
                _safe_log_debug(
                    "psutil nicht verfügbar – verwende Standard-Speicherlimit"
                )
            return cls.MAX_MEMORY_USAGE

    def validate_config(self) -> bool:
        """
        Validiert die aktuelle Konfiguration auf Konsistenz.
        """
        try:
            valid = (
                self.SAMPLE_RATE in [8000, 16000, 22050, 44100, 48000]
                and self.CHANNELS in [1, 2]
                and self.MIN_CHUNK_DURATION
                <= self.CHUNK_DURATION
                <= self.MAX_CHUNK_DURATION
                and 0.0 <= self.CHUNK_OVERLAP < self.CHUNK_DURATION
            )
            if not valid and self.ENABLE_DEBUG_LOGGING:
                logger.warning("Config-Validierung fehlgeschlagen")
            return valid
        except Exception as e:
            logger.error(f"Config-Validierung Ausnahme: {e}")
            return False

    def print_summary(
        self, verbose: bool = False, return_str: bool = False
    ) -> Optional[str]:
        """
        Gibt eine übersichtliche Zusammenfassung der wichtigsten Konfigurationswerte aus.

        Args:
            verbose: Wenn True, werden zusätzliche Details (VAD, Caches, Overlap, Plattform) angezeigt.
            return_str: Wenn True, wird der Zusammenfassungstext als String zurückgegeben,
                        anstatt ihn über logger.info auszugeben.

        Returns:
            Optional[str]: Bei return_str=True den formatierten Text, sonst None.
        """
        lines = []
        lines.append("=" * 60)
        lines.append("🎵 CONFIGURATION SUMMARY")
        lines.append("=" * 60)

        # ── Basis-Audio-Parameter ──────────────────────────────────────────
        lines.append(
            f"📊 Audio:        {self.SAMPLE_RATE} Hz, {self.CHANNELS} channel(s)"
        )
        lines.append(
            f"📦 Chunk:        {self.CHUNK_DURATION:.1f} s ({self.CHUNK_SIZE_BYTES:,} bytes)"
        )
        if verbose:
            lines.append(
                f"   Overlap:      {self.CHUNK_OVERLAP:.1f} s ({self.OVERLAP_SIZE_BYTES:,} bytes)"
            )
            lines.append(
                f"   Min/Max:      {self.MIN_CHUNK_DURATION:.1f} s / {self.MAX_CHUNK_DURATION:.1f} s"
            )
        lines.append(f"⚡ Bytes/sec:    {self.BYTES_PER_SECOND:,}")
        lines.append(f"🎛️ Filter:       {self.AUDIO_FILTER}")

        # ── Zusätzliche Audio-Einstellungen (nur bei verbose) ──────────────
        if verbose:
            lines.append(
                f"🎚️ Audio Enhancement: {'ON' if getattr(self, 'AUDIO_ENHANCEMENT_ENABLED', False) else 'OFF'}"
            )
            lines.append(
                f"🔇 VAD Filter:         {'ON' if getattr(self, 'ENABLE_VAD_FILTER', False) else 'OFF'}"
            )
            if getattr(self, "ENABLE_VAD_FILTER", False):
                lines.append(
                    f"   VAD Threshold:     {getattr(self, 'VAD_THRESHOLD', 0.25):.2f}"
                )
                lines.append(
                    f"   Min Speech (ms):   {getattr(self, 'VAD_MIN_SPEECH_DURATION_MS', 225)}"
                )
                lines.append(
                    f"   Min Silence (ms):  {getattr(self, 'VAD_MIN_SILENCE_DURATION_MS', 80)}"
                )

        # ── Performance & Caching ───────────────────────────────────────────
        lines.append(
            f"💾 Cache:        {'ON' if getattr(self, 'CACHE_ENABLED', True) else 'OFF'}"
        )
        if verbose:
            lines.append(
                f"   Max Cache Size: {getattr(self, 'MAX_CACHE_SIZE', 500)} entries"
            )
            lines.append(
                f"   TTL:            {getattr(self, 'TRANSCRIPTION_CACHE_TTL', 300)} s"
            )
        lines.append(
            f"🔄 Duplicate Check: {'ON' if getattr(self, 'DUPLICATE_CHECK_ENABLED', False) else 'OFF'}"
        )

        # ── Stream / Netzwerk (nur bei verbose) ────────────────────────────
        if verbose:
            lines.append(f"🌐 Stream Timeout: {getattr(self, 'STREAM_TIMEOUT', 25)} s")
            lines.append(
                f"🔁 Max Reconnects: {getattr(self, 'MAX_STREAM_RECONNECTS', 5)}"
            )
            lines.append(
                f"📥 Initial Buffer: {getattr(self, 'INITIAL_BUFFER_SECONDS', 2.0):.1f} s"
            )

            # Plattform-spezifische Konfiguration (falls vorhanden)
            if hasattr(self, "PLATFORM_CONFIG"):
                platform = SYSTEM.lower()
                plat_cfg = self.PLATFORM_CONFIG.get(platform, {})
                if plat_cfg:
                    flags = plat_cfg.get("ffmpeg_flags", [])
                    lines.append(
                        f"🖥️ Platform:      {platform} (FFmpeg flags: {flags})"
                    )

        # ── Validierungsstatus ──────────────────────────────────────────────
        valid = self.validate_config()
        lines.append(f"✅ Valid:         {'YES' if valid else 'NO'}")
        if not valid and verbose:
            issues = []
            if self.CHUNK_DURATION < self.MIN_CHUNK_DURATION:
                issues.append(f"Chunk < min ({self.MIN_CHUNK_DURATION:.1f}s)")
            if self.CHUNK_DURATION > self.MAX_CHUNK_DURATION:
                issues.append(f"Chunk > max ({self.MAX_CHUNK_DURATION:.1f}s)")
            if self.CHUNK_OVERLAP >= self.CHUNK_DURATION:
                issues.append("Overlap >= Chunk")
            if self.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
                issues.append(f"Sample rate {self.SAMPLE_RATE} not standard")
            if self.CHANNELS not in (1, 2):
                issues.append(f"Channels {self.CHANNELS} invalid")
            if issues:
                lines.append("   Issues: " + "; ".join(issues))

        lines.append("=" * 60)

        output = "\n".join(lines)

        if return_str:
            return output
        else:
            logger.info(output)
            return None

    def reset_to_defaults(self) -> None:
        """Setzt alle dynamischen Werte auf die Standardwerte aus ConfigDefaults zurück."""
        self._base_chunk_duration = ConfigDefaults.BASE_CHUNK_DURATION
        self.CHUNK_OVERLAP = ConfigDefaults.CHUNK_OVERLAP
        self.MIN_CHUNK_DURATION = ConfigDefaults.MIN_CHUNK_DURATION
        self.MAX_CHUNK_DURATION = ConfigDefaults.MAX_CHUNK_DURATION
        self.CHUNK_DURATION = ConfigDefaults.BASE_CHUNK_DURATION
        self.AUDIO_ENHANCEMENT_ENABLED = False
        self.DUPLICATE_CHECK_ENABLED = False
        self.CACHE_ENABLED = ConfigDefaults.CACHE_ENABLED
        if self.ENABLE_DEBUG_LOGGING:
            _safe_log_debug("Config auf Standardwerte zurückgesetzt")

    def get_debug_info(self) -> Dict[str, Any]:
        """
        Sammelt detaillierte Debug-Informationen über die aktuelle Konfiguration.

        Returns:
            Dictionary mit allen relevanten Werten (für Diagnosezwecke).
        """
        return {
            "sample_rate": self.SAMPLE_RATE,
            "channels": self.CHANNELS,
            "chunk_duration": self.CHUNK_DURATION,
            "chunk_size_bytes": self.CHUNK_SIZE_BYTES,
            "bytes_per_second": self.BYTES_PER_SECOND,
            "min_chunk_duration": self.MIN_CHUNK_DURATION,
            "max_chunk_duration": self.MAX_CHUNK_DURATION,
            "audio_filter": self.AUDIO_FILTER,
            "audio_enhancement": self.AUDIO_ENHANCEMENT_ENABLED,
            "duplicate_check": self.DUPLICATE_CHECK_ENABLED,
            "cache_enabled": self.CACHE_ENABLED,
            "max_cache_mb": self.MAX_CACHE_SIZE_MB,
            "whisper_models": self.WHISPER_MODELS,
            "vad_threshold": self.VAD_THRESHOLD,
            "valid": self.validate_config(),
        }


# =============================================================================
# 3. Vordefinierte Config-Profile
# =============================================================================
class RealtimeConfig(Config):
    """
    Konfiguration für Echtzeit-Transkription mit minimaler Latenz.

    Optimiert für kurze Antwortzeiten, weniger CPU‑Verbrauch und
    reduzierte Überlappung, um die Verarbeitungsdauer pro Chunk
    so gering wie möglich zu halten.
    """

    def __init__(self) -> None:
        super().__init__()
        self.CHUNK_DURATION = 5.0
        self.CHUNK_OVERLAP = 0.1
        self.STREAM_TIMEOUT = 5
        self.AUDIO_FILTER = "aresample=16000"
        self.AUDIO_ENHANCEMENT_ENABLED = False
        self.DUPLICATE_CHECK_ENABLED = False
        self.MAX_CONSECUTIVE_ERRORS = 3
        self.FFMPEG_THREADS = 1
        self.FFMPEG_BUFSIZE = "256k"
        self.FFMPEG_PROBESIZE = "16"
        self.FFMPEG_ANALYZE_DURATION = "0"


class HighAccuracyConfig(Config):
    """
    Konfiguration für höchste Transkriptionsgenauigkeit bei geringerem Zeitdruck.

    Diese Einstellungen priorisieren die Erkennungsqualität gegenüber der
    Geschwindigkeit.  Sie sind ideal für die Offline‑Verarbeitung von
    aufgezeichnetem Material (Podcasts, Vorträge, Hörbücher).
    """

    def __init__(self) -> None:
        super().__init__()
        self.CHUNK_DURATION = 25.0
        self.CHUNK_OVERLAP = 0.8
        self.AUDIO_FILTER = (
            "aresample=16000,"
            "volume=1.8,"
            "highpass=f=80,"
            "lowpass=f=3800,"
            "dynaudnorm=p=0.3:s=3:g=20"
        )
        self.AUDIO_ENHANCEMENT_ENABLED = True
        self.DUPLICATE_CHECK_ENABLED = True
        self.MAX_CONSECUTIVE_ERRORS = 10
        self.FFMPEG_BUFSIZE = "4096k"
        self.STREAM_TIMEOUT = 60


class YouTubeOptimizedConfig(Config):
    """
    Speziell auf YouTube‑Streams abgestimmte Konfiguration.

    Diese Einstellungen berücksichtigen die besonderen Eigenschaften von
    YouTube‑Livestreams und Video‑on‑Demand:

    * Kürzere Timeouts für eine schnellere Fehlererkennung.
    * Erhöhte Wiederholungsversuche, um auch bei instabilen Verbindungen
      das Audio zuverlässig zu extrahieren.
    * Aggressives Reconnect‑Verhalten mit kurzer Verzögerung.
    * Ein auf YouTube optimierter Audio‑Filter mit sanfter Dynamik‑
      Kompression und leichter Anhebung der Sprachfrequenzen.
    * Kein zusätzliches Audio‑Enhancement, um CPU‑Last zu sparen.
    """

    def __init__(self) -> None:
        super().__init__()
        self.FFMPEG_THREADS = 1
        self.FFMPEG_BUFSIZE = "2048k"
        self.YOUTUBE_TIMEOUT = 10_000_000
        self.RECONNECT_DELAY = 0.5
        self.YOUTUBE_URL_REFRESH_INTERVAL = 300
        self.MAX_REFRESH_ATTEMPTS = 8
        self.STREAM_TIMEOUT = 20
        self.AUDIO_FILTER = (
            "aresample=16000,"
            "volume=1.8,"
            "highpass=f=80,"
            "lowpass=f=3400,"
            "compand=attacks=0.01:decays=0.2:points=-80/-80|-45/-15|-27/-9|0/-7|20/-7"
        )
        self.AUDIO_ENHANCEMENT_ENABLED = False


# =============================================================================
# 4. Factory-Funktion get_config
# =============================================================================
def get_config(config_type: str = "default") -> Config:
    """
    Erzeugt und liefert eine Config‑Instanz für den angegebenen Konfigurationstyp.

    Unterstützte Typen:
        - ``"default"``            → Standard‑Konfiguration
        - ``"realtime"``           → Minimale Latenz (Echtzeit)
        - ``"high_accuracy"``      → Maximale Genauigkeit (Offline)
        - ``"youtube"``            → YouTube‑optimiert

    Bei einem unbekannten Typ wird die Standard‑Konfiguration verwendet
    und eine Warnung ausgegeben.  Die erzeugte Instanz wird automatisch
    validiert; falls die Validierung fehlschlägt, wird versucht, die
    Konfiguration zu reparieren.
    """
    configs = {
        "default": Config,
        "realtime": RealtimeConfig,
        "high_accuracy": HighAccuracyConfig,
        "youtube": YouTubeOptimizedConfig,
    }

    config_class = configs.get(config_type)
    if config_class is None:
        logger.warning(
            "⚠️ Unbekannter config_type '%s' – verwende 'default'.", config_type
        )
        config_class = Config

    try:
        config = config_class()
    except Exception as exc:
        logger.error(
            "❌ Fehler beim Erstellen der Konfiguration '%s': %s – "
            "verwende Standard‑Config.",
            config_type,
            exc,
        )
        config = Config()

    # Validierung und ggf. Reparatur
    if not config.validate_config():
        logger.warning(
            "Config '%s' ist inkonsistent – versuche Reparatur …",
            config_class.__name__,
        )
        # Direkte Korrektur
        if config.CHUNK_DURATION < config.MIN_CHUNK_DURATION:
            config.CHUNK_DURATION = config.MIN_CHUNK_DURATION
        if config.CHUNK_DURATION > config.MAX_CHUNK_DURATION:
            config.CHUNK_DURATION = config.MAX_CHUNK_DURATION
        if config.CHUNK_OVERLAP >= config.CHUNK_DURATION:
            config.CHUNK_OVERLAP = max(0.0, config.CHUNK_DURATION * 0.1)
        if config.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            config.SAMPLE_RATE = 16000
        if config.CHANNELS not in (1, 2):
            config.CHANNELS = 1

        if not config.validate_config():
            logger.error(
                "❌ Konnte Config '%s' nicht reparieren – verwende "
                "absolute Notfall‑Defaults.",
                config_class.__name__,
            )
            config = Config()
    else:
        if getattr(globals(), "DEBUG_LEVEL", 0) >= 2:
            _safe_log_debug(
                f"Config '{config_class.__name__}' erfolgreich erstellt und validiert "
                f"(chunk={config.CHUNK_DURATION:.1f}s, sr={config.SAMPLE_RATE}Hz, "
                f"ch={config.CHANNELS})"
            )

    return config


# =============================================================================
# 5. FastLazyLoader – optimierter, thread-sicherer Lazy-Loader
# =============================================================================
class FastLazyLoader:
    """
    Thread‑sicherer Lazy‑Loader für Module mit Caching und Verfügbarkeitsprüfung.

    Verbesserungen gegenüber der Basisversion:
    - Cache für erfolgreiche und fehlgeschlagene Importe (mit TTL).
    - Spezielle Handler für häufig genutzte Module (torch, faster-whisper, numpy, etc.).
    - Thread-sicher durch Verwendung von RLock und individuellen Locks pro Modul.
    - Metriken (Cache-Hits, Ladeversuche, Fehler) optional.
    - Mock-Modul bei Importfehlern gibt aussagekräftige Fehlermeldungen.
    """

    _loaded_modules: Dict[str, Any] = {}
    _module_locks: Dict[str, threading.Lock] = {}
    _global_lock = threading.Lock()
    _availability_cache: Dict[str, Tuple[bool, float]] = {}
    _availability_cache_ttl: float = 60.0
    _metrics_enabled: bool = False
    _metrics: Dict[str, Any] = {
        "load_attempts": 0,
        "load_success": 0,
        "load_failures": 0,
        "cache_hits": 0,
        "availability_checks": 0,
    }
    _metrics_lock = threading.RLock()
    _cache_lock = threading.RLock()
    _logger = logging.getLogger("dragon")

    @classmethod
    def configure(
        cls,
        *,
        availability_cache_ttl: Optional[float] = None,
        enable_metrics: bool = False,
    ) -> None:
        """
        Konfiguriert globale Parameter.
        """
        if availability_cache_ttl is not None:
            cls._availability_cache_ttl = availability_cache_ttl
        cls._metrics_enabled = enable_metrics
        cls._logger.debug(
            "FastLazyLoader configured: ttl=%ss, metrics=%s",
            cls._availability_cache_ttl,
            enable_metrics,
            extra={"component": "loader"},
        )

    @classmethod
    def _get_lock(cls, module_name: str) -> threading.Lock:
        """Gibt ein Lock für das Modul zurück (erzeugt eines, falls nicht vorhanden)."""
        with cls._global_lock:
            if module_name not in cls._module_locks:
                cls._module_locks[module_name] = threading.Lock()
            return cls._module_locks[module_name]

    @classmethod
    def _cleanup_availability_cache(cls) -> None:
        """Entfernt abgelaufene Einträge aus dem Verfügbarkeits‑Cache."""
        now = time.time()
        with cls._cache_lock:
            expired = [
                k
                for k, (_, ts) in cls._availability_cache.items()
                if now - ts > cls._availability_cache_ttl
            ]
            for k in expired:
                del cls._availability_cache[k]
                if cls._metrics_enabled:
                    cls._logger.debug(
                        "Removed expired availability entry for %s",
                        k,
                        extra={"component": "loader"},
                    )

    @classmethod
    def load(
        cls, module_name: str, import_paths: Union[str, List[str], None] = None
    ) -> Any:
        """
        Lädt ein Modul (lazy) und gibt es zurück.

        Args:
            module_name: Name des Moduls (z.B. "torch").
            import_paths: Optionaler Import-Pfad (oder Liste) – falls angegeben,
                          wird zuerst dieser Pfad versucht.

        Returns:
            Das geladene Modul oder ein Mock-Modul bei Importfehlern.
        """
        # ── Schneller Lese‑Pfad (Cache) ─────────────────────────────────────
        with cls._global_lock:
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                mod = cls._loaded_modules[module_name]
                # Mock-Modul trotzdem zurückgeben – der Aufrufer muss mit ImportError rechnen
                return mod

        # ── Schreib‑Pfad (mit modul‑spezifischem Lock) ──────────────────────
        lock = cls._get_lock(module_name)
        with lock:
            # Double-Check nach Lock-Erwerb
            if module_name in cls._loaded_modules:
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics["cache_hits"] += 1
                return cls._loaded_modules[module_name]

            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_attempts"] += 1

            # Spezielle Lade‑Handler für kritische Module
            special_handlers = {
                "torch": cls._load_torch,
                "faster_whisper": cls._load_faster_whisper,
                "numpy": cls._load_numpy,
                "deep_translator": cls._load_deep_translator,
                "scipy.signal": cls._load_scipy_signal,
            }

            if module_name in special_handlers:
                try:
                    module = special_handlers[module_name]()
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s via special handler",
                        module_name,
                        extra={"component": "loader"},
                    )
                    return module
                except ImportError as e:
                    cls._logger.debug(
                        "Special handler for %s failed: %s",
                        module_name,
                        e,
                        extra={"component": "loader"},
                    )

            # Standard‑Import‑Pfad durchprobieren
            if import_paths is None:
                paths = [module_name]
            elif isinstance(import_paths, str):
                paths = [import_paths]
            else:
                paths = import_paths

            last_error = None
            for path in paths:
                try:
                    module = importlib.import_module(path)
                    cls._loaded_modules[module_name] = module
                    if cls._metrics_enabled:
                        with cls._metrics_lock:
                            cls._metrics["load_success"] += 1
                    cls._logger.debug(
                        "Loaded %s from %s",
                        module_name,
                        path,
                        extra={"component": "loader"},
                    )
                    return module
                except ImportError as e:
                    last_error = e
                    continue

            # Kein Import möglich – Mock‑Modul zurückgeben
            cls._logger.debug(
                "Module %s not available: %s",
                module_name,
                last_error,
                extra={"component": "loader"},
            )
            if cls._metrics_enabled:
                with cls._metrics_lock:
                    cls._metrics["load_failures"] += 1

            # Mock-Modul – gibt beim ersten Zugriff eine Warnung aus
            class MockModule:
                _is_mock = True
                __name__ = module_name
                _warned: bool = False

                def __getattr__(self, name: str) -> Any:
                    if not MockModule._warned:
                        MockModule._warned = True
                        logging.getLogger("dragon").warning(
                            "⚠️ Zugriff auf Mock-Modul '%s' – "
                            "die eigentliche Bibliothek ist nicht installiert. "
                            "Funktionen werden fehlschlagen.",
                            module_name,
                        )
                    raise ImportError(f"Module {module_name} not available")

            mock = MockModule()
            cls._loaded_modules[module_name] = mock
            return mock

    @classmethod
    def _load_torch(cls):
        import torch

        try:
            import torch._logging

            torch._logging.set_logs(all=logging.ERROR)
        except Exception:
            pass
        return torch

    @classmethod
    def _load_faster_whisper(cls):
        """Lädt die faster-whisper Bibliothek und gibt die WhisperModel-Klasse zurück."""
        import os

        os.environ.setdefault("CT2_VERBOSE", "0")
        from faster_whisper import WhisperModel

        if cls._logger.isEnabledFor(logging.DEBUG):
            try:
                import faster_whisper

                version = getattr(faster_whisper, "__version__", "unknown")
                cls._logger.debug(
                    "faster-whisper version %s geladen",
                    version,
                    extra={"component": "loader"},
                )
            except Exception:
                pass
        return WhisperModel

    @classmethod
    def _load_numpy(cls):
        import numpy as np

        return np

    @classmethod
    def _load_deep_translator(cls):
        from deep_translator import GoogleTranslator

        return GoogleTranslator

    @classmethod
    def _load_scipy_signal(cls):
        import scipy.signal

        return scipy.signal

    @classmethod
    def is_available(cls, module_name: str, use_cache: bool = True) -> bool:
        """
        Prüft, ob ein Modul verfügbar ist (durch Suchpfad).
        """
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics["availability_checks"] += 1

        # Bereits (erfolgreich) geladen?
        if module_name in cls._loaded_modules:
            mod = cls._loaded_modules[module_name]
            return not getattr(mod, "_is_mock", False)

        # Cache prüfen (mit TTL)
        if use_cache:
            cls._cleanup_availability_cache()
            with cls._cache_lock:
                cached = cls._availability_cache.get(module_name)
                if cached is not None:
                    return cached[0]

        # Tatsächlich prüfen
        spec = importlib.util.find_spec(module_name)
        available = spec is not None

        if use_cache:
            with cls._cache_lock:
                cls._availability_cache[module_name] = (available, time.time())

        cls._logger.debug(
            "Availability check for %s: %s",
            module_name,
            available,
            extra={"component": "loader"},
        )
        return available

    @classmethod
    def clear_cache(cls, module_name: Optional[str] = None) -> None:
        """
        Leert den Modul‑Cache und den Verfügbarkeits‑Cache.
        """
        with cls._global_lock:
            if module_name is None:
                cls._loaded_modules.clear()
                cls._module_locks.clear()
                cls._availability_cache.clear()
                if cls._metrics_enabled:
                    with cls._metrics_lock:
                        cls._metrics = {
                            "load_attempts": 0,
                            "load_success": 0,
                            "load_failures": 0,
                            "cache_hits": 0,
                            "availability_checks": 0,
                        }
                cls._logger.debug("All caches cleared", extra={"component": "loader"})
            else:
                if module_name in cls._loaded_modules:
                    del cls._loaded_modules[module_name]
                if module_name in cls._module_locks:
                    del cls._module_locks[module_name]
                with cls._cache_lock:
                    if module_name in cls._availability_cache:
                        del cls._availability_cache[module_name]
                cls._logger.debug(
                    "Cache cleared for module %s",
                    module_name,
                    extra={"component": "loader"},
                )

    @classmethod
    def get_metrics(cls) -> Dict[str, Any]:
        """Gibt die gesammelten Metriken zurück (leeres Dict, wenn Metriken deaktiviert)."""
        if not cls._metrics_enabled:
            return {}
        with cls._metrics_lock:
            return cls._metrics.copy()

    @classmethod
    def reset_metrics(cls) -> None:
        """Setzt die Metriken zurück (nur wenn Metriken aktiviert)."""
        if cls._metrics_enabled:
            with cls._metrics_lock:
                cls._metrics = {
                    "load_attempts": 0,
                    "load_success": 0,
                    "load_failures": 0,
                    "cache_hits": 0,
                    "availability_checks": 0,
                }
            cls._logger.debug("Metrics reset", extra={"component": "loader"})


# =============================================================================
# 6. GPUStats – Einfacher Wrapper für pynvml
# =============================================================================
class GPUStats:
    """
    Singleton‑artige Hilfsklasse für einmalige Initialisierung von pynvml.
    Stellt den GPU‑Handle und grundlegende Funktionen bereit.
    """

    _initialized = False
    _nvml_handle = None
    _nvml_available = False
    _lock = threading.Lock()

    @classmethod
    def _ensure_initialized(cls):
        """Initialisiert pynvml genau einmal (threadsicher)."""
        if cls._initialized:
            return
        with cls._lock:
            if cls._initialized:
                return
            try:
                import pynvml

                pynvml.nvmlInit()
                cls._nvml_handle = pynvml.nvmlDeviceGetHandleByIndex(0)
                cls._nvml_available = True
            except (ImportError, pynvml.NVMLError) as e:
                _safe_log_debug(f"pynvml nicht verfügbar: {e}")
                cls._nvml_available = False
            finally:
                cls._initialized = True

    @classmethod
    def is_available(cls) -> bool:
        """Gibt zurück, ob pynvml erfolgreich initialisiert wurde."""
        cls._ensure_initialized()
        return cls._nvml_available

    @classmethod
    def get_temperature(cls) -> Optional[int]:
        """Aktuelle GPU‑Temperatur in °C oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetTemperature(
                cls._nvml_handle, pynvml.NVML_TEMPERATURE_GPU
            )
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_utilization(cls) -> Optional[int]:
        """GPU‑Auslastung in Prozent oder None bei Fehler."""
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            return pynvml.nvmlDeviceGetUtilizationRates(cls._nvml_handle).gpu
        except pynvml.NVMLError:
            return None

    @classmethod
    def get_memory_info(cls) -> Optional[Dict[str, int]]:
        """
        Gibt ein Dictionary mit Informationen über den GPU‑Speicher zurück.
        Enthält 'total', 'free' und 'used' in Bytes, oder None bei Fehler.
        """
        cls._ensure_initialized()
        if not cls._nvml_available:
            return None
        try:
            import pynvml

            mem = pynvml.nvmlDeviceGetMemoryInfo(cls._nvml_handle)
            return {
                "total": mem.total,
                "free": mem.free,
                "used": mem.used,
            }
        except pynvml.NVMLError:
            return None


class PlatformStderrFilter:
    """
    Filtert unerwünschte Zeilen aus dem stderr‑Stream, die von
    Plattform‑Bibliotheken (Rockchip, GPU‑Treibern, Windows‑Console)
    stammen und im normalen Betrieb keine relevante Information liefern.

    Die Klasse ist thread‑sicher und kann Muster dynamisch hinzufügen oder
    entfernen. Sie kann auch aus einer Konfigurationsdatei laden und führt
    Statistiken über gefilterte Zeilen.

    Attributes:
        original_stderr: Das originale stderr‑Objekt (z.B. sys.stderr).
        enabled: Ob die Filterung aktiv ist (kann zur Laufzeit deaktiviert werden).
        filter_patterns: Liste der aktuell aktiven Teilstring‑Muster.
        compiled_patterns: Kompilierte Regex‑Objekte für effizienteres Matching (optional).
        stats: Dictionary mit Zählern (total_lines, filtered_lines, forwarded_lines, errors).
    """

    def __init__(self, original_stderr: Any, use_regex: bool = False) -> None:
        """
        Initialisiert den Filter.

        Args:
            original_stderr: Das originale stderr‑Objekt (muss `write` und `flush` unterstützen).
            use_regex: Ob die Muster als reguläre Ausdrücke behandelt werden sollen.
                       Falls False, werden einfache Teilstring‑Vergleiche verwendet.

        Raises:
            ValueError: Wenn `original_stderr` nicht die erforderlichen Methoden besitzt.
        """
        if not hasattr(original_stderr, "write") or not hasattr(
            original_stderr, "flush"
        ):
            raise ValueError("original_stderr muss write() und flush() unterstützen")

        self.original_stderr = original_stderr
        self._use_regex = use_regex
        self._lock = threading.RLock()
        self._enabled = True

        # Standardmuster (als rohe Strings)
        self._raw_patterns: List[str] = [
            "mpp_soc:",
            "mpp_platform:",
            "can not found match soc name",
            "/proc/device-tree/compatible",
            "rockchip",
            "ffmpeg",
            "TORCH_NCCL",
        ]

        # Windows‑spezifische Muster (falls globale Konstante existiert)
        try:
            if IS_WINDOWS:  # noqa: F821
                self._raw_patterns.extend(
                    [
                        "Failed to set direct console mode",
                        "Console code page",
                        "chcp",
                        "win32api",
                    ]
                )
        except NameError:
            pass  # IS_WINDOWS nicht definiert – überspringe

        # Kompilierte Muster (falls use_regex=True)
        self._compiled_patterns: List[re.Pattern] = []
        self._rebuild_patterns()

        # Statistik
        self._stats: Dict[str, int] = {
            "total_lines": 0,
            "filtered_lines": 0,
            "forwarded_lines": 0,
            "errors": 0,
        }
        self._stats_lock = threading.RLock()

    # -------------------------------------------------------------------------
    # Pattern‑Verwaltung
    # -------------------------------------------------------------------------
    def _rebuild_patterns(self) -> None:
        """(Neu‑)Kompilierung der Muster, wenn use_regex=True."""
        if self._use_regex:
            self._compiled_patterns = []
            for pattern in self._raw_patterns:
                try:
                    self._compiled_patterns.append(re.compile(pattern, re.IGNORECASE))
                except re.error as e:
                    logger.warning(  # noqa: F821
                        "stderr_filter",
                        f"Ungültiges Regex‑Muster '{pattern}': {e} – ignoriert",
                    )
        else:
            self._compiled_patterns = []

    def add_pattern(self, pattern: str) -> None:
        """
        Fügt ein neues Filtermuster hinzu.

        Args:
            pattern: Ein Teilstring oder ein regulärer Ausdruck (abhängig von use_regex).
        """
        if not pattern or not isinstance(pattern, str):
            logger.warning(  # noqa: F821
                "stderr_filter", f"add_pattern: ungültiges Muster '{pattern}' ignoriert"
            )
            return

        with self._lock:
            if pattern not in self._raw_patterns:
                self._raw_patterns.append(pattern)
                if self._use_regex:
                    try:
                        self._compiled_patterns.append(
                            re.compile(pattern, re.IGNORECASE)
                        )
                    except re.error as e:
                        logger.warning(  # noqa: F821
                            "stderr_filter",
                            f"Regex‑Fehler für '{pattern}': {e} – Muster wird nicht hinzugefügt",
                        )
                        # Rückgängig machen
                        self._raw_patterns.pop()
                        return
                _safe_log_debug(
                    "stderr_filter", f"Muster hinzugefügt: '{pattern}'"
                )  # noqa: F821

    def remove_pattern(self, pattern: str) -> bool:
        """
        Entfernt ein Filtermuster.

        Args:
            pattern: Das zu entfernende Muster.

        Returns:
            True, wenn das Muster gefunden und entfernt wurde, sonst False.
        """
        with self._lock:
            if pattern in self._raw_patterns:
                self._raw_patterns.remove(pattern)
                if self._use_regex:
                    self._rebuild_patterns()
                _safe_log_debug(
                    "stderr_filter", f"Muster entfernt: '{pattern}'"
                )  # noqa: F821
                return True
            return False

    def clear_patterns(self) -> None:
        """Entfernt alle Filtermuster."""
        with self._lock:
            self._raw_patterns.clear()
            self._compiled_patterns.clear()
            _safe_log_debug("stderr_filter", "Alle Muster entfernt")  # noqa: F821

    def set_patterns(self, patterns: List[str]) -> None:
        """
        Ersetzt die gesamte Musterliste durch eine neue Liste.

        Args:
            patterns: Neue Liste von Mustern.
        """
        with self._lock:
            self._raw_patterns = list(patterns)
            self._rebuild_patterns()
            _safe_log_debug(  # noqa: F821
                "stderr_filter", f"Musterliste ersetzt ({len(patterns)} Einträge)"
            )

    def get_patterns(self) -> List[str]:
        """Gibt eine Kopie der aktuellen Musterliste zurück."""
        with self._lock:
            return self._raw_patterns.copy()

    # -------------------------------------------------------------------------
    # Laden aus Konfigurationsdatei (verbessert)
    # -------------------------------------------------------------------------
    def load_from_config(self, config_file: Optional[str] = None) -> int:
        """
        Lädt zusätzliche Filter‑Muster aus einer Textdatei.
    
        Die Datei sollte ein Muster pro Zeile enthalten. Leerzeilen und
        Zeilen, die mit '#' beginnen, werden ignoriert.

        Args:
            config_file: Pfad zur Konfigurationsdatei. Falls None, wird die
                         Umgebungsvariable DRAGON_STDERR_FILTER_FILE verwendet,
                         andernfalls ein Standardpfad im Konfigurationsverzeichnis.
    
        Returns:
            Anzahl der erfolgreich geladenen Muster.
        """
        # 1. Pfad bestimmen
        if config_file is None:
            config_file = os.environ.get("DRAGON_STDERR_FILTER_FILE", "").strip()
            if not config_file:
                try:
                    from .platform_utils import PlatformUtils
                    config_dir = PlatformUtils.get_platform_config_dir()
                except Exception:
                    logger.debug("Kann Konfigurationsverzeichnis nicht ermitteln – überspringe.")
                    return 0
                config_file = str(config_dir / "stderr_filters.txt")

        # 2. Datei einlesen
        try:
            with open(config_file, "r", encoding="utf-8") as f:
                lines = f.readlines()
        except FileNotFoundError:
            logger.debug("Filter‑Datei '%s' nicht gefunden.", config_file)
            return 0
        except (PermissionError, OSError) as e:
            logger.warning("Fehler beim Lesen von '%s': %s", config_file, e)
            return 0
        except Exception as e:
            logger.warning("Unerwarteter Fehler beim Lesen von '%s': %s", config_file, e)
            return 0

        # 3. Muster parsen und hinzufügen
        added = 0
        with self._lock:
            for line in lines:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if line not in self._raw_patterns:
                    self._raw_patterns.append(line)
                    added += 1
            if self._use_regex:
                self._rebuild_patterns()

        if added > 0:
            logger.info("%d Muster aus '%s' geladen.", added, config_file)
        else:
            logger.debug("Keine neuen Muster in '%s' gefunden.", config_file)
        return added
    
    # -------------------------------------------------------------------------
    # Filterung und Weiterleitung
    # -------------------------------------------------------------------------
    @property
    def enabled(self) -> bool:
        """Gibt zurück, ob die Filterung aktiv ist."""
        with self._lock:
            return self._enabled

    @enabled.setter
    def enabled(self, value: bool) -> None:
        """Aktiviert oder deaktiviert die Filterung."""
        with self._lock:
            self._enabled = bool(value)

    def write(self, text: str) -> None:
        """
        Schreibt *text* nur dann nach stderr, wenn er kein Filter‑Muster enthält.
        """
        if not text:
            return

        with self._stats_lock:
            self._stats["total_lines"] += 1

        if not self._enabled:
            self._forward(text)
            return

        # Musterprüfung (unter Lock, um konsistente Musterliste zu haben)
        with self._lock:
            patterns = self._raw_patterns
            compiled = self._compiled_patterns

        # Prüfen, ob der Text eines der Muster enthält
        if self._use_regex:
            matched = any(p.search(text) for p in compiled)
        else:
            matched = any(p in text for p in patterns)

        if matched:
            with self._stats_lock:
                self._stats["filtered_lines"] += 1
            return

        self._forward(text)

    def _forward(self, text: str) -> None:
        """Leitet den Text ungefiltert an das originale stderr weiter."""
        try:
            self.original_stderr.write(text)
            with self._stats_lock:
                self._stats["forwarded_lines"] += 1
        except Exception as e:
            with self._stats_lock:
                self._stats["errors"] += 1
            logger.warning("Fehler beim Weiterleiten an stderr: %s", e)

    def flush(self) -> None:
        """Leitet flush() an das originale stderr‑Objekt weiter."""
        self.original_stderr.flush()

    # -------------------------------------------------------------------------
    # Statistik
    # -------------------------------------------------------------------------
    def get_stats(self) -> Dict[str, int]:
        """
        Gibt eine Kopie der aktuellen Statistiken zurück.

        Returns:
            Dictionary mit total_lines, filtered_lines, forwarded_lines, errors.
        """
        with self._stats_lock:
            return self._stats.copy()

    def reset_stats(self) -> None:
        """Setzt alle Statistik‑Zähler auf Null zurück."""
        with self._stats_lock:
            for key in self._stats:
                self._stats[key] = 0

    # -------------------------------------------------------------------------
    # Kontextmanager für temporäre Deaktivierung
    # -------------------------------------------------------------------------
    @contextlib.contextmanager
    def disabled(self):
        """
        Kontextmanager, der die Filterung temporär deaktiviert.

        Beispiel:
            with stderr_filter.disabled():
                # Hier werden alle Zeilen weitergeleitet
                print("Debug", file=sys.stderr)
        """
        old = self.enabled
        self.enabled = False
        try:
            yield
        finally:
            self.enabled = old

    # -------------------------------------------------------------------------
    # Darstellung
    # -------------------------------------------------------------------------
    def __repr__(self) -> str:
        with self._lock:
            patterns_count = len(self._raw_patterns)
        with self._stats_lock:
            filtered = self._stats.get("filtered_lines", 0)
        return (
            f"<PlatformStderrFilter patterns={patterns_count} "
            f"enabled={self._enabled} filtered={filtered}>"
        )


# -----------------------------------------------------------------------------
# Logging-Helfer (sichere Fallbacks)
# -----------------------------------------------------------------------------


def _get_log_debug_impl():
    """Holt die `log_debug`‑Funktion aus dem Hauptmodul (einmalig, mit Cache)."""
    global _LOG_DEBUG_IMPL
    if _LOG_DEBUG_IMPL is not None:
        return _LOG_DEBUG_IMPL
    with _IMPORT_LOCK:
        if _LOG_DEBUG_IMPL is not None:
            return _LOG_DEBUG_IMPL
        try:
            from dragon_whisperer import log_debug

            _LOG_DEBUG_IMPL = log_debug
        except (ImportError, NameError, AttributeError):
            _LOG_DEBUG_IMPL = None
        return _LOG_DEBUG_IMPL


def _get_log_exception_impl():
    """Holt die `log_exception`‑Funktion aus dem Hauptmodul (einmalig, mit Cache)."""
    global _LOG_EXCEPTION_IMPL
    if _LOG_EXCEPTION_IMPL is not None:
        return _LOG_EXCEPTION_IMPL
    with _IMPORT_LOCK:
        if _LOG_EXCEPTION_IMPL is not None:
            return _LOG_EXCEPTION_IMPL
        try:
            from dragon_whisperer import log_exception

            _LOG_EXCEPTION_IMPL = log_exception
        except (ImportError, NameError, AttributeError):
            _LOG_EXCEPTION_IMPL = None
        return _LOG_EXCEPTION_IMPL


def _safe_log_debug(
    component_or_msg: str,
    msg: Optional[str] = None,
    *args: Any,
    **kwargs: Any,
) -> None:
    """
    Protokolliert eine Debug‑Meldung mit optionalem Komponenten‑Kontext.

    Die Funktion ist so flexibel, dass sie sowohl mit zwei Argumenten
    (component, msg) als auch mit nur einem Argument (msg) aufgerufen werden kann.
    Im letzteren Fall wird die Komponente auf "default" gesetzt.

    Args:
        component_or_msg: Entweder der Komponentenname ODER die Nachricht.
        msg: Wenn angegeben, die Nachricht (dann ist component_or_msg die Komponente).
        *args: Weitere Format‑Argumente.
        **kwargs: Zusätzliche Schlüsselwort‑Argumente für den Logger.
    """
    # ── 1. Parameter normalisieren ──────────────────────────────────
    if msg is None:
        component = "default"
        message = component_or_msg
    else:
        component = component_or_msg
        message = msg

    # ── 2. Versuche die zentrale Implementierung ────────────────────
    impl = _get_log_debug_impl()
    if impl is not None:
        impl(component, message, *args, **kwargs)
        return

    # ── 3. Fallback: eigenes Logging mit Prüfung der Debug‑Flags ──
    try:
        debug_level = globals().get("DEBUG_LEVEL", 0)
        debug_components = globals().get("DEBUG_COMPONENTS", [])
    except Exception:
        debug_level = 0
        debug_components = []

    if debug_level >= 3 or component in debug_components:
        logger = logging.getLogger("dragon")
        logger.debug(message, *args, extra={"component": component}, **kwargs)


def _safe_log_exception(
    component_or_msg: str,
    msg: Optional[str] = None,
    exc: Optional[Exception] = None,
    level: str = "error",
    **kwargs: Any,
) -> None:
    """
    Protokolliert eine Exception mit optionalem Komponenten‑Kontext.

    Flexible Signatur: Sowohl `(component, msg, exc)` als auch `(msg, exc)` sind
    möglich. Im letzteren Fall wird die Komponente auf "default" gesetzt.

    Args:
        component_or_msg: Entweder Komponentenname ODER Fehlermeldung.
        msg: Wenn angegeben, die Fehlermeldung (dann ist component_or_msg die Komponente).
        exc: Die Exception (optional, wird mit exc_info=True ausgegeben).
        level: Schweregrad ("error", "warning", "debug").
        **kwargs: Zusätzliche Argumente für den Logger.
    """
    # ── 1. Parameter normalisieren ──────────────────────────────────
    if msg is None:
        # Nur zwei Argumente? Dann ist das erste die Nachricht, das zweite die Exception
        if exc is not None:
            component = "default"
            message = component_or_msg
            # exc bleibt wie übergeben
        else:
            # Nur ein Argument: Fehlermeldung ohne Exception
            component = "default"
            message = component_or_msg
            exc = None
    else:
        # Drei Argumente: (component, message, exc)
        component = component_or_msg
        message = msg
        # exc wurde als dritter Parameter übergeben (oder ist None)

    # ── 2. Versuche die zentrale Implementierung ────────────────────
    impl = _get_log_exception_impl()
    if impl is not None:
        impl(component, message, exc, level, **kwargs)
        return

    # ── 3. Fallback ─────────────────────────────────────────────────
    logger = logging.getLogger("dragon")
    level_lower = level.lower() if isinstance(level, str) else "error"
    if level_lower not in ("error", "warning", "debug"):
        level_lower = "error"

    log_msg = f"[{component}] {message}"
    if level_lower == "error":
        logger.error(log_msg, exc_info=exc, extra={"component": component}, **kwargs)
    elif level_lower == "warning":
        logger.warning(log_msg, exc_info=exc, extra={"component": component}, **kwargs)
    else:
        logger.debug(log_msg, exc_info=exc, extra={"component": component}, **kwargs)


# -----------------------------------------------------------------------------
# Hauptklasse PlatformUtils
# -----------------------------------------------------------------------------
class PlatformUtils:
    """
    Plattformunabhängige Hilfsfunktionen für Dragon Whisperer.
    (Detaillierte Dokumentation siehe Modul-Docstring)
    """

    # --- Klassenattribute (Zustand, Caches, Locks) ---
    _environment_setup_done: ClassVar[bool] = False
    _environment_setup_lock: ClassVar[threading.RLock] = threading.RLock()

    _dependencies_checked: ClassVar[bool] = False
    _dependencies_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache: ClassVar[Dict[str, Tuple[bool, float]]] = {}
    _dependencies_cache_lock: ClassVar[threading.RLock] = threading.RLock()
    _dependencies_cache_ttl: ClassVar[float] = 60.0

    _ffmpeg_path: ClassVar[Optional[str]] = None
    _ffmpeg_path_lock: ClassVar[threading.RLock] = threading.RLock()

    _terminal_settings_saved: ClassVar[bool] = False
    _original_stty_settings: ClassVar[Optional[str]] = None
    _terminal_lock: ClassVar[threading.Lock] = threading.Lock()

    _base_dirs: ClassVar[Optional[List[Path]]] = None
    _user_dirs: ClassVar[List[Path]] = []
    _allowed_dirs_lock: ClassVar[threading.RLock] = threading.RLock()

    _test_home: ClassVar[Optional[Path]] = None
    _test_cwd: ClassVar[Optional[Path]] = None

    _DEBUG_COMPONENT: ClassVar[str] = "platform"
    _logger: ClassVar[logging.Logger] = logging.getLogger("dragon")

    _config_dir_logged: ClassVar[bool] = False

    _executable_cache: ClassVar[Dict[str, Optional[str]]] = {}
    _executable_cache_lock: ClassVar[threading.RLock] = threading.RLock()

    _console_configured: ClassVar[bool] = False
    _original_console_codepage_in: ClassVar[Optional[int]] = None
    _original_console_codepage_out: ClassVar[Optional[int]] = None
    _original_console_mode: ClassVar[Optional[int]] = None

    _is_container: ClassVar[Optional[bool]] = None
    _container_type: ClassVar[Optional[str]] = None

    # -------------------------------------------------------------------------
    # 1. Plattform- und Container-Erkennung
    # -------------------------------------------------------------------------
    @classmethod
    def is_wsl(cls) -> bool:
        """Erkennt, ob das System unter WSL (Windows Subsystem for Linux) läuft."""
        if not IS_LINUX:
            return False
        try:
            with open("/proc/version", "r") as f:
                version = f.read().lower()
                return "microsoft" in version or "wsl" in version
        except Exception:
            return False

    @classmethod
    def is_docker(cls) -> bool:
        """Erkennt, ob das System in einem Docker-Container läuft."""
        if not IS_LINUX:
            return False
        if os.path.exists("/.dockerenv"):
            return True
        try:
            with open("/proc/1/cgroup", "r") as f:
                return any("docker" in line for line in f)
        except Exception:
            return False

    @classmethod
    def is_flatpak(cls) -> bool:
        """Erkennt, ob das Programm als Flatpak läuft."""
        return "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ

    @classmethod
    def is_snap(cls) -> bool:
        """Erkennt, ob das Programm als Snap läuft."""
        return "SNAP" in os.environ or "SNAP_NAME" in os.environ

    @classmethod
    def get_container_type(cls) -> str:
        """Gibt den Containertyp zurück ('docker', 'wsl', 'flatpak', 'snap', 'none')."""
        if cls._container_type is None:
            if cls.is_docker():
                cls._container_type = "docker"
            elif cls.is_wsl():
                cls._container_type = "wsl"
            elif cls.is_flatpak():
                cls._container_type = "flatpak"
            elif cls.is_snap():
                cls._container_type = "snap"
            else:
                cls._container_type = "none"
        return cls._container_type

    @classmethod
    def is_containerized(cls) -> bool:
        """True, wenn das System in einer Container-Umgebung läuft."""
        return cls.get_container_type() != "none"

    @classmethod
    def is_headless(cls) -> bool:
        """Prüft, ob die Umgebung keine GUI unterstützt (kein DISPLAY, kein Wayland)."""
        if IS_WINDOWS:
            return False
        if IS_MACOS:
            return False
        if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"):
            return False
        try:
            import tkinter

            root = tkinter.Tk()
            root.destroy()
            return False
        except Exception:
            return True

    # -------------------------------------------------------------------------
    # 2. Verzeichnis‑Whitelist (Dateizugriffssicherheit)
    # -------------------------------------------------------------------------
    @classmethod
    def set_allowed_dirs(cls, dirs: List[str]) -> None:
        """
        Setzt die Liste der zusätzlich erlaubten Benutzerverzeichnisse.

        Args:
            dirs: Liste von Verzeichnispfaden (als String). Ungültige Pfade
                  werden ignoriert, existierende und lesbare Verzeichnisse
                  werden aufgelöst und gespeichert.
        """
        if not dirs:
            cls._logger.debug(
                "set_allowed_dirs: Leere Liste – keine Änderungen.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return

        cls._logger.debug(
            f"Setting user dirs: {dirs}", extra={"component": cls._DEBUG_COMPONENT}
        )
        with cls._allowed_dirs_lock:
            resolved = []
            for d in dirs:
                if not d or not isinstance(d, str):
                    cls._logger.debug(
                        f"  → Skipped (invalid entry): {d!r}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                d = d.strip()
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                except Exception as e:
                    cls._logger.debug(
                        f"  → Skipped (resolution error): {d} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    continue
                try:
                    if not p.exists():
                        cls._logger.debug(
                            f"  → Skipped (does not exist): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not p.is_dir():
                        cls._logger.debug(
                            f"  → Skipped (not a directory): {p}",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                        continue
                    if not os.access(p, os.R_OK):
                        cls._logger.warning(
                            f"Verzeichnis {p} ist nicht lesbar – "
                            "Dateien darin können nicht geöffnet werden.",
                            extra={"component": cls._DEBUG_COMPONENT},
                        )
                    resolved.append(p)
                    cls._logger.debug(
                        f"  → Resolved: {p}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except (PermissionError, OSError) as e:
                    cls._logger.debug(
                        f"  → Skipped (access error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except Exception as e:
                    cls._logger.debug(
                        f"  → Skipped (unexpected error): {p} – {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
            cls._user_dirs = resolved
            cls._base_dirs = None  # Cache invalidieren
            cls._logger.debug(
                f"Final user dirs: {[str(p) for p in resolved]}",
                extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def add_allowed_dir(cls, dir_path: str) -> bool:
        """Fügt ein einzelnes Verzeichnis zur Whitelist hinzu."""
        if not dir_path:
            return False
        current = cls.get_allowed_dirs()
        if dir_path in current:
            return True
        new_list = current + [dir_path]
        cls.set_allowed_dirs(new_list)
        return dir_path in cls.get_allowed_dirs()

    @classmethod
    def get_allowed_dirs(cls) -> List[str]:
        """Gibt die Liste der aktuell erlaubten Benutzerverzeichnisse als Strings zurück."""
        with cls._allowed_dirs_lock:
            return [str(p) for p in cls._user_dirs]

    @classmethod
    def reset_allowed_dirs(cls) -> None:
        """Setzt die Whitelist auf die Standard-Basisverzeichnisse zurück."""
        with cls._allowed_dirs_lock:
            cls._user_dirs = []
            cls._base_dirs = None

    @classmethod
    def is_path_allowed(cls, path: str) -> bool:
        """Prüft, ob ein gegebener Pfad innerhalb der erlaubten Verzeichnisse liegt."""
        try:
            real_path = Path(path).resolve()
        except Exception:
            return False
        for base in cls._get_allowed_dirs():
            try:
                real_path.relative_to(base)
                return True
            except ValueError:
                continue
        return False

    # -------------------------------------------------------------------------
    # 3. Konfigurationsverzeichnis
    # -------------------------------------------------------------------------
    @classmethod
    def get_platform_config_dir(cls) -> Path:
        """
        Gibt das plattformspezifische Konfigurationsverzeichnis zurück.

        Returns:
            Path: Verzeichnis, in dem dragon_settings.json und andere
                  Konfigurationsdateien gespeichert werden sollen.
        """
        if IS_WINDOWS:
            appdata = os.environ.get("APPDATA")
            if not appdata:
                appdata = str(Path.home() / "AppData" / "Roaming")
                cls._logger.debug(
                    "APPDATA not set, fallback to: %s",
                    appdata,
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            config_dir = Path(appdata) / "DragonWhisperer"
        elif IS_MACOS:
            config_dir = (
                Path.home() / "Library" / "Application Support" / "DragonWhisperer"
            )
        else:
            # Linux/Unix: XDG Base Directory Specification
            xdg_config = os.environ.get("XDG_CONFIG_HOME")
            if xdg_config:
                config_dir = Path(xdg_config) / "dragonwhisperer"
            else:
                config_dir = Path.home() / ".config" / "dragonwhisperer"
            # Flatpak-Override
            if cls.is_flatpak():
                config_dir = (
                    Path.home()
                    / ".var/app/com.dragonwhisperer/config"
                    / "dragonwhisperer"
                )
            elif cls.is_snap():
                config_dir = (
                    Path.home() / "snap/dragonwhisperer/current/.config/dragonwhisperer"
                )

        if not cls._config_dir_logged:
            cls._logger.debug(
                f"Config directory: {config_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            cls._config_dir_logged = True
        return config_dir

    @classmethod
    def ensure_platform_config_dir(cls) -> Path:
        """
        Stellt sicher, dass das Konfigurationsverzeichnis existiert.

        Returns:
            Path: Das (ggf. neu erstellte) Konfigurationsverzeichnis.
        """
        config_dir = cls.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
        cls._logger.debug(
            f"Ensured config directory exists: {config_dir}",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        return config_dir

    # -------------------------------------------------------------------------
    # 4. Prozess‑Terminierung (robust, mit Kindprozessen)
    # -------------------------------------------------------------------------
    @classmethod
    def kill_process_tree(cls, pid: int, timeout: float = 5.0) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse.

        Args:
            pid: Prozess-ID des Elternprozesses.
            timeout: Maximale Zeit in Sekunden für die Terminierung.

        Returns:
            True, wenn alle Prozesse beendet wurden, sonst False.
        """
        cls._logger.debug(
            f"Killing process tree for PID {pid} (timeout={timeout}s)",
            extra={"component": cls._DEBUG_COMPONENT},
        )
        start_time = time.monotonic()

        # ---- 1. Versuch: psutil (bevorzugt) ----
        try:
            import psutil

            parent = psutil.Process(pid)
            children = parent.children(recursive=True)
            cls._logger.debug(
                f"  psutil: Found {len(children)} child processes",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            for child in children:
                try:
                    child.terminate()
                    cls._logger.debug(
                        f"    Terminated child {child.pid}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except psutil.NoSuchProcess:
                    pass
            gone, alive = psutil.wait_procs(children, timeout=2.0)
            for child in alive:
                try:
                    child.kill()
                    cls._logger.debug(
                        f"    Killed child {child.pid}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                except psutil.NoSuchProcess:
                    pass
            parent.terminate()
            parent.wait(timeout=2.0)
            cls._logger.debug(
                f"  Terminated parent {pid}", extra={"component": cls._DEBUG_COMPONENT}
            )
            return True
        except ImportError:
            cls._logger.debug(
                "  psutil not available, using fallback",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except psutil.NoSuchProcess:
            cls._logger.debug(
                f"  Process {pid} does not exist",
                extra={"component": cls._DEBUG_COMPONENT},
            )
            return True
        except Exception as e:
            cls._logger.debug(
                f"  psutil error: {e}", extra={"component": cls._DEBUG_COMPONENT}
            )

        # ---- 2. Fallback ohne psutil ----
        try:
            if IS_WINDOWS:
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=max(0.1, timeout - (time.monotonic() - start_time)),
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                # Kurze Wartezeit, bis Prozesse terminiert sind
                time.sleep(0.5)
                try:
                    os.kill(pid, 0)  # Signal 0 = nur Existenz prüfen
                    cls._logger.debug(
                        f"  Process {pid} still alive after taskkill",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    return False
                except ProcessLookupError:
                    return True
            else:
                # Unix: killpg (Prozessgruppe)
                try:
                    pgid = os.getpgid(pid)
                    os.killpg(pgid, py_signal.SIGKILL)
                    time.sleep(0.2)
                    cls._logger.debug(
                        f"  Used killpg for PID {pid} (PGID {pgid})",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                    return True
                except (ProcessLookupError, PermissionError) as e:
                    cls._logger.debug(
                        f"  killpg failed: {e}",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                # pkill als Alternative
                subprocess.run(
                    ["pkill", "-9", "-P", str(pid)],
                    capture_output=True,
                    timeout=2.0,
                    check=False,
                )
                time.sleep(0.2)
                try:
                    os.kill(pid, 0)
                    return False
                except ProcessLookupError:
                    return True
        except subprocess.TimeoutExpired:
            cls._logger.debug(
                f"  Timeout killing process tree {pid}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except (OSError, subprocess.CalledProcessError) as e:
            cls._logger.debug(
                f"  Error killing process tree {pid}: {e}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except Exception as e:
            cls._logger.debug(
                f"  Unexpected error killing process tree {pid}: {e}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        return False

    @classmethod
    def terminate_process(
        cls,
        proc: subprocess.Popen,
        *,
        child_terminate_timeout: float = 2.0,
        child_kill_wait: float = 1.0,
        parent_terminate_timeout: float = 2.0,
        parent_kill_wait: float = 1.0,
        fallback_terminate_timeout: float = 2.0,
        fallback_kill_wait: float = 1.0,
        stats_callback: Optional[Callable[[str], None]] = None,
    ) -> bool:
        """
        Beendet einen Prozess und alle seine Kindprozesse robust (statische Methode).

        Args:
            proc: Der zu beendende Subprozess.
            child_terminate_timeout: Timeout für SIGTERM auf Kindprozesse (psutil).
            child_kill_wait: Wartezeit nach SIGKILL auf Kindprozesse.
            parent_terminate_timeout: Timeout für SIGTERM auf Elternprozess.
            parent_kill_wait: Wartezeit nach SIGKILL auf Elternprozess.
            fallback_terminate_timeout: Timeout für Fallback‑Terminierung (ohne psutil).
            fallback_kill_wait: Wartezeit nach Fallback‑SIGKILL.
            stats_callback: Optionaler Callback für Statistik (erhält den Namen der erfolgreichen Methode).

        Returns:
            True, wenn der Prozess beendet wurde, sonst False.
        """
        if proc is None or proc.poll() is not None:
            return True

        pid = proc.pid
        if pid is None:
            # Prozess ohne PID – direkt terminate versuchen
            try:
                proc.terminate()
                proc.wait(timeout=2.0)
                return proc.poll() is not None
            except Exception:
                return False

        # 1. psutil-Zweig
        try:
            import psutil

            parent = psutil.Process(pid)
            children = parent.children(recursive=True)
            for child in children:
                try:
                    child.terminate()
                except psutil.NoSuchProcess:
                    pass
            psutil.wait_procs(children, timeout=child_terminate_timeout)
            for child in children:
                if child.is_running():
                    try:
                        child.kill()
                    except psutil.NoSuchProcess:
                        pass
            parent.terminate()
            try:
                parent.wait(timeout=parent_terminate_timeout)
                if stats_callback:
                    stats_callback("psutil")
                return True
            except psutil.TimeoutExpired:
                parent.kill()
                parent.wait(timeout=parent_kill_wait)
                if stats_callback:
                    stats_callback("psutil_kill")
                return True
        except ImportError:
            pass
        except psutil.NoSuchProcess:
            return True
        except Exception as e:
            _safe_log_debug("proc", f"psutil termination error: {e}")

        # 2. Fallback ohne psutil
        try:
            if IS_WINDOWS:
                subprocess.run(
                    ["taskkill", "/F", "/T", "/PID", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("taskkill")
                    return True
                subprocess.run(
                    [
                        "wmic",
                        "process",
                        "where",
                        f"ParentProcessId={pid}",
                        "call",
                        "terminate",
                    ],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )
                proc.kill()
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("wmic")
                    return True
            else:
                try:
                    pgid = os.getpgid(pid)
                    os.killpg(pgid, py_signal.SIGKILL)
                    time.sleep(0.2)
                    if proc.poll() is not None:
                        if stats_callback:
                            stats_callback("killpg")
                        return True
                except (ProcessLookupError, PermissionError):
                    pass
                subprocess.run(
                    ["pkill", "-9", "-P", str(pid)],
                    capture_output=True,
                    timeout=fallback_terminate_timeout,
                    check=False,
                )
                os.kill(pid, py_signal.SIGKILL)
                time.sleep(0.2)
                if proc.poll() is not None:
                    if stats_callback:
                        stats_callback("pkill")
                    return True
        except Exception as e:
            _safe_log_debug("proc", f"Fallback termination error: {e}")

        # 3. Letzter direkter Versuch
        try:
            proc.terminate()
            proc.wait(timeout=fallback_terminate_timeout)
            if proc.poll() is not None:
                if stats_callback:
                    stats_callback("terminate")
                return True
            proc.kill()
            proc.wait(timeout=fallback_kill_wait)
            if proc.poll() is not None:
                if stats_callback:
                    stats_callback("kill")
                return True
        except Exception:
            pass

        if stats_callback:
            stats_callback("failed")
        return False

    @classmethod
    def check_platform_dependencies(cls, force: bool = False) -> bool:
        """
        Prüft, ob alle kritischen und optionalen Abhängigkeiten vorhanden sind.

        Args:
            force: Wenn True, wird die Prüfung erzwungen (Cache ignoriert).

        Returns:
            True, wenn alle kritischen Abhängigkeiten erfüllt sind.
            Bei fehlenden kritischen Abhängigkeiten wird ein RuntimeError ausgelöst.

        Raises:
            RuntimeError: Wenn mindestens eine kritische Abhängigkeit fehlt.
        """
        with cls._dependencies_lock:
            if not force and cls._dependencies_checked:
                cls._logger.debug(
                    "Dependencies already checked, skipping",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return True

            if force:
                cls._logger.info("🔄 Forced dependency re-check requested")
                cls._dependencies_checked = False
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache.clear()

            missing_critical: List[str] = []
            issues: List[str] = []

            cls._logger.info("🔍 Checking platform dependencies...")
            cls._logger.debug(
                "Starting dependency check", extra={"component": cls._DEBUG_COMPONENT}
            )

            # Hilfsfunktion für Tool‑Prüfung (mit Cache)
            def check_tool(name: str) -> bool:
                with cls._dependencies_cache_lock:
                    now = time.monotonic()
                    entry = cls._dependencies_cache.get(f"tool_{name}")
                    if entry and now - entry[1] < cls._dependencies_cache_ttl:
                        return entry[0]
                found = cls._find_executable(name) is not None
                with cls._dependencies_cache_lock:
                    cls._dependencies_cache[f"tool_{name}"] = (found, time.monotonic())
                return found

            cls._check_critical_tools(check_tool, missing_critical, issues)
            cls._check_optional_python_packages(issues)
            cls._check_optional_system_tools(check_tool, issues)
            cls._check_tts_components(check_tool, issues)
            cls._check_audio_players(check_tool, issues)

            if missing_critical:
                error_msg = cls._build_missing_critical_message(
                    missing_critical, issues
                )
                cls._dependencies_checked = False
                raise RuntimeError(error_msg)

            if issues:
                for issue in issues:
                    cls._logger.warning(f"⚠️ {issue}")

            cls._logger.info("✅ Alle kritischen Abhängigkeiten gefunden")
            cls._dependencies_checked = True
            return True

    @classmethod
    def _check_critical_tools(
        cls, check_tool, missing: List[str], issues: List[str]
    ) -> None:
        """Prüft ffmpeg und yt-dlp (kritische externe Tools)."""
        if not check_tool("ffmpeg"):
            missing.append("ffmpeg")
            issues.append("FFmpeg not found in PATH or standard locations")
            cls._logger.debug("  ✗ ffmpeg missing")
        else:
            cls._logger.debug("  ✓ ffmpeg found")

        if not check_tool("yt-dlp"):
            missing.append("yt-dlp")
            issues.append("yt-dlp not found in PATH")
            cls._logger.debug("  ✗ yt-dlp missing")
        else:
            cls._logger.debug("  ✓ yt-dlp found")

    @classmethod
    def _check_optional_python_packages(cls, issues: List[str]) -> None:
        """
        Prüft optionale Python-Pakete und fügt Warnungen zur `issues`-Liste hinzu.
        Plattformspezifische Warnungen werden nur auf dem jeweiligen Betriebssystem ausgegeben.
        Module, die später über FastLazyLoader geladen werden (whisper, torch, numpy, scipy),
        werden hier nicht als fehlend gemeldet, da sie erst nach der Abhängigkeitsprüfung
        initialisiert werden. Stattdessen werden DEBUG-Meldungen ausgegeben.

        Args:
            issues: Liste, in die Warnmeldungen eingefügt werden (wird direkt modifiziert).
        """

        # ── 1. Hilfsfunktion für Modul-Prüfung (mit Fallback) ──────────────
        def _is_module_available(
            module_name: str, package_name: Optional[str] = None
        ) -> bool:
            """Prüft, ob ein Python-Modul verfügbar ist.

            Args:
                module_name: Name des zu importierenden Moduls (z. B. 'whisper').
                package_name: Name des pip-Pakets (falls abweichend, z. B. 'openai-whisper').
                              Wird für Fallback-Prüfung verwendet.
            Returns:
                True, wenn das Modul importiert werden kann oder das Paket installiert ist.
            """
            # Versuche 1: Import des Moduls
            try:
                __import__(module_name)
                return True
            except ImportError:
                pass

            # Versuche 2: find_spec (falls Import fehlschlägt)
            try:
                if importlib.util.find_spec(module_name) is not None:
                    return True
            except (ModuleNotFoundError, AttributeError):
                pass

            # Versuche 3: Falls ein abweichender Paketname angegeben ist, prüfe via pip
            if package_name:
                try:
                    result = subprocess.run(
                        [sys.executable, "-m", "pip", "show", package_name],
                        capture_output=True,
                        text=True,
                        timeout=5,
                        check=False,
                    )
                    if result.returncode == 0:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "platform",
                                f"Paket {package_name} via pip show gefunden",
                            )
                        return True
                except Exception:
                    pass

            return False

        # ── 2. Whisper-Backends ──────────────────────────────────────────
        # openai-whisper: Das Modul heißt 'whisper', das Paket 'openai-whisper'
        openai_available = _is_module_available("whisper", "openai-whisper")
        faster_available = _is_module_available("faster_whisper", "faster-whisper")

        if not faster_available and not openai_available:
            # Nur Debug, da die Engine später in den Demo-Modus fällt
            log_debug(
                "platform",
                "Kein Whisper-Backend gefunden – wird später im Demo-Modus behandelt",
            )
        elif DEBUG_LEVEL >= 3:
            log_debug(
                "platform",
                f"Whisper-Backends: faster-whisper={faster_available}, openai-whisper={openai_available}",
            )

        # ── 3. deep-translator (wird später geladen) ──────────────────────
        if not _is_module_available("deep_translator", "deep-translator"):
            log_debug(
                "platform",
                "deep-translator nicht verfügbar (Übersetzung wird später ggf. eingeschränkt)",
            )

        # ── 4. PyTorch (optional, für GPU-Beschleunigung) ─────────────────
        if not _is_module_available("torch", "torch"):
            log_debug(
                "platform", "PyTorch nicht verfügbar – GPU-Beschleunigung deaktiviert"
            )

        # ── 5. numpy (benötigt für Audioverarbeitung) ────────────────────
        if not _is_module_available("numpy", "numpy"):
            log_debug(
                "platform", "numpy nicht verfügbar – Audio-Verbesserungen eingeschränkt"
            )

        # ── 6. scipy (optional, für Signalverarbeitung) ───────────────────
        if not _is_module_available("scipy", "scipy"):
            log_debug(
                "platform", "scipy nicht verfügbar – Signalverarbeitung eingeschränkt"
            )

        # ── 7. argostranslate (offline-Übersetzung) ──────────────────────
        if not _is_module_available("argostranslate", "argostranslate"):
            issues.append("argos-translate not available (offline translation limited)")

        # ── 8. psutil (System-Monitoring) ────────────────────────────────
        if not _is_module_available("psutil", "psutil"):
            issues.append("psutil not available (system monitoring limited)")

        # ── 9. pynvml (detaillierte GPU-Statistiken) ─────────────────────
        if not _is_module_available("pynvml", "pynvml"):
            # Keine Warnung, nur Debug, da es viele Systeme ohne NVIDIA-GPU gibt
            log_debug("platform", "pynvml not available (detailed GPU stats limited)")

        # ── 10. noisereduce (Rauschunterdrückung) ────────────────────────
        if not _is_module_available("noisereduce", "noisereduce"):
            issues.append("noisereduce not available (audio enhancement limited)")

        # ── 11. rapidfuzz (schnelle Textähnlichkeit) ─────────────────────
        if not _is_module_available("rapidfuzz", "rapidfuzz"):
            issues.append("rapidfuzz not available (duplicate detection slower)")

        # ── 12. python-docx (Word-Export) ────────────────────────────────
        if not _is_module_available("docx", "python-docx"):
            issues.append("python-docx not available (Word export disabled)")

        # ── 13. tiktoken (Token-Schätzung für LLM) ───────────────────────
        if not _is_module_available("tiktoken", "tiktoken"):
            issues.append("tiktoken not available (token estimation for LLM limited)")

        # ── 14. pyspellchecker (Hotword-Filterung) ───────────────────────
        if not _is_module_available("spellchecker", "pyspellchecker"):
            issues.append("pyspellchecker not available (hotword filtering limited)")

        # ── 15. keyring (sicherer Passwortspeicher) ──────────────────────
        if not _is_module_available("keyring", "keyring"):
            issues.append("keyring not available (secure password storage disabled)")

        # ── 16. win10toast (Windows-Desktop-Benachrichtigungen) ──────────
        if IS_WINDOWS and not _is_module_available("win10toast", "win10toast"):
            issues.append("win10toast not installed (desktop notifications disabled)")

        # ── 17. pyobjc (macOS-Desktop-Benachrichtigungen) ────────────────
        if IS_MACOS and not _is_module_available("Foundation", "pyobjc"):
            issues.append("pyobjc not installed (macOS notifications disabled)")

        # ── 18. tkinterdnd2 (Drag & Drop im SummarizeDialog) ─────────────
        if GUI_AVAILABLE and not _is_module_available("tkinterdnd2", "tkinterdnd2"):
            log_debug("platform", "tkinterdnd2 not available (drag & drop disabled)")

        # ── 19. Optional: Weitere nützliche Pakete (nur Debug) ────────────
        optional_packages = [
            ("langdetect", "langdetect", "language detection"),
            ("dimits", "dimits", "Piper TTS support"),
            ("pathvalidate", "pathvalidate", "Piper dependency"),
        ]
        for mod_name, pkg_name, description in optional_packages:
            if not _is_module_available(mod_name, pkg_name):
                log_debug("platform", f"{description} not available ({pkg_name})")

        if DEBUG_LEVEL >= 3:
            log_debug("platform", "Optionale Python-Pakete vollständig geprüft")

    @classmethod
    def _check_optional_system_tools(cls, check_tool, issues: List[str]) -> None:
        """Prüft optionale System-Tools (VLC, …)."""
        vlc_found = check_tool("vlc")
        if not vlc_found and IS_WINDOWS:
            for p in [
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]:
                if os.path.exists(p):
                    vlc_found = True
                    break
        if not vlc_found:
            issues.append("vlc not found (DVB‑S streams will not work)")

    @classmethod
    def _check_tts_components(cls, check_tool, issues: List[str]) -> None:
        """Prüft TTS‑Komponenten (espeak, piper)."""
        if not check_tool("espeak"):
            issues.append("espeak not found (lightweight TTS fallback unavailable)")

        piper_found = check_tool("piper")
        if not piper_found:
            # Fallback: Prüfe, ob Piper‑Modelle im Cache existieren
            try:
                cache_dir = cls.get_piper_cache_dir()
                if os.path.isdir(cache_dir):
                    for f in os.listdir(cache_dir):
                        if (
                            f.endswith(".onnx")
                            and os.path.getsize(os.path.join(cache_dir, f)) > 0
                        ):
                            piper_found = True
                            break
            except Exception:
                pass
        if not piper_found:
            issues.append("piper not found (high‑quality TTS will be unavailable)")

    @classmethod
    def _check_audio_players(cls, check_tool, issues: List[str]) -> None:
        """Prüft, ob mindestens ein Audio-Player verfügbar ist."""
        players = [
            name for name in ["ffplay", "aplay", "paplay", "sox"] if check_tool(name)
        ]
        if not players:
            issues.append("No audio player found – TTS will not produce sound")

    @classmethod
    def _build_missing_critical_message(
        cls, missing: List[str], issues: List[str]
    ) -> str:
        """Erstellt eine detaillierte Fehlermeldung für fehlende kritische Abhängigkeiten."""
        msg = f"❌ Fehlende kritische Abhängigkeiten: {', '.join(missing)}\n\n"
        msg += "\n".join(issues) + "\n"

        if "ffmpeg" in missing:
            msg += "\nFFmpeg Installation:\n"
            if IS_WINDOWS:
                msg += "  • Ausführen: winget install --source winget Gyan.FFmpeg\n"
            elif IS_MACOS:
                msg += "  • brew install ffmpeg\n"
            else:
                msg += "  • sudo apt install ffmpeg\n"
        if "yt-dlp" in missing:
            msg += "\nyt-dlp Installation:\n"
            msg += "  • pip install yt-dlp\n"
        if "tkinter" in missing:
            msg += "\nTkinter Installation:\n"
            msg += "  • Usually included with Python. On Linux: sudo apt-get install python3-tk\n"
        if "numpy" in missing:
            msg += "\nnumpy Installation:\n"
            msg += "  • pip install numpy\n"
        msg += "\n💡 Nach der Installation starten Sie Dragon Whisperer neu."
        return msg

    # -------------------------------------------------------------------------
    # 6. Pfadauflösung für ausführbare Dateien (mit Cache)
    # -------------------------------------------------------------------------
    @classmethod
    def _find_executable(cls, name: str) -> Optional[str]:
        """
        Findet eine ausführbare Datei (mit Cache). Threadsicher.

        Zuerst wird im System‑PATH gesucht, dann im Scripts‑Verzeichnis
        der aktuellen Python‑Umgebung (venv). Das Ergebnis wird gecacht.

        Args:
            name: Name der ausführbaren Datei (z. B. "ffmpeg").

        Returns:
            Absoluter Pfad zur Datei oder None, wenn nicht gefunden.
        """
        with cls._executable_cache_lock:
            if name in cls._executable_cache:
                return cls._executable_cache[name]

        exe = shutil.which(name)
        if exe:
            with cls._executable_cache_lock:
                cls._executable_cache[name] = exe
            if cls._logger.isEnabledFor(logging.DEBUG):
                cls._logger.debug(f"  → {name} gefunden im PATH: {exe}")
            return exe

        # Fallback: im Scripts-Verzeichnis des aktuellen Python-Interpreters suchen
        scripts_dir = os.path.dirname(sys.executable)
        candidate = os.path.join(scripts_dir, f"{name}{'.exe' if IS_WINDOWS else ''}")
        if os.path.isfile(candidate) and os.access(
            candidate, os.X_OK if not IS_WINDOWS else os.R_OK
        ):
            with cls._executable_cache_lock:
                cls._executable_cache[name] = candidate
            if cls._logger.isEnabledFor(logging.DEBUG):
                cls._logger.debug(
                    f"  → {name} gefunden unter {candidate} (venv‑Fallback)"
                )
            return candidate

        with cls._executable_cache_lock:
            cls._executable_cache[name] = None
        return None

    @classmethod
    def get_executable_path(cls, name: str) -> Optional[str]:
        """Öffentliche Methode zum Abrufen des Pfads einer ausführbaren Datei."""
        return cls._find_executable(name)

    @classmethod
    def get_ffmpeg_path(cls) -> Optional[str]:
        """
        Ermittelt den Pfad zur FFmpeg‑Executable (gecached, threadsicher).

        Returns:
            Absoluter Pfad zu ffmpeg oder None, wenn nicht gefunden.
        """
        with cls._ffmpeg_path_lock:
            if cls._ffmpeg_path is not None:
                return cls._ffmpeg_path

            env_path = os.environ.get("FFMPEG_PATH")
            if env_path and os.path.exists(env_path):
                cls._ffmpeg_path = env_path
                return cls._ffmpeg_path

            ffmpeg_path = cls._find_executable("ffmpeg")
            if ffmpeg_path:
                cls._ffmpeg_path = ffmpeg_path
                return cls._ffmpeg_path

            # Plattformspezifische Standardpfade als letzte Reserve
            if IS_WINDOWS:
                paths = [
                    "C:\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files\\ffmpeg\\bin\\ffmpeg.exe",
                    "C:\\Program Files (x86)\\ffmpeg\\bin\\ffmpeg.exe",
                ]
            elif IS_MACOS:
                paths = [
                    "/usr/local/bin/ffmpeg",
                    "/opt/homebrew/bin/ffmpeg",
                    "/usr/bin/ffmpeg",
                ]
            else:
                paths = [
                    "/usr/bin/ffmpeg",
                    "/usr/local/bin/ffmpeg",
                ]
            for path in paths:
                if os.path.exists(path):
                    cls._ffmpeg_path = path
                    return cls._ffmpeg_path

            cls._ffmpeg_path = None
            return None

    # -------------------------------------------------------------------------
    # 7. Plattforminformationen (öffentlich)
    # -------------------------------------------------------------------------
    @classmethod
    def get_platform_info(cls) -> Dict[str, Any]:
        """
        Liefert ein Dictionary mit detaillierten Plattforminformationen.

        Returns:
            Dict mit Schlüsseln wie 'system', 'is_windows', 'cpu_count', etc.
        """
        info: Dict[str, Any] = {
            "system": SYSTEM,
            "is_windows": IS_WINDOWS,
            "is_macos": IS_MACOS,
            "is_linux": IS_LINUX,
            "is_arm": IS_ARM,
            "is_x86": IS_X86,
            "is_wsl": cls.is_wsl(),
            "is_docker": cls.is_docker(),
            "is_flatpak": cls.is_flatpak(),
            "is_snap": cls.is_snap(),
            "is_containerized": cls.is_containerized(),
            "container_type": cls.get_container_type(),
            "is_headless": cls.is_headless(),
            "python_version": sys.version,
            "python_executable": sys.executable,
            "current_directory": os.getcwd(),
            "environment_setup": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "cpu_model": cls.get_cpu_model(),
            "total_ram_gb": cls.get_total_ram_gb(),
            "username": cls.get_username(),
            "hostname": cls.get_hostname(),
            "timezone": cls.get_timezone(),
            "desktop_environment": cls.get_desktop_environment(),
        }
        # CPU‑Anzahl
        try:
            import psutil

            info["cpu_count"] = psutil.cpu_count()
            info["cpu_count_logical"] = psutil.cpu_count(logical=True)
            freq = psutil.cpu_freq()
            info["cpu_freq_current_mhz"] = freq.current if freq else None
            mem = psutil.virtual_memory()
            info["memory_total_gb"] = mem.total / (1024**3)
            info["memory_available_gb"] = mem.available / (1024**3)
            info["memory_percent"] = mem.percent
            disk = psutil.disk_usage(os.getcwd())
            info["disk_free_gb"] = disk.free / (1024**3)
            info["disk_total_gb"] = disk.total / (1024**3)
        except ImportError:
            info["cpu_count"] = os.cpu_count()
            info["memory_total_gb"] = cls.get_total_ram_gb()
        except Exception as e:
            cls._logger.debug(f"psutil info error: {e}")

        # GPU-Informationen (via pynvml)
        try:
            import pynvml

            pynvml.nvmlInit()
            handle = pynvml.nvmlDeviceGetHandleByIndex(0)
            mem = pynvml.nvmlDeviceGetMemoryInfo(handle)
            info["gpu_name"] = pynvml.nvmlDeviceGetName(handle).decode()
            info["gpu_memory_total_gb"] = mem.total / (1024**3)
            info["gpu_memory_used_gb"] = mem.used / (1024**3)
            info["gpu_temperature_c"] = pynvml.nvmlDeviceGetTemperature(
                handle, pynvml.NVML_TEMPERATURE_GPU
            )
            info["gpu_utilization_percent"] = pynvml.nvmlDeviceGetUtilizationRates(
                handle
            ).gpu
            pynvml.nvmlShutdown()
        except ImportError:
            pass
        except Exception as e:
            cls._logger.debug(f"pynvml error: {e}")
        return info

    @classmethod
    def print_platform_info(cls) -> None:
        """Gibt die Plattforminformationen übersichtlich im Log aus."""
        info = cls.get_platform_info()
        cls._logger.info("\n" + "=" * 60)
        cls._logger.info("🐉 PLATFORM INFORMATION")
        cls._logger.info("=" * 60)
        for key, value in info.items():
            if key not in ["environment_setup", "dependencies_checked"]:
                cls._logger.info(f"{key:25} {value}")
        cls._logger.info("-" * 60)
        cls._logger.info(
            f"{'Environment Setup':25} {'✅' if info['environment_setup'] else '❌'}"
        )
        cls._logger.info(
            f"{'Dependencies Checked':25} {'✅' if info['dependencies_checked'] else '❌'}"
        )
        cls._logger.info("=" * 60)

    @classmethod
    def get_debug_info(cls) -> Dict[str, Any]:
        """
        Liefert detaillierte Debug‑Informationen über den internen Zustand.

        Returns:
            Dict mit internen Variablen (für Diagnosezwecke).
        """
        with cls._allowed_dirs_lock:
            user_dirs = [str(p) for p in cls._user_dirs]
            base_dirs = (
                [str(p) for p in cls._get_base_dirs()]
                if cls._base_dirs is not None
                else []
            )
        return {
            "user_dirs": user_dirs,
            "base_dirs": base_dirs,
            "ffmpeg_path": cls._ffmpeg_path,
            "terminal_settings_saved": cls._terminal_settings_saved,
            "original_stty_settings": cls._original_stty_settings,
            "environment_setup_done": cls._environment_setup_done,
            "dependencies_checked": cls._dependencies_checked,
            "test_home_override": str(cls._test_home) if cls._test_home else None,
            "test_cwd_override": str(cls._test_cwd) if cls._test_cwd else None,
            "console_configured": cls._console_configured,
            "container_type": cls.get_container_type(),
        }

    # -------------------------------------------------------------------------
    # 8. Umgebungseinrichtung (PATH, Konsole, Terminal)
    # -------------------------------------------------------------------------
    @classmethod
    def setup_platform_environment(cls) -> None:
        """
        Richtet plattformspezifische Umgebungsvariablen und Konsolen ein.

        Diese Methode sollte einmal zu Beginn des Programms aufgerufen werden.
        Sie ist idempotent (mehrfache Aufrufe sind ungefährlich).
        """
        with cls._environment_setup_lock:
            if cls._environment_setup_done:
                cls._logger.debug(
                    "Environment already set up",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                return

            cls._logger.info("🔧 Setting up platform environment...")
            cls._logger.debug(
                "Starting environment setup", extra={"component": cls._DEBUG_COMPONENT}
            )

            cls._save_terminal_settings()
            atexit.register(cls._restore_terminal_settings)

            if IS_WINDOWS:
                cls._setup_windows_console()
                atexit.register(cls._restore_windows_console)
                cls._logger.debug(
                    "Windows console setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            elif IS_MACOS:
                cls._setup_macos_temp_dir()
                cls._logger.debug(
                    "macOS temp dir setup completed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            else:
                cls._logger.debug(
                    "Linux: no extra setup needed",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
                if cls.is_containerized():
                    cls._logger.info(
                        f"🐳 Running in container: {cls.get_container_type()}"
                    )

            # Scripts‑Pfade zum PATH hinzufügen (für pip‑installierte Tools)
            cls._add_scripts_to_path()

            # Environment-Variablen für Unicode/UTF-8
            if IS_WINDOWS:
                os.environ["PYTHONIOENCODING"] = "utf-8"
            os.environ["PYTHONUTF8"] = "1"

            cls._environment_setup_done = True
            cls._logger.info("✅ Platform environment setup complete")
            cls._logger.debug(
                "Environment setup finished",
                extra={"component": cls._DEBUG_COMPONENT},
            )

    @classmethod
    def _add_scripts_to_path(cls) -> None:
        """Fügt die Scripts‑Verzeichnisse der aktuellen Python‑Umgebung zum PATH hinzu."""
        path_env = os.environ.get("PATH", "")
        paths_to_add: List[str] = []

        # 1. sysconfig.get_path('scripts')
        try:
            import sysconfig

            scripts_dir = sysconfig.get_path("scripts")
            if scripts_dir and os.path.isdir(scripts_dir):
                paths_to_add.append(scripts_dir)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls._logger.debug(
                    "Konnte Scripts‑Pfad (sysconfig) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        # 2. site.getuserbase()/Scripts (für --user Installationen)
        try:
            import site

            user_base = site.getuserbase()
            if IS_WINDOWS:
                user_scripts = os.path.join(user_base, "Scripts")
            else:
                user_scripts = os.path.join(user_base, "bin")
            if os.path.isdir(user_scripts):
                paths_to_add.append(user_scripts)
        except Exception as exc:
            if DEBUG_LEVEL >= 2:
                cls._logger.debug(
                    "Konnte Benutzer‑Scripts‑Pfad (site) nicht ermitteln: %s",
                    exc,
                    extra={"component": cls._DEBUG_COMPONENT},
                )

        # 3. Direktes Scripts‑Verzeichnis des Interpreters (falls nicht schon enthalten)
        scripts_dir = os.path.dirname(sys.executable)
        if os.path.isdir(scripts_dir) and scripts_dir not in paths_to_add:
            paths_to_add.append(scripts_dir)

        for p in paths_to_add:
            if p not in path_env.split(os.pathsep):
                path_env = p + os.pathsep + path_env
                if DEBUG_LEVEL >= 2:
                    cls._logger.debug(
                        "Scripts‑Pfad zum PATH hinzugefügt: %s",
                        p,
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        os.environ["PATH"] = path_env

    # -------------------------------------------------------------------------
    # 9. Windows‑Konsolen‑Setup (UTF‑8, VT)
    # -------------------------------------------------------------------------
    @classmethod
    def _get_windows_version(cls) -> Tuple[int, int, int]:
        """Gibt Windows-Version als Tupel (major, minor, build) zurück."""
        if not IS_WINDOWS:
            return (0, 0, 0)
        try:
            import ctypes

            class OSVERSIONINFOEXW(ctypes.Structure):
                _fields_ = [
                    ("dwOSVersionInfoSize", ctypes.c_ulong),
                    ("dwMajorVersion", ctypes.c_ulong),
                    ("dwMinorVersion", ctypes.c_ulong),
                    ("dwBuildNumber", ctypes.c_ulong),
                    ("dwPlatformId", ctypes.c_ulong),
                    ("szCSDVersion", ctypes.c_wchar * 128),
                    ("wServicePackMajor", ctypes.c_ushort),
                    ("wServicePackMinor", ctypes.c_ushort),
                    ("wSuiteMask", ctypes.c_ushort),
                    ("wProductType", ctypes.c_ubyte),
                    ("wReserved", ctypes.c_ubyte),
                ]

            kernel32 = ctypes.windll.kernel32
            ver = OSVERSIONINFOEXW()
            ver.dwOSVersionInfoSize = ctypes.sizeof(ver)
            if kernel32.RtlGetVersion(ctypes.byref(ver)) == 0:
                return (ver.dwMajorVersion, ver.dwMinorVersion, ver.dwBuildNumber)
        except Exception:
            pass

        try:
            import platform

            ver = platform.version().split(".")
            if len(ver) >= 3:
                try:
                    return (int(ver[0]), int(ver[1]), int(ver[2]))
                except ValueError:
                    pass
        except Exception:
            pass
        return (0, 0, 0)

    @classmethod
    def _setup_windows_console(cls) -> bool:
        """
        Aktiviert UTF‑8 und virtuelle Terminal‑Sequenzen unter Windows,
        sofern die Windows‑Version dies unterstützt (mindestens Windows 10
        Build 10586).  Die Konfiguration wird nur einmal durchgeführt.

        Returns:
            True, wenn die Konsole erfolgreich konfiguriert wurde, sonst False.
        """
        if not IS_WINDOWS or cls._console_configured:
            return cls._console_configured

        try:
            import ctypes
            from ctypes import wintypes
        except ImportError:
            cls._logger.warning(
                "ctypes nicht verfügbar – Windows‑Konsolen‑Setup nicht möglich."
            )
            return False

        kernel32 = ctypes.windll.kernel32
        kernel32.SetConsoleCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleCP.restype = wintypes.BOOL
        kernel32.SetConsoleOutputCP.argtypes = [wintypes.UINT]
        kernel32.SetConsoleOutputCP.restype = wintypes.BOOL
        kernel32.GetConsoleMode.argtypes = [
            wintypes.HANDLE,
            ctypes.POINTER(wintypes.DWORD),
        ]
        kernel32.GetConsoleMode.restype = wintypes.BOOL
        kernel32.SetConsoleMode.argtypes = [wintypes.HANDLE, wintypes.DWORD]
        kernel32.SetConsoleMode.restype = wintypes.BOOL

        STD_OUTPUT_HANDLE = -11
        hOut = kernel32.GetStdHandle(STD_OUTPUT_HANDLE)
        if hOut is None or hOut == ctypes.c_void_p(-1).value:
            cls._logger.warning(
                "Standard‑Ausgabe‑Handle nicht verfügbar – Konsolen‑Setup fehlgeschlagen."
            )
            return False

        mode_out = wintypes.DWORD()
        if not kernel32.GetConsoleMode(hOut, ctypes.byref(mode_out)):
            cls._logger.warning(
                "GetConsoleMode für Ausgabe fehlgeschlagen – Kann Konsolen‑Modus nicht ändern."
            )
            return False

        cls._original_console_mode = mode_out.value
        cls._original_console_codepage_in = kernel32.GetConsoleCP()
        cls._original_console_codepage_out = kernel32.GetConsoleOutputCP()

        # UTF‑8 setzen (65001)
        if cls._original_console_codepage_in != 65001:
            if not kernel32.SetConsoleCP(65001):
                cls._logger.warning(
                    "SetConsoleCP(65001) fehlgeschlagen – Eingabe‑Codepage nicht geändert."
                )
        if cls._original_console_codepage_out != 65001:
            if not kernel32.SetConsoleOutputCP(65001):
                cls._logger.warning(
                    "SetConsoleOutputCP(65001) fehlgeschlagen – Ausgabe‑Codepage nicht geändert."
                )

        major, minor, build = cls._get_windows_version()
        if major >= 10 and build >= 10586:
            ENABLE_VIRTUAL_TERMINAL_PROCESSING = 0x0004
            ENABLE_PROCESSED_OUTPUT = 0x0001
            new_mode = (
                mode_out.value
                | ENABLE_VIRTUAL_TERMINAL_PROCESSING
                | ENABLE_PROCESSED_OUTPUT
            )
            if (mode_out.value & ENABLE_VIRTUAL_TERMINAL_PROCESSING) == 0:
                if kernel32.SetConsoleMode(hOut, new_mode):
                    cls._logger.debug(
                        "Windows console: VT‑Verarbeitung aktiviert (Ausgabe).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
                else:
                    cls._logger.debug(
                        f"VT‑Aktivierung fehlgeschlagen – wird ignoriert (Build {build}).",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
        else:
            cls._logger.debug(
                f"VT processing not supported on this Windows version (build {build})",
                extra={"component": cls._DEBUG_COMPONENT},
            )

        # Optional: VT für Eingabe aktivieren (auch nur ab ausreichend neuer Version)
        if major >= 10 and build >= 10586:
            STD_INPUT_HANDLE = -10
            hIn = kernel32.GetStdHandle(STD_INPUT_HANDLE)
            if hIn not in (None, ctypes.c_void_p(-1).value):
                mode_in = wintypes.DWORD()
                if kernel32.GetConsoleMode(hIn, ctypes.byref(mode_in)):
                    ENABLE_VIRTUAL_TERMINAL_INPUT = 0x0200
                    if (mode_in.value & ENABLE_VIRTUAL_TERMINAL_INPUT) == 0:
                        kernel32.SetConsoleMode(
                            hIn, mode_in.value | ENABLE_VIRTUAL_TERMINAL_INPUT
                        )
                        if DEBUG_LEVEL >= 4:
                            _safe_log_debug("console", "VT‑Eingabe aktiviert.")

        cls._console_configured = True
        return True

    @classmethod
    def _restore_windows_console(cls) -> None:
        """Stellt die ursprünglichen Konsolen‑Einstellungen wieder her."""
        if not IS_WINDOWS or not cls._console_configured:
            return
        try:
            import ctypes

            kernel32 = ctypes.windll.kernel32
            if cls._original_console_codepage_out is not None:
                kernel32.SetConsoleOutputCP(cls._original_console_codepage_out)
            if cls._original_console_codepage_in is not None:
                kernel32.SetConsoleCP(cls._original_console_codepage_in)
            if cls._original_console_mode is not None:
                hOut = kernel32.GetStdHandle(-11)
                if hOut not in (None, ctypes.c_void_p(-1).value):
                    kernel32.SetConsoleMode(hOut, cls._original_console_mode)
            cls._logger.debug(
                "Windows‑Konsolen‑Einstellungen wiederhergestellt.",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except Exception as e:
            cls._logger.debug(f"Fehler beim Wiederherstellen der Konsole: {e}")
        finally:
            cls._console_configured = False

    @classmethod
    def _setup_macos_temp_dir(cls) -> None:
        """Erstellt ein temporäres Verzeichnis für Dragon Whisperer unter macOS."""
        temp_dir = Path(tempfile.gettempdir()) / "dragonwhisperer"
        try:
            temp_dir.mkdir(parents=True, exist_ok=True)
            cls._logger.debug(
                f"macOS temp dir ensured: {temp_dir}",
                extra={"component": cls._DEBUG_COMPONENT},
            )
        except (OSError, PermissionError) as e:
            cls._logger.warning(f"⚠️ macOS temp dir creation failed: {e}")

    @classmethod
    def _save_terminal_settings(cls) -> None:
        """Speichert die aktuellen Terminal‑Einstellungen (Linux)."""
        if not IS_LINUX or cls._terminal_settings_saved:
            return
        with cls._terminal_lock:
            try:
                result = subprocess.run(
                    ["stty", "-g"],
                    capture_output=True,
                    text=True,
                    check=False,
                    timeout=2,
                )
                if result.returncode == 0 and result.stdout:
                    cls._original_stty_settings = result.stdout.strip()
                    cls._terminal_settings_saved = True
                    cls._logger.debug(
                        "Terminal settings saved",
                        extra={"component": cls._DEBUG_COMPONENT},
                    )
            except (subprocess.TimeoutExpired, OSError):
                if DEBUG_LEVEL >= 2:
                    cls._logger.debug("stty -g failed")

    @classmethod
    def _restore_terminal_settings(cls) -> None:
        """Stellt die ursprünglichen Terminal‑Einstellungen wieder her (Linux)."""
        if not IS_LINUX or cls._original_stty_settings is None:
            return
        with cls._terminal_lock:
            try:
                subprocess.run(
                    ["stty", cls._original_stty_settings], check=False, timeout=2
                )
                cls._logger.debug(
                    "Terminal settings restored",
                    extra={"component": cls._DEBUG_COMPONENT},
                )
            except Exception:
                pass

    # -------------------------------------------------------------------------
    # 10. Theme‑Anwendung auf Tkinter‑Widgets
    # -------------------------------------------------------------------------
    @classmethod
    def apply_theme_to_widget_tree(
        cls,
        root_widget: tk.Widget,
        theme: Any,
        update_idletasks: bool = True,
        include_ttk: bool = True,
        ttk_styles: Optional[Dict[str, Dict[str, str]]] = None,
    ) -> None:
        """
        Wendet das übergebene Theme rekursiv auf alle tk‑Widgets im Teilbaum an.

        Diese Methode ist iterativ (Stack) und daher auch für sehr tiefe
        Widget‑Bäume geeignet. Sie behandelt sowohl normale tk‑Widgets als auch
        ttk‑Widgets (optional) und spezielle Container wie ScrolledText oder
        PanedWindow.

        Args:
            root_widget: Wurzel-Widget (z.B. Toplevel oder Frame).
            theme: Theme-Objekt (Attribute wie BG_PRIMARY, TEXT_PRIMARY, etc.)
            update_idletasks: Wenn True, wird `update_idletasks()` aufgerufen.
            include_ttk: Wenn True, werden ttk‑Widgets mit Standard‑Styles konfiguriert.
            ttk_styles: Optionales Dict mit Style‑Überschreibungen für ttk‑Widgets.
        """
        if not GUI_AVAILABLE or root_widget is None:
            return

        # Hilfsfunktionen
        def _get_theme_attr(attr: str, fallback: str) -> str:
            try:
                return getattr(theme, attr, fallback)
            except Exception:
                try:
                    return getattr(DarkTheme(), attr, fallback)
                except Exception:
                    return fallback

        def _safe_configure(widget: tk.Widget, **kwargs: Any) -> None:
            if not kwargs:
                return
            clean = {
                k: v for k, v in kwargs.items() if isinstance(k, str) and k.strip()
            }
            if not clean:
                return
            try:
                widget.configure(**clean)
            except tk.TclError:
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug("theme", f"_safe_configure({widget}) Fehler: {e}")

        def _apply_ttk_style(widget: ttk.Widget, style_name: str) -> None:
            if not include_ttk:
                return
            try:
                style = ttk.Style()
                base_style: Dict[str, str] = {}
                if ttk_styles is not None and style_name in ttk_styles:
                    base_style.update(ttk_styles[style_name])
                base_style.setdefault(
                    "fieldbackground",
                    _get_theme_attr(
                        "INPUT_BG", _get_theme_attr("BG_TERTIARY", "#242d38")
                    ),
                )
                base_style.setdefault(
                    "background", _get_theme_attr("BG_TERTIARY", "#242d38")
                )
                base_style.setdefault(
                    "foreground", _get_theme_attr("TEXT_PRIMARY", "#e6edf3")
                )
                base_style.setdefault(
                    "selectbackground", _get_theme_attr("COMBO_SELECTION", "#1f6feb")
                )
                base_style.setdefault(
                    "selectforeground", _get_theme_attr("TEXT_PRIMARY", "#e6edf3")
                )
                style.configure(style_name, **base_style)
                widget.configure(style=style_name)
            except Exception:
                pass

        # Iterativer Stack
        stack: List[Union[tk.Widget, tk.Toplevel]] = [root_widget]
        total_updated = 0
        total_skipped_ttk = 0

        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue

            w_class = widget.__class__

            # ttk‑Widgets
            if issubclass(w_class, ttk.Widget):
                if not include_ttk:
                    total_skipped_ttk += 1
                    try:
                        stack.extend(widget.winfo_children())
                    except tk.TclError:
                        pass
                    continue

                style_name = None
                if isinstance(widget, ttk.Combobox):
                    style_name = "Dark.TCombobox"
                elif isinstance(widget, ttk.Progressbar):
                    style_name = "Dark.Horizontal.TProgressbar"
                elif isinstance(widget, ttk.Entry):
                    style_name = "Dark.TEntry"
                elif isinstance(widget, ttk.Label):
                    style_name = "Dark.TLabel"
                elif isinstance(widget, ttk.Button):
                    style_name = "Dark.TButton"
                if style_name:
                    _apply_ttk_style(widget, style_name)

                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Spezialfall: ScrolledText
            if w_class == scrolledtext.ScrolledText:
                try:
                    inner = widget.text
                    if inner and inner.winfo_exists():
                        _safe_configure(
                            inner,
                            bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                            fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                            selectbackground=_get_theme_attr(
                                "COMBO_SELECTION", "#1f6feb"
                            ),
                            selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        )
                        total_updated += 1
                except Exception:
                    pass
                try:
                    vbar = widget.vbar
                    if vbar and vbar.winfo_exists():
                        _safe_configure(
                            vbar,
                            bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                            activebackground=_get_theme_attr(
                                "SCROLLBAR_HOVER", "#999999"
                            ),
                            troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                        total_updated += 1
                except Exception:
                    pass
                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Spezialfall: PanedWindow
            if w_class == tk.PanedWindow:
                try:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        sashrelief="raised",
                        sashwidth=4,
                    )
                    total_updated += 1
                except Exception:
                    pass
                try:
                    stack.extend(widget.winfo_children())
                except tk.TclError:
                    pass
                continue

            # Standard‑tk‑Widgets
            try:
                if w_class in (tk.Label,):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_PRIMARY", "#ffffff"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class in (tk.Button,):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_TERTIARY", "#cccccc"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        activebackground=_get_theme_attr("BG_HOVER", "#dddddd"),
                        activeforeground=_get_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    total_updated += 1
                elif w_class in (tk.Checkbutton, tk.Radiobutton):
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        activebackground=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        activeforeground=_get_theme_attr("TEXT_ACCENT", "#1f6feb"),
                    )
                    total_updated += 1
                elif w_class in (tk.Entry, tk.Spinbox, tk.Text):
                    input_bg = _get_theme_attr(
                        "INPUT_BG", _get_theme_attr("BG_TERTIARY", "#ffffff")
                    )
                    _safe_configure(
                        widget,
                        bg=input_bg,
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        insertbackground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    if w_class == tk.Spinbox:
                        _safe_configure(
                            widget,
                            buttonbackground=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        )
                    total_updated += 1
                elif w_class == tk.Frame:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                elif w_class == tk.LabelFrame:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scale:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_SECONDARY", "#f0f0f0"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Listbox:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                        fg=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                        selectbackground=_get_theme_attr("COMBO_SELECTION", "#1f6feb"),
                        selectforeground=_get_theme_attr("TEXT_PRIMARY", "#000000"),
                    )
                    total_updated += 1
                elif w_class == tk.Scrollbar:
                    _safe_configure(
                        widget,
                        bg=_get_theme_attr("SCROLLBAR", "#b3b3b3"),
                        activebackground=_get_theme_attr("SCROLLBAR_HOVER", "#999999"),
                        troughcolor=_get_theme_attr("BG_TERTIARY", "#e5e5e5"),
                    )
                    total_updated += 1
                elif w_class == tk.Canvas:
                    _safe_configure(widget, bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                    total_updated += 1
                else:
                    try:
                        widget.configure(bg=_get_theme_attr("BG_PRIMARY", "#ffffff"))
                        total_updated += 1
                    except tk.TclError:
                        pass
            except (tk.TclError, AttributeError):
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    _safe_log_debug("theme", f"Fehler bei {w_class.__name__}: {e}")

            try:
                stack.extend(widget.winfo_children())
            except tk.TclError:
                pass

        if update_idletasks:
            try:
                root_widget.update_idletasks()
            except tk.TclError:
                pass

        if DEBUG_LEVEL >= 3:
            _safe_log_debug(
                "theme",
                f"apply_theme_to_widget_tree: {total_updated} tk-Widgets aktualisiert, "
                f"{total_skipped_ttk} ttk-Widgets übersprungen (include_ttk={include_ttk})",
            )

    # -------------------------------------------------------------------------
    # 11. URL‑ und Pfad‑Validierung (sicher)
    # -------------------------------------------------------------------------
    @classmethod
    def sanitize_url(cls, url: str) -> str:
        """Entfernt überflüssige Whitespaces und bereinigt die URL."""
        return url.strip() if url else ""

    @classmethod
    def validate_file_path(
        cls, file_url: str, allowed_dirs: Optional[List[str]] = None
    ) -> Tuple[bool, str]:
        """
        Validiert eine file://‑URL.

        Args:
            file_url: Die URL im Format file://...
            allowed_dirs: Zusätzlich erlaubte Verzeichnisse (optional).

        Returns:
            (True, absoluter Pfad) oder (False, Fehlermeldung).
        """
        cls._logger.debug(
            f"Validating file URL: {file_url}",
            extra={"component": cls._DEBUG_COMPONENT},
        )

        if not file_url.startswith("file://"):
            return False, "Keine file://-URL"

        try:
            if IS_WINDOWS and file_url.startswith("file:///"):
                path_part = file_url[8:]
            else:
                path_part = file_url[len("file://") :]
            path_part = urllib.request.url2pathname(path_part)
        except Exception as e:
            return False, f"Pfad kann nicht extrahiert werden: {e}"

        try:
            real_path = Path(path_part).resolve()
        except Exception as e:
            return False, f"Pfad kann nicht normalisiert werden: {e}"

        if not real_path.exists():
            return False, f"Datei existiert nicht: {real_path}"
        if not real_path.is_file():
            return False, "Keine gültige Datei (möglicherweise ein Verzeichnis)"

        allowed_bases = cls._get_allowed_dirs()
        if allowed_dirs:
            for d in allowed_dirs:
                if not d:
                    continue
                try:
                    p = Path(d).resolve()
                    if p.exists():
                        allowed_bases.append(p)
                except Exception:
                    pass

        if not allowed_bases:
            return False, "Keine erlaubten Verzeichnisse definiert"

        for base in allowed_bases:
            try:
                real_path.relative_to(base)
                return True, str(real_path)
            except ValueError:
                continue

        return False, "Datei außerhalb der erlaubten Verzeichnisse"

    @classmethod
    def validate_url(cls, url: str) -> Tuple[bool, str]:
        """
        Validiert eine beliebige URL (http, https, file, dvb, ...).

        Args:
            url: Die zu validierende URL.

        Returns:
            (True, "ok") oder (False, Fehlermeldung).
        """
        if not url:
            return False, "URL is empty"

        url = cls.sanitize_url(url)
        cls._logger.debug(
            f"Validating URL: {url}", extra={"component": cls._DEBUG_COMPONENT}
        )

        if url.startswith(("dvb://", "dvb-s://")):
            return cls._validate_dvb_url(url)
        if url.startswith("file://"):
            return cls.validate_file_path(url)

        if not url.startswith(("http://", "https://")):
            return False, f"Nicht unterstütztes URL-Schema: {url[:50]}"

        try:
            parsed = urllib.parse.urlparse(url)
            if not parsed.netloc:
                return False, "Keine Netzwerkadresse in URL"

            allowed_chars = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
            components = parsed.path + parsed.query + parsed.fragment + parsed.params
            if not re.match(f"^[{allowed_chars}]*$", components):
                return False, f"URL enthält nicht erlaubte Zeichen: {components[:50]}"

            return True, "ok"
        except Exception as e:
            return False, f"URL-Parsing fehlgeschlagen: {e}"

    @classmethod
    def _validate_dvb_url(cls, url: str) -> Tuple[bool, str]:
        """Validiert eine DVB‑URL (dvb:// oder dvb-s://)."""
        params_part = url[8:] if url.startswith("dvb-s://") else url[6:]
        allowed = r"a-zA-Z0-9=&\-_.+"
        if not re.match(f"^[{allowed}]*$", params_part):
            return (
                False,
                f"DVB-Parameter enthalten ungültige Zeichen: {params_part[:50]}",
            )
        if "frequency=" not in params_part:
            return False, "DVB-URL muss 'frequency=' enthalten"
        return True, "ok"

    # -------------------------------------------------------------------------
    # 12. Test‑Overrides (für Unit‑Tests)
    # -------------------------------------------------------------------------
    @classmethod
    def set_test_home(cls, path: Optional[Path]) -> None:
        """Überschreibt das Home‑Verzeichnis für Tests. Nur zu Testzwecken."""
        cls._test_home = path
        cls._logger.debug(
            f"Test home set to: {path}", extra={"component": cls._DEBUG_COMPONENT}
        )

    @classmethod
    def set_test_cwd(cls, path: Optional[Path]) -> None:
        """Überschreibt das aktuelle Arbeitsverzeichnis für Tests."""
        cls._test_cwd = path
        cls._logger.debug(
            f"Test cwd set to: {path}", extra={"component": cls._DEBUG_COMPONENT}
        )

    # -------------------------------------------------------------------------
    # 13. Interne Helfer für Verzeichnis‑Whitelist
    # -------------------------------------------------------------------------
    @classmethod
    def _get_base_dirs(cls) -> List[Path]:
        """Liefert die immer erlaubten Basisverzeichnisse (Home, CWD, tmp, Cache)."""
        with cls._allowed_dirs_lock:
            if cls._base_dirs is None:
                cls._base_dirs = [
                    cls._get_home().resolve(),
                    cls._get_cwd().resolve(),
                    Path(tempfile.gettempdir()).resolve(),
                ]
                cache_dir = cls._get_home() / ".cache" / "dragonwhisperer"
                if cache_dir.exists():
                    cls._base_dirs.append(cache_dir.resolve())
            return cls._base_dirs

    @classmethod
    def _get_allowed_dirs(cls) -> List[Path]:
        """Gibt die Vereinigung von Basis- und Benutzerverzeichnissen zurück."""
        base = cls._get_base_dirs()
        with cls._allowed_dirs_lock:
            return base + cls._user_dirs

    @classmethod
    def _get_home(cls) -> Path:
        """Gibt das Home‑Verzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_home:
            return cls._test_home
        return Path.home()

    @classmethod
    def _get_cwd(cls) -> Path:
        """Gibt das aktuelle Arbeitsverzeichnis zurück (kann für Tests überschrieben werden)."""
        if cls._test_cwd:
            return cls._test_cwd
        return Path.cwd()

    # -------------------------------------------------------------------------
    # 14. Temporäre Verzeichnisse und Dateien (mit Auto-Cleanup)
    # -------------------------------------------------------------------------
    @classmethod
    def get_temp_dir(cls, subfolder: Optional[str] = None) -> Path:
        """
        Gibt ein plattformunabhängiges temporäres Verzeichnis für Dragon Whisperer zurück.

        Das Verzeichnis liegt im System‑Temp‑Pfad und heißt 'dragonwhisperer'.
        Falls ein Unterordner angegeben wird, wird dieser darin erstellt.

        Args:
            subfolder: Optionaler Unterordnername (z. B. "lost_chunks").

        Returns:
            Path zum (ggf. neu erstellten) temporären Verzeichnis.
        """
        base = Path(tempfile.gettempdir()) / "dragonwhisperer"
        base.mkdir(parents=True, exist_ok=True)
        if subfolder:
            target = base / subfolder
            target.mkdir(parents=True, exist_ok=True)
            return target
        return base

    @classmethod
    @contextmanager
    def temporary_directory(
        cls,
        prefix: str = "dw_temp_",
        keep: bool = False,
        cleanup_on_exit: bool = True,
    ) -> Iterator[Path]:
        """
        Kontextmanager für ein temporäres Verzeichnis, das nach Verlassen gelöscht wird.

        Args:
            prefix: Prefix für den Verzeichnisnamen.
            keep: Wenn True, wird das Verzeichnis nach Verlassen des Kontexts nicht gelöscht.
            cleanup_on_exit: Wenn True (und keep=False), wird ein atexit-Handler registriert,
                             der das Verzeichnis auch bei Programmabbruch (z.B. KeyboardInterrupt)
                             zu löschen versucht.

        Yields:
            Path zum erstellten temporären Verzeichnis.
        """
        import atexit
        import shutil
        import tempfile
        from pathlib import Path

        # Temporäres Verzeichnis erstellen
        temp_dir = Path(tempfile.mkdtemp(prefix=prefix))
        log_debug("platform", f"Temporäres Verzeichnis erstellt: {temp_dir}")

        def _cleanup() -> None:
            """Löscht das temporäre Verzeichnis, falls es noch existiert."""
            if not temp_dir.exists():
                return
            try:
                shutil.rmtree(temp_dir, ignore_errors=False)
                log_debug("platform", f"Temporäres Verzeichnis gelöscht: {temp_dir}")
            except PermissionError as e:
                log_debug(
                    "platform", f"Keine Berechtigung zum Löschen von {temp_dir}: {e}"
                )
            except OSError as e:
                log_debug("platform", f"OS-Fehler beim Löschen von {temp_dir}: {e}")
            except Exception as e:
                log_debug(
                    "platform", f"Unerwarteter Fehler beim Löschen von {temp_dir}: {e}"
                )

        # atexit-Handler registrieren, falls gewünscht und Verzeichnis nicht behalten wird
        if cleanup_on_exit and not keep:
            atexit.register(_cleanup)

        try:
            yield temp_dir
        finally:
            if not keep:
                # Entferne den atexit-Handler, um doppeltes Löschen zu vermeiden
                if cleanup_on_exit:
                    try:
                        atexit.unregister(_cleanup)
                    except (AttributeError, Exception):
                        # atexit.unregister existiert erst ab Python 3.7 – ignorieren
                        pass
                # Jetzt sofort löschen
                _cleanup()

    @classmethod
    @contextmanager
    def temporary_file(
        cls,
        suffix: str = ".tmp",
        prefix: str = "dw_",
        dir: Optional[Path] = None,
        text_mode: bool = False,
        encoding: str = "utf-8",
        keep: bool = False,
        cleanup_on_exit: bool = True,
    ) -> Iterator[Path]:
        """
        Kontextmanager für eine temporäre Datei, die nach Verlassen gelöscht wird.

        Args:
            suffix: Dateiendung (z. B. ".txt").
            prefix: Prefix für den Dateinamen.
            dir:    Zielverzeichnis für die temporäre Datei (None = System‑Temp).
            text_mode: Wenn True, wird die Datei im Textmodus geöffnet (Standard: binär).
            encoding:  Kodierung für Textmodus (Standard: utf-8).
            keep:      Wenn True, wird die Datei nach Verlassen des Kontexts nicht gelöscht.
            cleanup_on_exit: Wenn True (und keep=False), wird ein atexit-Handler registriert,
                             der die Datei auch bei Programmabbruch zu löschen versucht.

        Yields:
            Path zur erstellten temporären Datei.
        """
        import atexit
        import tempfile
        from pathlib import Path

        # Temporäre Datei anlegen (binär oder Text)
        if text_mode:
            fd, path = tempfile.mkstemp(
                suffix=suffix, prefix=prefix, dir=dir, text=text_mode
            )
            os.close(fd)
        else:
            fd, path = tempfile.mkstemp(suffix=suffix, prefix=prefix, dir=dir)
            os.close(fd)

        temp_path = Path(path)
        log_debug("platform", f"Temporäre Datei erstellt: {temp_path}")

        def _cleanup() -> None:
            """Löscht die temporäre Datei, falls sie noch existiert."""
            if not temp_path.exists():
                return
            try:
                temp_path.unlink()
                log_debug("platform", f"Temporäre Datei gelöscht: {temp_path}")
            except PermissionError as e:
                log_debug(
                    "platform", f"Keine Berechtigung zum Löschen von {temp_path}: {e}"
                )
            except OSError as e:
                log_debug("platform", f"OS-Fehler beim Löschen von {temp_path}: {e}")
            except Exception as e:
                log_debug(
                    "platform", f"Unerwarteter Fehler beim Löschen von {temp_path}: {e}"
                )

        # atexit-Handler registrieren, falls gewünscht und Datei nicht behalten wird
        if cleanup_on_exit and not keep:
            atexit.register(_cleanup)

        try:
            yield temp_path
        finally:
            if not keep:
                # Entferne den atexit-Handler, um doppeltes Löschen zu vermeiden
                if cleanup_on_exit:
                    try:
                        atexit.unregister(_cleanup)
                    except (AttributeError, Exception):
                        # atexit.unregister existiert erst ab Python 3.7 – ignorieren
                        pass
                # Jetzt sofort löschen
                _cleanup()

    # -------------------------------------------------------------------------
    # 15. Datei-Explorer öffnen
    # -------------------------------------------------------------------------
    @classmethod
    def open_file_explorer(cls, path: Path) -> bool:
        """
        Öffnet den systemeigenen Datei-Explorer (Windows) / Finder (macOS) / Nautilus (Linux)
        am angegebenen Pfad.

        Args:
            path: Das Verzeichnis oder die Datei, die angezeigt werden soll.

        Returns:
            True, wenn der Befehl erfolgreich gestartet wurde, sonst False.
        """
        if not path.exists():
            cls._logger.warning(f"open_file_explorer: Pfad existiert nicht: {path}")
            return False
        try:
            if IS_WINDOWS:
                os.startfile(str(path))
            elif IS_MACOS:
                subprocess.run(["open", str(path)], check=True)
            else:
                # Linux: versuche verschiedene Dateimanager
                for cmd in ["xdg-open", "nautilus", "dolphin", "thunar"]:
                    if shutil.which(cmd):
                        subprocess.run([cmd, str(path)], check=False)
                        break
                else:
                    cls._logger.warning("Kein Dateimanager gefunden.")
                    return False
            cls._logger.debug(f"Datei-Explorer geöffnet: {path}")
            return True
        except Exception as e:
            cls._logger.error(f"Fehler beim Öffnen des Datei-Explorers: {e}")
            return False

    # -------------------------------------------------------------------------
    # 16. Systemkodierung ermitteln
    # -------------------------------------------------------------------------
    @classmethod
    def get_system_encoding(cls) -> str:
        """
        Liefert die vom System bevorzugte Kodierung (für Textdateien etc.).

        Returns:
            String wie 'utf-8', 'cp1252', etc.
        """
        encoding = sys.getfilesystemencoding()
        if not encoding or encoding.lower() in ("ascii", "ansi"):
            return "utf-8"
        return encoding

    @classmethod
    def get_network_interfaces(cls) -> Dict[str, Dict[str, Any]]:
        """
        Gibt Informationen zu den verfügbaren Netzwerkschnittstellen zurück.

        Returns:
            Dict mit Schnittstellennamen als Schlüssel und Details (IP, MAC, etc.).
        """
        interfaces = {}
        try:
            import netifaces

            for iface in netifaces.interfaces():
                addrs = netifaces.ifaddresses(iface)
                interfaces[iface] = {
                    "ipv4": addrs.get(netifaces.AF_INET, [{}])[0].get("addr"),
                    "ipv6": addrs.get(netifaces.AF_INET6, [{}])[0].get("addr"),
                    "mac": addrs.get(netifaces.AF_LINK, [{}])[0].get("addr"),
                }
        except ImportError:
            cls._logger.debug("netifaces not installed – network info limited")
        return interfaces

    _PUBLIC_IP_CACHE_TTL: float = 60.0
    _DEFAULT_IP_SERVICES: ClassVar[List[str]] = [
        "https://api.ipify.org",
        "https://icanhazip.com",
        "https://ifconfig.me/ip",
        "https://checkip.amazonaws.com",
        "https://ipv4.icanhazip.com",
    ]

    @classmethod
    def _fetch_ip_from_service(cls, url: str, timeout: float) -> Optional[str]:
        """
        Fragt einen einzelnen Dienst ab und gibt die IPv4-Adresse zurück.

        Args:
            url: Die Dienst-URL (http oder https).
            timeout: Timeout in Sekunden für die Anfrage.

        Returns:
            Die IPv4-Adresse als String oder None bei Fehler.
        """
        # ── 1. URL-Schema validieren (Sicherheit – behebt Bandit B310) ──
        import urllib.parse

        parsed = urllib.parse.urlparse(url)
        if parsed.scheme not in ("http", "https"):
            cls._logger.debug(
                "Überspringe nicht-http/s URL: %s",
                url,
                extra={"component": "platform"},
            )
            return None

        # ── 2. Anfrage mit `requests` (bevorzugt) oder `urllib` ──────────
        try:
            # 2a. requests verfügbar?
            try:
                import requests

                response = requests.get(
                    url,
                    timeout=timeout,
                    headers={"User-Agent": "DragonWhisperer/4.0"},
                )
                if response.status_code == 200:
                    ip = response.text.strip()
                    # Validierung: nur Ziffern und Punkte (IPv4)
                    if ip and all(c.isdigit() or c == "." for c in ip):
                        return ip
                return None
            except ImportError:
                # 2b. Fallback: urllib.request
                import urllib.request

                req = urllib.request.Request(
                    url,
                    headers={"User-Agent": "DragonWhisperer/4.0"},
                )
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    if resp.status == 200:
                        ip = resp.read().decode("utf-8").strip()
                        if ip and all(c.isdigit() or c == "." for c in ip):
                            return ip
                return None
        except Exception as e:
            cls._logger.debug(
                "Fehler bei %s: %s",
                url,
                e,
                extra={"component": "platform"},
            )
            return None

    @classmethod
    def get_public_ip(
        cls,
        timeout: float = 5.0,
        use_cache: bool = True,
        services: Optional[List[str]] = None,
        max_workers: Optional[int] = None,
    ) -> Optional[str]:
        """
        Ermittelt die öffentliche IPv4-Adresse über externe Dienste (parallel).

        Die Methode fragt mehrere Dienste parallel ab und verwendet das erste
        erfolgreiche Ergebnis.  Das Ergebnis wird für 60 Sekunden gecacht.

        Verbesserungen gegenüber der ursprünglichen Version:
        - Parallele Abfragen (ThreadPoolExecutor) für minimale Latenz.
        - Sichere URL-Validierung (nur http/https) – behebt Bandit B310.
        - Erweiterte Dienstliste (inkl. checkip.amazonaws.com).
        - Konfigurierbare Dienstliste und maximale Worker-Anzahl.
        - Robuste Fehlerbehandlung mit detailliertem, aber nicht übermäßigem Logging.
        - Automatische Fallback auf urllib, falls requests nicht installiert ist.
        - Cache mit konfigurierbarer TTL (Klassenkonstante).

        Args:
            timeout: Timeout in Sekunden pro Anfrage (Standard 5.0).
            use_cache: Ob der Cache verwendet werden soll (Standard True).
            services: Optionale Liste von Dienst-URLs (überschreibt die Standardliste).
            max_workers: Maximale Anzahl paralleler Worker (Standard = Anzahl der Dienste).

        Returns:
            Die öffentliche IPv4-Adresse als String oder None bei Fehlschlag.
        """
        # ── 1. Cache-Prüfung ──────────────────────────────────────────────────
        if use_cache:
            now = time.monotonic()
            if hasattr(cls, "_public_ip_cache") and hasattr(
                cls, "_public_ip_cache_time"
            ):
                if (
                    cls._public_ip_cache is not None
                    and (now - cls._public_ip_cache_time) < cls._PUBLIC_IP_CACHE_TTL
                ):
                    cls._logger.debug(
                        "get_public_ip: Cache-Treffer (IP=%s, age=%.1fs)",
                        cls._public_ip_cache,
                        now - cls._public_ip_cache_time,
                        extra={"component": "platform"},
                    )
                    return cls._public_ip_cache
            else:
                # Cache initialisieren
                cls._public_ip_cache = None
                cls._public_ip_cache_time = 0.0

        # ── 2. Dienstliste festlegen ──────────────────────────────────────────
        services_to_try = services or cls._DEFAULT_IP_SERVICES
        if not services_to_try:
            cls._logger.warning(
                "get_public_ip: Keine Dienste zum Abfragen.",
                extra={"component": "platform"},
            )
            return None

        max_workers = max_workers or min(len(services_to_try), 4)
        cls._logger.debug(
            "get_public_ip: Starte parallele Abfrage von %d Diensten (max_workers=%d)",
            len(services_to_try),
            max_workers,
            extra={"component": "platform"},
        )

        # ── 3. Parallele Anfragen ─────────────────────────────────────────────
        from concurrent.futures import ThreadPoolExecutor, as_completed

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            # Futures für alle Dienste starten
            future_to_url = {
                executor.submit(cls._fetch_ip_from_service, url, timeout): url
                for url in services_to_try
            }

            # Ergebnisse auswerten (sobald sie fertig sind)
            for future in as_completed(future_to_url):
                url = future_to_url[future]
                try:
                    ip = future.result(timeout=timeout + 1.0)  # zusätzlicher Puffer
                    if ip:
                        cls._logger.debug(
                            "get_public_ip: Erfolg über %s (IP=%s)",
                            url,
                            ip,
                            extra={"component": "platform"},
                        )
                        if use_cache:
                            cls._public_ip_cache = ip
                            cls._public_ip_cache_time = time.monotonic()
                        return ip
                    else:
                        cls._logger.debug(
                            "get_public_ip: %s lieferte keine gültige IP",
                            url,
                            extra={"component": "platform"},
                        )
                except Exception as e:
                    cls._logger.debug(
                        "get_public_ip: Fehler bei %s – %s",
                        url,
                        e,
                        extra={"component": "platform"},
                    )

        # ── 4. Alle Dienste fehlgeschlagen ──────────────────────────────────
        cls._logger.warning(
            "get_public_ip: Alle Dienste fehlgeschlagen.",
            extra={"component": "platform"},
        )
        return None


    @classmethod
    def safe_exec(
        cls,
        cmd: Union[List[str], str],
        timeout: float = 30.0,
        env: Optional[Dict[str, str]] = None,
        sanitize_env: bool = True,
        input_data: Optional[str] = None,
        cancel_event: Optional[threading.Event] = None,
    ) -> Tuple[int, str, str]:
        """
        Führt einen externen Befehl sicher aus, ohne Risiko von Shell‑Injection.

        Args:
            cmd:         Befehlsliste (bevorzugt) oder String (wird mit shlex.split
                         in eine Liste zerlegt – dabei wird eine Warnung ausgegeben).
            timeout:     Timeout in Sekunden (0 = kein Timeout).
            env:         Optionales Umgebungs‑Dictionary. Wenn None,
                         wird die aktuelle Umgebung verwendet (ggf. bereinigt).
            sanitize_env: Wenn True, werden potenziell gefährliche
                         Umgebungsvariablen (PYTHONPATH, LD_PRELOAD, …)
                         aus der Umgebung entfernt, sofern sie nicht
                         explizit in `env` gesetzt sind.
            input_data:  Optionaler String, der an stdin des Subprozesses gesendet wird.
            cancel_event: Optionales Event, das bei Setzen den Prozess vorzeitig
                         abbricht (wird während der Ausführung regelmäßig geprüft).

        Returns:
            Tuple[int, str, str]: (returncode, stdout, stderr).
            Bei Timeout oder Abbruch: returncode = -1, stderr enthält die Ursache.
        """
        import shlex
        import time

        # ── 1. Eingabe validieren und normalisieren ──────────────────────
        if isinstance(cmd, str):
            logger.warning(
                "safe_exec: cmd als String übergeben – dies wird nicht empfohlen. "
                "Verwenden Sie stattdessen eine Liste von Argumenten."
            )
            cmd = shlex.split(cmd)
        elif not isinstance(cmd, (list, tuple)):
            raise TypeError("cmd muss eine Liste oder ein String sein")

        if not cmd:
            raise ValueError("cmd darf nicht leer sein")

        # ── 2. Umgebung vorbereiten ────────────────────────────────────
        effective_env = env if env is not None else os.environ.copy()
        if sanitize_env:
            dangerous_vars = [
                "PYTHONPATH",
                "PYTHONHOME",
                "LD_PRELOAD",
                "LD_LIBRARY_PATH",
                "PYTHONWARNINGS",
                "PYTHONHASHSEED",
            ]
            for var in dangerous_vars:
                if var in effective_env and var not in (env or {}):
                    log_debug("safe_exec", f"Entferne gefährliche Variable: {var}")
                    del effective_env[var]

        # ── 3. Plattformspezifische Argumente für subprocess ────────────
        creationflags, start_new_session = cls._get_subprocess_flags()

        # ── 4. Befehl ausführen (mit Timeout und Abbruchunterstützung) ──
        cmd_str = " ".join(cmd) if isinstance(cmd, list) else cmd
        log_debug("safe_exec", f"Befehl: {cmd_str}")

        start_time = time.perf_counter()
        proc = None

        try:
            # Verwende Popen für bessere Kontrolle (cancel_event)
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                stdin=subprocess.PIPE if input_data is not None else subprocess.DEVNULL,
                text=True,
                encoding="utf-8",
                errors="replace",
                env=effective_env,
                creationflags=creationflags,
                start_new_session=start_new_session,
                shell=False,  # ★ explizit False – sicher ★
            )

            # ── 5. Warten mit regelmäßiger Abbruchprüfung ──────────────
            deadline = time.time() + timeout if timeout > 0 else float("inf")
            poll_interval = 0.2
            stdout_parts: List[str] = []
            stderr_parts: List[str] = []

            # stdin-Daten senden (falls vorhanden)
            if input_data is not None and proc.stdin is not None:
                try:
                    proc.stdin.write(input_data)
                    proc.stdin.close()
                except (BrokenPipeError, OSError) as e:
                    log_debug("safe_exec", f"stdin write failed: {e}")

            while True:
                if cancel_event is not None and cancel_event.is_set():
                    log_debug("safe_exec", "Abbruch durch cancel_event")
                    if proc.poll() is None:
                        proc.terminate()
                        try:
                            proc.wait(timeout=1.0)
                        except subprocess.TimeoutExpired:
                            proc.kill()
                            proc.wait(timeout=0.5)
                    return -1, "", "Cancelled by user"

                if timeout > 0 and time.time() >= deadline:
                    log_debug("safe_exec", f"Timeout nach {timeout}s")
                    if proc.poll() is None:
                        proc.terminate()
                        try:
                            proc.wait(timeout=1.0)
                        except subprocess.TimeoutExpired:
                            proc.kill()
                            proc.wait(timeout=0.5)
                    return -1, "", f"Timeout after {timeout}s"

                # Prüfe, ob Prozess beendet ist
                if proc.poll() is not None:
                    # Restliche Ausgaben lesen
                    stdout, stderr = proc.communicate(timeout=1.0)
                    if stdout:
                        stdout_parts.append(stdout)
                    if stderr:
                        stderr_parts.append(stderr)
                    break

                time.sleep(poll_interval)

            elapsed_ms = (time.perf_counter() - start_time) * 1000
            log_debug(
                "safe_exec",
                f"Beendet in {elapsed_ms:.1f} ms, Rückgabewert {proc.returncode}",
            )

            stdout_str = "".join(stdout_parts).strip()
            stderr_str = "".join(stderr_parts).strip()
            return proc.returncode, stdout_str, stderr_str

        except FileNotFoundError as e:
            log_debug("safe_exec", f"Datei nicht gefunden: {e}")
            return -1, "", f"File not found: {e}"
        except PermissionError as e:
            log_debug("safe_exec", f"Keine Ausführungsberechtigung: {e}")
            return -1, "", f"Permission denied: {e}"
        except Exception as e:
            log_debug("safe_exec", f"Unerwarteter Fehler: {e}")
            return -1, "", str(e)
        finally:
            # Sicherheitshalber Prozess killen, falls noch am Leben
            if proc is not None and proc.poll() is None:
                try:
                    proc.kill()
                    proc.wait(timeout=0.5)
                except Exception:
                    pass

    @classmethod
    def _get_subprocess_flags(cls) -> Tuple[int, bool]:
        """
        Gibt plattformspezifische Flags für subprocess.Popen zurück.
        Returns:
            Tuple[int, bool]: (creationflags, start_new_session)
        """
        if IS_WINDOWS:
            return subprocess.CREATE_NO_WINDOW, False
        else:
            return 0, True

    @classmethod
    def sanitize_environment(cls, keep_vars: Optional[List[str]] = None) -> None:
        """
        Entfernt potenziell gefährliche Umgebungsvariablen (z. B. PYTHONPATH, LD_PRELOAD).
        Kann vor dem Start von Subprozessen aufgerufen werden.

        Args:
            keep_vars: Liste von Variablen, die erhalten bleiben sollen.
        """
        dangerous = [
            "PYTHONPATH",
            "PYTHONHOME",
            "LD_PRELOAD",
            "LD_LIBRARY_PATH",
            "PYTHONWARNINGS",
            "PYTHONHASHSEED",
        ]
        keep = set(keep_vars or [])
        for var in dangerous:
            if var in os.environ and var not in keep:
                cls._logger.debug(f"Removing dangerous env var: {var}")
                del os.environ[var]

    @classmethod
    def is_admin(cls) -> bool:
        """
        Prüft, ob das Programm mit Administratorrechten (Windows) / root (Linux/macOS) läuft.

        Returns:
            True, wenn das Programm erhöhte Privilegien besitzt, sonst False.
        """
        try:
            if IS_WINDOWS:
                import ctypes

                return ctypes.windll.shell32.IsUserAnAdmin() != 0
            else:
                return os.geteuid() == 0
        except Exception as e:
            _safe_log_debug("platform", f"is_admin() failed: {e}")
            return False

    @classmethod
    def restart_as_admin(cls, args: Optional[List[str]] = None) -> None:
        """
        Startet das Programm mit Administratorrechten neu (nur Windows).

        Diese Methode beendet den aktuellen Prozess und startet ein neues Fenster
        mit erhöhten Rechten. Auf Unix‑Systemen wird nichts getan (dort wird ein
        manuelles 'sudo' vorausgesetzt).  Die Methode ist vollständig defensiv
        und protokolliert alle Fehler, ohne den aktuellen Prozess zu gefährden.

        Args:
            args: Optionale Liste zusätzlicher Kommandozeilenargumente für den Neustart.
                  Wenn None, werden die ursprünglichen sys.argv[1:] verwendet.
        """
        import shlex

        # ── 1. Nur unter Windows sinnvoll ──────────────────────────────
        if not IS_WINDOWS:
            logger.info("restart_as_admin: Nur unter Windows verfügbar – überspringe.")
            return

        # ── 2. Rekursionsschutz: bereits laufender Neustart? ──────────
        if (
            hasattr(cls, "_admin_restart_in_progress")
            and cls._admin_restart_in_progress
        ):
            logger.warning(
                "restart_as_admin: Ein Neustart ist bereits im Gange – "
                "überspringe, um eine Schleife zu vermeiden."
            )
            return

        # ── 3. Parameter vorbereiten ───────────────────────────────────
        script = os.path.abspath(sys.argv[0])
        params = sys.argv[1:] if args is None else args

        # Keine Argumente? Dann leeren String verwenden.
        if params:
            # Verwende shlex.quote für sicheres Quoten, insbesondere bei Leerzeichen
            param_str = " ".join(shlex.quote(p) for p in params)
        else:
            param_str = ""

        # Vollständige Befehlszeile für das neue Fenster
        # Das erste Argument nach dem Programm muss der Skriptname sein.
        command_line = f'"{script}" {param_str}'.strip()

        # ── 4. Versuch 1: ShellExecuteW (standard runas) ───────────────
        try:
            import ctypes

            # ShellExecuteW Prototyp:
            # HINSTANCE ShellExecuteW(
            #   HWND    hwnd,
            #   LPCWSTR lpOperation,
            #   LPCWSTR lpFile,
            #   LPCWSTR lpParameters,
            #   LPCWSTR lpDirectory,
            #   INT     nShowCmd
            # );
            ctypes.windll.shell32.ShellExecuteW(
                None,  # hwnd (kein Elternfenster)
                "runas",  # lpOperation → Adminrechte anfordern
                sys.executable,  # lpFile → Python‑Interpreter
                command_line,  # lpParameters → Skript + Argumente
                None,  # lpDirectory (aktuelles Verzeichnis)
                1,  # nShowCmd (SW_SHOWNORMAL = 1)
            )
            cls._admin_restart_in_progress = True
            logger.info(
                "✅ Neustart mit Adminrechten angefordert (ShellExecuteW). "
                "Beende aktuellen Prozess in 0,5 s..."
            )
            # Kurze Verzögerung, damit das neue Fenster Zeit zum Starten hat
            time.sleep(0.5)
            sys.exit(0)

        except AttributeError:
            logger.error(
                "restart_as_admin: ShellExecuteW nicht verfügbar – "
                "ctypes möglicherweise fehlerhaft."
            )
        except Exception as e:
            logger.warning(
                f"restart_as_admin: ShellExecuteW fehlgeschlagen: {e}. "
                "Versuche PowerShell‑Fallback..."
            )

        # ── 5. Versuch 2: PowerShell Start-Process mit -Verb RunAs ──────
        try:
            # PowerShell‑Befehl: Start-Process -FilePath ... -ArgumentList ... -Verb RunAs
            # Erstelle eine temporäre PS‑Skriptdatei, um lange Befehlszeilen zu umgehen
            import tempfile

            ps_script_content = f"""
            Start-Process -FilePath '{sys.executable}' `
                -ArgumentList '{command_line}' `
                -Verb RunAs -WindowStyle Normal
            """
            with tempfile.NamedTemporaryFile(
                mode="w",
                suffix=".ps1",
                delete=False,
                encoding="utf-8",
            ) as f:
                f.write(ps_script_content)
                ps_script_path = f.name

            # PowerShell ausführen, um das Skript zu starten
            subprocess.run(
                ["powershell", "-ExecutionPolicy", "Bypass", "-File", ps_script_path],
                check=False,
                capture_output=True,
                timeout=10,
            )
            # Temporäre Datei löschen (nach einer kurzen Pause, damit der Start Zeit hat)
            time.sleep(0.3)
            try:
                os.unlink(ps_script_path)
            except Exception:
                pass

            cls._admin_restart_in_progress = True
            logger.info(
                "✅ Neustart mit Adminrechten angefordert (PowerShell). "
                "Beende aktuellen Prozess in 0,5 s..."
            )
            time.sleep(0.5)
            sys.exit(0)

        except Exception as e:
            logger.error(
                f"restart_as_admin: Auch PowerShell‑Fallback fehlgeschlagen: {e}"
            )
            # Keine weiteren Versuche – benachrichtige den Benutzer
            try:
                import ctypes

                ctypes.windll.user32.MessageBoxW(
                    0,
                    f"Neustart mit Administratorrechten fehlgeschlagen:\n{e}\n\n"
                    "Bitte starten Sie das Programm manuell als Administrator.",
                    "Neustart fehlgeschlagen",
                    0x10,  # MB_ICONERROR
                )
            except Exception:
                pass

    @classmethod
    def get_desktop_environment(cls) -> str:
        """
        Ermittelt die aktuelle Desktop‑Umgebung (Linux, macOS, Windows).

        Returns:
            String mit dem Namen der Desktop-Umgebung (klein geschrieben) oder
            "unknown" (Linux), "macos", "windows".
        """
        if IS_WINDOWS:
            return "windows"
        if IS_MACOS:
            return "macos"
        if not IS_LINUX:
            return "unknown"
        de = os.environ.get("XDG_CURRENT_DESKTOP", "")
        if de:
            first = de.split(":", 1)[0].strip().lower()
            if first:
                return first
        de = os.environ.get("DESKTOP_SESSION", "")
        if de:
            return os.path.basename(de).lower()
        if "GNOME_DESKTOP_SESSION_ID" in os.environ:
            return "gnome"
        if "KDE_FULL_SESSION" in os.environ:
            return "kde"
        if "XFCE_VERSION" in os.environ:
            return "xfce"
        if "LXQT_SESSION_CONFIG" in os.environ:
            return "lxqt"
        if "LXDE_SESSION" in os.environ:
            return "lxde"
        if "MATE_DESKTOP_SESSION_ID" in os.environ:
            return "mate"
        if "CINNAMON_VERSION" in os.environ:
            return "cinnamon"
        if "BUDGIE_DESKTOP" in os.environ:
            return "budgie"
        if "SWAYSOCK" in os.environ:
            return "sway"
        if "HYPRLAND_INSTANCE_SIGNATURE" in os.environ:
            return "hyprland"
        if "I3SOCK" in os.environ or "I3_CONFIG_FILE" in os.environ:
            return "i3"
        session_type = os.environ.get("XDG_SESSION_TYPE", "").lower()
        if session_type in ("x11", "wayland"):
            return session_type
        return "unknown"

    # -------------------------------------------------------------------------
    # 19. Weitere nützliche Helfer (Hardware, System)
    # -------------------------------------------------------------------------
    @classmethod
    def get_cpu_model(cls) -> str:
        """
        Ermittelt das CPU‑Modell (ohne psutil, nur Standardbibliothek).

        Returns:
            String mit dem CPU‑Modell oder "unknown".
        """
        if IS_WINDOWS:
            try:
                import winreg

                key = winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"HARDWARE\DESCRIPTION\System\CentralProcessor\0",
                )
                name, _ = winreg.QueryValueEx(key, "ProcessorNameString")
                return name.strip()
            except Exception:
                try:
                    import platform

                    return platform.processor() or "unknown"
                except Exception:
                    return "unknown"
        elif IS_MACOS:
            try:
                result = subprocess.run(
                    ["sysctl", "-n", "machdep.cpu.brand_string"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                )
                if result.returncode == 0 and result.stdout.strip():
                    return result.stdout.strip()
            except Exception:
                pass
            return "Apple" if IS_ARM else "Intel Mac"
        else:  # Linux
            try:
                with open("/proc/cpuinfo", "r") as f:
                    for line in f:
                        if "model name" in line:
                            return line.split(":", 1)[1].strip()
            except Exception:
                pass
            try:
                result = subprocess.run(
                    ["lscpu", "-J"], capture_output=True, text=True, timeout=2
                )
                if result.returncode == 0:
                    import json

                    data = json.loads(result.stdout)
                    for item in data.get("lscpu", []):
                        if item.get("field", "") == "Model name":
                            return item.get("data", "unknown")
            except Exception:
                pass
        return "unknown"

    @classmethod
    def get_total_ram_gb(cls) -> float:
        """Ermittelt den gesamten Arbeitsspeicher in Gigabyte (ohne psutil)."""
        try:
            if IS_WINDOWS:
                import ctypes

                kernel32 = ctypes.windll.kernel32

                class MEMORYSTATUSEX(ctypes.Structure):
                    _fields_ = [
                        ("dwLength", ctypes.c_ulong),
                        ("dwMemoryLoad", ctypes.c_ulong),
                        ("ullTotalPhys", ctypes.c_ulonglong),
                        ("ullAvailPhys", ctypes.c_ulonglong),
                        ("ullTotalPageFile", ctypes.c_ulonglong),
                        ("ullAvailPageFile", ctypes.c_ulonglong),
                        ("ullTotalVirtual", ctypes.c_ulonglong),
                        ("ullAvailVirtual", ctypes.c_ulonglong),
                        ("ullAvailExtendedVirtual", ctypes.c_ulonglong),
                    ]

                mem = MEMORYSTATUSEX()
                mem.dwLength = ctypes.sizeof(mem)
                if kernel32.GlobalMemoryStatusEx(ctypes.byref(mem)):
                    return mem.ullTotalPhys / (1024**3)
            elif IS_MACOS:
                result = subprocess.run(
                    ["sysctl", "-n", "hw.memsize"],
                    capture_output=True,
                    text=True,
                    timeout=2,
                )
                if result.returncode == 0:
                    return int(result.stdout.strip()) / (1024**3)
            else:  # Linux
                with open("/proc/meminfo", "r") as f:
                    for line in f:
                        if "MemTotal" in line:
                            kb = int(line.split()[1])
                            return kb / (1024 * 1024)
        except Exception:
            pass
        return 0.0

    @classmethod
    def get_free_disk_gb(cls, path: str = "/") -> float:
        """Ermittelt den freien Speicherplatz auf einem Laufwerk in GB."""
        try:
            usage = shutil.disk_usage(path)
            return usage.free / (1024**3)
        except Exception:
            return 0.0

    @classmethod
    def get_username(cls) -> str:
        """Gibt den aktuellen Benutzernamen zurück."""
        try:
            return os.getlogin()
        except Exception:
            return os.environ.get("USER", os.environ.get("USERNAME", "unknown"))

    @classmethod
    def get_hostname(cls) -> str:
        """Gibt den Hostnamen des Systems zurück."""
        try:
            return socket.gethostname()
        except Exception:
            return "unknown"

    @classmethod
    def get_timezone(cls) -> str:
        """Ermittelt die aktuelle Zeitzone (als IANA‑Name oder UTC±Offset)."""
        try:
            import time

            if time.daylight:
                offset = time.altzone
            else:
                offset = time.timezone
            return f"UTC{offset//3600:+d}"
        except Exception:
            return "unknown"

    # -------------------------------------------------------------------------
    # 20. Netzwerk‑ und System‑Helfer
    # -------------------------------------------------------------------------
    @classmethod
    def open_url(cls, url: str) -> bool:
        """Öffnet eine URL im Standardbrowser."""
        try:
            import webbrowser

            webbrowser.open(url)
            return True
        except Exception as e:
            cls._logger.warning(f"Failed to open URL {url}: {e}")
            return False

    @classmethod
    def show_notification(
        cls,
        title: str,
        message: str,
        timeout: int = 5,
        parent: Optional[tk.Tk] = None,
    ) -> bool:
        """
        Zeigt eine Desktop‑Benachrichtigung an (falls möglich).

        Verwendet:
          - Windows: win10toast (falls installiert)
          - macOS:   pyobjc (NSUserNotification)
          - Linux:   notify-send (falls im PATH)

        Falls keine der Methoden verfügbar ist, wird die Meldung über
        print() ausgegeben (nur bei DEBUG_LEVEL >= 1).

        Args:
            title:    Titel der Benachrichtigung
            message:  Text der Benachrichtigung
            timeout:  Dauer in Sekunden, für die die Benachrichtigung
                      angezeigt wird (wird vom jeweiligen Backend
                      bestmöglich unterstützt)
            parent:   Optionales parent‑Widget für GUI‑Fallbacks
                      (derzeit ungenutzt)

        Returns:
            True, wenn die Benachrichtigung erfolgreich gesendet wurde,
            False im Fehlerfall oder wenn kein Backend verfügbar ist.
        """
        # ------------------------------------------------------------------
        # 1. Plattform und grundlegende Verfügbarkeit ermitteln
        # ------------------------------------------------------------------
        if not title or not message:
            log_debug("notify", "show_notification: title oder message leer")
            return False

        # ------------------------------------------------------------------
        # 2. Windows – win10toast
        # ------------------------------------------------------------------
        if IS_WINDOWS:
            try:
                from win10toast import ToastNotifier

                toaster = ToastNotifier()
                # Win10toast verwendet `duration` in Sekunden,
                # Standard ist 5, maximale Dauer ist ca. 30 s.
                toaster.show_toast(
                    title,
                    message,
                    duration=timeout,
                    threaded=True,
                )
                log_debug("notify", "Windows‑Benachrichtigung gesendet")
                return True
            except ImportError:
                log_debug("notify", "win10toast nicht installiert")
            except Exception as e:
                log_debug("notify", f"win10toast Fehler: {e}")

        # ------------------------------------------------------------------
        # 3. macOS – NSUserNotification (pyobjc)
        # ------------------------------------------------------------------
        elif IS_MACOS:
            try:
                from Foundation import NSUserNotification, NSUserNotificationCenter

                notification = NSUserNotification.alloc().init()
                notification.setTitle_(title)
                notification.setInformativeText_(message)
                # Zeitstempel für sofortige Anzeige
                notification.setDeliveryDate_(None)
                # Timeout kann bei NSUserNotification nicht direkt gesetzt werden;
                # die Benachrichtigung verschwindet nach einigen Sekunden automatisch.
                NSUserNotificationCenter.defaultUserNotificationCenter().scheduleNotification_(
                    notification
                )
                log_debug("notify", "macOS‑Benachrichtigung gesendet")
                return True
            except ImportError:
                log_debug("notify", "pyobjc (Foundation) nicht installiert")
            except Exception as e:
                log_debug("notify", f"macOS‑Benachrichtigungsfehler: {e}")

        # ------------------------------------------------------------------
        # 4. Linux – notify-send
        # ------------------------------------------------------------------
        else:  # Linux / andere Unix‑ähnliche Systeme
            # notify-send im Pfad?
            if shutil.which("notify-send") is None:
                log_debug("notify", "notify-send nicht im PATH")
            else:
                try:
                    # Timeout in Millisekunden
                    timeout_ms = int(timeout * 1000)
                    # -u critical sorgt für höhere Dringlichkeit, bleibt aber länger
                    # Wir verwenden -t für die Zeitüberschreitung.
                    subprocess.run(
                        [
                            "notify-send",
                            "-t",
                            str(timeout_ms),
                            title,
                            message,
                        ],
                        check=False,
                        capture_output=True,
                        timeout=timeout + 2,
                    )
                    log_debug("notify", "Linux‑Benachrichtigung gesendet")
                    return True
                except Exception as e:
                    log_debug("notify", f"notify-send Fehler: {e}")

        # ------------------------------------------------------------------
        # 5. Fallback: Ausgabe auf die Konsole (nur bei aktivem Debug)
        # ------------------------------------------------------------------
        if DEBUG_LEVEL >= 1 or "notify" in DEBUG_COMPONENTS:
            log_debug(
                "notify",
                f"Desktop‑Benachrichtigung nicht möglich – "
                f"Konsole: [{title}] {message}",
            )
        # Für den Benutzer, falls die GUI läuft, könnte man ein tkMessageBox
        # anzeigen, aber das würde den Benutzer stören. Daher unterlassen.
        return False

    @classmethod
    def get_installed_fonts(cls) -> List[str]:
        """
        Gibt eine Liste der systemweit installierten Schriftarten zurück (Caching empfohlen).
        Keine externe Abhängigkeit – nur Standardbibliotheken.
        """
        fonts = []
        try:
            if IS_WINDOWS:
                import winreg

                key = winreg.OpenKey(
                    winreg.HKEY_LOCAL_MACHINE,
                    r"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts",
                )
                i = 0
                while True:
                    try:
                        name, _, _ = winreg.EnumValue(key, i)
                        if name.lower().endswith((".ttf", ".otf")):
                            fonts.append(name.rsplit("(", 1)[0].strip())
                        i += 1
                    except OSError:
                        break
            elif IS_MACOS:
                fonts_dir = Path("/System/Library/Fonts/")
                if fonts_dir.exists():
                    fonts.extend([f.stem for f in fonts_dir.glob("*.ttf")])
                    fonts.extend([f.stem for f in fonts_dir.glob("*.otf")])
            else:
                # Linux: fc-list (falls verfügbar)
                if shutil.which("fc-list"):
                    result = subprocess.run(
                        ["fc-list", ":", "family"],
                        capture_output=True,
                        text=True,
                        timeout=5,
                    )
                    if result.returncode == 0:
                        for line in result.stdout.splitlines():
                            family = line.split(":", 1)[0].strip()
                            if family:
                                fonts.append(family)
                else:
                    # Fallback: /usr/share/fonts
                    fonts_dir = Path("/usr/share/fonts")
                    if fonts_dir.exists():
                        for f in fonts_dir.rglob("*.ttf"):
                            fonts.append(f.stem)
                        for f in fonts_dir.rglob("*.otf"):
                            fonts.append(f.stem)
        except Exception as e:
            cls._logger.debug(f"Font detection failed: {e}")
        return sorted(set(fonts))

    @classmethod
    def is_internet_available(
        cls,
        test_url: str = "https://1.1.1.1",
        timeout: float = 3.0,
        use_cache: bool = True,
        cache_ttl: float = 10.0,
    ) -> bool:
        """
        Prüft, ob eine Internetverbindung besteht, indem eine HTTP‑Anfrage an einen
        zuverlässigen Server gesendet wird.

        Args:
            test_url:   URL, die für den Test verwendet wird (Standard: Cloudflare DNS 1.1.1.1).
            timeout:    Timeout in Sekunden für die Anfrage.
            use_cache:  Wenn True, wird ein zwischengespeichertes Ergebnis verwendet,
                        solange es nicht älter als `cache_ttl` Sekunden ist.
            cache_ttl:  Gültigkeitsdauer des Caches in Sekunden (nur wenn use_cache=True).

        Returns:
            True, wenn eine Internetverbindung besteht, sonst False.
        """
        # ── 1. Cache‑Prüfung ─────────────────────────────────────────────
        if use_cache:
            now = time.monotonic()
            if hasattr(cls, "_internet_cache") and hasattr(cls, "_internet_cache_time"):
                if (now - cls._internet_cache_time) < cache_ttl:
                    cls._logger.debug(
                        "is_internet_available: Cache‑Treffer (available=%s, age=%.1fs)",
                        cls._internet_cache,
                        now - cls._internet_cache_time,
                        extra={"component": "platform"},
                    )
                    return cls._internet_cache
            else:
                # Cache initialisieren
                cls._internet_cache = None
                cls._internet_cache_time = 0.0

        # ── 2. Verfügbarkeit von `requests` prüfen ───────────────────────
        try:
            import requests

            _requests_available = True
        except ImportError:
            _requests_available = False
            cls._logger.debug(
                "is_internet_available: requests nicht installiert – verwende urllib",
                extra={"component": "platform"},
            )

        # ── 3. Test durchführen ──────────────────────────────────────────
        available = False
        try:
            if _requests_available:
                response = requests.get(test_url, timeout=timeout)
                available = response.status_code == 200
                if available:
                    cls._logger.debug(
                        "is_internet_available: erfolgreich über requests (HTTP %d)",
                        response.status_code,
                        extra={"component": "platform"},
                    )
                else:
                    cls._logger.debug(
                        "is_internet_available: requests lieferte HTTP %d",
                        response.status_code,
                        extra={"component": "platform"},
                    )
            else:
                # Fallback mit urllib.request
                import urllib.request

                req = urllib.request.Request(
                    test_url,
                    headers={"User-Agent": "DragonWhisperer/4.0"},
                )
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    available = resp.status == 200
                    cls._logger.debug(
                        "is_internet_available (urllib): HTTP %d",
                        resp.status,
                        extra={"component": "platform"},
                    )
        except (urllib.error.URLError, urllib.error.HTTPError) as e:
            cls._logger.debug(
                "is_internet_available: urllib‑Fehler – %s",
                str(e),
                extra={"component": "platform"},
            )
        except Exception as e:
            cls._logger.debug(
                "is_internet_available: unerwarteter Fehler – %s",
                str(e),
                extra={"component": "platform"},
            )

        # ── 4. Cache aktualisieren ───────────────────────────────────────
        if use_cache:
            cls._internet_cache = available
            cls._internet_cache_time = time.monotonic()

        return available

    # -------------------------------------------------------------------------
    # 21. Schlüsselbund (keyring) – optional
    # -------------------------------------------------------------------------
    @classmethod
    def save_password(cls, service: str, username: str, password: str) -> bool:
        """Speichert ein Passwort sicher im systeminternen Schlüsselbund (erfordert 'keyring')."""
        try:
            import keyring

            keyring.set_password(service, username, password)
            return True
        except ImportError:
            cls._logger.debug("keyring not installed – password not saved")
            return False
        except Exception as e:
            cls._logger.warning(f"Failed to save password: {e}")
            return False

    @classmethod
    def get_password(cls, service: str, username: str) -> Optional[str]:
        """Ruft ein Passwort aus dem Schlüsselbund ab."""
        try:
            import keyring

            return keyring.get_password(service, username)
        except ImportError:
            cls._logger.debug("keyring not installed – cannot retrieve password")
            return None
        except Exception as e:
            cls._logger.warning(f"Failed to get password: {e}")
            return None

    @classmethod
    def delete_password(cls, service: str, username: str) -> bool:
        """Löscht ein Passwort aus dem Schlüsselbund."""
        try:
            import keyring

            keyring.delete_password(service, username)
            return True
        except ImportError:
            cls._logger.debug("keyring not installed – password not deleted")
            return False
        except Exception as e:
            cls._logger.warning(f"Failed to delete password: {e}")
            return False

    # -------------------------------------------------------------------------
    # 22. Verknüpfungen (Shortcuts)
    # -------------------------------------------------------------------------
    @classmethod
    def create_shortcut(
        cls,
        target: Path,
        link_path: Path,
        description: str = "",
        arguments: str = "",
        working_dir: Optional[Path] = None,
        icon_path: Optional[Path] = None,
        use_terminal: bool = False,
    ) -> bool:
        """
        Erstellt eine Verknüpfung (Windows: .lnk, Linux: .desktop, macOS: .app / .webloc? – teilweise).

        Returns:
            True bei Erfolg, sonst False.
        """
        import shlex

        # ── 1. Ziel existiert? ──────────────────────────────────────────
        if not target.exists():
            cls._logger.warning(
                f"create_shortcut: Ziel existiert nicht: {target}",
                extra={"component": "platform"},
            )
            return False

        # ── 2. Zielverzeichnis für die Verknüpfung erstellen ────────────
        try:
            link_path.parent.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            cls._logger.error(
                f"create_shortcut: Verzeichnis für Verknüpfung konnte nicht erstellt werden: {e}",
                extra={"component": "platform"},
            )
            return False

        # ── 3. Plattformspezifische Erstellung ──────────────────────────
        try:
            if IS_WINDOWS:
                # Windows: .lnk mit WScript.Shell
                try:
                    from win32com.client import Dispatch
                except ImportError:
                    cls._logger.warning(
                        "create_shortcut: pywin32 nicht installiert – "
                        "Windows‑Verknüpfungen können nicht erstellt werden. "
                        "Installieren Sie mit: pip install pywin32",
                        extra={"component": "platform"},
                    )
                    return False

                shell = Dispatch("WScript.Shell")
                shortcut = shell.CreateShortCut(str(link_path))

                # Ziel und Argumente (mit korrekter Behandlung von Leerzeichen)
                shortcut.Targetpath = str(target)
                if arguments:
                    shortcut.Arguments = arguments

                if working_dir:
                    shortcut.WorkingDirectory = str(working_dir)

                if icon_path and icon_path.exists():
                    shortcut.IconLocation = str(icon_path)

                if description:
                    shortcut.Description = description

                shortcut.save()
                cls._logger.debug(
                    f"Windows‑Verknüpfung erstellt: {link_path}",
                    extra={"component": "platform"},
                )
                return True

            elif IS_MACOS:
                # macOS: .webloc oder .app? Für ausführbare Dateien verwenden wir
                # einen einfachen Alias mit `ln`? Besser: Skript, das `open -a` nutzt.
                # Da macOS sehr restriktiv ist, beschränken wir uns auf eine Warnung.
                cls._logger.warning(
                    "create_shortcut: macOS wird derzeit nicht vollständig unterstützt. "
                    "Erstelle stattdessen eine ausführbare shell‑Datei.",
                    extra={"component": "platform"},
                )
                # Fallback: einfaches Shell‑Skript
                script_content = f"""#!/bin/bash
cd "{working_dir or target.parent}"
"{target}" {arguments}
"""
                script_path = link_path.with_suffix(".command")
                with open(script_path, "w", encoding="utf-8") as f:
                    f.write(script_content)
                # Sicherheitsverbesserung: 0o750 statt 0o755
                os.chmod(script_path, 0o700)
                cls._logger.debug(
                    f"macOS‑Fallback‑Skript erstellt: {script_path}",
                    extra={"component": "platform"},
                )
                return True

            else:  # Linux / Unix
                # .desktop‑Datei nach freedesktop.org‑Standard
                # Escapen von Pfaden und Argumenten
                quoted_target = shlex.quote(str(target))
                quoted_args = shlex.quote(arguments) if arguments else ""
                if quoted_args:
                    exec_line = f"{quoted_target} {quoted_args}"
                else:
                    exec_line = quoted_target

                # Arbeitsverzeichnis (optional)
                work_dir = str(working_dir) if working_dir else str(target.parent)
                # Icon (optional)
                icon_line = str(icon_path) if icon_path and icon_path.exists() else ""

                # Beschreibung oder Standardname
                name = description if description else target.stem

                # Terminal‑Option
                terminal_setting = "true" if use_terminal else "false"

                desktop_entry = f"""[Desktop Entry]
Version=1.0
Type=Application
Name={name}
Comment={description}
Exec={exec_line}
Path={work_dir}
Icon={icon_line}
Terminal={terminal_setting}
StartupNotify=true
Categories=Utility;
"""
                with open(link_path, "w", encoding="utf-8") as f:
                    f.write(desktop_entry)
                # Sicherheitsverbesserung: 0o750 statt 0o755
                os.chmod(link_path, 0o644)
                cls._logger.debug(
                    f"Linux‑Desktop‑Verknüpfung erstellt: {link_path}",
                    extra={"component": "platform"},
                )
                return True

        except Exception as e:
            cls._logger.error(
                f"create_shortcut: Unerwarteter Fehler: {e}",
                exc_info=True,
                extra={"component": "platform"},
            )
            return False

    # -------------------------------------------------------------------------
    # 23. Prozess‑Liste und Prozess‑Suche (ohne psutil minimal)
    # -------------------------------------------------------------------------
    @classmethod
    def get_process_list(cls, include_cmdline: bool = True) -> List[Dict[str, Any]]:
        """
        Gibt eine Liste aller laufenden Prozesse zurück (PID, Name, evtl. CommandLine).
        Ohne psutil wird eine einfachere Liste zurückgegeben.

        Args:
            include_cmdline: Wenn True, wird auch die vollständige Kommandozeile
                             abgerufen (kann bei vielen Prozessen langsamer sein).

        Returns:
            Liste von Dictionaries mit Schlüsseln 'pid', 'name', 'cmdline'.

        Notes:
            Bandit B607 (teilweiser Pfad) wird für 'tasklist' ignoriert,
            da es ein Windows‑Systemtool ist und im PATH liegt.
        """
        processes: List[Dict[str, Any]] = []

        # ── 1. psutil (bevorzugt, schnell und zuverlässig) ─────────────
        try:
            import psutil

            attrs = ["pid", "name"]
            if include_cmdline:
                attrs.append("cmdline")

            for proc in psutil.process_iter(attrs):
                try:
                    info = proc.info
                    entry: Dict[str, Any] = {
                        "pid": info["pid"],
                        "name": info["name"],
                    }
                    if include_cmdline:
                        cmdline = info.get("cmdline")
                        entry["cmdline"] = " ".join(cmdline) if cmdline else ""
                    processes.append(entry)
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    # Prozess verschwand oder keine Rechte – einfach überspringen
                    continue
            return processes

        except ImportError:
            # psutil nicht installiert → Fallback
            logger.debug("psutil not available, using fallback process listing")

        # ── 2. Windows-Fallback (tasklist) ─────────────────────────────
        if IS_WINDOWS:
            try:
                # tasklist ohne Shell, als Liste
                result = subprocess.run(
                    ["tasklist", "/FO", "CSV", "/NH"],
                    capture_output=True,
                    text=True,
                    timeout=10,
                    check=False,
                )
                if result.returncode == 0 and result.stdout:
                    for line in result.stdout.strip().splitlines():
                        if not line:
                            continue
                        # CSV-Zeilen parsen: "Image Name","PID",...
                        parts = line.strip('"').split('","')
                        if len(parts) >= 2:
                            try:
                                pid = int(parts[1])
                            except ValueError:
                                continue
                            processes.append(
                                {
                                    "pid": pid,
                                    "name": parts[0],
                                    "cmdline": "",
                                }
                            )
            except subprocess.TimeoutExpired:
                logger.warning("tasklist timed out")
            except Exception as e:
                logger.debug(f"tasklist fallback error: {e}")

            return processes

        # ── 3. Linux/Unix-Fallback (zuerst /proc, dann ps) ────────────
        # 3a. /proc-Dateisystem (schnell, aber nicht immer lesbar)
        try:
            proc_path = Path("/proc")
            if proc_path.exists() and proc_path.is_dir():
                for proc_dir in proc_path.iterdir():
                    if proc_dir.is_dir() and proc_dir.name.isdigit():
                        try:
                            pid = int(proc_dir.name)
                            # Prozessname aus /proc/<pid>/comm
                            comm_file = proc_dir / "comm"
                            if comm_file.exists():
                                with open(comm_file, "r") as f:
                                    name = f.read().strip()
                            else:
                                name = "unknown"
                            processes.append({"pid": pid, "name": name, "cmdline": ""})
                        except (ValueError, OSError, PermissionError):
                            continue
                if processes:
                    return processes
        except Exception as e:
            logger.debug(f"/proc fallback error: {e}")

        # 3b. ps-Befehl (falls verfügbar) – liefert auch cmdline
        try:
            if include_cmdline:
                cmd = ["ps", "-eo", "pid,comm,args", "--no-headers"]
            else:
                cmd = ["ps", "-eo", "pid,comm", "--no-headers"]

            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=10,
                check=False,
            )
            if result.returncode == 0 and result.stdout:
                for line in result.stdout.strip().splitlines():
                    parts = line.strip().split(None, 2 if include_cmdline else 1)
                    if not parts:
                        continue
                    try:
                        pid = int(parts[0])
                        name = parts[1] if len(parts) > 1 else "unknown"
                        cmdline = parts[2] if len(parts) > 2 else ""
                        processes.append(
                            {
                                "pid": pid,
                                "name": name,
                                "cmdline": cmdline if include_cmdline else "",
                            }
                        )
                    except (ValueError, IndexError):
                        continue
        except subprocess.TimeoutExpired:
            logger.warning("ps command timed out")
        except Exception as e:
            logger.debug(f"ps fallback error: {e}")

        return processes

    @classmethod
    def find_process_by_name(cls, name: str) -> Optional[int]:
        """Findet die erste PID eines Prozesses mit dem gegebenen Namen."""
        for proc in cls.get_process_list():
            if proc.get("name", "").lower() == name.lower():
                return proc.get("pid")
        return None

    @classmethod
    def kill_process(cls, pid: int, force: bool = True) -> bool:
        """Beendet einen einzelnen Prozess (ohne Kindprozesse)."""
        try:
            import psutil

            proc = psutil.Process(pid)
            if force:
                proc.kill()
            else:
                proc.terminate()
            proc.wait(timeout=2.0)
            return True
        except ImportError:
            # Fallback mit os.kill
            try:
                if force:
                    os.kill(pid, py_signal.SIGKILL)
                else:
                    os.kill(pid, py_signal.SIGTERM)
                time.sleep(0.2)
                os.kill(pid, 0)  # Prüft, ob noch existiert
                return False
            except ProcessLookupError:
                return True
            except Exception:
                return False
        except Exception:
            return False

    @classmethod
    def get_piper_cache_dir(cls) -> str:
        """Plattformübergreifendes Piper‑Cache‑Verzeichnis."""
        if IS_WINDOWS:
            base = os.environ.get("APPDATA", os.path.expanduser("~\\AppData\\Roaming"))
            return os.path.join(base, "piper")
        base = os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache"))
        return os.path.join(base, "piper")


