class DummyQueue(queue.Queue):
    """
    Thread‑sichere Dummy‑Queue, die sich exakt wie `queue.Queue` verhält,
    aber die interne Speicherung über eine einfache Python‑Liste realisiert.
    Sie erbt von `queue.Queue`, überschreibt nur die geschützten Hooks
    und ist dadurch in allen typisierten Kontexten voll kompatibel.
    """

    __slots__ = ()

    def __init__(self, maxsize: int = 0) -> None:
        super().__init__(maxsize)

    def _init(self, maxsize: int) -> None:
        self.queue: List[Any] = []

    def _qsize(self) -> int:
        return len(self.queue)

    def _put(self, item: Any) -> None:
        self.queue.append(item)

    def _get(self) -> Any:
        return self.queue.pop(0)


@dataclass
class TranscriptionResult:
    """
    Ergebnis einer Transkription mit Text, Konfidenz, Sprache und optionalen Zeitstempeln.

    Attributes:
        text: Der transkribierte Text.
        confidence: Konfidenzwert der Transkription (0.0 – 1.0).
        language: ISO‑Sprachcode (z. B. "de", "en") oder "unknown".
        language_probability: Wahrscheinlichkeit der Spracherkennung (optional).
        timestamp: Unix‑Zeitstempel der Erstellung.
        start: Startzeit in Sekunden (für Untertitel).
        end: Endzeit in Sekunden (für Untertitel).
    """

    text: str
    confidence: float
    language: str = "unknown"
    language_probability: Optional[float] = None  # FIXED: Feld ergänzt
    timestamp: float = field(default_factory=time.time)
    start: Optional[float] = None
    end: Optional[float] = None

    def __post_init__(self) -> None:
        """Validiert und korrigiert die Werte."""
        if not isinstance(self.confidence, (int, float)):
            self.confidence = 0.0
        self.confidence = max(0.0, min(1.0, float(self.confidence)))

        if self.language_probability is not None:
            self.language_probability = max(
                0.0, min(1.0, float(self.language_probability))
            )

        if self.start is not None and self.start < 0.0:
            self.start = 0.0

        if self.end is not None and self.end < 0.0:
            self.end = 0.0

        if self.start is not None and self.end is not None and self.end < self.start:
            self.end = self.start + 0.001

    def to_dict(self) -> Dict[str, Any]:
        """Konvertiert das Objekt in ein Dictionary (für JSON‑Export)."""
        return {
            "text": self.text,
            "confidence": self.confidence,
            "language": self.language,
            "language_probability": self.language_probability,
            "timestamp": self.timestamp,
            "start": self.start,
            "end": self.end,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TranscriptionResult":
        """Erstellt ein Objekt aus einem Dictionary."""
        return cls(
            text=data.get("text", ""),
            confidence=data.get("confidence", 0.0),
            language=data.get("language", "unknown"),
            language_probability=data.get("language_probability"),
            timestamp=data.get("timestamp", time.time()),
            start=data.get("start"),
            end=data.get("end"),
        )

    def __repr__(self) -> str:
        preview = self.text[:50] + "…" if len(self.text) > 50 else self.text
        return (
            f"TranscriptionResult(text='{preview}', "
            f"conf={self.confidence:.2f}, lang='{self.language}')"
        )


@dataclass
class TranslationResult:
    """
    Ergebnis einer Übersetzung mit Original, Übersetzung und Metadaten.

    Attributes:
        original: Der Originaltext (Quellsprache).
        translated: Der übersetzte Text (Zielsprache).
        source_lang: ISO‑Code der Quellsprache (oder "auto").
        target_lang: ISO‑Code der Zielsprache.
        timestamp: Unix‑Zeitstempel der Erstellung.
        start: Startzeit in Sekunden (für Untertitel).
        end: Endzeit in Sekunden (für Untertitel).
        confidence: Optionale Konfidenz der Übersetzung (0.0 – 1.0).  # FIXED: Feld ergänzt
    """

    original: str
    translated: str
    source_lang: str = "auto"
    target_lang: str = "de"
    timestamp: float = field(default_factory=time.time)
    start: Optional[float] = None
    end: Optional[float] = None
    confidence: Optional[float] = None  # FIXED: Feld ergänzt

    def __post_init__(self) -> None:
        """Validiert und korrigiert die Werte."""
        if self.confidence is not None:
            self.confidence = max(0.0, min(1.0, float(self.confidence)))

        if self.start is not None and self.start < 0.0:
            self.start = 0.0

        if self.end is not None and self.end < 0.0:
            self.end = 0.0

        if self.start is not None and self.end is not None and self.end < self.start:
            self.end = self.start + 0.001

    def to_dict(self) -> Dict[str, Any]:
        """Konvertiert das Objekt in ein Dictionary (für JSON‑Export)."""
        return {
            "original": self.original,
            "translated": self.translated,
            "source_lang": self.source_lang,
            "target_lang": self.target_lang,
            "timestamp": self.timestamp,
            "start": self.start,
            "end": self.end,
            "confidence": self.confidence,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "TranslationResult":
        """Erstellt ein Objekt aus einem Dictionary."""
        return cls(
            original=data.get("original", ""),
            translated=data.get("translated", ""),
            source_lang=data.get("source_lang", "auto"),
            target_lang=data.get("target_lang", "de"),
            timestamp=data.get("timestamp", time.time()),
            start=data.get("start"),
            end=data.get("end"),
            confidence=data.get("confidence"),
        )

    def __repr__(self) -> str:
        preview = (
            self.translated[:50] + "…" if len(self.translated) > 50 else self.translated
        )
        return (
            f"TranslationResult(translated='{preview}', "
            f"src='{self.source_lang}', tgt='{self.target_lang}')"
        )


@dataclass
class StreamInfo:
    """
    Metadaten eines Streams (YouTube, Twitch, etc.).
    """

    title: str
    uploader: str
    duration: str
    view_count: int
    platform: str
    description: str = ""
    duration_seconds: Optional[float] = None
    is_live: bool = False
    thumbnail: str = ""
    original_url: str = ""
    stream_url: Optional[str] = None
    channel_id: Optional[str] = None  # FIXED: Feld ergänzt
    uploader_url: Optional[str] = None  # FIXED: Feld ergänzt

    def __post_init__(self) -> None:
        """Validiert und korrigiert die Werte, berechnet duration_seconds falls möglich."""
        if self.view_count < 0:
            self.view_count = 0

        # Wenn duration_seconds fehlt, aber duration ein String ist, versuche zu parsen
        if self.duration_seconds is None and self.duration and self.duration != "Live":
            try:
                parts = list(map(float, self.duration.split(":")))
                if len(parts) == 3:
                    self.duration_seconds = parts[0] * 3600 + parts[1] * 60 + parts[2]
                elif len(parts) == 2:
                    self.duration_seconds = parts[0] * 60 + parts[1]
                elif len(parts) == 1:
                    self.duration_seconds = parts[0]
            except (ValueError, AttributeError):
                pass

        # Kürze Beschreibung auf 500 Zeichen
        if self.description and len(self.description) > 500:
            self.description = self.description[:497] + "..."

        # Plattform normalisieren
        if self.platform:
            self.platform = self.platform.lower()

    def to_dict(self) -> Dict[str, Any]:
        """Konvertiert das Objekt in ein Dictionary (für JSON‑Export)."""
        return {
            "title": self.title,
            "uploader": self.uploader,
            "duration": self.duration,
            "view_count": self.view_count,
            "platform": self.platform,
            "description": self.description,
            "duration_seconds": self.duration_seconds,
            "is_live": self.is_live,
            "thumbnail": self.thumbnail,
            "original_url": self.original_url,
            "stream_url": self.stream_url,
            "channel_id": self.channel_id,
            "uploader_url": self.uploader_url,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "StreamInfo":
        """Erstellt ein Objekt aus einem Dictionary."""
        return cls(
            title=data.get("title", "Unknown Stream"),
            uploader=data.get("uploader", "Unknown"),
            duration=data.get("duration", "Live"),
            view_count=data.get("view_count", 0),
            platform=data.get("platform", "unknown"),
            description=data.get("description", ""),
            duration_seconds=data.get("duration_seconds"),
            is_live=data.get("is_live", False),
            thumbnail=data.get("thumbnail", ""),
            original_url=data.get("original_url", ""),
            stream_url=data.get("stream_url"),
            channel_id=data.get("channel_id"),
            uploader_url=data.get("uploader_url"),
        )

    def __repr__(self) -> str:
        title_preview = self.title[:40] + "…" if len(self.title) > 40 else self.title
        return (
            f"StreamInfo(title='{title_preview}', "
            f"uploader='{self.uploader}', "
            f"duration='{self.duration}', "
            f"platform='{self.platform}')"
        )


# ─────────────────────────────────────────────────────────────────
# Leichtgewichtige Info‑ und Segmentklassen (mit __slots__ und Typen)
# ─────────────────────────────────────────────────────────────────
class _EmptyInfo:
    """Fallback‑Info, wenn Transkription fehlschlägt."""

    language: str = "unknown"
    duration: float = 0.0


class _UniversalInfo:
    """Einheitliche Metadaten aus verschiedenen Transkriptions‑Backends."""

    __slots__ = ("language", "duration")

    language: str
    duration: float

    def __init__(self, result_dict: Dict[str, Any]) -> None:
        self.language = str(result_dict.get("language", "unknown"))
        raw_duration = result_dict.get("duration", 0.0)
        try:
            self.duration = float(raw_duration)
        except (ValueError, TypeError):
            self.duration = 0.0


class _UniversalSegment:
    """Einheitliches Segment‑Interface für verschiedene Backends."""

    __slots__ = ("text", "start", "end", "confidence")

    text: str
    start: float
    end: float
    confidence: float

    def __init__(self, seg_dict: Dict[str, Any]) -> None:
        self.text = str(seg_dict.get("text", "")).strip()
        try:
            self.start = float(seg_dict.get("start", 0.0))
        except (ValueError, TypeError):
            self.start = 0.0
        try:
            self.end = float(seg_dict.get("end", 0.0))
        except (ValueError, TypeError):
            self.end = 0.0
        try:
            self.confidence = float(seg_dict.get("confidence", 0.9))
        except (ValueError, TypeError):
            self.confidence = 0.9


class _EmergencySegment:
    """Notfall‑Segment, wenn strukturierte Daten fehlen."""

    __slots__ = ("text", "start", "end", "confidence")

    text: str
    start: float
    end: float
    confidence: float

    def __init__(self, seg_dict: Dict[str, Any]) -> None:
        self.text = str(seg_dict.get("text", ""))
        try:
            self.start = float(seg_dict.get("start", 0.0))
        except (ValueError, TypeError):
            self.start = 0.0
        try:
            self.end = float(seg_dict.get("end", 0.0))
        except (ValueError, TypeError):
            self.end = 0.0
        self.confidence = 0.5


class SimplePerformanceTracker:
    """
    Leichtgewichtiger, thread‑sicherer Performance‑Tracker für die
    zentralen Verarbeitungsmetriken von Dragon Whisperer.

    Erweiterungen gegenüber der Basisversion:
    - Zeitmessung mit ``time.monotonic()`` (unabhängig von Systemuhr‑Sprüngen)
    - Fehlerzähler für Transkriptionen und Übersetzungen
    - Berechnung von Verarbeitungsraten pro Minute
    - ``reset()``-Methode zum Zurücksetzen aller Zähler
    """

    __slots__ = (
        "transcription_count",
        "translation_count",
        "transcription_errors",
        "translation_errors",
        "start_time",
        "cache_hits",
        "cache_misses",
        "_lock",
    )

    def __init__(self) -> None:
        self.transcription_count = 0
        self.translation_count = 0
        self.transcription_errors = 0
        self.translation_errors = 0
        self.start_time = time.monotonic()
        self.cache_hits = 0
        self.cache_misses = 0
        self._lock = threading.RLock()

    # ── Ereignis‑Logging ──────────────────────────────────────────
    def log_transcription(self) -> None:
        with self._lock:
            self.transcription_count += 1

    def log_translation(self) -> None:
        with self._lock:
            self.translation_count += 1

    def log_transcription_error(self) -> None:
        with self._lock:
            self.transcription_errors += 1

    def log_translation_error(self) -> None:
        with self._lock:
            self.translation_errors += 1

    def log_cache_hit(self) -> None:
        with self._lock:
            self.cache_hits += 1

    def log_cache_miss(self) -> None:
        with self._lock:
            self.cache_misses += 1

    # ── Statistiken ───────────────────────────────────────────────
    def get_basic_stats(self) -> Dict[str, Any]:
        """
        Liefert ein Dictionary mit den aktuellen Leistungs‑ und
        Cache‑Metriken.  Alle Werte sind ``float`` oder ``int``,
        sodass sie maschinell weiterverarbeitet werden können.
        """
        with self._lock:
            elapsed_seconds = time.monotonic() - self.start_time
            uptime_minutes = elapsed_seconds / 60.0

            total_cache = self.cache_hits + self.cache_misses
            cache_hit_rate = self.cache_hits / total_cache if total_cache > 0 else 0.0

            return {
                "transcriptions": self.transcription_count,
                "translations": self.translation_count,
                "transcription_errors": self.transcription_errors,
                "translation_errors": self.translation_errors,
                "transcriptions_per_min": (
                    self.transcription_count / uptime_minutes
                    if uptime_minutes > 0
                    else 0.0
                ),
                "translations_per_min": (
                    self.translation_count / uptime_minutes
                    if uptime_minutes > 0
                    else 0.0
                ),
                "uptime_minutes": uptime_minutes,
                "cache_hits": self.cache_hits,
                "cache_misses": self.cache_misses,
                "cache_hit_rate": cache_hit_rate,
                "cache_hit_rate_pct": f"{cache_hit_rate:.1%}",
                "timestamp": datetime.now().isoformat(),
            }

    def reset(self) -> None:
        """
        Setzt alle Zähler und die Startzeit zurück.
        """
        with self._lock:
            self.transcription_count = 0
            self.translation_count = 0
            self.transcription_errors = 0
            self.translation_errors = 0
            self.cache_hits = 0
            self.cache_misses = 0
            self.start_time = time.monotonic()


# Globale Logger-Referenz (wird im Hauptmodul definiert)
# logger = None  # type: ignore
# log_debug = None  # type: ignore

T = TypeVar("T")


class OptimizedThreadPoolExecutor:
    """
    Thread‑Pool‑Executor mit begrenzter Warteschlange (Semaphore), Timeout, Retry,
    dynamischem Shutdown‑Timeout und verbesserter Abbruchunterstützung.
    """

    def __init__(
        self,
        max_workers: int = 4,
        thread_name_prefix: str = "OptExec",
        max_queue_size: int = 100,
        dynamic_workers: bool = False,
        min_workers: int = 2,
        max_workers_limit: int = 32,
    ) -> None:
        """
        Args:
            max_workers: Anfängliche maximale Anzahl gleichzeitig laufender Worker‑Threads.
            thread_name_prefix: Präfix für die Namen der Worker‑Threads.
            max_queue_size: Maximale Anzahl wartender Tasks (Semaphore‑Limit).
            dynamic_workers: Wenn True, kann die Worker‑Anzahl später dynamisch angepasst werden.
            min_workers: Minimale Worker‑Anzahl (nur bei dynamic_workers=True).
            max_workers_limit: Maximale Worker‑Anzahl (nur bei dynamic_workers=True).
        """
        if max_workers < 1:
            raise ValueError("max_workers must be >= 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be >= 1")
        if dynamic_workers and min_workers < 1:
            raise ValueError("min_workers must be >= 1")
        if dynamic_workers and max_workers_limit < min_workers:
            raise ValueError("max_workers_limit must be >= min_workers")

        self._max_workers = max_workers
        self._thread_name_prefix = thread_name_prefix
        self._max_queue_size = max_queue_size
        self._dynamic_workers = dynamic_workers
        self._min_workers = min_workers
        self._max_workers_limit = max_workers_limit

        # Interner Executor (ThreadPoolExecutor)
        self._executor = ThreadPoolExecutor(
            max_workers=max_workers,
            thread_name_prefix=thread_name_prefix,
        )

        # Semaphore zur Begrenzung der wartenden Tasks (nicht der aktiven)
        self._semaphore = threading.Semaphore(max_queue_size)

        # Shutdown‑Status und Locks
        self._shutdown = False
        self._shutdown_lock = threading.RLock()
        self._shutdown_cond = threading.Condition(self._shutdown_lock)
        self._shutdown_done = False

        # Menge aller aktiven Futures (für wartenden Shutdown)
        self._active_futures: Set[Future] = set()
        self._active_futures_lock = threading.Lock()

        # Event für unterbrechbaren Schlaf (für Retry‑Schleifen)
        self._stop_event = threading.Event()

        # Letzte Warnung bei voller Queue (Spam‑Schutz)
        self._last_queue_warning_time = 0.0

        # Finalizer als Sicherheitsnetz
        self._finalizer = weakref.finalize(self, self._shutdown_finalizer)

        # Statistiken
        self._stats_lock = threading.RLock()
        self._stats = {
            "submitted": 0,
            "completed": 0,
            "failed": 0,
            "retries": 0,
            "timeouts": 0,
            "cancelled": 0,
            "queue_drops": 0,
            "start_time": time.time(),
        }

        if log_debug is not None and getattr(log_debug, "__call__", False):
            log_debug(
                "executor",
                f"OptimizedThreadPoolExecutor initialized: max_workers={max_workers}, "
                f"max_queue_size={max_queue_size}, dynamic={dynamic_workers}",
            )

    # ------------------------------------------------------------------
    # Eigenschaften
    # ------------------------------------------------------------------
    @property
    def max_workers(self) -> int:
        """Gibt die maximale Anzahl der Worker‑Threads zurück."""
        return self._max_workers

    def set_max_workers(self, new_max_workers: int) -> None:
        """
        Passt die maximale Anzahl der Worker‑Threads dynamisch an.
        Startet den internen ThreadPoolExecutor neu, was laufende Tasks nicht beeinträchtigt,
        aber neue Tasks werden mit der neuen Worker‑Anzahl ausgeführt.

        Args:
            new_max_workers: Neue maximale Worker‑Anzahl (muss >= 1 sein).
        """
        if not self._dynamic_workers:
            raise RuntimeError(
                "Dynamic worker adjustment disabled. Set dynamic_workers=True in constructor."
            )
        if new_max_workers < self._min_workers:
            new_max_workers = self._min_workers
        if new_max_workers > self._max_workers_limit:
            new_max_workers = self._max_workers_limit
        if new_max_workers == self._max_workers:
            return

        old_workers = self._max_workers
        self._max_workers = new_max_workers

        old_executor = self._executor
        self._executor = ThreadPoolExecutor(
            max_workers=new_max_workers,
            thread_name_prefix=self._thread_name_prefix,
        )

        def _shutdown_old():
            try:
                safe_shutdown_executor(old_executor, wait=True, cancel_futures=False)
            except Exception:
                pass

        threading.Thread(target=_shutdown_old, daemon=True).start()

        if log_debug is not None and getattr(log_debug, "__call__", False):
            log_debug(
                "executor", f"Worker count adjusted: {old_workers} → {new_max_workers}"
            )

    def get_queue_size(self) -> int:
        """Gibt die aktuelle Anzahl wartender Tasks zurück (Semaphore‑Zähler)."""
        # Der Semaphore-Zähler ist nicht direkt lesbar, aber wir können die Anzahl der
        # wartenden Threads schätzen, indem wir die Anzahl der aktiven Futures von der
        # maximalen Queue-Größe abziehen? Besser: Wir führen einen eigenen Zähler.
        # Da Semaphore keinen direkten Zugriff auf die Anzahl der Wartenden bietet,
        # verwenden wir einen zusätzlichen Zähler.
        # Hier implementieren wir eine einfache Schätzung: max_queue_size - verfügbare Semaphore.
        # Das ist nicht exakt, aber für Diagnosezwecke ausreichend.
        # Alternative: Wir führen einen eigenen Zähler für eingereichte, aber noch nicht
        # bearbeitete Tasks. Das ist aufwändiger. Für die meisten Anwendungsfälle reicht
        # die Anzahl der aktiven Futures.
        with self._active_futures_lock:
            return len(self._active_futures)

    def get_active_future_count(self) -> int:
        """Gibt die Anzahl der aktuell laufenden oder noch nicht abgeschlossenen Futures zurück."""
        with self._active_futures_lock:
            return len(self._active_futures)

    def get_stats(self) -> Dict[str, Any]:
        """Gibt eine Kopie der internen Statistiken zurück."""
        with self._stats_lock:
            stats = self._stats.copy()
            stats["uptime"] = time.time() - stats["start_time"]
            stats["active_futures"] = self.get_active_future_count()
            stats["queue_size"] = self.get_queue_size()
            stats["max_workers"] = self._max_workers
            stats["max_queue_size"] = self._max_queue_size
            stats["shutdown"] = self._shutdown
            return stats

    # ------------------------------------------------------------------
    # Kernmethode: Task einreichen
    # ------------------------------------------------------------------
    def submit(
        self,
        fn: Callable[..., T],
        *args: Any,
        block: bool = True,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Future[T]:
        """
        Reicht eine Aufgabe zur Ausführung ein.

        Args:
            fn: Die aufzurufende Funktion.
            *args: Positionsargumente für fn.
            block: Ob blockierend auf einen freien Slot gewartet werden soll.
            timeout: Max. Wartezeit auf einen freien Slot (Sekunden), nur wenn block=True.
            **kwargs: Schlüsselwortargumente für fn.

        Returns:
            Future, die das Ergebnis repräsentiert.

        Raises:
            RuntimeError: Wenn der Executor bereits heruntergefahren ist oder
                          das Timeout beim Warten auf einen freien Slot überschritten wurde.
        """
        # ── 1. Prüfen, ob Executor bereits heruntergefahren ist ─────────
        with self._shutdown_lock:
            if self._shutdown:
                raise RuntimeError("Executor wurde bereits heruntergefahren")

        # ── 2. Semaphore erwerben (blockierend oder nicht) ─────────────
        acquired = False
        try:
            acquired = self._semaphore.acquire(blocking=block, timeout=timeout)
            if not acquired:
                now = time.time()
                if now - self._last_queue_warning_time > 5.0:
                    if logger is not None:
                        logger.warning(
                            f"⚠️ OptimizedThreadPoolExecutor: Queue voll (max {self._max_queue_size} Tasks) – "
                            f"Anfrage abgelehnt nach Timeout {timeout}s"
                        )
                    self._last_queue_warning_time = now
                raise RuntimeError(
                    f"Queue voll (max {self._max_queue_size} Tasks) nach Timeout"
                )
        except Exception:
            if acquired:
                self._semaphore.release()
            raise

        # ── 3. Unter Lock erneut prüfen, ob während des Wartens shutdown erfolgte ──
        with self._shutdown_lock:
            if self._shutdown:
                self._semaphore.release()
                raise RuntimeError(
                    "Executor wurde während des Wartens heruntergefahren"
                )

        # ── 4. Task einreichen und Future registrieren ─────────────────
        try:
            with self._stats_lock:
                self._stats["submitted"] += 1

            future = self._executor.submit(fn, *args, **kwargs)

            # Future in die Menge der aktiven Futures aufnehmen
            with self._active_futures_lock:
                self._active_futures.add(future)

            # Callback für automatische Bereinigung nach Abschluss
            def _release_and_cleanup(f: Future) -> None:
                with self._active_futures_lock:
                    self._active_futures.discard(f)
                self._semaphore.release()
                with self._shutdown_cond:
                    self._shutdown_cond.notify_all()
                with self._stats_lock:
                    if f.cancelled():
                        self._stats["cancelled"] += 1
                    elif f.exception() is not None:
                        self._stats["failed"] += 1
                    else:
                        self._stats["completed"] += 1

            future.add_done_callback(_release_and_cleanup)
            return future

        except Exception:
            self._semaphore.release()
            raise

    # ------------------------------------------------------------------
    # submit mit Timeout
    # ------------------------------------------------------------------
    def submit_with_timeout(
        self,
        fn: Callable[..., T],
        timeout: Optional[float] = None,
        *args: Any,
        **kwargs: Any,
    ) -> T:
        """
        Reicht eine Aufgabe ein und wartet auf das Ergebnis mit Timeout.

        Args:
            fn: Die aufzurufende Funktion.
            timeout: Max. Zeit in Sekunden auf das Ergebnis zu warten.
            *args, **kwargs: Argumente für fn.

        Returns:
            Das Ergebnis der Funktion.

        Raises:
            TimeoutError: Wenn das Timeout überschritten wurde.
        """
        future = self.submit(fn, *args, **kwargs)
        try:
            result = future.result(timeout=timeout)
            return result
        except FutureTimeout as exc:
            future.cancel()
            with self._stats_lock:
                self._stats["timeouts"] += 1
            raise TimeoutError(
                f"Timeout nach {timeout}s bei Ausführung von {getattr(fn, '__name__', 'unknown')}"
            ) from exc

    # ------------------------------------------------------------------
    # submit mit Wiederholungen (Retry)
    # ------------------------------------------------------------------
    def submit_with_retry(
        self,
        fn: Callable[..., T],
        max_retries: int = 3,
        retry_delay_base: float = 1.0,
        retry_delay_max: float = 10.0,
        timeout_per_attempt: Optional[float] = None,
        retry_on_exceptions: Tuple[type[Exception], ...] = (Exception,),
        cancel_event: Optional[threading.Event] = None,
        *args: Any,
        **kwargs: Any,
    ) -> T:
        """
        Reicht eine Aufgabe ein und wiederholt sie bei bestimmten Exceptions.

        Args:
            fn: Die aufzurufende Funktion.
            max_retries: Maximale Anzahl Wiederholungen (insgesamt max_retries+1 Versuche).
            retry_delay_base: Basis‑Verzögerung für exponentiellen Backoff (Sekunden).
            retry_delay_max: Maximale Verzögerung (Sekunden).
            timeout_per_attempt: Timeout pro Versuch (Sekunden), optional.
            retry_on_exceptions: Exception‑Typen, bei denen wiederholt werden soll.
            cancel_event: Optionales Event, das die Wiederholungen vorzeitig abbrechen kann.
            *args, **kwargs: Argumente für fn.

        Returns:
            Das Ergebnis der Funktion.

        Raises:
            RuntimeError: Wenn alle Versuche fehlschlagen.
        """
        last_exception: Optional[Exception] = None
        for attempt in range(max_retries + 1):
            with self._shutdown_lock:
                if self._shutdown:
                    raise RuntimeError("Executor wurde während Retry heruntergefahren")
            if cancel_event is not None and cancel_event.is_set():
                raise RuntimeError("Retry abgebrochen durch cancel_event")

            try:
                if timeout_per_attempt is not None:
                    result = self.submit_with_timeout(
                        fn, timeout_per_attempt, *args, **kwargs
                    )
                else:
                    future = self.submit(fn, *args, **kwargs)
                    result = future.result()
                with self._stats_lock:
                    self._stats["retries"] += attempt  # Anzahl der Wiederholungen
                if log_debug is not None and getattr(log_debug, "__call__", False):
                    log_debug(
                        "executor",
                        f"Funktion {getattr(fn, '__name__', 'unknown')} erfolgreich nach {attempt} Versuchen",
                    )
                return result
            except retry_on_exceptions as e:
                last_exception = e
                if attempt < max_retries:
                    delay = min(retry_delay_max, retry_delay_base * (2**attempt))
                    if logger is not None:
                        logger.warning(
                            f"Funktion {getattr(fn, '__name__', 'unknown')} fehlgeschlagen "
                            f"(Versuch {attempt + 1}/{max_retries + 1}): {e}. "
                            f"Nächster Versuch in {delay:.1f}s"
                        )
                    self._interruptible_sleep(delay, cancel_event=cancel_event)
                else:
                    if logger is not None:
                        logger.error(
                            f"Funktion {getattr(fn, '__name__', 'unknown')} auch nach "
                            f"{max_retries + 1} Versuchen fehlgeschlagen: {e}"
                        )
                    raise  # letzten Fehler weiterwerfen
            except Exception as e:
                if logger is not None:
                    logger.error(
                        f"Nicht wiederholbarer Fehler in {getattr(fn, '__name__', 'unknown')}: {e}"
                    )
                raise

        if last_exception is not None:
            raise last_exception
        raise RuntimeError(
            f"Alle {max_retries + 1} Versuche für {getattr(fn, '__name__', 'unknown')} fehlgeschlagen"
        )

    # ------------------------------------------------------------------
    # submit mit Callback (asynchrone Benachrichtigung)
    # ------------------------------------------------------------------
    def submit_with_callback(
        self,
        fn: Callable[..., T],
        callback: Callable[[Future[T]], None],
        *args: Any,
        **kwargs: Any,
    ) -> Future[T]:
        """
        Reicht eine Aufgabe ein und ruft einen Callback auf, sobald die Future abgeschlossen ist.

        Args:
            fn: Die aufzurufende Funktion.
            callback: Callback, der die Future als Argument erhält.
            *args, **kwargs: Argumente für fn.

        Returns:
            Future, die das Ergebnis repräsentiert.
        """
        future = self.submit(fn, *args, **kwargs)
        future.add_done_callback(callback)
        return future

    # ------------------------------------------------------------------
    # Map mit Timeout
    # ------------------------------------------------------------------
    def map_with_timeout(
        self,
        fn: Callable[..., T],
        iterable: Union[list, tuple],
        timeout_per_item: Optional[float] = None,
        *args: Any,
        **kwargs: Any,
    ) -> list[T]:
        """
        Wendet eine Funktion auf jedes Element einer Iterable an, mit Timeout pro Element.

        Args:
            fn: Die aufzurufende Funktion (erhält das Element als erstes Argument).
            iterable: Liste oder Tuple von Eingabewerten.
            timeout_per_item: Max. Zeit pro Element in Sekunden.
            *args, **kwargs: Weitere Argumente für fn (nach dem Element).

        Returns:
            Liste der Ergebnisse in der gleichen Reihenfolge wie die Eingabe.

        Raises:
            TimeoutError: Wenn das Timeout für ein Element überschritten wurde.
            Exception: Jede andere Exception, die in fn auftritt.
        """
        futures = [self.submit(fn, item, *args, **kwargs) for item in iterable]
        results = []
        try:
            for i, future in enumerate(futures):
                results.append(future.result(timeout=timeout_per_item))
        except Exception:
            # Breche alle noch nicht abgeschlossenen Futures ab
            for f in futures[i:]:
                f.cancel()
            raise
        return results

    # ------------------------------------------------------------------
    # Alle wartenden Tasks abbrechen
    # ------------------------------------------------------------------
    def cancel_all_pending(self) -> int:
        """
        Bricht alle noch nicht gestarteten Tasks ab (die noch in der Queue warten).
        Gibt die Anzahl der abgebrochenen Futures zurück.

        Da wir keinen direkten Zugriff auf die Queue haben, brechen wir alle
        aktiven Futures ab, die noch nicht gestartet wurden (d. h. deren
        `_state` nicht `RUNNING` ist). Dies ist ein Best-Effort-Ansatz.
        """
        cancelled = 0
        with self._active_futures_lock:
            for future in list(self._active_futures):
                if not future.done() and not future.running():
                    if future.cancel():
                        cancelled += 1
        if log_debug is not None and getattr(log_debug, "__call__", False):
            log_debug("executor", f"Cancelled {cancelled} pending future(s)")
        return cancelled

    # ------------------------------------------------------------------
    # Sofortiger Shutdown (aggressiv)
    # ------------------------------------------------------------------
    def shutdown_now(self, timeout: float = 2.0) -> None:
        """
        Fährt den Executor sofort herunter, bricht alle aktiven Futures ab
        und gibt alle Semaphore frei.

        Args:
            timeout: Zeit in Sekunden, die auf die Beendigung der Worker‑Threads gewartet wird.
        """
        self.shutdown(wait=True, cancel_futures=True, timeout=timeout)

    # ------------------------------------------------------------------
    # Hilfsmethoden
    # ------------------------------------------------------------------
    def _interruptible_sleep(
        self,
        duration: float,
        check_interval: float = 0.1,
        cancel_event: Optional[threading.Event] = None,
    ) -> None:
        """
        Schlafe für `duration` Sekunden, unterbreche aber, wenn der Executor
        heruntergefahren wird oder `cancel_event` gesetzt wird.

        Verwendet `threading.Event.wait()` für sofortige Reaktion.
        """
        if duration <= 0:
            return

        # Falls ein cancel_event übergeben wurde, warten wir auf beide Events
        if cancel_event is not None:
            end_time = time.monotonic() + duration
            while time.monotonic() < end_time:
                # Warte auf das Stop-Event oder das cancel_event
                wait_time = min(check_interval, end_time - time.monotonic())
                # Korrektur: Verwende self._stop_event.wait() mit Timeout
                if self._stop_event.wait(timeout=wait_time):
                    # stop_event wurde gesetzt -> Executor fährt herunter
                    return
                if cancel_event.is_set():
                    return
        else:
            # Nur Stop-Event prüfen
            end_time = time.monotonic() + duration
            while time.monotonic() < end_time:
                # Prüfe, ob der Executor heruntergefahren wurde
                with self._shutdown_lock:
                    if self._shutdown:
                        return
                wait_time = min(check_interval, end_time - time.monotonic())
                if self._stop_event.wait(timeout=wait_time):
                    return

    # ------------------------------------------------------------------
    # Shutdown (mit optionalem Timeout für aktive Futures)
    # ------------------------------------------------------------------
    def shutdown(
        self,
        wait: bool = True,
        cancel_futures: bool = False,
        timeout: Optional[float] = None,
    ) -> None:
        """
        Fährt den Executor herunter. Nimmt keine neuen Aufgaben mehr an.

        Args:
            wait: Wenn True, blockiert die Methode, bis alle eingereichten Aufgaben
                  abgeschlossen sind (oder das Timeout eintritt).
            cancel_futures: Wenn True, werden noch nicht gestartete Aufgaben abgebrochen.
            timeout: Maximale Zeit in Sekunden, die auf die Fertigstellung aktiver
                     Futures gewartet wird (nur wenn `wait=True`). `None` bedeutet unbegrenzt.
        """
        # ── 1. Idempotenz und Lock ─────────────────────────────────────
        with self._shutdown_lock:
            if self._shutdown_done:
                if log_debug is not None and getattr(log_debug, "__call__", False):
                    log_debug("executor", "shutdown called but already shut down")
                return
            self._shutdown = True
            self._shutdown_done = True
            self._stop_event.set()

        # ── 2. Internen Executor herunterfahren ─────────────────────────
        executor = getattr(self, "_executor", None)
        if executor is not None:
            try:
                # Python 3.9+ unterstützt cancel_futures
                safe_shutdown_executor(
                    executor, wait=False, cancel_futures=cancel_futures
                )
                if log_debug is not None and getattr(log_debug, "__call__", False):
                    log_debug(
                        "executor",
                        "internal executor shutdown(wait=False, cancel_futures=%s) called",
                        cancel_futures,
                    )
            except TypeError:
                # Fallback für ältere Python‑Versionen
                executor.shutdown(wait=False)
                if cancel_futures:
                    # Manuelles Abbrechen der noch nicht gestarteten Futures
                    with self._active_futures_lock:
                        for future in list(self._active_futures):
                            if not future.done():
                                future.cancel()
                    if log_debug is not None and getattr(log_debug, "__call__", False):
                        log_debug(
                            "executor",
                            "cancel_futures manually applied (TypeError fallback)",
                        )
            except Exception as e:
                if logger is not None:
                    logger.warning(f"Error during internal executor shutdown: {e}")

        # ── 3. Optional: auf Fertigstellung aller aktiven Futures warten (mit Timeout) ──
        if wait:
            start_time = time.monotonic()
            with self._shutdown_cond:
                while True:
                    with self._active_futures_lock:
                        remaining = len(self._active_futures)
                    if remaining == 0:
                        break
                    if timeout is not None:
                        elapsed = time.monotonic() - start_time
                        if elapsed >= timeout:
                            if logger is not None:
                                logger.warning(
                                    f"Shutdown timeout after {timeout}s – {remaining} Future(s) still active"
                                )
                            break
                        wait_remaining = timeout - elapsed
                    else:
                        wait_remaining = 1.0  # kurze Intervalle für reaktives Warten
                    if log_debug is not None and getattr(log_debug, "__call__", False):
                        log_debug(
                            "executor",
                            f"Waiting for {remaining} active future(s) to complete... (timeout={wait_remaining:.1f}s)",
                        )
                    self._shutdown_cond.wait(timeout=min(1.0, wait_remaining))

        # ── 4. Verbleibende Worker‑Threads des internen Executors joinen ──
        worker_threads = []
        try:
            if executor is not None:
                worker_threads = list(getattr(executor, "_threads", set()))
        except Exception:
            pass

        if not worker_threads:
            prefix = getattr(self, "_thread_name_prefix", "OptExec")
            for t in threading.enumerate():
                if (
                    t.name.startswith(prefix)
                    and t.is_alive()
                    and t is not threading.current_thread()
                ):
                    worker_threads.append(t)

        if worker_threads and wait:
            deadline = time.monotonic() + 5.0  # maximal 5 Sekunden für Thread‑Joins
            for t in worker_threads:
                if t is threading.current_thread():
                    continue
                if not t.is_alive():
                    continue
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    if log_debug is not None and getattr(log_debug, "__call__", False):
                        log_debug(
                            "executor",
                            "Shutdown timeout reached, skipping further joins",
                        )
                    break
                t.join(timeout=remaining)
                if t.is_alive():
                    if logger is not None:
                        logger.warning(
                            f"Worker thread '{t.name}' did not terminate within timeout"
                        )
                    try:
                        t.daemon = True
                    except RuntimeError:
                        pass

        # ── 5. Alle wartenden submit()-Aufrufe durch Freigabe aller Semaphore entblockieren ──
        with self._shutdown_lock:
            for _ in range(self._max_queue_size):
                try:
                    self._semaphore.release()
                except ValueError:
                    break

        self._executor = None
        if log_debug is not None and getattr(log_debug, "__call__", False):
            log_debug(
                "executor",
                "Shutdown completed (wait=%s, cancel_futures=%s, timeout=%s)",
                wait,
                cancel_futures,
                timeout,
            )

    def _shutdown_finalizer(self) -> None:
        """Finalizer, der sicherstellt, dass der Executor heruntergefahren wird."""
        if not getattr(self, "_shutdown_done", False):
            try:
                self.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass

    # ------------------------------------------------------------------
    # Kontextmanager‑Unterstützung
    # ------------------------------------------------------------------
    def __enter__(self) -> "OptimizedThreadPoolExecutor":
        return self

    def __exit__(
        self,
        exc_type: Optional[type],
        exc_val: Optional[BaseException],
        exc_tb: Optional[Any],
    ) -> Literal[False]:
        """
        Beendet den Executor und wartet auf alle noch ausstehenden Aufgaben.
        Gibt immer ``False`` zurück, damit Ausnahmen nicht unterdrückt werden.
        """
        if log_debug is not None and getattr(log_debug, "__call__", False):
            log_debug(
                "executor",
                f"OptimizedThreadPoolExecutor.__exit__: initiating shutdown "
                f"(exc_type={exc_type.__name__ if exc_type else 'None'})",
            )
        self.shutdown(wait=True, cancel_futures=True, timeout=30.0)
        return False

    def __del__(self) -> None:
        """Destruktor als letzte Sicherheitslinie."""
        if not getattr(self, "_shutdown_done", False):
            try:
                self.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass

    def __repr__(self) -> str:
        active = self.get_active_future_count()
        queue = self.get_queue_size()
        return (
            f"<OptimizedThreadPoolExecutor "
            f"max_workers={self._max_workers}, "
            f"queue_size={self._max_queue_size}, "
            f"active_futures={active}, "
            f"pending={queue}, "
            f"shutdown={self._shutdown}>"
        )


class TTLCache:
    """
    Thread-sicherer TTL-Cache mit LRU-Eviction und periodischer Bereinigung.

    Verbesserungen (v4.3+):
    - Schutz gegen `cleanup_interval = 0` (Division durch Null)
    - Validierung von `maxsize` und `ttl` im Konstruktor
    - `__len__` Methode für einfache Größenabfrage
    - `__repr__` für bessere Debug-Ausgabe
    - Verbesserte Typannotationen
    - Detaillierte Docstrings für alle öffentlichen Methoden

    Die Klasse ist vollständig thread‑sicher durch Verwendung eines `RLock`.
    """

    def __init__(
        self,
        maxsize: int = 128,
        ttl: float = 300.0,
        cleanup_interval: int = 100,
    ) -> None:
        """
        Args:
            maxsize: Maximale Anzahl Einträge (LRU-Eviction). Muss >= 1 sein.
            ttl: Lebensdauer eines Eintrags in Sekunden. Muss > 0 sein.
            cleanup_interval: Anzahl der Zugriffe (`get`/`put`), nach denen eine Bereinigung
                              abgelaufener Einträge durchgeführt wird. Bei 0 wird nie
                              automatisch bereinigt (nur manuell über `clear_expired`).
        """
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")

        self.maxsize = maxsize
        self.ttl = ttl
        # cleanup_interval = 0 bedeutet: keine automatische Bereinigung
        self._cleanup_interval = (
            max(1, cleanup_interval) if cleanup_interval != 0 else 0
        )
        self._cache: OrderedDict[str, Tuple[Any, float]] = OrderedDict()
        self._lock = threading.RLock()
        self._access_counter = 0

    def _clear_expired(self) -> None:
        """
        Entfernt alle abgelaufenen Einträge aus dem Cache.
        Diese Methode muss innerhalb des Locks aufgerufen werden.
        """
        now = time.monotonic()
        # Erstelle eine Liste der abgelaufenen Keys, um während der Iteration zu löschen
        expired = [key for key, (_, ts) in self._cache.items() if now - ts > self.ttl]
        for key in expired:
            del self._cache[key]

    def get(self, key: str) -> Optional[Any]:
        """
        Ruft einen Wert aus dem Cache ab.

        Args:
            key: Der Schlüssel.

        Returns:
            Den Wert oder None, wenn der Schlüssel nicht existiert oder abgelaufen ist.
        """
        with self._lock:
            self._access_counter += 1
            if (
                self._cleanup_interval > 0
                and self._access_counter % self._cleanup_interval == 0
            ):
                self._clear_expired()

            if key in self._cache:
                value, ts = self._cache[key]
                now = time.monotonic()
                if now - ts <= self.ttl:
                    # Noch gültig – als zuletzt verwendet markieren
                    self._cache.move_to_end(key)
                    return value
                else:
                    # Abgelaufen – entfernen
                    del self._cache[key]
            return None

    def put(self, key: str, value: Any) -> None:
        """
        Speichert einen Wert im Cache mit TTL.
        Überschreitet die Anzahl der Einträge die maximale Kapazität,
        werden zuerst alle abgelaufenen Einträge entfernt. Reicht das
        immer noch nicht aus, wird der am längsten nicht verwendete
        (LRU) Eintrag verworfen.

        Args:
            key:   Der Schlüssel (beliebiger String).
            value: Der zu speichernde Wert.
        """
        with self._lock:
            # 1. Zugriffszähler für periodische Bereinigung erhöhen
            self._access_counter += 1

            # 2. Periodische Bereinigung (falls aktiviert)
            if (
                self._cleanup_interval > 0
                and self._access_counter % self._cleanup_interval == 0
            ):
                self._clear_expired()

            now = time.monotonic()

            # 3. Schlüssel bereits vorhanden → aktualisieren
            if key in self._cache:
                self._cache.move_to_end(key)  # LRU‑Ordnung aktualisieren
                self._cache[key] = (value, now)  # Wert und Zeitstempel überschreiben
                return

            # 4. Neuer Eintrag – zuerst Platz schaffen, falls nötig
            if len(self._cache) >= self.maxsize:
                # 4a. Versuche zuerst, abgelaufene Einträge zu entfernen
                self._clear_expired()
                # 4b. Falls immer noch zu viele Einträge, entferne den LRU‑Eintrag
                if len(self._cache) >= self.maxsize:
                    self._cache.popitem(last=False)

            # 5. Neuen Eintrag einfügen
            self._cache[key] = (value, now)

    def clear(self) -> None:
        """Leert den gesamten Cache."""
        with self._lock:
            self._cache.clear()

    def clear_expired(self) -> int:
        """
        Entfernt alle abgelaufenen Einträge.

        Returns:
            Anzahl der entfernten Einträge.
        """
        with self._lock:
            before = len(self._cache)
            self._clear_expired()
            return before - len(self._cache)

    def get_stats(self) -> Dict[str, Any]:
        """
        Gibt Statistiken über den Cache zurück.

        Returns:
            Dictionary mit den Schlüsseln 'size', 'maxsize', 'ttl'.
        """
        with self._lock:
            self._clear_expired()
            return {
                "size": len(self._cache),
                "maxsize": self.maxsize,
                "ttl": self.ttl,
            }

    def __contains__(self, key: str) -> bool:
        """
        Prüft, ob ein gültiger (nicht abgelaufener) Eintrag für den Schlüssel existiert.

        Args:
            key: Der Schlüssel.

        Returns:
            True, wenn der Schlüssel existiert und nicht abgelaufen ist.
        """
        with self._lock:
            if key not in self._cache:
                return False
            _, ts = self._cache[key]
            return time.monotonic() - ts <= self.ttl

    def __len__(self) -> int:
        """
        Gibt die aktuelle Anzahl der **gültigen** Einträge zurück
        (abgelaufene Einträge werden vor dem Zählen entfernt).

        Returns:
            Anzahl der gültigen Einträge.
        """
        with self._lock:
            self._clear_expired()
            return len(self._cache)

    def __repr__(self) -> str:
        """Gibt eine lesbare Repräsentation des Caches zurück."""
        with self._lock:
            return f"<TTLCache size={len(self._cache)}/{self.maxsize} ttl={self.ttl}>"


class LRUCache:
    """
    Thread-sicherer LRU-Cache (Least Recently Used) mit begrenzter Kapazität.

    Die Klasse ist vollständig thread‑sicher durch Verwendung eines `RLock`.
    """

    def __init__(self, maxsize: int = 128) -> None:
        """
        Args:
            maxsize: Maximale Anzahl der Einträge. Muss >= 1 sein.
        """
        if maxsize < 1:
            raise ValueError("maxsize must be >= 1")
        self.maxsize = maxsize
        self._cache: OrderedDict[str, Any] = OrderedDict()
        self._lock = threading.RLock()

    def get(self, key: str) -> Optional[Any]:
        """
        Ruft einen Wert aus dem Cache ab und markiert ihn als zuletzt verwendet.

        Args:
            key: Der Schlüssel.

        Returns:
            Den Wert oder None, wenn der Schlüssel nicht existiert.
        """
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
                return self._cache[key]
            return None

    def put(self, key: str, value: Any) -> None:
        """
        Speichert einen Wert im Cache.
        Ist der Cache voll, wird der am längsten nicht verwendete Eintrag entfernt.

        Args:
            key: Der Schlüssel.
            value: Der zu speichernde Wert.
        """
        with self._lock:
            if key in self._cache:
                # Bereits vorhanden – aktualisieren und an das Ende verschieben
                self._cache.move_to_end(key)
            self._cache[key] = value
            if len(self._cache) > self.maxsize:
                self._cache.popitem(last=False)

    def pop(self, key: str) -> Optional[Any]:
        """
        Entfernt einen Eintrag aus dem Cache und gibt seinen Wert zurück.

        Args:
            key: Der zu entfernende Schlüssel.

        Returns:
            Den Wert des entfernten Eintrags oder None, wenn der Schlüssel nicht existiert.
        """
        with self._lock:
            return self._cache.pop(key, None)

    def popitem(self) -> Tuple[str, Any]:
        """
        Entfernt den am längsten nicht verwendeten Eintrag und gibt (Schlüssel, Wert) zurück.

        Returns:
            Tuple (key, value) des entfernten Eintrags.

        Raises:
            KeyError: Wenn der Cache leer ist.
        """
        with self._lock:
            if not self._cache:
                raise KeyError("popitem(): cache is empty")
            return self._cache.popitem(last=False)

    def get_or_put(self, key: str, default: Any) -> Any:
        """
        Ruft einen Wert ab oder speichert einen Standardwert, falls nicht vorhanden.

        Args:
            key: Der Schlüssel.
            default: Der zu speichernde Wert, falls der Schlüssel fehlt.

        Returns:
            Den vorhandenen oder neu gespeicherten Wert.
        """
        with self._lock:
            if key in self._cache:
                self._cache.move_to_end(key)
                return self._cache[key]
            else:
                self.put(key, default)
                return default

    def peek(self, key: str) -> Optional[Any]:
        """
        Betrachtet einen Wert, ohne die LRU-Ordnung zu ändern.

        Args:
            key: Der Schlüssel.

        Returns:
            Den Wert oder None, wenn der Schlüssel nicht existiert.
        """
        with self._lock:
            return self._cache.get(key)

    def remove(self, key: str) -> bool:
        """
        Entfernt einen Eintrag aus dem Cache (Synonym für `pop`).

        Args:
            key: Der Schlüssel.

        Returns:
            True, wenn der Eintrag entfernt wurde, sonst False.
        """
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False

    def clear(self) -> None:
        """Leert den gesamten Cache."""
        with self._lock:
            self._cache.clear()

    def get_stats(self) -> Dict[str, Any]:
        """
        Gibt Statistiken über den Cache zurück.

        Returns:
            Dictionary mit den Schlüsseln 'size' und 'maxsize'.
        """
        with self._lock:
            return {
                "size": len(self._cache),
                "maxsize": self.maxsize,
            }

    # ------------------------------------------------------------------
    # Dict-ähnliche API (optional, aber praktisch)
    # ------------------------------------------------------------------
    def __getitem__(self, key: str) -> Any:
        """
        Ruft einen Wert ab (wie `get`), wirft aber KeyError bei Fehlen.
        """
        with self._lock:
            if key not in self._cache:
                raise KeyError(key)
            self._cache.move_to_end(key)
            return self._cache[key]

    def __setitem__(self, key: str, value: Any) -> None:
        """Speichert einen Wert (wie `put`)."""
        self.put(key, value)

    def __delitem__(self, key: str) -> None:
        """Entfernt einen Eintrag (wie `pop`), wirft KeyError bei Fehlen."""
        with self._lock:
            if key not in self._cache:
                raise KeyError(key)
            del self._cache[key]

    def __contains__(self, key: str) -> bool:
        """
        Prüft, ob ein Schlüssel im Cache vorhanden ist.
        (Dieser Zugriff ändert nicht die LRU-Ordnung.)
        """
        with self._lock:
            return key in self._cache

    def __len__(self) -> int:
        """Gibt die aktuelle Anzahl der Einträge zurück."""
        with self._lock:
            return len(self._cache)

    def __repr__(self) -> str:
        """Gibt eine lesbare Repräsentation des Caches zurück."""
        with self._lock:
            return f"<LRUCache size={len(self._cache)}/{self.maxsize}>"


class CacheManager:
    """
    Zentrale Verwaltung aller Caches (Transkription, Übersetzung, Audio, generisch).

    Die Klasse ist vollständig thread‑sicher.
    """

    # Maximale Anzahl von Einträgen im generischen LRU-Cache
    GENERIC_CACHE_MAXSIZE: int = 500

    def __init__(self, cleanup_interval: int = 300) -> None:
        """
        Args:
            cleanup_interval: Intervall für die periodische Cache-Bereinigung in Sekunden.
                              Bei 0 wird kein Hintergrund-Thread gestartet.
        """
        # ── 1. Caches initialisieren ────────────────────────────────────
        self.transcription_cache = TTLCache(
            maxsize=Config.TRANSCRIPTION_CACHE_SIZE,
            ttl=Config.TRANSCRIPTION_CACHE_TTL,
        )
        self.translation_cache = LRUCache(
            maxsize=Config.TRANSLATION_CACHE_SIZE,
        )
        self.audio_cache = LRUCache(
            maxsize=Config.AUDIO_CACHE_SIZE,
        )
        self.generic_cache = LRUCache(maxsize=self.GENERIC_CACHE_MAXSIZE)

        # ── 2. Thread-Steuerung ────────────────────────────────────────
        self._stop_event = threading.Event()
        self._cleanup_interval = cleanup_interval
        self._cleanup_thread: Optional[threading.Thread] = None
        self._cleanup_thread_lock = threading.RLock()
        self._disposed = False
        self._disposed_lock = threading.RLock()

        # ── 3. Metriken (thread-safe) ──────────────────────────────────
        self._metrics_lock = threading.RLock()
        self._metrics: Dict[str, int] = {
            "transcription_hits": 0,
            "transcription_misses": 0,
            "translation_hits": 0,
            "translation_misses": 0,
            "audio_hits": 0,
            "audio_misses": 0,
            "generic_hits": 0,
            "generic_misses": 0,
            "evictions_total": 0,
            "cleanup_cycles": 0,
        }

        self._debug = logger.isEnabledFor(logging.DEBUG)

        # ── 4. Cleanup-Thread starten (wenn gewünscht) ──────────────────
        if self._cleanup_interval > 0:
            self._start_cleanup_thread()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "cache",
                "CacheManager initialisiert (cleanup_interval=%ds, "
                "translation_cache=LRU maxsize=%d, generic_cache=LRU maxsize=%d)",
                cleanup_interval,
                Config.TRANSLATION_CACHE_SIZE,
                self.GENERIC_CACHE_MAXSIZE,
            )

    # ==================================================================
    # Generic Cache (beliebige Schlüssel-Wert-Paare)
    # ==================================================================
    def get_cached_generic(self, key: str) -> Optional[Any]:
        """Ruft einen Wert aus dem generischen LRU-Cache ab."""
        result = self.generic_cache.get(key)
        with self._metrics_lock:
            if result is not None:
                self._metrics["generic_hits"] += 1
            else:
                self._metrics["generic_misses"] += 1
        return result

    def put_generic_cache(self, key: str, value: Any) -> None:
        """Speichert einen Wert im generischen LRU-Cache."""
        self.generic_cache.put(key, value)
        if self._debug:
            log_debug("cache", "Cached generic value for key '%.50s…'", key)

    def get_cached_transcription(
        self, text: str, language: str = "unknown"
    ) -> Optional[TranscriptionResult]:
        """Ruft ein transkribiertes Ergebnis aus dem TTL-Cache ab."""
        key = hashlib.sha256(f"{text}:{language}".encode()).hexdigest()
        result = self.transcription_cache.get(key)
        with self._metrics_lock:
            if result is not None:
                self._metrics["transcription_hits"] += 1
            else:
                self._metrics["transcription_misses"] += 1
        return result

    def cache_transcription(self, result: TranscriptionResult) -> str:
        """Speichert ein Transkriptionsergebnis im Cache und gibt den Schlüssel zurück."""
        key = hashlib.sha256(f"{result.text}:{result.language}".encode()).hexdigest()
        self.transcription_cache.put(key, result)
        if self._debug:
            log_debug("cache", f"Cached transcription: {result.text[:50]}...")
        return key

    # ==================================================================
    # Übersetzungs-Cache (LRU)
    # ==================================================================
    def get_cached_translation(
        self, original: str, target_lang: str
    ) -> Optional[TranslationResult]:
        """Ruft eine Übersetzung aus dem LRU-Cache ab."""
        key = hashlib.sha256((original + target_lang).encode()).hexdigest()
        result = self.translation_cache.get(key)
        with self._metrics_lock:
            if result is not None:
                self._metrics["translation_hits"] += 1
            else:
                self._metrics["translation_misses"] += 1
        return result

    def cache_translation(self, result: TranslationResult) -> str:
        """Speichert eine Übersetzung im Cache und gibt den Schlüssel zurück."""
        key = hashlib.sha256(
            (result.original + result.target_lang).encode()
        ).hexdigest()
        self.translation_cache.put(key, result)
        if self._debug:
            log_debug("cache", f"Cached translation: {result.translated[:50]}...")
        return key

    def get_cached_audio(self, identifier: str) -> Optional[bytes]:
        """Ruft Audiodaten aus dem LRU-Cache ab."""
        key = hashlib.sha256(identifier.encode()).hexdigest()
        result = self.audio_cache.get(key)
        with self._metrics_lock:
            if result is not None:
                self._metrics["audio_hits"] += 1
            else:
                self._metrics["audio_misses"] += 1
        return result

    def cache_audio(self, audio_data: bytes, identifier: str) -> str:
        """Speichert Audiodaten im Cache und gibt den Schlüssel zurück."""
        key = hashlib.sha256(identifier.encode()).hexdigest()
        self.audio_cache.put(key, audio_data)
        if self._debug:
            log_debug(
                "cache",
                f"Cached audio ({len(audio_data)} bytes) for {identifier[:20]}...",
            )
        return key

    def _start_cleanup_thread(self) -> None:
        """Startet den Hintergrund‑Thread für die periodische Cache‑Bereinigung."""
        with self._cleanup_thread_lock:
            if self._cleanup_thread is not None and self._cleanup_thread.is_alive():
                if self._debug:
                    log_debug("cache", "Cleanup thread already running")
                return

            self._stop_event.clear()
            self._cleanup_thread = threading.Thread(
                target=self._cleanup_worker,
                daemon=True,
                name="CacheCleanup",
            )
            self._cleanup_thread.start()
            if self._debug:
                log_debug(
                    "cache",
                    "CacheCleanup thread started (daemon, interval=%ds, tid=%s)",
                    self._cleanup_interval,
                    self._cleanup_thread.ident,
                )

    def _cleanup_worker(self) -> None:
        """
        Worker‑Methode für den periodischen Cleanup‑Thread.
        Verwendet `_stop_event.wait()` für sofortige Reaktion auf Shutdown.
        """
        logger.debug("CacheCleanup thread started")
        last_error_time = 0.0
        consecutive_errors = 0

        while not self._stop_event.wait(self._cleanup_interval):
            if self._disposed:
                logger.debug("CacheCleanup: disposed flag detected, exiting")
                break

            try:
                start = time.perf_counter()
                expired = self.clear_expired_entries()
                duration = (time.perf_counter() - start) * 1000

                with self._metrics_lock:
                    self._metrics["cleanup_cycles"] += 1

                if (
                    self._debug
                    or DEBUG_LEVEL >= 3
                    or expired["transcription_expired"] > 0
                    or expired["translation_expired"] > 0
                    or expired["audio_expired"] > 0
                ):

                    log_debug(
                        "cache",
                        f"Cleanup cycle #{self._metrics['cleanup_cycles']}: "
                        f"{expired['transcription_expired']} transcription, "
                        f"{expired['translation_expired']} translation, "
                        f"{expired['audio_expired']} audio entries removed "
                        f"in {duration:.2f}ms",
                    )

                consecutive_errors = 0

            except Exception as e:
                now = time.time()
                if now - last_error_time >= 60.0:
                    consecutive_errors += 1
                    logger.error(
                        f"Fehler bei periodischer Cache-Bereinigung (Versuch #{consecutive_errors}): {e}",
                        exc_info=True,
                    )
                    last_error_time = now
                elif DEBUG_LEVEL >= 3:
                    log_debug("cache", f"Cleanup error (suppressed): {e}")

                if self._stop_event.wait(1.0):
                    break

        logger.debug("CacheCleanup thread terminated")

    def clear_expired_entries(self) -> Dict[str, int]:
        """
        Entfernt alle abgelaufenen Einträge aus den zeitbasierten Caches.
        Der LRU-Übersetzungs‑Cache hat keine zeitliche Begrenzung.
        """
        trans_exp = self.transcription_cache.clear_expired()
        # Übersetzungscache hat kein Ablaufdatum – nichts zu tun
        audio_exp = 0  # LRU-Cache hat auch kein Ablaufdatum

        with self._metrics_lock:
            self._metrics["evictions_total"] += trans_exp

        return {
            "transcription_expired": trans_exp,
            "translation_expired": 0,
            "audio_expired": audio_exp,
        }

    def clear_all_caches(self) -> Dict[str, int]:
        """
        Leert **alle** Caches (Transkription, Übersetzung, Audio, generisch)
        und gibt die Anzahl der jeweils entfernten Einträge zurück.

        Returns:
            Dictionary mit den Namen der Caches und der Anzahl gelöschter Einträge.
        """
        cleared = {}
        with self._disposed_lock:
            if self._disposed:
                logger.warning("clear_all_caches called on disposed CacheManager")
                return {"error": "disposed"}

            # 1. Transcription Cache (TTL)
            trans_before = self.transcription_cache.get_stats().get("size", 0)
            self.transcription_cache.clear()
            cleared["transcription"] = trans_before

            # 2. Translation Cache (LRU)
            transl_before = self.translation_cache.get_stats().get("size", 0)
            self.translation_cache.clear()
            cleared["translation"] = transl_before

            # 3. Audio Cache (LRU)
            audio_before = self.audio_cache.get_stats().get("size", 0)
            self.audio_cache.clear()
            cleared["audio"] = audio_before

            # 4. Generic Cache (LRU)
            generic_before = self.generic_cache.get_stats().get("size", 0)
            self.generic_cache.clear()
            cleared["generic"] = generic_before

            # Metriken zurücksetzen (optional)
            self.reset_metrics()

            if self._debug:
                log_debug("cache", f"All caches cleared: {cleared}")

            return cleared

    def get_stats(self) -> Dict[str, Any]:
        """Gibt detaillierte Statistiken über alle Caches zurück."""
        return {
            "transcription_cache": self.transcription_cache.get_stats(),
            "translation_cache": self.translation_cache.get_stats(),
            "audio_cache": self.audio_cache.get_stats(),
            "generic_cache": self.generic_cache.get_stats(),
        }

    def get_metrics(self) -> Dict[str, int]:
        """Gibt die Zugriffsmetriken zurück (Kopie)."""
        with self._metrics_lock:
            return self._metrics.copy()

    def reset_metrics(self) -> None:
        """Setzt alle Zugriffsmetriken zurück (behält evictions_total und cleanup_cycles)."""
        with self._metrics_lock:
            for key in list(self._metrics.keys()):
                if key not in ("evictions_total", "cleanup_cycles"):
                    self._metrics[key] = 0

    # ==================================================================
    # Debug-Informationen
    # ==================================================================
    def get_debug_info(self) -> Dict[str, Any]:
        """Liefert umfangreiche Debug‑Informationen für Diagnosezwecke."""
        with self._disposed_lock:
            disposed = self._disposed
        return {
            "cleanup_interval": self._cleanup_interval,
            "cleanup_thread_alive": (
                self._cleanup_thread.is_alive() if self._cleanup_thread else False
            ),
            "stop_event_set": self._stop_event.is_set(),
            "disposed": disposed,
            "metrics": self.get_metrics(),
            "cache_stats": self.get_stats(),
        }

    # ==================================================================
    # Ressourcenfreigabe
    # ==================================================================
    def dispose(self, force: bool = False) -> None:
        """
        Gibt alle Ressourcen des CacheManagers frei.

        Args:
            force: Wenn True, wird der Cleanup-Thread sofort abgebrochen
                   (ohne auf die aktuelle Iteration zu warten) und die Caches
                   werden sofort geleert. Andernfalls wird der Thread geordnet
                   beendet (Join mit 5 s Timeout).
        """
        with self._disposed_lock:
            if self._disposed:
                if DEBUG_LEVEL >= 3:
                    log_debug("cache", "CacheManager already disposed, skipping")
                return
            self._disposed = True

        # Statistik vor dem Löschen ausgeben
        if self._debug or DEBUG_LEVEL >= 3:
            stats = self.get_stats()
            log_debug(
                "cache",
                f"Disposing CacheManager - current sizes: "
                f"transcription={stats['transcription_cache']['size']}, "
                f"translation={stats['translation_cache']['size']}, "
                f"audio={stats['audio_cache']['size']}, "
                f"generic={stats['generic_cache']['size']}",
            )

        # Cleanup-Thread stoppen
        self._stop_event.set()
        if self._cleanup_thread is not None and self._cleanup_thread.is_alive():
            if not force:
                if DEBUG_LEVEL >= 3:
                    log_debug("cache", "Waiting for cleanup thread to finish...")
                self._cleanup_thread.join(timeout=5.0)
                if self._cleanup_thread.is_alive():
                    logger.warning(
                        "CacheCleanup thread did not terminate within timeout – "
                        "marking as daemon."
                    )
                    self._cleanup_thread.daemon = True
                else:
                    if DEBUG_LEVEL >= 3:
                        log_debug("cache", "Cleanup thread terminated normally")
            else:
                if DEBUG_LEVEL >= 3:
                    log_debug("cache", "Force mode: not waiting for cleanup thread")
        self._cleanup_thread = None

        # Caches leeren
        self.transcription_cache.clear()
        self.translation_cache.clear()
        self.audio_cache.clear()
        self.generic_cache.clear()

        # Metriken zurücksetzen (optional)
        with self._metrics_lock:
            self._metrics.clear()

        # Garbage Collection anstoßen
        gc.collect()

        if DEBUG_LEVEL >= 3:
            log_debug("cache", "CacheManager disposed")
        else:
            logger.debug("CacheManager disposed")

    def __repr__(self) -> str:
        stats = self.get_stats()
        return (
            f"<CacheManager transcription={stats['transcription_cache']['size']}/"
            f"{stats['transcription_cache']['maxsize']} "
            f"translation={stats['translation_cache']['size']}/"
            f"{stats['translation_cache']['maxsize']}>"
        )


class DebugFilter(logging.Filter):
    """
    Thread‑sicherer Log‑Filter für komponentenbezogene Debug‑Ausgaben.

    Filterregeln (in dieser Priorität):
        1) debug_level >= 3 → ALLES durchlassen (maximale Ausgabe)
        2) Komponente in Whitelist → durchlassen (mit Rate‑Limit für DEBUG)
        3) Schweregrad WARNING oder höher → durchlassen
        4) sonst blockieren
    """

    def __init__(
        self,
        enable_metrics: bool = False,
        rate_limit: float = 0.0,
        debug_level: int = 0,
        debug_components: Optional[List[str]] = None,
        min_component_level: int = 1,
        log_filter_decisions: Optional[bool] = None,
    ) -> None:
        """
        Args:
            enable_metrics: Wenn True, werden interne Zähler geführt.
            rate_limit: Maximale Anzahl von Debug‑Meldungen pro Sekunde
                und Komponente. 0 = deaktiviert.
            debug_level: Globaler Debug‑Level (0-3).
            debug_components: Liste von Komponenten, deren Debug‑Ausgaben
                immer angezeigt werden (unabhängig vom globalen Level).
            min_component_level: Mindest‑Schweregrad für Komponenten-Meldungen
                (0=DEBUG, 1=INFO, 2=WARNING, 3=ERROR).
            log_filter_decisions: Wenn True, wird jede Filterentscheidung
                (mit Ausnahme von Regel 1) auf DEBUG geloggt. Wenn None,
                wird automatisch True gesetzt, wenn debug_level >= 4 oder
                "filter" in debug_components enthalten ist.
        """
        super().__init__()
        self._lock = threading.RLock()
        self._enable_metrics = enable_metrics
        self._rate_limit = max(0.0, rate_limit)
        self._debug_level = debug_level
        self._debug_components = set(debug_components or [])
        self._min_component_level = max(0, min(3, min_component_level))

        # Automatische Entscheidung für log_filter_decisions
        if log_filter_decisions is None:
            self._log_filter_decisions = (
                debug_level >= 4 or "filter" in self._debug_components
            )
        else:
            self._log_filter_decisions = log_filter_decisions

        # Token‑Bucket‑Cache: {component: (tokens, last_refill)}
        self._buckets: Dict[str, Tuple[float, float]] = {}

        # Metriken
        self._passed = 0
        self._blocked = 0
        self._rate_limited = 0
        self._errors = 0
        self._total_processed = 0

        if DEBUG_LEVEL >= 3:
            log_debug(
                "filter",
                f"DebugFilter initialisiert: level={debug_level}, "
                f"components={debug_components}, "
                f"rate_limit={rate_limit}, "
                f"log_filter_decisions={self._log_filter_decisions}",
            )

    def update_config(
        self,
        debug_level: Optional[int] = None,
        debug_components: Optional[List[str]] = None,
        enable_metrics: Optional[bool] = None,
        rate_limit: Optional[float] = None,
        min_component_level: Optional[int] = None,
        log_filter_decisions: Optional[bool] = None,
    ) -> None:
        """Aktualisiert die Filter‑Konfiguration zur Laufzeit (thread‑sicher)."""
        with self._lock:
            if debug_level is not None:
                self._debug_level = max(0, min(3, debug_level))
            if debug_components is not None:
                self._debug_components = set(debug_components)
            if enable_metrics is not None:
                self._enable_metrics = enable_metrics
            if rate_limit is not None:
                self._rate_limit = max(0.0, rate_limit)
                if self._rate_limit == 0.0:
                    self._buckets.clear()
            if min_component_level is not None:
                self._min_component_level = max(0, min(3, min_component_level))
            if log_filter_decisions is not None:
                self._log_filter_decisions = log_filter_decisions
            else:
                # Automatisch setzen, wenn nicht explizit übergeben
                self._log_filter_decisions = (
                    self._debug_level >= 4 or "filter" in self._debug_components
                )

        if DEBUG_LEVEL >= 4:
            log_debug("filter", "DebugFilter-Konfiguration aktualisiert")

    # ─── KERNMETHODE: FILTER ─────────────────────────────────────

    def filter(self, record: logging.LogRecord) -> bool:
        """
        Entscheidet, ob der Log‑Eintrag ausgegeben wird.
        Bei Exceptions wird die Meldung sicherheitshalber durchgelassen.
        """
        try:
            result = self._filter_impl(record)
            if self._log_filter_decisions and not getattr(
                record, "_filter_logged", False
            ):
                # Protokolliere die Entscheidung, aber vermeide Rekursion
                record._filter_logged = True
                logger = logging.getLogger("dragon")
                if logger.isEnabledFor(logging.DEBUG):
                    logger.debug(
                        f"[Filter] {record.levelname}: {record.getMessage()[:80]} -> {'PASS' if result else 'BLOCK'}",
                        extra={"component": "filter", "_filter_logged": True},
                    )
            return result
        except Exception:
            if self._enable_metrics:
                with self._lock:
                    self._errors += 1
            return True

    # ── Klassenkonstante für Level‑Mapping ───────────────────────

    _LEVEL_MAP = {
        0: logging.DEBUG,
        1: logging.INFO,
        2: logging.WARNING,
        3: logging.ERROR,
    }

    def _filter_impl(self, record: logging.LogRecord) -> bool:
        """
        Eigentliche Filter‑Logik (thread‑sicher).

        Filterregeln (in dieser Priorität):
        1) globaler Debug‑Level >= 3 → ALLES durchlassen
        2) Komponente in Whitelist → durchlassen (mit Rate‑Limit für DEBUG)
        3) Schweregrad WARNING oder höher → durchlassen
        4) sonst blockieren
        """
        try:
            with self._lock:
                curr_level = self._debug_level
                curr_components = self._debug_components
                metrics_on = self._enable_metrics
                rate_limit = self._rate_limit
                min_comp_level = self._min_component_level
                self._total_processed += 1

            # ─── REGEL 1: Globaler Debug‑Level >= 3 → ALLES durchlassen ───
            if curr_level >= 3:
                if metrics_on:
                    with self._lock:
                        self._passed += 1
                return True

            # ─── REGEL 2: Komponenten‑Filter ──────────────────────────────
            component = getattr(record, "component", None)

            if component and component in curr_components:
                min_level = self._LEVEL_MAP.get(min_comp_level, logging.DEBUG)
                if record.levelno < min_level:
                    if metrics_on:
                        with self._lock:
                            self._blocked += 1
                    return False

                if record.levelno <= logging.DEBUG and not self._check_rate_limit(
                    component, rate_limit
                ):
                    if metrics_on:
                        with self._lock:
                            self._rate_limited += 1
                    return False

                if metrics_on:
                    with self._lock:
                        self._passed += 1
                return True

            # ─── REGEL 3: Schweregrad WARNING oder höher ──────────────────
            if record.levelno >= logging.WARNING:
                if metrics_on:
                    with self._lock:
                        self._passed += 1
                return True

            # ─── REGEL 4: Sonst blockieren ──────────────────────────────────
            if metrics_on:
                with self._lock:
                    self._blocked += 1
            return False

        except Exception:
            if self._enable_metrics:
                with self._lock:
                    self._errors += 1
            return True

    def _check_rate_limit(
        self,
        component: str,
        limit: float,
        burst: Optional[float] = None,
    ) -> bool:
        """Token‑Bucket mit optionaler Burst‑Größe."""
        if limit <= 0.0:
            return True

        if burst is None:
            burst = limit

        now = time.monotonic()
        try:
            with self._lock:
                tokens, last = self._buckets.get(component, (burst, now))
                elapsed = now - last
                tokens = min(burst, tokens + elapsed * limit)

                if tokens >= 1.0:
                    tokens -= 1.0
                    self._buckets[component] = (tokens, now)
                    return True
                else:
                    self._buckets[component] = (tokens, now)
                    return False
        except Exception:
            return True

    def get_metrics(self) -> Dict[str, int]:
        """Gibt die aktuellen Filter‑Statistiken zurück."""
        if not self._enable_metrics:
            return {"metrics_disabled": True}
        with self._lock:
            return {
                "passed": self._passed,
                "blocked": self._blocked,
                "rate_limited": self._rate_limited,
                "errors": self._errors,
                "total_processed": self._total_processed,
            }

    def reset_metrics(self) -> None:
        """Setzt alle Zähler zurück."""
        if self._enable_metrics:
            with self._lock:
                self._passed = 0
                self._blocked = 0
                self._rate_limited = 0
                self._errors = 0
                self._total_processed = 0

    def add_component(self, component: str) -> None:
        with self._lock:
            self._debug_components.add(component)

    def remove_component(self, component: str) -> None:
        with self._lock:
            self._debug_components.discard(component)

    def set_components(self, components: List[str]) -> None:
        with self._lock:
            self._debug_components = set(components)

    def get_components(self) -> List[str]:
        with self._lock:
            return list(self._debug_components)

    def has_component(self, component: str) -> bool:
        with self._lock:
            return component in self._debug_components

    @property
    def debug_level(self) -> int:
        with self._lock:
            return self._debug_level

    @debug_level.setter
    def debug_level(self, value: int) -> None:
        with self._lock:
            self._debug_level = max(0, min(3, value))

    @property
    def min_component_level(self) -> int:
        with self._lock:
            return self._min_component_level

    @min_component_level.setter
    def min_component_level(self, value: int) -> None:
        with self._lock:
            self._min_component_level = max(0, min(3, value))

    @property
    def rate_limit(self) -> float:
        with self._lock:
            return self._rate_limit

    @rate_limit.setter
    def rate_limit(self, value: float) -> None:
        with self._lock:
            self._rate_limit = max(0.0, value)
            if self._rate_limit == 0.0:
                self._buckets.clear()

    # ─── DARSTELLUNG ──────────────────────────────────────────────

    def __repr__(self) -> str:
        with self._lock:
            return (
                f"<DebugFilter level={self._debug_level}, "
                f"min_comp_level={self._min_component_level}, "
                f"components={sorted(self._debug_components)}, "
                f"rate_limit={self._rate_limit}/s, "
                f"metrics={self._enable_metrics}, "
                f"passed={self._passed}, blocked={self._blocked}, "
                f"rate_limited={self._rate_limited}, errors={self._errors}, "
                f"total_processed={self._total_processed}>"
            )


# ─────────────────────────────────────────────────────────────────────────────
# HILFSFUNKTIONEN
# ─────────────────────────────────────────────────────────────────────────────
# ─────────────────────────────────────────────────────────────────────────────
# HILFSFUNKTIONEN
# ─────────────────────────────────────────────────────────────────────────────


def log_debug(component: str, msg: str, *args: Any, **kwargs: Any) -> None:
    """
    Schreibt eine Debug‑Meldung mit Komponenten‑Kontext.

    Diese Funktion delegiert die Filterung (Schweregrad, Komponenten‑Whitelist,
    Rate‑Limiting) an den bereits registrierten `DebugFilter`. Sie selbst
    führt nur eine minimale Vorabprüfung durch, um den Overhead bei
    deaktiviertem Debugging zu minimieren.

    Args:
        component: Name der Komponente (z. B. ``"ollama"``, ``"ffmpeg"``).
        msg: Die Format‑Nachricht (%-Format oder f‑String).
        *args: Argumente für die Formatierung.
        **kwargs: Zusätzliche Schlüsselwort‑Argumente (z. B. `exc_info`).
    """
    # ── 1. Logger sicher holen ──────────────────────────────────────
    try:
        _logger = logging.getLogger("dragon")
    except Exception:
        return

    # ── 2. Schneller Vorfilter: DEBUG überhaupt aktiviert? ─────────
    #    Verwende den globalen DEBUG_LEVEL, um teure Aufrufe zu vermeiden.
    if DEBUG_LEVEL < 1:
        return

    if not _logger.isEnabledFor(logging.DEBUG):
        return

    # ── 3. Meldung mit Komponenten‑Kontext ausgeben ────────────────
    _logger.debug(msg, *args, extra={"component": component}, **kwargs)


def log_exception(
    component: str, msg: str, exc: Exception, level: str = "error"
) -> None:
    """
    Protokolliert eine Exception mit Komponenten‑Kontext.

    Die Exception wird mit vollständigem Stacktrace geloggt. Der Parameter `exc`
    wird als `exc_info` verwendet, sodass der Traceback korrekt ausgegeben wird.
    Die Exception wird nicht in die Format‑Nachricht eingefügt, um doppelte Ausgabe
    zu vermeiden.

    Args:
        component: Name der betroffenen Komponente (z. B. ``"ollama"``).
        msg: Beschreibung des Fehlers (kein Platzhalter für die Exception).
        exc: Das Exception‑Objekt.
        level: Schweregrad (``"error"``, ``"warning"``, ``"debug"``).
               Bei unbekanntem Wert wird ``"error"`` verwendet.
    """
    # ── 1. Fallback für leere Werte ──────────────────────────────────
    _component = component if component else "unknown"
    _msg = msg if msg else "No message"

    # ── 2. Logger sicher holen ───────────────────────────────────────
    try:
        _logger = logging.getLogger("dragon")
    except Exception:
        return

    # ── 3. Level normalisieren ───────────────────────────────────────
    level_lower = level.lower() if isinstance(level, str) else "error"
    if level_lower not in ("error", "warning", "debug"):
        level_lower = "error"

    # ── 4. Nachricht ohne Exception-String ───────────────────────────
    log_msg = f"[{_component}] {_msg}"

    # ── 5. Loggen mit exc_info=exc (gibt vollen Traceback aus) ───────
    if level_lower == "error":
        _logger.error(log_msg, exc_info=exc, extra={"component": component})
    elif level_lower == "warning":
        _logger.warning(log_msg, exc_info=exc, extra={"component": component})
    else:  # debug
        _logger.debug(log_msg, exc_info=exc, extra={"component": component})


def split_sentences(text: str, language: Optional[str] = None) -> List[str]:
    """
    Robustes Satz‑Splitting ohne variable‑width lookbehind.
    Funktioniert mit Python >= 3.14.

    Zerlegt einen Text in Sätze anhand von Satzendzeichen (., !, ?, 。, ！, ？)
    und beachtet gängige Abkürzungen (Dr., Mr., etc.), damit diese nicht
    fälschlich als Satzende interpretiert werden.

    Args:
        text: Der zu zerlegende Text.
        language: Optionaler Sprachcode ('de', 'en', …). Wird eine Sprache
            angegeben, wird eine spezifische Abkürzungsliste verwendet.
            Ist keine Sprache angegeben, wird eine umfangreiche, sprach-
            übergreifende Liste genutzt, die sowohl deutsche als auch
            englische und weitere gängige Abkürzungen enthält.

    Returns:
        Eine Liste von Sätzen (ohne abschließende Leerzeichen).
        Bei leerer Eingabe wird eine leere Liste zurückgegeben.
    """
    if not text or not text.strip():
        return []

    # ── Sprachspezifische Abkürzungslisten ─────────────────────────
    _ABBREVIATIONS: Dict[str, frozenset[str]] = {
        "de": frozenset(
            {
                "Dr.",
                "Prof.",
                "etc.",
                "usw.",
                "z.B.",
                "d.h.",
                "bzw.",
                "ca.",
                "ggf.",
                "evtl.",
                "i.d.R.",
                "u.a.",
                "sog.",
                "inkl.",
                "exkl.",
                "bez.",
                "bzw.",
                "v.a.",
                "u.U.",
                "m.E.",
                "o.ä.",
                "Nr.",
                "Bd.",
                "Jr.",
                "Sr.",
                "Hr.",
                "Fr.",
            }
        ),
        "en": frozenset(
            {
                "Dr.",
                "Mr.",
                "Mrs.",
                "Ms.",
                "Prof.",
                "etc.",
                "e.g.",
                "i.e.",
                "vs.",
                "ca.",
                "No.",
                "Jr.",
                "Sr.",
                "St.",
                "Ave.",
                "Blvd.",
                "Rd.",
                "Dept.",
                "Univ.",
                "et al.",
                "a.m.",
                "p.m.",
                "Ph.D.",
                "M.D.",
                "B.A.",
                "M.A.",
                "B.Sc.",
                "M.Sc.",
            }
        ),
        "fr": frozenset(
            {
                "M.",
                "Mme",
                "Mlle",
                "Dr.",
                "Prof.",
                "etc.",
                "p.ex.",
                "c.-à-d.",
                "av.",
                "apr.",
                "env.",
                "nr.",
                "vol.",
            }
        ),
        "es": frozenset(
            {
                "Dr.",
                "Dra.",
                "Sr.",
                "Sra.",
                "Srta.",
                "Prof.",
                "etc.",
                "ej.",
                "p.ej.",
                "aprox.",
                "núm.",
                "vol.",
            }
        ),
        "it": frozenset(
            {
                "Dott.",
                "Prof.",
                "Sig.",
                "Sig.ra",
                "Sig.na",
                "ecc.",
                "es.",
                "p.es.",
                "n.",
                "vol.",
            }
        ),
        "pt": frozenset(
            {
                "Dr.",
                "Dra.",
                "Sr.",
                "Sra.",
                "Srta.",
                "Prof.",
                "etc.",
                "ex.",
                "p.ex.",
                "aprox.",
                "nº.",
                "vol.",
            }
        ),
        "nl": frozenset(
            {
                "Dr.",
                "Prof.",
                "etc.",
                "bijv.",
                "d.w.z.",
                "m.a.w.",
                "o.a.",
                "v.a.",
                "t/m",
                "bv.",
                "mw.",
                "dhr.",
            }
        ),
        "pl": frozenset(
            {
                "dr",
                "prof.",
                "np.",
                "tzn.",
                "itp.",
                "tj.",
                "ul.",
                "nr",
                "rys.",
                "tab.",
                "rozdz.",
            }
        ),
        "ru": frozenset(
            {
                "др.",
                "проф.",
                "и т.д.",
                "т.е.",
                "напр.",
                "см.",
                "стр.",
                "рис.",
                "табл.",
                "гл.",
                "раз.",
            }
        ),
        "ja": frozenset({"氏", "博士", "教授", "など", "例", "図", "表", "参照"}),
        "zh": frozenset({"博士", "教授", "例如", "等", "图", "表", "参见"}),
        "ko": frozenset({"박사", "교수", "예를", "등", "그림", "표", "참조"}),
    }

    # ── Fallback: kombinierte, sprachübergreifende Liste ───────────
    _FALLBACK_ABBREVIATIONS: frozenset[str] = frozenset(
        abbr for lang_set in _ABBREVIATIONS.values() for abbr in lang_set
    )

    # ── Auswahl der Abkürzungsmenge ────────────────────────────────
    if language and language.lower() in _ABBREVIATIONS:
        abbreviations = _ABBREVIATIONS[language.lower()]
    else:
        abbreviations = _FALLBACK_ABBREVIATIONS

    # ── 1. Grober Split an Satzendzeichen + folgendem Leerzeichen ─
    parts = re.split(r"(?<=[.!?。！？])\s+", text.strip())
    sentences = []

    # ── 2. Nachträglich Abkürzungen wieder ankleben ────────────────
    escaped = [re.escape(abbr) for abbr in abbreviations]
    escaped.sort(key=len, reverse=True)
    pattern = r"\b(?:" + "|".join(escaped) + r")$"
    _abbr_pattern = re.compile(pattern, re.IGNORECASE)

    for part in parts:
        if not part:
            continue
        if sentences and _abbr_pattern.search(sentences[-1]):
            sentences[-1] = sentences[-1] + " " + part
        else:
            sentences.append(part)

    return sentences


class AppContext:
    """
    Zentraler, thread‑sicherer Singleton‑Kontext für die gesamte Anwendung.

    Bietet Zugriff auf:
    - `event_bus` (zentrale Event‑Verwaltung)
    - `cache_manager` (zentrales Caching)
    - `theme` (aktuelles Theme‑Objekt)
    - Methoden zum Wechseln des Themes und zur Abfrage der aktuellen Konfiguration.

    **Verwendung:**
        >>> ctx = AppContext()
        >>> ctx.event_bus.subscribe("transcription", callback)
        >>> ctx.cache_manager.get_cached_transcription(...)
        >>> current_theme = ctx.theme

    **Hinweis:** Diese Klasse ist ein **Thread‑sicherer Singleton**.
    Mehrfache Instanziierungen liefern dasselbe Objekt zurück.
    Direkte Instanziierung von `EventBus`, `CacheManager` oder `Theme` außerhalb
    des Kontexts sollte vermieden werden, um Inkonsistenzen zu verhindern.
    """

    _instance: Optional["AppContext"] = None
    _instance_lock = threading.Lock()
    _init_lock = threading.RLock()
    _initialized: bool = False

    # Theme‑Mapping als Klassenattribut (unveränderlich)
    _THEME_MAP: ClassVar[Dict[str, type]] = {
        "dark": DarkTheme,
        "light": LightTheme,
        "pastel": PastelTheme,
        "highcontrast": HighContrastTheme,
        "dracula": DraculaTheme,
        "nord": NordTheme,
        "solarized": SolarizedDarkTheme,
        "gruvbox": GruvboxDarkTheme,
        "onedark": OneDarkTheme,
        "monokai": MonokaiTheme,
        "a11y-dark": A11yDarkTheme,
        "catppuccin": CatppuccinMochaTheme,
        "tokyonight": TokyoNightTheme,
    }

    # Cache für Theme‑Instanzen (lazy, vermeidet mehrfache Instanziierung)
    _theme_cache: ClassVar[Dict[str, Any]] = {}
    _theme_cache_lock = threading.RLock()

    def __new__(cls) -> "AppContext":
        """Erzeugt das Singleton‑Objekt (thread‑sicher)."""
        with cls._instance_lock:
            if cls._instance is None:
                instance = super().__new__(cls)
                cls._instance = instance
            else:
                instance = cls._instance
        return instance

    def __init__(self) -> None:
        """
        Initialisiert den AppContext genau einmal (thread‑sicher).
        """
        with self._init_lock:
            if self._initialized:
                return
            self._initialized = True

        # ── 1. Theme initialisieren (DarkTheme als Default) ──────────
        self._theme_name: str = "dark"
        self._theme: Any = DarkTheme()

        # ── 2. CacheManager erstellen ────────────────────────────────
        self.cache_manager: CacheManager = CacheManager()

        # ── 3. DebugFilter für Logging ───────────────────────────────
        self._debug_filter = DebugFilter()
        logger.addFilter(self._debug_filter)

        # ── 4. EventBus erstellen (mit Scheduler für GUI‑Thread) ─────
        self.event_bus: EventBus = EventBus()

        # ── 5. Optionale spätere Registrierung des Schedulers ────────
        #    (Wird später von der GUI gesetzt, wenn der Hauptthread bereit ist)
        self._scheduler_set = False

        if DEBUG_LEVEL >= 3:
            log_debug("app", "AppContext initialisiert (Theme=dark, Cache, EventBus)")

    # ──────────────────────────────────────────────────────────────
    # Properties für Theme (mit Lazy‑Caching)
    # ──────────────────────────────────────────────────────────────
    @property
    def theme(self) -> Any:
        """Aktuelles Theme‑Objekt (read‑only)."""
        return self._theme

    @property
    def theme_name(self) -> str:
        """Aktueller Theme‑Name (z. B. 'dark', 'light')."""
        return self._theme_name

    def set_theme(self, theme_name: str) -> None:
        """
        Wechselt das aktuelle Theme (thread‑sicher).

        Das Theme‑Objekt wird aus einem internen Cache geladen oder neu instanziiert.
        Bei ungültigem Namen wird `DarkTheme` verwendet.

        Args:
            theme_name: Name des Themes (z. B. 'dark', 'light', 'nord').

        Raises:
            KeyError: Wenn der Theme‑Name nicht existiert (wird abgefangen).
        """
        theme_name_lower = theme_name.lower()
        # ── 1. Theme‑Instanz aus Cache holen oder neu erzeugen ──────
        with self._theme_cache_lock:
            if theme_name_lower not in self._theme_cache:
                theme_class = self._THEME_MAP.get(theme_name_lower, DarkTheme)
                self._theme_cache[theme_name_lower] = theme_class()
            new_theme = self._theme_cache[theme_name_lower]

        # ── 2. Atomarer Wechsel (unter Lock) ────────────────────────
        with self._init_lock:  # Verwende _init_lock, um race‑frei zu sein
            old_name = self._theme_name
            self._theme = new_theme
            self._theme_name = theme_name_lower

        if DEBUG_LEVEL >= 3:
            log_debug(
                "app", "Theme gewechselt von '%s' zu '%s'", old_name, theme_name_lower
            )

        # ── 3. EventBus benachrichtigen (falls vorhanden) ────────────
        if self.event_bus is not None:
            try:
                self.event_bus.emit(
                    "theme_changed",
                    {
                        "old_theme": old_name,
                        "new_theme": theme_name_lower,
                    },
                )
            except Exception as e:
                log_debug("app", "Theme‑Event konnte nicht gesendet werden: %s", e)

    def set_scheduler(self, scheduler: Callable[[Callable, int], None]) -> None:
        """
        Setzt den Scheduler für den EventBus (z. B. um GUI‑Updates zu planen).

        Diese Methode sollte **einmal** von der GUI aufgerufen werden, wenn der
        Haupt‑Thread bereit ist (z. B. nach dem Erstellen des `tk.Tk()`‑Objekts).

        Args:
            scheduler: Eine Funktion, die einen Callback und eine Verzögerung
                       (in Millisekunden) erhält, z. B. `root.after`.
        """
        if self.event_bus is not None:
            self.event_bus.set_scheduler(scheduler)
            self._scheduler_set = True
            if DEBUG_LEVEL >= 3:
                log_debug("app", "EventBus‑Scheduler gesetzt")
        else:
            logger.warning("set_scheduler aufgerufen, aber event_bus ist None")

    def get_debug_info(self) -> Dict[str, Any]:
        """Gibt Debug‑Informationen über den AppContext zurück."""
        with self._init_lock:
            theme_name = self._theme_name
        return {
            "theme_name": theme_name,
            "scheduler_set": self._scheduler_set,
            "event_bus_info": (
                self.event_bus.get_debug_info() if self.event_bus else None
            ),
            "cache_stats": (
                self.cache_manager.get_stats() if self.cache_manager else None
            ),
        }

    def dispose(self) -> None:
        """Gibt alle Ressourcen des AppContext frei (idempotent)."""
        with self._init_lock:
            if not self._initialized:
                return
            self._initialized = False

        logger.debug("AppContext.dispose() wird ausgeführt...")
        if self.event_bus is not None:
            self.event_bus.clear()
            self.event_bus = None
        if self.cache_manager is not None:
            self.cache_manager.dispose()
            self.cache_manager = None
        # Theme‑Cache leeren
        with self._theme_cache_lock:
            self._theme_cache.clear()
        if self._debug_filter is not None:
            logger.removeFilter(self._debug_filter)
            self._debug_filter = None
        self._scheduler_set = False
        logger.debug("AppContext.dispose() abgeschlossen")


class ProcessingError(Exception):
    """
    Wird bei Fehlern während der Verarbeitung (Export, Transkription, etc.) ausgelöst.
    Enthält optionale Detailinformationen und einen Fehlercode.
    """

    def __init__(
        self,
        message: str = "Processing error",
        details: Optional[str] = None,
        code: Optional[int] = None,
    ) -> None:
        self.message = message
        self.details = details
        self.code = code
        super().__init__(self.message)

    def __str__(self) -> str:
        parts = [self.message]
        if self.code is not None:
            parts.append(f"[Code {self.code}]")
        if self.details:
            parts.append(f"({self.details})")
        return " ".join(parts)

    def to_dict(self) -> Dict[str, Any]:
        """Konvertiert die Exception in ein Dictionary (für Logging/JSON)."""
        return {
            "type": self.__class__.__name__,
            "message": self.message,
            "details": self.details,
            "code": self.code,
        }


# =============================================================================
# GLOBALER EXECUTOR
# =============================================================================

_CPU_COUNT: int = os.cpu_count() or 2
_EXECUTOR_WORKERS: int = max(2, min(_CPU_COUNT // 2, 8))  # Erhöht von //4 auf //2
_EXECUTOR_QUEUE: int = 200
_EXECUTOR: Optional[OptimizedThreadPoolExecutor] = None
_EXECUTOR_LOCK = threading.RLock()


def _get_global_executor() -> OptimizedThreadPoolExecutor:
    """Lazy‑Initialisierung des globalen Executors (thread‑sicher)."""
    global _EXECUTOR
    with _EXECUTOR_LOCK:
        if _EXECUTOR is None:
            _EXECUTOR = OptimizedThreadPoolExecutor(
                max_workers=_EXECUTOR_WORKERS,
                thread_name_prefix="ProcExec",
                max_queue_size=_EXECUTOR_QUEUE,
            )
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "executor",
                    "Globaler Executor initialisiert (workers=%d, queue=%d)",
                    _EXECUTOR_WORKERS,
                    _EXECUTOR_QUEUE,
                )
        return _EXECUTOR


def _shutdown_global_executor() -> None:
    """Idempotenter, sicherer Shutdown des globalen Executors."""
    global _EXECUTOR
    with _EXECUTOR_LOCK:
        if _EXECUTOR is not None:
            try:
                safe_shutdown_executor(_EXECUTOR, wait=True, cancel_futures=True)
                if DEBUG_LEVEL >= 2:
                    log_debug("executor", "Globaler Executor heruntergefahren")
            except Exception as exc:
                logger.warning("Fehler beim Shutdown des globalen Executors: %s", exc)
            finally:
                _EXECUTOR = None


atexit.register(_shutdown_global_executor)


# =============================================================================
# DEKORATEURE
# =============================================================================


def execution_decorator(
    timeout: int = 60,
    max_retries: int = 3,
    *,
    executor: Optional[OptimizedThreadPoolExecutor] = None,
    retry_delay_base: float = 1.0,
    retry_delay_max: float = 30.0,
) -> Callable:
    """
    Dekorator, der eine Funktion mit Timeout und Wiederholungen ausführt.

    Verbesserungen:
    - Konfigurierbarer exponentieller Backoff (retry_delay_base, retry_delay_max).
    - Verwendung des globalen Executors oder eines benutzerdefinierten.
    - Fängt `FutureTimeout` ab und führt Wiederholungen durch.
    - Bei Timeout wird die Future abgebrochen.
    - Loggt jeden Versuch (mit Debug‑Level).

    Args:
        timeout: Maximale Ausführungszeit in Sekunden pro Versuch.
        max_retries: Maximale Anzahl Wiederholungen (0 = kein Wiederholung).
        executor: Optionaler Executor (sonst globaler).
        retry_delay_base: Basis‑Verzögerung für exponentiellen Backoff (Sekunden).
        retry_delay_max: Maximale Verzögerung (Sekunden).

    Returns:
        Dekorierte Funktion.
    """

    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            nonlocal executor
            exec_ref = executor if executor is not None else _get_global_executor()
            last_exception: Optional[Exception] = None
            for attempt in range(max_retries + 1):
                future: Optional[Future] = None
                try:
                    future = exec_ref.submit(func, *args, **kwargs)
                    return future.result(timeout=timeout)
                except FutureTimeout as exc:
                    if future is not None and not future.done():
                        future.cancel()
                    last_exception = exc
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "executor",
                            "Timeout in %s (Versuch %d/%d)",
                            func.__name__,
                            attempt + 1,
                            max_retries + 1,
                        )
                    else:
                        logger.warning(
                            "⏰ Timeout in %s (Versuch %d/%d)",
                            func.__name__,
                            attempt + 1,
                            max_retries + 1,
                        )
                except Exception as exc:
                    last_exception = exc
                    logger.warning(
                        "⚠️ Exception in %s (Versuch %d/%d): %s",
                        func.__name__,
                        attempt + 1,
                        max_retries + 1,
                        str(exc)[:120],
                    )

                if attempt < max_retries:
                    # Exponentieller Backoff mit Jitter
                    delay = min(retry_delay_max, retry_delay_base * (2**attempt))
                    jitter = random.uniform(0, delay * 0.2)
                    wait_time = delay + jitter
                    time.sleep(wait_time)

            if last_exception is not None:
                raise last_exception
            raise RuntimeError(
                f"execution_decorator: alle {max_retries + 1} Versuche "
                f"für {func.__name__} ohne Ergebnis beendet."
            )

        return wrapper

    return decorator


def gui_operation_decorator(
    fallback: Any = None,
    log_level: str = "debug",
    re_raise_exceptions: Tuple[type[Exception], ...] = (),
    error_callback: Optional[Callable[[Exception], None]] = None,
) -> Callable:
    """
    Dekorator für GUI‑Methoden, die im Hauptthread ausgeführt werden.
    Fängt Tkinter‑ und andere Laufzeitfehler ab, protokolliert sie und
    gibt einen konfigurierbaren Fallback‑Wert zurück.

    Der Dekorator kann sowohl mit als auch ohne Klammern verwendet werden:
        @gui_operation_decorator
        def my_callback(event):
            ...

        @gui_operation_decorator(fallback=False, log_level="warning")
        def another_callback():
            ...

    Args:
        fallback: Wert, der im Fehlerfall zurückgegeben wird (default: None).
        log_level: Schweregrad für das Logging (`debug`, `info`, `warning`, `error`).
        re_raise_exceptions: Tuple von Exception‑Typen, die nicht abgefangen werden
                             (z. B. `(KeyboardInterrupt,)`). Werden direkt wieder geworfen.
        error_callback: Optionale Funktion, die im Fehlerfall mit der Exception aufgerufen wird.

    Returns:
        Dekorierte Funktion.
    """
    # ── Ermöglicht Verwendung ohne Klammern ─────────────────────────────
    if callable(fallback):
        # Fallback ist in diesem Fall die zu dekorierende Funktion
        func = fallback
        return gui_operation_decorator()(func)

    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return func(*args, **kwargs)
            except re_raise_exceptions:
                raise
            except tk.TclError as exc:
                # Widget zerstört – harmlos, nur bei Debug loggen
                _log_gui_error(func.__name__, exc, log_level, component="gui")
                if error_callback is not None:
                    try:
                        error_callback(exc)
                    except Exception:
                        pass
                return fallback
            except RuntimeError as exc:
                _log_gui_error(func.__name__, exc, log_level, component="gui")
                if error_callback is not None:
                    try:
                        error_callback(exc)
                    except Exception:
                        pass
                return fallback
            except Exception as exc:
                _log_gui_error(
                    func.__name__, exc, "error", component="gui", exc_info=True
                )
                if error_callback is not None:
                    try:
                        error_callback(exc)
                    except Exception:
                        pass
                return fallback

        return wrapper

    return decorator


def _log_gui_error(
    func_name: str,
    exc: Exception,
    log_level: str,
    component: str = "gui",
    exc_info: bool = False,
) -> None:
    """
    Hilfsfunktion zum einheitlichen Logging von GUI‑Fehlern.
    """
    level = log_level.lower() if isinstance(log_level, str) else "debug"
    if level not in ("debug", "info", "warning", "error"):
        level = "debug"

    msg = f"GUI operation '{func_name}' failed: {type(exc).__name__}: {exc}"
    logger = logging.getLogger("dragon")

    if level == "debug":
        logger.debug(msg, exc_info=exc_info, extra={"component": component})
    elif level == "info":
        logger.info(msg, exc_info=exc_info, extra={"component": component})
    elif level == "warning":
        logger.warning(msg, exc_info=exc_info, extra={"component": component})
    else:  # error
        logger.error(msg, exc_info=exc_info, extra={"component": component})


def async_gui_operation_decorator(
    fallback: Any = None,
    log_errors: bool = True,
    error_callback: Optional[Callable[[Exception], None]] = None,
    re_raise_exceptions: Tuple[type[Exception], ...] = (),
) -> Callable:
    """
    Dekorator für asynchrone GUI‑Operationen (werden in Hintergrund‑Threads ausgeführt).
    Fängt Exceptions ab, protokolliert sie und gibt einen Fallback‑Wert zurück.

    Args:
        fallback: Wert, der im Fehlerfall zurückgegeben wird.
        log_errors: Ob der Fehler geloggt werden soll.
        error_callback: Optionale Funktion, die im Fehlerfall mit der Exception aufgerufen wird.
        re_raise_exceptions: Tuple von Exception‑Typen, die nicht abgefangen werden
                             (z. B. `(asyncio.CancelledError,)`). Wird direkt
                             wieder geworfen.
    Returns:
        Dekorierte Funktion.
    """

    def decorator(func: Callable) -> Callable:
        # Importe hier, um zirkuläre Abhängigkeiten zu vermeiden
        import inspect
        from functools import wraps

        @wraps(func)
        def sync_wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return func(*args, **kwargs)
            except re_raise_exceptions:
                # Bestimmte Exceptions werden nicht abgefangen
                raise
            except Exception as exc:
                if log_errors:
                    logger.error(
                        "Async GUI operation failed in %s: %s",
                        func.__name__,
                        exc,
                        exc_info=True,
                    )
                if error_callback is not None:
                    try:
                        error_callback(exc)
                    except Exception:
                        pass
                return fallback

        @wraps(func)
        async def async_wrapper(*args: Any, **kwargs: Any) -> Any:
            try:
                return await func(*args, **kwargs)
            except re_raise_exceptions:
                raise
            except Exception as exc:
                if log_errors:
                    logger.error(
                        "Async GUI operation failed in %s: %s",
                        func.__name__,
                        exc,
                        exc_info=True,
                    )
                if error_callback is not None:
                    try:
                        error_callback(exc)
                    except Exception:
                        pass
                return fallback

        # Prüfen, ob die Funktion asynchron ist
        if inspect.iscoroutinefunction(func):
            return async_wrapper
        else:
            return sync_wrapper

    return decorator


class MemoryManager(PeriodicTaskMixin):
    """Verwaltung von Textpuffern mit automatischer Größenbegrenzung,
    parallelen Größen‑Deques und dynamischer Speicherbereinigung."""

    __slots__ = (
        "_buffers",
        "_size_deques",
        "_buffer_sizes",
        "_lock",
        "_max_memory_per_component",
        "_last_gc_time",
        "_gc_interval",
        "_memory_warning_threshold",
        "_long_term_monitor",
        "_monitoring_active",
        "_psutil",
        "_cache_stats",
        "_debug",
        "_max_text_size_bytes",
    )

    MAX_TEXT_SIZE_BYTES = 2 * 1024 * 1024

    def __init__(self) -> None:
        PeriodicTaskMixin.__init__(
            self, interval=60, task=self._perform_periodic_maintenance
        )

        self._buffers: Dict[str, deque] = {}
        self._size_deques: Dict[str, deque] = {}
        self._buffer_sizes: Dict[str, int] = {}
        self._lock = threading.RLock()
        self._max_memory_per_component = 100 * 1024 * 1024
        self._last_gc_time = time.time()
        self._gc_interval = 300
        self._memory_warning_threshold = 0.8
        self._long_term_monitor: Deque[Dict[str, Any]] = deque(maxlen=1000)
        self._monitoring_active = True
        self._psutil = None
        self._cache_stats = {"total_allocated": 0, "total_freed": 0}
        self._debug = logger.isEnabledFor(logging.DEBUG)

    def _perform_periodic_maintenance(self) -> None:
        """Wird periodisch aufgerufen, führt Speicher‑Health‑Check durch."""
        try:
            self._perform_memory_health_check()
        except Exception as e:
            if self._debug:
                log_debug("memory", f"Maintenance worker error: {e}")

    def _perform_memory_health_check(self) -> None:
        """Prüft Speicherverbrauch und löst ggf. aggressive Bereinigung aus."""
        with self._lock:
            total_memory = sum(self._buffer_sizes.values())
            memory_usage_percent = total_memory / self._max_memory_per_component
            current_time = time.time()
            do_gc = memory_usage_percent > 0.8 or (
                current_time - self._last_gc_time > self._gc_interval
            )

        if do_gc:
            gc.collect()
            if self._debug:
                log_debug(
                    "memory",
                    f"GC executed, memory used: {self.get_total_memory_usage() / 1024 / 1024:.2f} MB",
                )
            with self._lock:
                self._last_gc_time = time.time()

        if memory_usage_percent > 0.8:
            if self._debug:
                log_debug(
                    "memory",
                    f"High buffer memory: {memory_usage_percent:.1%}, starting aggressive cleanup",
                )
            cleanup_thread = threading.Thread(
                target=self.aggressive_cleanup, daemon=True
            )
            cleanup_thread.start()

        psutil = self._get_psutil()
        if psutil is None:
            return

        try:
            system_memory = psutil.virtual_memory()
            system_usage_percent = system_memory.percent / 100.0
            process = psutil.Process()
            process_memory = process.memory_info().rss
            process_usage_percent = process_memory / Config.MAX_MEMORY_USAGE

            sample = {
                "timestamp": time.time(),
                "system_usage": system_usage_percent,
                "process_usage": process_usage_percent,
                "system_mb": system_memory.used // (1024 * 1024),
                "process_mb": process_memory // (1024 * 1024),
            }
            self._long_term_monitor.append(sample)

            if self._debug:
                log_debug(
                    "memory",
                    f"Health: system={system_usage_percent:.1%}, process={process_usage_percent:.1%}",
                )

            if system_usage_percent > self._memory_warning_threshold:
                logger.warning(
                    f"⚠️ High system memory usage: {system_memory.percent:.1f}%"
                )
            if process_usage_percent > self._memory_warning_threshold:
                logger.warning(
                    f"⚠️ High process memory usage: {process_usage_percent:.1%}"
                )
                self.aggressive_cleanup()

            if len(self._long_term_monitor) >= 10:
                recent = list(self._long_term_monitor)[-10:]
                avg_sys = sum(s["system_usage"] for s in recent) / 10
                if avg_sys > 0.75:
                    logger.warning(f"⚠️ Sustained high memory usage: {avg_sys:.1%}")
        except Exception as e:
            if self._debug:
                log_debug("memory", f"Health check error: {e}")

    def _get_psutil(self):
        if self._psutil is None:
            try:
                import psutil

                self._psutil = psutil
            except ImportError:
                self._psutil = False
        return self._psutil if self._psutil is not False else None

    def _get_target_ratio(self) -> float:
        """
        Bestimmt den Anteil der maximalen Speichergrenze,
        der nach der Bereinigung angestrebt wird.
        Bei hohem Systemdruck wird aggressiver bereinigt.
        """
        try:
            psutil = self._get_psutil()
            if psutil is not None:
                mem = psutil.virtual_memory()
                if mem.percent > 90:
                    return 0.5
                if mem.percent > 80:
                    return 0.6
                if mem.percent > 70:
                    return 0.7
        except Exception:
            pass
        return 0.7

    def _size_of_text(self, text: str) -> int:
        """Gibt die ungefähre Speichergröße eines Strings in Bytes zurück."""
        return sys.getsizeof(text)

    def add_text(self, component: str, text: str) -> None:
        """Fügt einen Text in den Puffer ein, mit optionaler Kürzung zu großer Texte."""
        if not text or not text.strip():
            return

        if len(text) > self.MAX_TEXT_SIZE_BYTES * 2:
            text = text[: self.MAX_TEXT_SIZE_BYTES] + "... [truncated]"
            if self._debug:
                log_debug("memory", f"Truncated oversized text for {component}")

        with self._lock:
            if component not in self._buffers:
                self._buffers[component] = deque(maxlen=Config.MAX_TEXT_LINES)
                self._size_deques[component] = deque(maxlen=Config.MAX_TEXT_LINES)
                self._buffer_sizes[component] = 0

            text_size = self._size_of_text(text)
            current_size = self._buffer_sizes[component]

            if current_size + text_size > self._max_memory_per_component:
                self._optimize_buffer(component)

            self._buffers[component].append(text)
            self._size_deques[component].append(text_size)
            self._buffer_sizes[component] += text_size
            self._cache_stats["total_allocated"] += text_size

    def get_text(self, component: str) -> str:
        """Gibt den gesamten Puffer einer Komponente als verketteten String zurück."""
        with self._lock:
            if component not in self._buffers:
                return ""
            return "\n".join(self._buffers[component])

    def clear_component(self, component: str) -> None:
        """Löscht den gesamten Puffer einer Komponente."""
        with self._lock:
            if component in self._buffers:
                del self._buffers[component]
            if component in self._size_deques:
                del self._size_deques[component]
            if component in self._buffer_sizes:
                del self._buffer_sizes[component]
            if self._debug:
                logger.info(f"🧹 Component {component} cleared")

    def _optimize_buffer(self, component: str) -> None:
        """
        Entfernt alte Einträge aus dem Puffer, bis die dynamische Zielgröße erreicht ist.
        Verwendet parallele Größen‑Deques für schnellen Zugriff.
        """
        with self._lock:
            if component not in self._buffers:
                return
            dq = self._buffers[component]
            size_dq = self._size_deques[component]
            current_size = self._buffer_sizes.get(component, 0)
            if len(dq) != len(size_dq):
                logger.warning(
                    f"Buffer-Konsistenzproblem für {component}: "
                    f"len(dq)={len(dq)} != len(size_dq)={len(size_dq)} – Korrektur"
                )
                min_len = min(len(dq), len(size_dq))
                while len(dq) > min_len:
                    dq.pop()
                while len(size_dq) > min_len:
                    size_dq.pop()
                current_size = sum(size_dq)
                self._buffer_sizes[component] = current_size
            target_ratio = self._get_target_ratio()
            target_size = int(self._max_memory_per_component * target_ratio)
            if current_size <= target_size:
                return
            removed_bytes = 0
            removed_count = 0
            max_iterations = 10000
            iterations = 0
            while (
                current_size > target_size
                and dq
                and size_dq
                and iterations < max_iterations
            ):
                dq.popleft()
                size = size_dq.popleft()
                removed_bytes += size
                removed_count += 1
                current_size -= size
                iterations += 1

            if iterations >= max_iterations:
                logger.warning(
                    f"Buffer optimization for {component} reached iteration limit "
                    f"({max_iterations}) – may be stuck"
                )
            self._buffer_sizes[component] = max(0, current_size)
            self._cache_stats["total_freed"] += removed_bytes
            actual_size = sum(size_dq)
            if actual_size != current_size:
                logger.warning(
                    f"Buffer size mismatch for {component}: stored {current_size}, "
                    f"actual {actual_size}. Correcting."
                )
                self._buffer_sizes[component] = actual_size
                current_size = actual_size
            if removed_count > 0 and self._debug:
                log_debug(
                    "memory",
                    f"Buffer {component} optimized: removed {removed_count} entries, "
                    f"freed {removed_bytes} bytes, new size {current_size} bytes, "
                    f"remaining entries: {len(dq)}",
                )
                if removed_bytes > 10 * 1024 * 1024:
                    gc.collect()
                    log_debug(
                        "memory",
                        f"Triggered GC after freeing {removed_bytes / 1024 / 1024:.1f} MB",
                    )

    def aggressive_cleanup(self) -> None:
        """Entfernt aggressiv Einträge aus allen Puffern, um Speicher freizugeben."""
        logger.info("🧹 Starting aggressive memory cleanup...")
        with self._lock:
            components = list(self._buffers.keys())

        for component in components:
            try:
                with self._lock:
                    if component not in self._buffers:
                        continue
                    dq = self._buffers[component]
                    size_dq = self._size_deques[component]
                    current_len = len(dq)
                    if current_len > 100:
                        keep_count = max(50, current_len // 2)
                        removed_bytes = 0
                        removed_count = 0
                        while len(dq) > keep_count:
                            dq.popleft()
                            size = size_dq.popleft()
                            removed_bytes += size
                            removed_count += 1
                        self._buffer_sizes[component] -= removed_bytes
                        self._cache_stats["total_freed"] += removed_bytes
                        logger.info(
                            f"  ↪ {component}: {current_len} → {len(dq)} entries, "
                            f"freed {removed_bytes} bytes"
                        )
            except Exception as e:
                logger.warning(f"⚠️ Cleanup error for {component}: {e}")

        threading.Thread(target=gc.collect, daemon=True).start()
        logger.info("✅ Aggressive cleanup completed")

    def optimize_all_buffers(self) -> None:
        """Optimiert alle Puffer (ruft _optimize_buffer für jede Komponente auf)."""
        logger.info("🧹 Optimizing all buffers...")
        with self._lock:
            components = list(self._buffers.keys())
        for comp in components:
            self._optimize_buffer(comp)
        gc.collect()
        logger.info("✅ All buffers optimized")

    def get_memory_stats(self) -> Dict[str, Any]:
        """Liefert detaillierte Speicherstatistiken."""
        psutil = self._get_psutil()
        if psutil is None:
            return {}

        try:
            system_memory = psutil.virtual_memory()
            process = psutil.Process()
            process_memory = process.memory_info().rss

            with self._lock:
                buffer_count = len(self._buffers)
                total_buffer_size = sum(self._buffer_sizes.values())

            return {
                "system_usage_percent": system_memory.percent,
                "system_used_mb": system_memory.used // (1024 * 1024),
                "system_total_mb": system_memory.total // (1024 * 1024),
                "process_usage_percent": (process_memory / Config.MAX_MEMORY_USAGE)
                * 100,
                "process_used_mb": process_memory // (1024 * 1024),
                "process_peak_mb": self._get_peak_memory() // (1024 * 1024),
                "long_term_samples": len(self._long_term_monitor),
                "buffer_components": buffer_count,
                "total_buffer_size_mb": total_buffer_size // (1024 * 1024),
                "active_monitoring": self._monitoring_active,
            }
        except Exception as e:
            if self._debug:
                log_debug("memory", f"Stats error: {e}")
            return {}

    def _get_peak_memory(self) -> int:
        psutil = self._get_psutil()
        if psutil is None:
            return 0
        try:
            process = psutil.Process()
            return process.memory_info().rss
        except Exception:
            return 0

    def get_buffer_stats(self, component: str) -> Dict[str, Any]:
        """Liefert detaillierte Informationen über einen einzelnen Puffer."""
        with self._lock:
            if component not in self._buffers:
                return {"type": "not_found"}
            dq = self._buffers[component]
            size_dq = self._size_deques[component]
            return {
                "type": "deque",
                "size": len(dq),
                "capacity": Config.MAX_TEXT_LINES,
                "memory_bytes": self._buffer_sizes.get(component, 0),
                "maxlen": dq.maxlen,
                "avg_entry_size_bytes": (
                    self._buffer_sizes[component] / len(dq) if dq else 0
                ),
                "min_entry_size_bytes": min(size_dq) if size_dq else 0,
                "max_entry_size_bytes": max(size_dq) if size_dq else 0,
            }

    def list_components(self) -> List[str]:
        """Listet alle vorhandenen Pufferkomponenten auf."""
        with self._lock:
            return list(self._buffers.keys())

    def get_total_memory_usage(self) -> int:
        """Summe der Bytes in allen Puffern."""
        with self._lock:
            return sum(self._buffer_sizes.values())

    def print_debug_info(self) -> None:
        """Gibt detaillierte Debug‑Informationen aus."""
        stats = self.get_memory_stats()
        logger.info("\n" + "=" * 50)
        logger.info("🧠 MEMORY MANAGER DEBUG INFO")
        logger.info("=" * 50)
        logger.info(
            f"System Memory: {stats.get('system_used_mb', 0)}MB / "
            f"{stats.get('system_total_mb', 0)}MB ({stats.get('system_usage_percent', 0):.1f}%)"
        )
        logger.info(
            f"Process Memory: {stats.get('process_used_mb', 0)}MB "
            f"({stats.get('process_usage_percent', 0):.1f}%)"
        )
        logger.info(f"Buffer Components: {stats.get('buffer_components', 0)}")
        logger.info(f"Total Buffer Size: {stats.get('total_buffer_size_mb', 0)}MB")
        logger.info(f"Long Term Samples: {stats.get('long_term_samples', 0)}")

        components = self.list_components()
        if components:
            logger.info(f"\nActive Components ({len(components)}):")
            for comp in components[:5]:
                comp_stats = self.get_buffer_stats(comp)
                logger.info(
                    f"  • {comp}: {comp_stats['type']}, "
                    f"size: {comp_stats.get('size', 0)}, "
                    f"avg size: {comp_stats.get('avg_entry_size_bytes', 0):.0f} bytes"
                )
            if len(components) > 5:
                logger.info(f"  ... and {len(components) - 5} more")
        logger.info("=" * 50)

    def dispose(self) -> None:
        """Gibt alle Ressourcen des MemoryManagers frei."""
        self._monitoring_active = False
        self.stop_periodic_task()
        if not self.wait_for_stop(timeout=2.0):
            logger.warning(
                "⚠️ MemoryManager cleanup thread did not terminate within timeout"
            )
        with self._lock:
            self._buffers.clear()
            self._size_deques.clear()
            self._buffer_sizes.clear()
            self._long_term_monitor.clear()
        gc.collect()
        if self._debug:
            logger.info("✅ MemoryManager disposed")


class BaseTranslationEngine(ABC):
    """
    Abstrakte Basisklasse für alle Übersetzungs‑Engines in Dragon Whisperer.

    Definiert die minimal erforderliche Schnittstelle und stellt optionale,
    wiederverwendbare Hilfsmethoden bereit (Segmentierung, Batch‑Übersetzung,
    Wiederholungslogik und Text‑Validierung), die von konkreten Engine‑
    Implementierungen genutzt werden können, aber **nicht** müssen.

    **Hinweis für Unterklassen:**
    Wenn die Unterklasse einen eigenen ``__init__`` benötigt, sollte sie
    ``super().__init__()`` aufrufen, um die optionalen Parameter
    (``max_retries``, ``retry_delay``) zu initialisieren.
    """

    # Standardwerte für Wiederholungen – können überschrieben werden
    DEFAULT_MAX_RETRIES: int = 3
    DEFAULT_RETRY_DELAY: float = 1.0  # Basis in Sekunden

    def __init__(
        self,
        max_retries: Optional[int] = None,
        retry_delay: Optional[float] = None,
    ) -> None:
        """
        Initialisiert die Basis‑Engine.

        Args:
            max_retries: Maximale Anzahl von Wiederholungen bei einem
                fehlgeschlagenen Übersetzungsversuch.  Falls ``None``,
                wird ``DEFAULT_MAX_RETRIES`` verwendet.
            retry_delay: Basis‑Wartezeit in Sekunden zwischen Wiederholungen
                (wird exponentiell erhöht).  Falls ``None``, wird
                ``DEFAULT_RETRY_DELAY`` verwendet.
        """
        self._max_retries = (
            max_retries if max_retries is not None else self.DEFAULT_MAX_RETRIES
        )
        self._retry_delay = (
            retry_delay if retry_delay is not None else self.DEFAULT_RETRY_DELAY
        )

    # ------------------------------------------------------------------
    # Abstrakte Schnittstelle
    # ------------------------------------------------------------------
    @abstractmethod
    def set_target_language(self, target_lang: str) -> None:
        """
        Setzt die Zielsprache für alle folgenden Übersetzungen.

        Args:
            target_lang: ISO‑639‑1‑Code der Zielsprache (z. B. ``'de'``).
        """

    @abstractmethod
    def translate_text(
        self, text: str, source_lang: str = "auto"
    ) -> Optional[TranslationResult]:
        """
        Übersetzt einen einzelnen Text.
        """

    @abstractmethod
    def dispose(self) -> None:
        """Gibt alle von der Engine belegten Ressourcen frei."""

    # ------------------------------------------------------------------
    # Konkrete Hilfsmethoden
    # ------------------------------------------------------------------
    def _validate_text(self, text: str) -> str:
        """
        Bereinigt und validiert den Eingabetext.

        Entfernt führende/abschließende Whitespaces und kürzt extrem
        lange Texte (optional).  Gibt den bereinigten Text zurück oder
        einen leeren String.
        """
        if not text:
            return ""
        cleaned = text.strip()
        # Optionale Längenbegrenzung (kann von Unterklassen angepasst werden)
        max_len = getattr(self, "_max_text_length", 5000)
        if len(cleaned) > max_len:
            cleaned = cleaned[:max_len] + "…"
        return cleaned

    def translate_batch(
        self,
        texts: List[str],
        source_lang: str = "auto",
        *,
        concurrency: int = 1,
    ) -> List[Optional[TranslationResult]]:
        """
        Übersetzt eine Liste von Texten.

        Standardimplementierung: sequenzielle Verarbeitung.
        Unterklassen können diese Methode überschreiben, um parallele
        Übersetzungen zu ermöglichen.
        """
        return [self.translate_text(t, source_lang) for t in texts]

    def translate_sentences(
        self,
        text: str,
        source_lang: str = "auto",
    ) -> List[Optional[TranslationResult]]:
        """
        Teilt einen langen Text in Sätze auf und übersetzt jeden einzeln.

        Verwendet die globale Funktion ``split_sentences()``, die auch
        im Hauptmodul definiert ist.

        Returns:
            Liste der Übersetzungsergebnisse pro Satz.
        """
        sentences = split_sentences(text)
        if not sentences:
            return [self.translate_text(text, source_lang)]
        return self.translate_batch(sentences, source_lang)

    def _retry_translate(
        self,
        text: str,
        source_lang: str = "auto",
        *,
        max_retries: Optional[int] = None,
        base_delay: Optional[float] = None,
    ) -> Optional[TranslationResult]:
        """
        Übersetzt *text* mit automatischer Wiederholung bei Fehlern.

        Verwendet exponentielles Backoff zwischen den Versuchen.
        """
        retries = max_retries if max_retries is not None else self._max_retries
        delay = base_delay if base_delay is not None else self._retry_delay

        last_exception: Optional[Exception] = None
        for attempt in range(retries + 1):
            try:
                result = self.translate_text(text, source_lang)
                if result is not None and result.translated:
                    return result
            except Exception as exc:
                last_exception = exc
                logger.warning(
                    "Übersetzungsversuch %d/%d fehlgeschlagen: %s",
                    attempt + 1,
                    retries + 1,
                    exc,
                )

            if attempt < retries:
                wait = delay * (2**attempt)
                time.sleep(wait)

        if last_exception:
            logger.error(
                "Übersetzung nach %d Versuchen endgültig fehlgeschlagen: %s",
                retries + 1,
                last_exception,
            )
        return None

    def _preprocess_text(self, text: str) -> str:
        """
        Pre‑Processing Hook, der vor der Übersetzung aufgerufen wird.

        Standardimplementierung: macht nichts.
        """
        return text

    def _postprocess_translation(self, translated: str) -> str:
        """
        Post‑Processing Hook, der nach der Übersetzung aufgerufen wird.

        Standardimplementierung: macht nichts.
        """
        return translated


class ErrorHandlingMixin:
    """
    Mixin für robuste Fehlerbehandlung mit automatischer Deaktivierung
    bei zu vielen Fehlern.

    Die Klasse ist so konzipiert, dass sie in mehreren Kontexten
    (Übersetzungs‑Engines, Plugins, …) verwendet werden kann.
    """

    def __init__(
        self,
        max_errors: int = 5,
        disable_duration: float = 300.0,
        *,
        on_disable: Optional[Callable[[], None]] = None,
        on_reenable: Optional[Callable[[], None]] = None,
    ) -> None:
        """
        Initialisiert die Fehlerbehandlungs‑Logik.

        Args:
            max_errors: Maximale Anzahl aufeinanderfolgender Fehler,
                bevor die Komponente vorübergehend deaktiviert wird.
            disable_duration: Dauer (in Sekunden), für die die Komponente
                deaktiviert bleibt, nachdem die Fehlerschwelle erreicht wurde.
            on_disable: Optionaler Callback, der aufgerufen wird, wenn
                die Komponente deaktiviert wird.
            on_reenable: Optionaler Callback, der aufgerufen wird, wenn
                die Komponente nach Ablauf der Deaktivierungsdauer wieder
                aktiviert wird.
        """
        self._error_count = 0
        self._disabled_until = 0.0
        self._max_errors = max_errors
        self._disable_duration = disable_duration
        self._error_lock = threading.RLock()

        # Optionale Callbacks
        self._on_disable_callback = on_disable
        self._on_reenable_callback = on_reenable

        # Interner Zähler, um wiederholte Warnmeldungen zu unterdrücken
        self._last_warning_time = 0.0

    def _check_disable(self) -> None:
        """
        Prüft, ob die Engine aufgrund zu vieler Fehler deaktiviert werden soll.

        Falls die Fehlerschwelle erreicht wurde und die Komponente noch
        nicht deaktiviert ist, wird ``_disabled_until`` gesetzt und eine
        Warnung ausgegeben.
        """
        with self._error_lock:
            if self._error_count >= self._max_errors and self._disabled_until == 0.0:
                self._disabled_until = time.time() + self._disable_duration
                # Nur einmal alle 60 Sekunden eine Warnung ausgeben,
                # um Log‑Flut zu vermeiden.
                now = time.time()
                if now - self._last_warning_time > 60.0:
                    self._last_warning_time = now
                    logger.warning(
                        "⚠️ %s vorübergehend deaktiviert für %ds " "wegen %d Fehlern",
                        self.__class__.__name__,
                        self._disable_duration,
                        self._error_count,
                    )
                # Optionalen Callback ausführen (außerhalb des Locks)
                if self._on_disable_callback is not None:
                    self._on_disable_callback()

    def is_functional(self) -> bool:
        """
        Gibt zurück, ob die Komponente aktuell nutzbar ist.

        Ist die Deaktivierungsdauer abgelaufen, wird der Fehlerzähler
        zurückgesetzt und ``_reinitialize()`` aufgerufen.
        """
        with self._error_lock:
            now = time.time()
            # Noch deaktiviert?
            if self._disabled_until > now:
                return False

            # Deaktivierungsdauer abgelaufen → zurücksetzen
            if self._error_count >= self._max_errors:
                if now >= self._disabled_until:
                    self._error_count = 0
                    self._disabled_until = 0.0
                    try:
                        self._reinitialize()
                    except Exception as e:
                        logger.error(
                            "Fehler in _reinitialize von %s: %s",
                            self.__class__.__name__,
                            e,
                        )
                    # Optionalen Reenable‑Callback ausführen
                    if self._on_reenable_callback is not None:
                        self._on_reenable_callback()
                    return True
                else:
                    return False
            return True

    def _reinitialize(self) -> None:
        """
        Wird aufgerufen, wenn die Komponente nach einer Deaktivierung
        wieder aktiviert wird.

        Kann von Unterklassen überschrieben werden, um z.B. Verbindungen
        neu aufzubauen.
        """

    def _record_success(self) -> None:
        """
        Setzt den Fehlerzähler zurück (Erfolg) und entfernt eine
        eventuell bestehende Deaktivierung.
        """
        with self._error_lock:
            self._error_count = 0
            self._disabled_until = 0.0

    def _record_error(self) -> None:
        """
        Erhöht den Fehlerzähler und prüft auf Deaktivierung.

        Diese Methode sollte immer dann aufgerufen werden, wenn ein
        nicht‑behebbarer Fehler aufgetreten ist.
        """
        with self._error_lock:
            self._error_count += 1
            self._check_disable()

    def reset_errors(self) -> None:
        """
        Setzt den Fehlerzähler manuell zurück und entfernt eine
        aktive Deaktivierung.

        Nützlich, wenn sich die Umstände geändert haben (z.B. manuelle
        Neueinrichtung der Komponente).
        """
        with self._error_lock:
            self._error_count = 0
            self._disabled_until = 0.0
            logger.info(
                "%s: Fehlerzähler manuell zurückgesetzt.",
                self.__class__.__name__,
            )


class BaseCachedTranslationEngine(BaseTranslationEngine, ErrorHandlingMixin):
    """
    Basisklasse für Übersetzungs‑Engines mit Caching und automatischer Fehlerbehandlung.

    Erbt Funktionalität von ``BaseTranslationEngine`` (für optionale Retry‑Logik,
    Batch‑Übersetzung, etc.) und ``ErrorHandlingMixin`` (automatische
    Deaktivierung bei zu vielen Fehlern).

    Konkrete Implementierungen **müssen** ``_call_translation_api`` überschreiben.
    """

    def __init__(
        self,
        default_target_lang: str = "de",
        settings: Optional["AdvancedSettings"] = None,
        max_retries: int = 3,
        retry_delay_base: float = 1.0,
        retry_delay_max: float = 5.0,
        cache_manager: Optional[CacheManager] = None,
        max_errors: int = 5,
        disable_duration: float = 300.0,
    ):
        # ── Basisklassen mit den gewünschten Parametern initialisieren ──
        BaseTranslationEngine.__init__(
            self,
            max_retries=max_retries,
            retry_delay=retry_delay_base,
        )
        ErrorHandlingMixin.__init__(
            self,
            max_errors=max_errors,
            disable_duration=disable_duration,
        )

        self.default_target_lang = default_target_lang
        self.settings = settings or AdvancedSettings()

        # Maximales Intervall zwischen Wiederholungen (deckelt exponentielles Backoff)
        self._retry_delay_max = retry_delay_max

        # Cache & Übersetzungs‑Historie
        self._cache_manager = cache_manager or AppContext().cache_manager
        self._lock = threading.RLock()
        self._last_translations: Deque[str] = deque(maxlen=15)
        self.last_detected_language = "auto"

        # Qualitäts‑Monitoring
        self._low_quality_count = 0
        self._max_low_quality = 3

    def set_target_language(self, target_lang: str) -> None:
        """Setzt die Zielsprache und leert den gesamten Übersetzungs‑Cache."""
        if target_lang != self.default_target_lang:
            self.default_target_lang = target_lang
            with self._lock:
                self._cache_manager.translation_cache.clear()
                self._last_translations.clear()
                self._error_count = 0
                self._disabled_until = 0.0

    @abstractmethod
    def _call_translation_api(
        self, text: str, source_lang: str, target_lang: str
    ) -> Optional[str]:
        """
        Führt den eigentlichen Übersetzungs‑API‑Aufruf durch.

        Args:
            text: Bereits bereinigter Quelltext.
            source_lang: Ermittelte oder vorgegebene Quellsprache.
            target_lang: Zielsprache (ISO‑Code).

        Returns:
            Übersetzter String oder ``None`` bei Fehlschlag.
        """

    def _is_valid_translation(self, original: str, translated: str) -> bool:
        """
        Prüft, ob die Übersetzung sinnvoll ist.

        Args:
            original: Originaltext (Quellsprache)
            translated: Übersetzungstext

        Returns:
            True, wenn die Übersetzung akzeptabel ist, sonst False.
        """
        if not translated or len(translated) < 2:
            return False

        if translated.lower() == original.lower():
            return True

        if len(translated) > len(original) * 8:
            return False

        alpha_orig = sum(c.isalpha() for c in original) / max(len(original), 1)
        alpha_trans = sum(c.isalpha() for c in translated) / max(len(translated), 1)
        if alpha_trans < 0.3 and alpha_orig > 0.5:
            return False

        return True

    def _rate_translation_quality(self, original: str, translated: str) -> float:
        """
        Bewertet die Qualität einer Übersetzung (0.0 – 1.0).

        Bewertungsfaktoren:
        - Mindestwortanzahl relativ zum Original.
        - Verhältnis der Wort‑/Zeichenanzahl (akzeptabler Bereich).
        - Ausreichender Anteil alphabetischer Zeichen.
        """
        if not translated or len(translated) < 2:
            return 0.0
        orig_words = len(original.split())
        trans_words = len(translated.split())
        if trans_words < 2 and orig_words > 2:
            return 0.0
        if orig_words > 0:
            ratio = trans_words / orig_words
            if ratio < 0.2 or ratio > 5.0:
                return 0.0
        alpha_orig = sum(c.isalpha() for c in original) / max(len(original), 1)
        alpha_trans = sum(c.isalpha() for c in translated) / max(len(translated), 1)
        if alpha_trans < 0.3 and alpha_orig > 0.5:
            return 0.0
        return 1.0

    def translate_text(
        self, text: str, source_lang: str = "auto", target_lang: Optional[str] = None
    ) -> Optional[TranslationResult]:
        """
        Übersetzt einen Text mit Caching, Wiederholungsversuchen und
        verbesserter Fehlerbehandlung sowie Negativ‑Cache für fehlgeschlagene
        Übersetzungen.

        Args:
            text: Der zu übersetzende Text.
            source_lang: ISO‑Code der Quellsprache (oder "auto").
            target_lang: ISO‑Code der Zielsprache (optional, sonst Default).

        Returns:
            TranslationResult bei Erfolg, sonst None.
        """
        # ── 0. Debug: Methodeneintritt ────────────────────────────────────
        log_debug(
            "translate",
            "🔍 BaseCachedTranslationEngine.translate_text ENTER: text='%s…', source_lang=%s, target_lang=%s",
            text[:50] if text else "None",
            source_lang,
            target_lang,
        )

        # ── 1. Engine verfügbar und funktionsfähig? ──────────────────────
        if not self.is_functional():
            log_debug("translate", f"{self.__class__.__name__} derzeit deaktiviert")
            return None

        # ── 2. Zielsprache bestimmen ───────────────────────────────────
        target = target_lang or self.default_target_lang
        log_debug("translate", f"  Zielsprache: {target}")

        # ── 3. Leere oder ungültige Eingabe ─────────────────────────────
        if not text:
            log_debug("translate", "  Text ist leer – überspringe")
            return None
        original_text = text.strip()
        if len(original_text) < 2:
            log_debug("translate", "  Text zu kurz (<2 Zeichen) – überspringe")
            return None

        # ── 4. Negativ‑Cache (fehlgeschlagene Übersetzungen) ─────────────
        if not hasattr(self, "_failed_translation_cache"):
            # TTLCache ist im globalen Namensraum definiert
            self._failed_translation_cache = TTLCache(maxsize=200, ttl=60)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate", "Negativ‑Cache initialisiert (maxsize=200, ttl=60s)"
                )
        if self._failed_translation_cache.get(original_text) is not None:
            log_debug(
                "translate",
                "  Negativ‑Cache‑Treffer für '%s…' – Übersetzung übersprungen",
                original_text[:30],
            )
            return None

        # ── 5. Duplikatprüfung (kurzzeitiger Cache) ────────────────────
        with self._lock:
            if original_text in self._last_translations:
                log_debug(
                    "translate",
                    "  Duplikat in _last_translations gefunden – überspringe",
                )
                return None
            cached = self._cache_manager.get_cached_translation(original_text, target)
            if cached is not None:
                log_debug("translate", "  Cache‑Treffer für '%s…'", original_text[:50])
                return cached
            log_debug("translate", "  Kein Cache‑Treffer – rufe API auf")

        # ── 6. Wiederholungsschleife mit exponentiellem Backoff ─────────
        last_exception = None
        base_delay = getattr(self, "_retry_delay", 1.0)
        max_retries = getattr(self, "_max_retries", 3)
        last_invalid_response = (
            None  # für Erkennung sich wiederholender ungültiger Antworten
        )

        for attempt in range(max_retries + 1):
            log_debug(
                "translate",
                "  Versuch %d/%d (base_delay=%.1f)",
                attempt + 1,
                max_retries + 1,
                base_delay,
            )
            try:
                # API‑Aufruf (implementiert in Unterklasse)
                translated_text = self._call_translation_api(
                    original_text, source_lang, target
                )
                if not translated_text or not translated_text.strip():
                    log_debug(
                        "translate",
                        "  API gab leere/None Antwort – wiederhole (Versuch %d)",
                        attempt + 1,
                    )
                    # Bei leerer Antwort: Kurze Pause, dann nächster Versuch
                    time.sleep(base_delay * (2**attempt))
                    continue

                # Prüfen, ob sich die ungültige Antwort wiederholt
                if translated_text == last_invalid_response:
                    log_debug(
                        "translate",
                        "  Wiederholte ungültige Antwort '%s…' – breche ab",
                        translated_text[:30],
                    )
                    self._failed_translation_cache.put(original_text, True)
                    return None
                last_invalid_response = translated_text

                log_debug(
                    "translate",
                    "  API lieferte Übersetzung (%d Zeichen): '%s…'",
                    len(translated_text),
                    translated_text[:50] if translated_text else "",
                )

                # Validierung der Übersetzung (Länge, Zeichensatz, etc.)
                if not self._is_valid_translation(original_text, translated_text):
                    # Falls die Übersetzung identisch mit dem Original ist (z.B. Eigenname),
                    # behandeln wir es als Erfolg, nicht als Fehler.
                    if translated_text.strip().lower() == original_text.strip().lower():
                        log_debug(
                            "translate",
                            "Identische Übersetzung (Eigenname) – akzeptiert, überspringe Wiederholung",
                        )
                        # Erfolg – Ergebnis vorbereiten (ohne Wiederholung)
                        result = TranslationResult(
                            original=original_text,
                            translated=translated_text.strip(),
                            source_lang=source_lang,
                            target_lang=target,
                        )
                        quality = self._rate_translation_quality(
                            original_text, translated_text
                        )
                        if quality < 0.5:
                            log_debug(
                                "translate",
                                f"  Qualität niedrig ({quality:.2f}) – Fehler gezählt",
                            )
                            self._record_error()
                        else:
                            log_debug(
                                "translate",
                                f"  Qualität OK ({quality:.2f}) – Erfolg gezählt",
                            )
                            self._record_success()
                        with self._lock:
                            self._cache_manager.cache_translation(result)
                            self._last_translations.append(original_text)
                        log_debug(
                            "translate",
                            "✅ Übersetzung erfolgreich (identisch): %d Zeichen",
                            len(translated_text),
                        )
                        return result
                    else:
                        log_debug(
                            "translate",
                            "Übersetzung ungültig (is_valid_translation=False) – wiederhole",
                        )
                        time.sleep(base_delay)  # kurze Pause vor Wiederholung
                        continue

                # Erfolg – Ergebnis vorbereiten
                result = TranslationResult(
                    original=original_text,
                    translated=translated_text.strip(),
                    source_lang=source_lang,
                    target_lang=target,
                )

                # Qualität bewerten (optional, für Statistik)
                quality = self._rate_translation_quality(original_text, translated_text)
                if quality < 0.5:
                    log_debug(
                        "translate",
                        f"  Qualität niedrig ({quality:.2f}) – Fehler gezählt",
                    )
                    self._record_error()
                else:
                    log_debug(
                        "translate", f"  Qualität OK ({quality:.2f}) – Erfolg gezählt"
                    )
                    self._record_success()

                # Im Cache ablegen und in die Duplikat‑Historie aufnehmen
                with self._lock:
                    self._cache_manager.cache_translation(result)
                    self._last_translations.append(original_text)

                log_debug(
                    "translate",
                    "✅ Übersetzung erfolgreich: %d Zeichen",
                    len(translated_text),
                )
                return result

            except Exception as e:
                last_exception = e
                self._record_error()
                log_debug(
                    "translate",
                    "  ❌ Versuch %d/%d fehlgeschlagen: %s",
                    attempt + 1,
                    max_retries + 1,
                    str(e)[:100],
                )
                if attempt < max_retries:
                    delay = min(5.0, base_delay * (2**attempt))
                    log_debug("translate", "  Warte %.1fs vor nächstem Versuch", delay)
                    time.sleep(delay)

        # ── 7. Alle Versuche fehlgeschlagen → Negativ‑Cache eintragen ────
        self._failed_translation_cache.put(original_text, True)
        if last_exception:
            logger.warning(
                f"Übersetzung fehlgeschlagen nach {max_retries+1} Versuchen: {last_exception}"
            )
        else:
            logger.warning(
                "Übersetzung fehlgeschlagen – kein Ergebnis nach allen Versuchen"
            )
        return None

    # ------------------------------------------------------------------
    # Ressourcen freigeben
    # ------------------------------------------------------------------
    def dispose(self) -> None:
        """Räumt Cache, Historie und Fehlerzustände auf."""
        with self._lock:
            self._cache_manager.translation_cache.clear()
            self._last_translations.clear()
            self._error_count = 0
            self._disabled_until = 0.0
            self._low_quality_count = 0
            gc.collect()


class GoogleTranslationEngine(BaseCachedTranslationEngine):
    """
    Übersetzungs‑Engine mit Google Translate, persistenter Session und robustem Fallback.
    """

    MAX_DIRECT_FAILURES = 5
    DIRECT_DISABLE_DURATION = 300.0

    __slots__ = (
        "translator",
        "googletranslator_class",
        "_session",
        "_direct_failures",
        "_direct_failures_lock",
        "_use_direct",
        "_direct_disabled_until",
        "_requests",
        "_lock",
    )

    _GOOGLE_LANG_MAP = {
        "zh": "zh-CN",
        "zh-cn": "zh-CN",
        "zh-tw": "zh-TW",
        "he": "iw",
        "fil": "tl",
        "ht": "ht",
        "tl": "fil",
    }

    def __init__(
        self,
        target_lang: str = "de",
        settings: Optional["AdvancedSettings"] = None,
        cache_manager: Optional[CacheManager] = None,
        event_bus: Optional[EventBus] = None,
    ) -> None:
        super().__init__(
            target_lang,
            settings,
            max_retries=3,
            retry_delay_base=1.0,
            retry_delay_max=5.0,
            cache_manager=cache_manager,
            max_errors=10,
            disable_duration=60.0,
        )
        self.translator = None
        self.googletranslator_class = None
        self._session = None
        self._requests = None
        self._direct_failures = 0
        self._direct_failures_lock = threading.RLock()
        self._use_direct = True
        self._direct_disabled_until = 0.0
        self._lock = threading.RLock()
        self._session_lock = threading.Lock()
        self._setup_session()
        self._setup_translator()

    def _setup_session(self) -> None:
        """
        Erzeugt eine persistente Requests‑Session mit Retry‑Adapter.
        Falls `requests` fehlt, wird `self.available` = False gesetzt.
        """
        try:
            import requests
            from urllib3.util.retry import Retry
        except ImportError:
            self._session = None
            self._requests = None
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate", "requests nicht verfügbar – Session bleibt deaktiviert"
                )
            return

        self._requests = requests
        self._session = requests.Session()

        retry_strategy = Retry(
            total=2,
            backoff_factor=0.5,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=["GET"],
        )

        try:
            if NamedHTTPAdapter is not None:
                adapter = NamedHTTPAdapter(
                    pool_name="DW-Google", max_retries=retry_strategy
                )
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "translate",
                        "GoogleTranslationEngine: using NamedHTTPAdapter (pool_name='DW-Google')",
                    )
            else:
                from requests.adapters import HTTPAdapter

                adapter = HTTPAdapter(max_retries=retry_strategy)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "translate", "NamedHTTPAdapter not available, using HTTPAdapter"
                    )
        except Exception as e:
            logger.warning(f"Failed to create NamedHTTPAdapter: {e}")
            from requests.adapters import HTTPAdapter

            adapter = HTTPAdapter(max_retries=retry_strategy)

        self._session.mount("http://", adapter)
        self._session.mount("https://", adapter)
        self._session.headers.update(
            {
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/120.0.0.0 Safari/537.36"
                ),
                "Accept": "application/json, text/plain, */*",
                "Accept-Language": "en-US,en;q=0.5",
            }
        )
        self._session.timeout = (10, 30)

    def _setup_translator(self) -> None:
        """
        Initialisiert den deep_translator als primäre Übersetzungs‑Engine.

        Die Zielsprache wird zuerst über ``_map_to_google_code`` und
        anschließend über ``_normalize_target_for_deep_translator``
        normalisiert, sodass der deep_translator immer einen gültigen
        Sprachcode erhält und keine Warnungen oder automatischen
        Fallbacks erzeugt werden.
        """
        if not TRANSLATOR_AVAILABLE:
            self.translator = None
            if DEBUG_LEVEL >= 2:
                log_debug("translate", "deep_translator nicht verfügbar – überspringe")
            return

        try:
            from deep_translator import GoogleTranslator

            self.googletranslator_class = GoogleTranslator

            # Zielsprache in zwei Stufen normalisieren:
            # 1. Google‑kompatiblen Code erzeugen
            target = self._map_to_google_code(self.default_target_lang)
            # 2. Code auf deep_translator‑Kompatibilität prüfen
            target = self._normalize_target_for_deep_translator(target)

            self.translator = GoogleTranslator(source="auto", target=target, timeout=10)

            if DEBUG_LEVEL >= 2:
                log_debug(
                    "translate",
                    "deep_translator initialisiert (Zielsprache: %s)",
                    target,
                )
        except Exception as e:
            logger.warning(
                "GoogleTranslationEngine: deep_translator konnte nicht "
                "initialisiert werden: %s",
                e,
            )
            self.translator = None

    def _reset_session(self) -> None:
        """
        Baut die Session komplett neu auf. Nützlich nach schweren Netzfehlern.
        """
        with self._lock:
            if self._session:
                try:
                    self._session.close()
                except Exception:
                    pass
            self._setup_session()

    def set_target_language(self, target_lang: str) -> None:
        normalized = self._map_to_google_code(target_lang)
        super().set_target_language(normalized)
        self._setup_session()
        self._setup_translator()
        self._direct_failures = 0
        self._use_direct = True
        self._direct_disabled_until = 0.0
        if DEBUG_LEVEL >= 2:
            log_debug(
                "translate",
                f"Zielsprache auf {normalized} gesetzt, Engine zurückgesetzt",
            )

    @classmethod
    def _map_to_google_code(cls, lang_code: str) -> str:
        """Konvertiert ISO‑Code in Google‑kompatiblen Code."""
        if lang_code == "auto":
            return "auto"
        return cls._GOOGLE_LANG_MAP.get(lang_code.lower(), lang_code.lower())

    @classmethod
    def _normalize_target_for_deep_translator(cls, lang_code: str) -> str:
        """
        Konvertiert Google‑Sprachcodes in das von deep_translator
        erwartete Format, um Warnungen und fehlerhafte Fallbacks zu
        vermeiden.
        """
        # ── 1. Hart kodierte Mappings für bekannte Problemfälle ────
        KNOWN_MAPPINGS = {
            "fil": "tl",  # Filipino wird von deep_translator als 'tl' erwartet
            # Weitere Einträge bei Bedarf:
            # "iw": "he",
            # "zh-CN": "zh-cn",
            # "zh-TW": "zh-tw",
        }
        if lang_code in KNOWN_MAPPINGS:
            mapped = KNOWN_MAPPINGS[lang_code]
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate",
                    "_normalize_target_for_deep_translator: mapped '%s' → '%s'",
                    lang_code,
                    mapped,
                )
            return mapped

        # ── 2. Dynamische Prüfung gegen die von deep_translator
        try:
            from deep_translator.constants import GOOGLE_LANGUAGES

            if lang_code not in GOOGLE_LANGUAGES:
                # Fallback: wenn nicht unterstützt, auf 'auto' setzen
                # und Warnung ausgeben
                logger.warning(
                    "deep_translator unterstützt '%s' nicht – "
                    "verwende 'auto' als Zielsprache.",
                    lang_code,
                )
                return "auto"
        except ImportError:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate",
                    "deep_translator.constants nicht verfügbar – "
                    "überspringe dynamische Prüfung.",
                )
        except Exception as exc:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate",
                    "Fehler bei dynamischer Sprachprüfung: %s",
                    exc,
                )

        return lang_code

    def _preprocess_text(self, text: str) -> str:
        if not text:
            return ""
        text = re.sub(r"\s+", " ", text.strip())
        if len(text) > 750:
            cut_pos = text.rfind(" ", 0, 750)
            if cut_pos == -1:
                cut_pos = 750
            text = text[:cut_pos]
        return text

    def _postprocess_translation(self, translated: str, original: str = "") -> str:
        """
        Post‑Processing für Google‑Übersetzungen.

        Bereinigt Groß‑/Kleinschreibung, stellt sicher, dass der Text mit
        einem Satzendzeichen abschließt, und normalisiert Whitespace.

        Der optionale Parameter *original* wird von dieser Engine nicht
        verwendet, ist aber in der Signatur enthalten, um mit der
        erweiterten Basisklasse kompatibel zu sein und künftige
        Erweiterungen zu ermöglichen.
        """
        if not translated:
            return ""
        result = translated.strip()
        if result and result[0].islower():
            result = result[0].upper() + result[1:]
        if result and result[-1] not in ".!?。！？":
            result += "."
        result = re.sub(r"\s+", " ", result)
        return result

    def _call_google_api_direct(
        self, text: str, src: str, target: str
    ) -> Optional[str]:
        """
        Ruft die direkte Google‑JSON‑API auf, um eine Übersetzung zu erhalten.
        """
        # ── 1. Prüfen, ob die direkte API derzeit gesperrt ist ────────
        with self._direct_failures_lock:
            now = time.time()
            if not self._use_direct:
                if now < self._direct_disabled_until:
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "translate",
                            "Direkte API noch deaktiviert bis %s",
                            time.ctime(self._direct_disabled_until),
                        )
                    return None
                # Sperrzeit abgelaufen → wieder aktivieren
                self._use_direct = True
                self._direct_failures = 0
                if DEBUG_LEVEL >= 2:
                    log_debug("translate", "Direkte API wieder aktiviert")

        # ── 2. Session initialisieren (falls noch nicht geschehen) ────
        with self._lock:
            if self._session is None:
                self._setup_session()  # setzt self._session unter Lock
                if self._session is None:
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "translate", "Session kann nicht erstellt werden – Abbruch"
                        )
                    return None

        # ── 3. Parameter vorbereiten ──────────────────────────────────
        url = "https://translate.google.com/translate_a/single"
        params = {"client": "gtx", "sl": src, "tl": target, "dt": "t", "q": text}

        # ── 4. Wiederholungsschleife ──────────────────────────────────
        for attempt in range(3):
            try:
                # Session unter Lock abholen und direkt verwenden
                with self._lock:
                    # Nach einer vorherigen Rücksetzung könnte die Session fehlen
                    if self._session is None:
                        self._setup_session()
                        if self._session is None:
                            if DEBUG_LEVEL >= 2:
                                log_debug("translate", "Session verloren – Abbruch")
                            break
                    response = self._session.get(url, params=params, timeout=10)

                if response.status_code == 200:
                    # Erfolg – Fehlerzähler zurücksetzen
                    with self._direct_failures_lock:
                        self._direct_failures = 0
                    try:
                        data = response.json()
                    except json.JSONDecodeError:
                        if DEBUG_LEVEL >= 2:
                            log_debug("translate", "Ungültiges JSON – wiederhole")
                        time.sleep(1.0)
                        continue

                    if data and isinstance(data, list) and data[0]:
                        translated = "".join(
                            item[0] for item in data[0] if item and item[0]
                        )
                        if translated.strip():
                            return translated.strip()

                    # Antwort syntaktisch korrekt, aber keine Übersetzung enthalten
                    if DEBUG_LEVEL >= 2:
                        log_debug("translate", "Antwort ohne verwertbare Übersetzung")
                    continue

                if response.status_code == 429:
                    if DEBUG_LEVEL >= 2:
                        log_debug("translate", "HTTP 429 – Rate‑Limit")
                elif response.status_code >= 500:
                    if DEBUG_LEVEL >= 2:
                        log_debug("translate", "Serverfehler %d", response.status_code)
                else:
                    # Andere Fehler (4xx) sind meist nicht behebbar – nicht endlos retry
                    logger.warning(
                        "Google‑API meldet Status %d – Übersetzung abgebrochen",
                        response.status_code,
                    )
                    break

            except (
                self._requests.exceptions.Timeout,
                self._requests.exceptions.ConnectionError,
                self._requests.exceptions.RequestException,
            ) as e:
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "translate",
                        "Direkte API, Versuch %d: %s",
                        attempt + 1,
                        e,
                    )
            except Exception as e:
                logger.warning("Unerwarteter Fehler in direkter Google‑API: %s", e)
                break  # bei unbekannten Fehlern nicht retry

            # Exponentielles Backoff mit Jitter (0.5 .. 2.5 s)
            delay = min(3.0, 1.2**attempt) + random.uniform(0, 0.5)
            time.sleep(delay)

        # ── 5. Alle Versuche fehlgeschlagen → Zähler erhöhen & ggf. sperren ──
        with self._direct_failures_lock:
            self._direct_failures += 1
            if self._direct_failures >= self.MAX_DIRECT_FAILURES:
                self._use_direct = False
                self._direct_disabled_until = time.time() + self.DIRECT_DISABLE_DURATION
                logger.warning(
                    "Google direct API wurde nach %d Fehlern für %.0f s deaktiviert",
                    self._direct_failures,
                    self.DIRECT_DISABLE_DURATION,
                )

        return None

    def _retry_with_backoff(
        self,
        operation_name: str,
        func: Callable[[], Optional[str]],
        max_attempts: int = 3,
        base_delay: float = 0.8,
        backoff_factor: float = 2.0,
        max_delay: float = 10.0,
    ) -> Optional[str]:
        """
        Führt *func* wiederholt aus, mit exponentiellem Backoff und Jitter.
        Gibt den Rückgabewert von *func* zurück oder None bei endgültigem Fehlschlag.
        """
        last_exception = None
        for attempt in range(1, max_attempts + 1):
            try:
                result = func()
                if result and result.strip():
                    return result
            except Exception as exc:
                last_exception = exc
                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "translate",
                        "%s, attempt %d/%d: %s",
                        operation_name,
                        attempt,
                        max_attempts,
                        exc,
                    )

            if attempt < max_attempts:
                delay = min(max_delay, base_delay * (backoff_factor ** (attempt - 1)))
                jitter = random.uniform(0, delay * 0.5)
                total_sleep = delay + jitter
                if DEBUG_LEVEL >= 3:
                    log_debug("translate", "Retrying in %.2f s", total_sleep)
                time.sleep(total_sleep)

        if last_exception and DEBUG_LEVEL >= 2:
            log_debug(
                "translate",
                "%s: all %d attempts failed, last error: %s",
                operation_name,
                max_attempts,
                last_exception,
            )
        return None

    def _call_translation_api(
        self, text: str, source_lang: str, target_lang: str
    ) -> Optional[str]:
        """
        Führt die Übersetzung mit maximaler Robustheit aus.
        """
        clean_text = self._preprocess_text(text)
        if not clean_text:
            return None

        src = self._map_to_google_code(source_lang)
        target = self._map_to_google_code(target_lang)
        translated = self._translate_via_deep_translator(clean_text, src, target)
        if translated:
            return translated

        if self._use_direct and self._session:
            translated = self._translate_via_direct_api(clean_text, src, target)
            if translated:
                return translated

        if not translated:
            logger.warning("Google‑Übersetzung: kein Ergebnis für '%.50s…'", clean_text)
        return None

    def _translate_via_deep_translator(
        self, text: str, src: str, target: str
    ) -> Optional[str]:
        """
        Versucht die Übersetzung mit deep_translator, inklusive
        Wiederholungen und Thread‑Safe Zugriff.
        """
        with self._lock:
            if self.translator is None and TRANSLATOR_AVAILABLE:
                self._setup_translator()

        def attempt() -> Optional[str]:
            with self._lock:
                if self.translator is None:
                    raise RuntimeError("deep_translator ist nicht verfügbar")
                return self.translator.translate(text, source=src, target=target)

        return self._retry_with_backoff(
            "deep_translator",
            attempt,
            max_attempts=3,
            base_delay=0.8,
            max_delay=10.0,
        )

    def _translate_via_direct_api(
        self, text: str, src: str, target: str
    ) -> Optional[str]:
        """
        Versucht die Übersetzung über die direkte Google‑JSON‑API,
        mit Wiederholungen und Session‑Lock.
        """
        with self._direct_failures_lock:
            now = time.time()
            if not self._use_direct:
                if now < self._direct_disabled_until:
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "translate",
                            "Direkte API noch deaktiviert bis %s",
                            time.ctime(self._direct_disabled_until),
                        )
                    return None
                self._use_direct = True
                self._direct_failures = 0

        def attempt() -> Optional[str]:
            return self._call_google_api_direct(text, src, target)

        return self._retry_with_backoff(
            "direct_api",
            attempt,
            max_attempts=2,
            base_delay=1.0,
            max_delay=5.0,
        )

    def translate_text(
        self, text: str, source_lang: str = "auto", target_lang: Optional[str] = None
    ) -> Optional[TranslationResult]:
        """
        Übersetzt einen Text mit Caching, Wiederholungsversuchen und
        verbesserter Fehlerbehandlung sowie Negativ‑Cache für fehlgeschlagene
        Übersetzungen.
        """
        # ── 0. Debug: Methodeneintritt ────────────────────────────────────
        log_debug(
            "translate",
            "🔍 GoogleTranslationEngine.translate_text ENTER: text='%s…', source_lang=%s, target_lang=%s",
            text[:50] if text else "None",
            source_lang,
            target_lang,
        )

        # ── 1. Engine verfügbar und funktionsfähig? ──────────────────────
        if not self.is_functional():
            log_debug("translate", f"{self.__class__.__name__} derzeit deaktiviert")
            return None

        # ── 2. Zielsprache bestimmen ───────────────────────────────────
        target = target_lang or self.default_target_lang
        log_debug("translate", f"  Zielsprache: {target}")

        # ── 3. Leere oder ungültige Eingabe ─────────────────────────────
        if not text:
            log_debug("translate", "  Text ist leer – überspringe")
            return None
        original_text = text.strip()
        if len(original_text) < 2:
            log_debug("translate", "  Text zu kurz (<2 Zeichen) – überspringe")
            return None

        # ── 4. Negativ‑Cache (fehlgeschlagene Übersetzungen) ─────────────
        #    Lazy‑Initialisierung des TTL‑Caches (kein relativer Import!)
        if not hasattr(self, "_failed_translation_cache"):
            # TTLCache ist im globalen Namensraum des Skripts definiert
            self._failed_translation_cache = TTLCache(maxsize=200, ttl=60)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate", "Negativ‑Cache initialisiert (maxsize=200, ttl=60s)"
                )
        if self._failed_translation_cache.get(original_text) is not None:
            log_debug(
                "translate",
                "  Negativ‑Cache‑Treffer für '%s…' – Übersetzung übersprungen",
                original_text[:30],
            )
            return None

        # ── 5. Duplikatprüfung (kurzzeitiger Cache) ────────────────────
        with self._lock:
            if original_text in self._last_translations:
                log_debug(
                    "translate",
                    "  Duplikat in _last_translations gefunden – überspringe",
                )
                return None
            cached = self._cache_manager.get_cached_translation(original_text, target)
            if cached is not None:
                log_debug("translate", "  Cache‑Treffer für '%s…'", original_text[:50])
                return cached
            log_debug("translate", "  Kein Cache‑Treffer – rufe API auf")

        # ── 6. Wiederholungsschleife mit exponentiellem Backoff ─────────
        last_exception = None
        base_delay = getattr(self, "_retry_delay", 1.0)
        max_retries = getattr(self, "_max_retries", 3)
        last_invalid_response = (
            None  # für Erkennung sich wiederholender ungültiger Antworten
        )

        for attempt in range(max_retries + 1):
            log_debug(
                "translate",
                "  Versuch %d/%d (base_delay=%.1f)",
                attempt + 1,
                max_retries + 1,
                base_delay,
            )
            try:
                # API‑Aufruf (thread‑sicher, eigene Session pro Request)
                translated_text = self._call_translation_api(
                    original_text, source_lang, target
                )
                if not translated_text or not translated_text.strip():
                    log_debug(
                        "translate",
                        "  API gab leere/None Antwort – wiederhole (Versuch %d)",
                        attempt + 1,
                    )
                    # Bei leerer Antwort: Kurze Pause, dann nächster Versuch
                    time.sleep(base_delay * (2**attempt))
                    continue

                # Prüfen, ob sich die ungültige Antwort wiederholt
                if translated_text == last_invalid_response:
                    log_debug(
                        "translate",
                        "  Wiederholte ungültige Antwort '%s…' – breche ab",
                        translated_text[:30],
                    )
                    self._failed_translation_cache.put(original_text, True)
                    return None
                last_invalid_response = translated_text

                log_debug(
                    "translate",
                    "  API lieferte Übersetzung (%d Zeichen): '%s…'",
                    len(translated_text),
                    translated_text[:50] if translated_text else "",
                )

                # Validierung der Übersetzung (Länge, Zeichensatz, etc.)
                if not self._is_valid_translation(original_text, translated_text):
                    log_debug(
                        "translate",
                        "  Übersetzung ungültig (is_valid_translation=False) – wiederhole",
                    )
                    time.sleep(base_delay)  # kurze Pause vor Wiederholung
                    continue

                # Erfolg – Ergebnis vorbereiten
                result = TranslationResult(
                    original=original_text,
                    translated=translated_text.strip(),
                    source_lang=source_lang,
                    target_lang=target,
                )

                # Qualität bewerten (optional, für Statistik)
                quality = self._rate_translation_quality(original_text, translated_text)
                if quality < 0.5:
                    log_debug(
                        "translate",
                        f"  Qualität niedrig ({quality:.2f}) – Fehler gezählt",
                    )
                    self._record_error()
                else:
                    log_debug(
                        "translate", f"  Qualität OK ({quality:.2f}) – Erfolg gezählt"
                    )
                    self._record_success()

                # Im Cache ablegen und in die Duplikat‑Historie aufnehmen
                with self._lock:
                    self._cache_manager.cache_translation(result)
                    self._last_translations.append(original_text)

                log_debug(
                    "translate",
                    "✅ Übersetzung erfolgreich: %d Zeichen",
                    len(translated_text),
                )
                return result

            except Exception as e:
                last_exception = e
                self._record_error()
                log_debug(
                    "translate",
                    "  ❌ Versuch %d/%d fehlgeschlagen: %s",
                    attempt + 1,
                    max_retries + 1,
                    str(e)[:100],
                )
                if attempt < max_retries:
                    delay = min(5.0, base_delay * (2**attempt))
                    log_debug("translate", "  Warte %.1fs vor nächstem Versuch", delay)
                    time.sleep(delay)

        # ── 7. Alle Versuche fehlgeschlagen → Negativ‑Cache eintragen ────
        self._failed_translation_cache.put(original_text, True)
        if last_exception:
            logger.warning(
                f"Übersetzung fehlgeschlagen nach {max_retries+1} Versuchen: {last_exception}"
            )
        else:
            logger.warning(
                "Übersetzung fehlgeschlagen – kein Ergebnis nach allen Versuchen"
            )
        return None

    def _rate_translation_quality(self, original: str, translated: str) -> float:
        if not translated or len(translated) < 2:
            return 0.0
        orig_words = len(original.split())
        trans_words = len(translated.split())
        if trans_words < 2 and orig_words > 2:
            return 0.0
        if orig_words > 0:
            ratio = trans_words / orig_words
            if ratio < 0.2 or ratio > 5.0:
                return 0.0
        alpha_orig = sum(c.isalpha() for c in original) / max(len(original), 1)
        alpha_trans = sum(c.isalpha() for c in translated) / max(len(translated), 1)
        if alpha_trans < 0.3 and alpha_orig > 0.5:
            return 0.0
        return 1.0

    def _reinitialize(self) -> None:
        logger.info("GoogleTranslationEngine reinitialisiert")
        self._setup_session()
        self._setup_translator()
        self._direct_failures = 0
        self._use_direct = True
        self._direct_disabled_until = 0.0
        with self._error_lock:
            self._error_count = 0
            self._disabled_until = 0.0

    def dispose(self) -> None:
        super().dispose()
        if self._session:
            try:
                self._session.close()
            except Exception:
                pass
            self._session = None
        self.translator = None
        if DEBUG_LEVEL >= 2:
            log_debug("translate", "GoogleTranslationEngine disposed")


class OllamaTranslationEngine(BaseCachedTranslationEngine):
    """Übersetzungs‑Engine mit lokalem Ollama‑Modell – robust und threadsicher."""
    __slots__ = (
        "_requests",
        "model",
        "host",
        "temperature",
        "timeout",
        "system_prompt",
        "available",
        "_available_models",
        "_models_cache_time",
        "_models_cache_ttl",
        "_timeout_retries",
        "_timeout_backoff_base",
        "_keep_alive",
        "_consecutive_network_errors",
        "_health_check_lock",
    )

    DEFAULT_SYSTEM_PROMPT: str = (
        "You are a professional translator. Your only task is to translate "
        "the given text accurately and faithfully into the target language. "
        "Do not add any explanations, notes, comments, or additional text. "
        "Output ONLY the translation, nothing else. "
        "Do not include any characters from other writing systems."
    )

    def __init__(
        self,
        target_lang: str = "de",
        settings: Optional["AdvancedSettings"] = None,
        model: str = "llama3.1:8b",
        host: str = "http://localhost:11434",
        temperature: float = 0.0,
        timeout: int = 90,
        system_prompt: Optional[str] = None,
        cache_manager: Optional[CacheManager] = None,
        timeout_retries: int = 2,
        timeout_backoff_base: float = 2.0,
    ) -> None:
        """Initialisiert die Ollama‑Übersetzungs‑Engine.

        Args:
            target_lang: Zielsprache (ISO‑Code).
            settings: Erweiterte Einstellungen (optional).
            model: Name des zu verwendenden Ollama‑Modells.
            host: Basis‑URL des Ollama‑Servers.
            temperature: Temperatur für die Generierung.
            timeout: Timeout pro Anfrage in Sekunden.
            system_prompt: System‑Prompt (optional).
            cache_manager: Zentraler Cache‑Manager (optional).
            timeout_retries: Anzahl Wiederholungen bei Timeout.
            timeout_backoff_base: Basis‑Wartezeit für exponentiellen Backoff.
        """
        validated_host = self._validate_and_normalize_host(host)
        if validated_host != host:
            logger.warning(
                "⚠️ Ungültige Ollama-Host-URL '%s' – verwende '%s'",
                host,
                validated_host,
            )

        if settings is not None:
            if hasattr(settings, "ollama_timeout"):
                timeout = settings.ollama_timeout
            if hasattr(settings, "ollama_temperature"):
                temperature = settings.ollama_temperature
            self._keep_alive = getattr(settings, "ollama_keep_alive", 60)
        else:
            self._keep_alive = 60

        self.timeout = timeout
        self._timeout_retries = timeout_retries
        self._timeout_backoff_base = timeout_backoff_base

        super().__init__(
            target_lang,
            settings,
            max_retries=3,
            retry_delay_base=1.0,
            retry_delay_max=5.0,
            cache_manager=cache_manager,
            max_errors=10,
            disable_duration=120.0,
        )

        self.model = model
        self.host = validated_host.rstrip("/")
        self.temperature = temperature
        self.system_prompt = system_prompt or self.DEFAULT_SYSTEM_PROMPT
        self.available = OLLAMA_AVAILABLE and (requests is not None)
        self._requests = None
        self._consecutive_network_errors = 0
        self._health_check_lock = threading.Lock()

        if self.available:
            import requests as _requests

            self._requests = _requests

        # Modell‑Cache wird erst beim ersten Zugriff gefüllt (lazy)
        self._available_models: List[str] = []
        self._models_cache_time = 0.0
        self._models_cache_ttl = 300

        if DEBUG_LEVEL >= 2:
            log_debug(
                "ollama",
                "OllamaTranslationEngine initialisiert: model=%s, host=%s",
                model,
                self.host,
            )

    @staticmethod
    def _validate_and_normalize_host(host: str) -> str:
        """Normalisiert die Ollama‑Server‑URL auf ``http://host:11434``.

        Fehlende Teile werden ergänzt, ungültige Eingaben führen zum
        Standard ``http://localhost:11434``.
        """
        DEFAULT_HOST = "http://localhost:11434"
        if not host or not isinstance(host, str):
            return DEFAULT_HOST
        host = host.strip()
        if not host:
            return DEFAULT_HOST
        if "://" not in host:
            host = "http://" + host
        try:
            parsed = urllib.parse.urlparse(host)
        except Exception:
            return DEFAULT_HOST
        if not parsed.scheme or not parsed.netloc:
            return DEFAULT_HOST
        if parsed.scheme not in ("http", "https"):
            logger.warning(
                "⚠️ Nicht unterstütztes URL-Schema '%s' – verwende 'http'",
                parsed.scheme,
            )
            parsed = parsed._replace(scheme="http")
        netloc = parsed.netloc
        if ":" not in netloc:
            netloc = f"{netloc}:11434"
        normalized = urllib.parse.urlunparse((parsed.scheme, netloc, "", "", "", ""))
        return normalized.rstrip("/")

    def _calculate_timeout(
        self, prompt: str, text: str, max_timeout: float = 300.0
    ) -> float:
        """
        Berechnet einen dynamischen Timeout für die Ollama‑Generierung.

        Verwendet die Token‑Schätzung für *prompt* + *text* und multipliziert
        sie mit einem konservativen Faktor (0,2 s/Token).  Der Wert liegt
        garantiert zwischen 30 s und *max_timeout* (Standard 300 s).

        Args:
            prompt: Der Prompt‑Text.
            text: Der zu verarbeitende Text.
            max_timeout: Maximale Timeout‑Dauer in Sekunden.

        Returns:
            Timeout in Sekunden als Gleitkommazahl.
        """
        try:
            total_tokens = self._estimate_tokens(prompt) + self._estimate_tokens(text)
        except Exception:
            total_tokens = 500

        timeout = max(30.0, min(max_timeout, total_tokens * 0.2))
        return timeout

    def _fetch_available_models(self) -> List[str]:
        """Ermittelt die verfügbaren Modelle direkt per ``requests.get``
        und cached sie mit einer konfigurierbaren TTL.

        Diese Methode wird erst beim ersten Zugriff auf `get_available_models`
        oder `is_model_available` ausgeführt und blockiert daher nicht den
        Programmstart.
        """
        if not self.available or self._requests is None:
            return []
        with self._lock:
            now = time.time()
            if (
                now - self._models_cache_time <= self._models_cache_ttl
                and self._available_models
            ):
                return self._available_models.copy()

        try:
            r = self._requests.get(
                f"{self.host}/api/tags",
                timeout=5,
                headers={
                    "User-Agent": "DragonWhisperer/4.0",
                    "Accept": "application/json",
                },
            )
            if r.status_code == 200:
                data = r.json()
                self._available_models = [m["name"] for m in data.get("models", [])]
                self._models_cache_time = time.time()
        except Exception:
            pass
        return self._available_models.copy()

    def is_model_available(self, model: Optional[str] = None) -> bool:
        """Prüft, ob das Modell auf dem Server verfügbar ist.

        Kann der Server nicht erreicht werden, wird konservativ ``True``
        zurückgegeben.
        """
        check_model = model or self.model
        available = self._fetch_available_models()
        return (not available) or (check_model in available)

    def is_server_reachable(self) -> bool:
        """Prüft die Server‑Erreichbarkeit mit kurzem Timeout."""
        if not self.available or self._requests is None:
            return False
        try:
            r = self._requests.get(
                f"{self.host}/api/tags",
                timeout=3,
                headers={
                    "User-Agent": "DragonWhisperer/4.0",
                    "Accept": "application/json",
                },
            )
            return r.status_code == 200
        except Exception:
            return False

    def _perform_health_check(self) -> bool:
        """Thread‑sicherer Kurz‑Health‑Check vor einer Übersetzungsanfrage."""
        with self._health_check_lock:
            return self.is_server_reachable()

    def _sanitize_text(self, text: str) -> str:
        """Entfernt Steuerzeichen und kürzt bei Bedarf."""
        cleaned = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", text)
        if len(cleaned) > 2000:
            cleaned = cleaned[:2000] + "…"
        return cleaned

    def _build_translation_prompt(
        self, text: str, source_lang: str, target_lang: str
    ) -> str:
        """Erzeugt den Übersetzungs‑Prompt mit klaren Regeln."""
        source_name = (
            SUPPORTED_LANGUAGES.get(source_lang, source_lang)
            if source_lang != "auto"
            else "the detected language"
        )
        target_name = SUPPORTED_LANGUAGES.get(target_lang, target_lang)
        safe_text = self._sanitize_text(text)
        return (
            f"Translate the following text from {source_name} to {target_name}.\n"
            f"Rules:\n"
            f"- Output ONLY the translation.\n"
            f"- Do NOT add any notes, explanations, comments, or disclaimers.\n"
            f"- Do NOT include the original text.\n"
            f"- Preserve formatting (line breaks, paragraphs).\n"
            f"- Use ONLY {target_name} – no other language or script.\n\n"
            f"Text:\n{safe_text}\n\n"
            f"Translation:"
        )

    def _call_ollama_with_timeout_retry(
        self,
        prompt: str,
        temperature_override: Optional[float] = None,
        cancel_event: Optional[threading.Event] = None,
        timeout_override: Optional[float] = None,
    ) -> Optional[str]:
        """
        Sendet den Prompt an die Ollama‑API und wiederholt bei Bedarf.

        Verwendet einen direkten ``requests.post``-Aufruf – keine
        persistente Session.  Rückgabe ist der bereinigte Antworttext oder
        ``None``.

        Args:
            prompt: Der Prompt (vollständiger Text).
            temperature_override: Optional abweichende Temperatur.
            cancel_event: Optionales Event für vorzeitigen Abbruch.
            timeout_override: Optional abweichender Timeout in Sekunden.

        Returns:
            Antworttext oder None bei Fehlschlag / Abbruch.
        """
        # ── 1. Grundlegende Verfügbarkeit prüfen ──────────────────────────
        if not self.available or self._requests is None:
            raise RuntimeError("Ollama nicht verfügbar")

        if not self.is_model_available():
            self._try_model_fallback()

        # ── 2. Parameter vorbereiten ──────────────────────────────────────
        effective_temp = (
            temperature_override
            if temperature_override is not None
            else self.temperature
        )

        payload = {
            "model": self.model,
            "prompt": prompt,
            "stream": False,
            "options": {"temperature": effective_temp},
            "keep_alive": self._keep_alive,
            "system": self.system_prompt,
        }

        # ── 3. Timeout berechnen ──────────────────────────────────────────
        base_timeout = timeout_override if timeout_override is not None else self.timeout
        dynamic_timeout = base_timeout + max(0, int(len(prompt) * 0.05))
        # Absolute Obergrenze: 600 Sekunden (10 Minuten)
        effective_timeout = min(dynamic_timeout, 600.0)

        total_attempts = self._timeout_retries + 1

        # ── 4. Wiederholungsschleife ──────────────────────────────────────
        for attempt in range(total_attempts):
            # 4a. Abbruch durch Benutzer
            if cancel_event and cancel_event.is_set():
                log_debug("ollama", "Request durch cancel_event abgebrochen")
                return None

            # 4b. Zeitmessung für Backoff
            start_req = time.monotonic()

            try:
                response = self._requests.post(
                    f"{self.host}/api/generate",
                    json=payload,
                    timeout=effective_timeout,
                )
                req_duration = (time.monotonic() - start_req) * 1000

                # ── 5. Erfolgreiche Antwort ──────────────────────────────
                if response.status_code == 200:
                    try:
                        data = response.json()
                    except json.JSONDecodeError:
                        if attempt < total_attempts - 1:
                            log_debug(
                                "ollama",
                                "JSON-Decode-Fehler (Versuch %d/%d) – wiederhole",
                                attempt + 1,
                                total_attempts,
                            )
                            self._wait_with_backoff(attempt, "Invalid JSON")
                            continue
                        return None

                    translated = data.get("response", "").strip()
                    if translated:
                        self._consecutive_network_errors = 0
                        log_debug(
                            "ollama",
                            "Antwort erhalten (Dauer: %.1f ms, Versuch %d)",
                            req_duration,
                            attempt + 1,
                        )
                        return translated

                    # Leere Antwort – wiederholen, aber nur einmal
                    if attempt < total_attempts - 1:
                        log_debug(
                            "ollama",
                            "Leere Antwort (Versuch %d/%d) – wiederhole",
                            attempt + 1,
                            total_attempts,
                        )
                        self._wait_with_backoff(attempt, "Empty response")
                        continue
                    log_debug("ollama", "Leere Antwort nach allen Versuchen")
                    return None

                # ── 6. HTTP-Fehler ──────────────────────────────────────
                if response.status_code in (429, 500, 502, 503, 504):
                    if attempt < total_attempts - 1:
                        log_debug(
                            "ollama",
                            "HTTP %d (Versuch %d/%d) – wiederhole",
                            response.status_code,
                            attempt + 1,
                            total_attempts,
                        )
                        self._wait_with_backoff(attempt, f"HTTP {response.status_code}")
                        continue
                    logger.error(
                        "Ollama dauerhafter Fehler %d (nach %d Versuchen)",
                        response.status_code,
                        total_attempts,
                    )
                    return None
                else:
                    # Andere HTTP-Fehler (4xx, 5xx) – sofort abbrechen
                    logger.error(
                        "Ollama HTTP %d: %s",
                        response.status_code,
                        response.text[:200],
                    )
                    return None

            # ── 7. Netzwerkfehler ────────────────────────────────────────
            except self._requests.exceptions.RequestException as exc:
                if attempt < total_attempts - 1:
                    log_debug(
                        "ollama",
                        "Netzwerkfehler (Versuch %d/%d): %s",
                        attempt + 1,
                        total_attempts,
                        exc,
                    )
                    self._wait_with_backoff(attempt, type(exc).__name__)
                    continue
                logger.error(
                    "Netzwerkfehler nach %d Versuchen: %s",
                    total_attempts,
                    exc,
                )
                return None

            # ── 8. Unerwartete Fehler ────────────────────────────────────
            except Exception as exc:
                logger.error(
                    "Unerwarteter Fehler (Versuch %d/%d): %s",
                    attempt + 1,
                    total_attempts,
                    exc,
                    exc_info=True,
                )
                return None

        # ── 9. Endgültiger Fehlschlag ────────────────────────────────────
        logger.warning(
            "Ollama-Anfrage nach %d Versuchen fehlgeschlagen",
            total_attempts,
        )
        return None

    def _wait_with_backoff(self, attempt: int, reason: str) -> None:
        """Berechnet exponentielle Wartezeit mit Jitter."""
        base = self._timeout_backoff_base * (2**attempt)
        jitter = base * 0.2 * (2 * random.random() - 1)
        delay = max(0.1, min(30.0, base + jitter))
        log_debug("ollama", f"Backoff wegen {reason}: {delay:.2f}s")
        time.sleep(delay)

    def _try_model_fallback(self) -> bool:
        """Versucht, auf ein anderes verfügbares Modell umzuschalten.

        Returns:
            ``True``, wenn ein Fallback‑Modell aktiviert wurde.
        """
        available = self._fetch_available_models()
        if not available:
            return False
        if self.model in available:
            return False
        fallback_model = available[0]
        logger.warning(
            "Ollama‑Modell '%s' nicht verfügbar – wechsle zu '%s'",
            self.model,
            fallback_model,
        )
        self.model = fallback_model
        return True

    # ------------------------------------------------------------------
    # Übersetzungs‑Logik (unverändert)
    # ------------------------------------------------------------------
    def _preprocess_text(self, text: str) -> str:
        """Normalisiert Whitespace und entfernt führende/trailing Spaces."""
        if not text:
            return ""
        return re.sub(r"\s+", " ", text.strip())

    def _postprocess_translation(self, translated: str, original: str = "") -> str:
        """
        Bereinigt die Modell‑Antwort um Artefakte und wiederholte Phrasen.

        Der optionale Parameter *original* wird von dieser Engine nicht
        verwendet, ist aber in der Signatur enthalten, um mit der
        erweiterten Basisklasse ``BaseTranslationEngine`` kompatibel zu
        sein und künftige Erweiterungen zu ermöglichen.
        """
        if not translated:
            return ""
        for pattern in [
            r"\(Note:.*?\)",
            r"\(Please keep in mind.*?\)",
            r"Translation:\s*",
        ]:
            translated = re.sub(
                pattern, "", translated, flags=re.IGNORECASE | re.DOTALL
            )
        translated = re.sub(r"\n{3,}", "\n\n", translated)
        translated = re.sub(r" +", " ", translated).strip()
        return translated if translated else original

    def _rate_translation_quality(self, original: str, translated: str) -> float:
        """Bewertet die Übersetzungsqualität heuristisch (0.0 – 1.0)."""
        if not translated or len(translated) < 2:
            return 0.0
        orig_words = len(original.split())
        trans_words = len(translated.split())
        if trans_words < 2 and orig_words > 2:
            return 0.0
        if orig_words > 0:
            ratio = trans_words / orig_words
            if ratio < 0.2 or ratio > 5.0:
                return 0.0
        alpha_orig = sum(c.isalpha() for c in original) / max(len(original), 1)
        alpha_trans = sum(c.isalpha() for c in translated) / max(len(translated), 1)
        if alpha_trans < 0.3 and alpha_orig > 0.5:
            return 0.0
        return 1.0

    def _call_translation_api(
        self, text: str, source_lang: str, target_lang: str
    ) -> Optional[str]:
        """
        Führt die Übersetzung mit Ollama aus – inklusive Health‑Check,
        mehreren Prompt‑Strategien, Retry‑Logik und Fallback auf andere Engines.

        Args:
            text: Der zu übersetzende Text.
            source_lang: ISO‑Code der Quellsprache (oder "auto").
            target_lang: ISO‑Code der Zielsprache.

        Returns:
            Übersetzter Text oder None bei Fehlschlag.
        """
        # ── 1. Text vorbereiten ──────────────────────────────────────────
        clean_text = self._preprocess_text(text)
        if not clean_text:
            return None

        # ── 2. Health‑Check (Server erreichbar?) ────────────────────────
        if not self._perform_health_check():
            logger.warning("Ollama‑Server nicht erreichbar – Übersetzung abgebrochen")
            self._record_error()
            return None

        # ── 3. Prompt erstellen ──────────────────────────────────────────
        prompt = self._build_translation_prompt(clean_text, source_lang, target_lang)

        # ── 4. Dynamisches Timeout berechnen ────────────────────────────
        # ★ FIX: Übergabe von prompt UND clean_text
        timeout = self._calculate_timeout(prompt, clean_text, max_timeout=300.0)

        # ── 5. Strategien definieren (mit abnehmender Komplexität) ──────
        strategies: List[Tuple[str, str, float]] = [
            ("Standard", prompt, self.temperature),
        ]
        if self.temperature > 0.0:
            strategies.append(("Standard (temp=0.0)", prompt, 0.0))
        strategies.append(
            (
                "Minimal Prompt",
                f"Translate the following text to "
                f"{SUPPORTED_LANGUAGES.get(target_lang, target_lang)}. "
                f"Output only the translation, no additional text.\n\n{clean_text}",
                0.0,
            )
        )

        # ── 6. Strategien durchprobieren (mit Retry pro Strategie) ──────
        last_exception: Optional[Exception] = None
        for strategy_name, strat_prompt, strat_temp in strategies:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "ollama",
                    "Versuche Übersetzungs‑Strategie '%s' (temp=%s, timeout=%.1fs)",
                    strategy_name,
                    strat_temp,
                    timeout,
                )

            # Retry‑Schleife für diese Strategie (max. 3 Versuche)
            for attempt in range(1, self._max_retries + 2):  # +1 für ersten Versuch
                try:
                    translated = self._call_ollama_with_timeout_retry(
                        strat_prompt,
                        temperature_override=strat_temp,
                        timeout_override=timeout,
                    )
                    if translated:
                        post = self._postprocess_translation(translated, clean_text)
                        if post:
                            self._record_success()
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ollama",
                                    "Strategie '%s' erfolgreich (Versuch %d)",
                                    strategy_name,
                                    attempt,
                                )
                            return post
                        else:
                            if DEBUG_LEVEL >= 3:
                                log_debug(
                                    "ollama",
                                    "Strategie '%s' lieferte leeren Text nach Post‑Processing",
                                    strategy_name,
                                )
                    else:
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "ollama",
                                "Strategie '%s' lieferte keine Übersetzung (Versuch %d)",
                                strategy_name,
                                attempt,
                            )
                except RuntimeError as exc:
                    last_exception = exc
                    if "model not found" in str(exc).lower():
                        logger.error(
                            "Ollama‑Modell '%s' nicht gefunden – breche ab.", self.model
                        )
                        return None
                    logger.warning(
                        "Strategie '%s' RuntimeError (Versuch %d): %s",
                        strategy_name,
                        attempt,
                        exc,
                    )
                except Exception as exc:
                    last_exception = exc
                    logger.warning(
                        "Strategie '%s' Fehler (Versuch %d): %s",
                        strategy_name,
                        attempt,
                        exc,
                    )

                # Wenn nicht letzter Versuch, exponentieller Backoff
                if attempt <= self._max_retries:
                    delay = min(10.0, self._retry_delay * (2 ** (attempt - 1)))
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "ollama",
                            "Warte %.1fs vor nächstem Versuch für Strategie '%s'",
                            delay,
                            strategy_name,
                        )
                    time.sleep(delay)

            # Wenn alle Versuche einer Strategie fehlschlagen, nächste Strategie

        # ── 7. Alle Strategien fehlgeschlagen → Fallback auf andere Engine ──
        logger.warning(
            "Ollama‑Übersetzung fehlgeschlagen – alle %d Strategien ohne Ergebnis.",
            len(strategies),
        )
        self._record_error()

        # ── 8. Fallback auf Google oder Argos (falls vorhanden) ──────────
        if hasattr(self, "fallback_engine") and self.fallback_engine is not None:
            try:
                logger.info("Versuche Fallback‑Übersetzung mit %s", type(self.fallback_engine).__name__)
                fallback_result = self.fallback_engine.translate_text(clean_text, source_lang)
                if fallback_result and fallback_result.translated:
                    logger.info("Fallback erfolgreich")
                    return fallback_result.translated
                else:
                    logger.warning("Fallback lieferte keine Übersetzung")
            except Exception as exc:
                logger.error("Fallback‑Übersetzung fehlgeschlagen: %s", exc)

        # ── 9. Endgültiger Fehlschlag ──────────────────────────────────
        logger.error(
            "Ollama‑Übersetzung endgültig fehlgeschlagen – kein Ergebnis."
        )
        if last_exception:
            logger.debug("Letzte Exception: %s", last_exception)
        return None

    def _reinitialize(self) -> None:
        """Setzt den Modell‑Cache zurück und lädt frische Daten."""
        logger.info("🔄 OllamaTranslationEngine wird reinitialisiert...")
        with self._lock:
            self._models_cache_time = 0
            self._available_models = []
        self._fetch_available_models()

    def dispose(self) -> None:
        """Gibt Ressourcen frei und leert Caches."""
        super().dispose()
        self._available_models.clear()
        if DEBUG_LEVEL >= 2:
            log_debug("ollama", "OllamaTranslationEngine disposed")


class ReflectionTranslationEngine(BaseTranslationEngine):
    """Zweistufige Übersetzungs‑Engine mit Reflexion und Verbesserung.

    Die Engine verwendet eine beliebige ``BaseTranslationEngine`` als
    Basis und führt nach der Erstübersetzung eine Selbstrevision mit
    Ollama durch.  Sie ist sowohl mit der alten API
    (``_call_ollama_with_timeout_retry``) der
    ``OllamaTranslationEngine`` als auch mit der neuen API
    (``_call_ollama_with_retry``) des ``OllamaSummarizer`` kompatibel.

    Die Prompts für den Reflexions‑ und Verbesserungs‑Schritt werden
    sprachabhängig gewählt, um die Qualität der Korrektur weiter zu
    erhöhen – insbesondere für Deutsch als Zielsprache.
    """

    def __init__(
        self,
        base_engine: BaseTranslationEngine,
        settings: "AdvancedSettings",
        timeout: int = 120,
        cancel_event: Optional[threading.Event] = None,
    ) -> None:
        """Initialisiert die ReflectionTranslationEngine.

        Args:
            base_engine: Eine funktionsfähige Übersetzungs‑Engine,
                die von ``BaseTranslationEngine`` abgeleitet ist und
                entweder ``_call_ollama_with_timeout_retry`` oder
                ``_call_ollama_with_retry`` bereitstellt.
            settings: Die erweiterten Anwendungseinstellungen.
            timeout: Max. Laufzeit für jeden Reflexions‑/Verbesserungs‑
                Aufruf (wird an die Basis‑Engine weitergereicht).
            cancel_event: Optionales Event zum externen Abbruch aller
                Ollama‑Aufrufe.
        """
        super().__init__()
        self.base_engine = base_engine
        self.settings = settings
        self.timeout = timeout
        self.cancel_event = cancel_event
        self._lock = threading.RLock()

        # ── Englische Prompt‑Vorlagen (Fallback) ───────────────────
        self._prompts_en: Dict[str, str] = {
            "reflection_system": (
                "You are an expert linguistic editor and reviewer. "
                "Answer only in the target language. "
                "Do not include any characters from other writing systems."
            ),
            "reflection_template": (
                "Review the following translation from {source_lang} to "
                "{target_lang}.\n\n"
                "Original text:\n{source_text}\n\n"
                "Draft translation:\n{draft_translation}\n\n"
                "Provide a concise list of improvements regarding:\n"
                "- Accuracy (factual errors, missing nuances)\n"
                "- Tone & style (joyful, sad, formal, informal, …)\n"
                "- Naturalness (idiomatic {target_lang})\n"
                "- Culturally appropriate wording\n\n"
                "Output ONLY the analysis, NO new translation."
            ),
            "improvement_system": (
                "You are a master translator. "
                "Answer only in the target language. "
                "Do not include any characters from other writing systems. "
                "Output ONLY the final translation, no explanations."
            ),
            "improvement_template": (
                "Improve the draft translation based on the critique.\n\n"
                "Original text:\n{source_text}\n\n"
                "Draft translation:\n{draft_translation}\n\n"
                "Critique:\n{reflection}\n\n"
                "Now provide an accurate, natural {target_lang} translation. "
                "Output ONLY the translation."
            ),
        }

        # ── Deutsche Prompt‑Vorlagen ───────────────────────────────
        #   Studien zeigen, dass Prompts in der Zielsprache die
        #   Antwortqualität lokaler Modelle signifikant verbessern.
        self._prompts_de: Dict[str, str] = {
            "reflection_system": (
                "Du bist ein fachkundiger sprachlicher Lektor und Prüfer. "
                "Antworte ausschließlich in der Zielsprache. "
                "Verwende keinerlei Zeichen aus anderen Schriftsystemen."
            ),
            "reflection_template": (
                "Überprüfe die folgende Übersetzung von {source_lang} nach "
                "{target_lang}.\n\n"
                "Originaltext:\n{source_text}\n\n"
                "Erstübersetzung:\n{draft_translation}\n\n"
                "Gib eine knappe Liste mit Verbesserungsvorschlägen zu:\n"
                "- Genauigkeit (Faktenfehler, fehlende Nuancen)\n"
                "- Ton & Stil (fröhlich, traurig, formell, informell, …)\n"
                "- Natürlichkeit (idiomatisches {target_lang})\n"
                "- Kulturell passende Formulierungen\n\n"
                "Gib NUR die Analyse aus, KEINE neue Übersetzung."
            ),
            "improvement_system": (
                "Du bist ein erstklassiger Übersetzer. "
                "Antworte ausschließlich in der Zielsprache. "
                "Verwende keinerlei Zeichen aus anderen Schriftsystemen. "
                "Gib NUR die endgültige Übersetzung aus, keine Erklärungen."
            ),
            "improvement_template": (
                "Verbessere die Erstübersetzung anhand der Kritik.\n\n"
                "Originaltext:\n{source_text}\n\n"
                "Erstübersetzung:\n{draft_translation}\n\n"
                "Kritik:\n{reflection}\n\n"
                "Liefere nun eine präzise, natürliche {target_lang}-Übersetzung. "
                "Gib NUR die Übersetzung aus."
            ),
        }

        if DEBUG_LEVEL >= 3:
            log_debug(
                "reflection",
                "ReflectionTranslationEngine initialisiert (base=%s, timeout=%d)",
                type(base_engine).__name__,
                timeout,
            )

    # ------------------------------------------------------------------
    # Öffentliche API
    # ------------------------------------------------------------------
    def set_target_language(self, target_lang: str) -> None:
        """Leitet die Zielsprache an die Basis‑Engine weiter."""
        with self._lock:
            if self.base_engine is not None:
                self.base_engine.set_target_language(target_lang)

    def translate_text(
        self, text: str, source_lang: str = "auto", target_lang: Optional[str] = None
    ) -> Optional[TranslationResult]:
        """
        Übersetzt einen Text mit Caching, intelligenten Wiederholungsversuchen
        und Negativ‑Cache für kürzlich fehlgeschlagene Übersetzungen.

        - Echte Netzwerk‑/Zeitfehler führen zu exponentiellem Backoff.
        - Leere oder strukturell ungültige Serverantworten werden maximal
          **einmal** wiederholt; danach wird der Versuch abgebrochen.
        - Texte, die bereits innerhalb der letzten 60 s zu einer endgültig
          fehlgeschlagenen Übersetzung führten, werden sofort mit ``None``
          beantwortet, ohne die API erneut zu belasten.
        """
        # ── Grundzustand prüfen ────────────────────────────────────
        if not self.is_functional():
            log_debug("translate", f"{self.__class__.__name__} derzeit deaktiviert")
            return None

        target = target_lang or self.default_target_lang
        # *** Die problematische Prüfung wurde entfernt ***
        # if source_lang != "auto" and source_lang == target:
        #     return None

        if not text:
            return None
        original_text = text.strip()
        if len(original_text) < 2:
            return None

        # ── Negativ‑Cache (lazy initialisiert, TTL 60 s) ──────────
        if not hasattr(self, "_failed_translation_cache"):
            self._failed_translation_cache = TTLCache(maxsize=200, ttl=60)
        if self._failed_translation_cache.get(original_text) is not None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "translate",
                    "Übersetzung von '%s…' kürzlich fehlgeschlagen – überspringe API.",
                    original_text[:30],
                )
            return None

        # ── Positiv‑Cache und Duplikat‑Historie ───────────────────
        with self._lock:
            if original_text in self._last_translations:
                return None
            cached = self._cache_manager.get_cached_translation(original_text, target)
            if cached is not None:
                return cached

        # ── Zähler für leere / ungültige Antworten ─────────────────
        empty_or_invalid_attempts = 0
        MAX_EMPTY_RETRIES = 1
        NETWORK_BACKOFF_BASE = self._retry_delay
        CONTENT_RETRY_DELAY = 0.5

        last_exception = None
        for attempt in range(self._max_retries + 1):
            try:
                translated_text = self._call_translation_api(
                    original_text, source_lang, target
                )

                if translated_text is None:
                    raise ConnectionError("_call_translation_api returned None")

                if not translated_text or not translated_text.strip():
                    empty_or_invalid_attempts += 1
                    if empty_or_invalid_attempts > MAX_EMPTY_RETRIES:
                        log_debug(
                            "translate",
                            "Max. leere/ungültige Antworten (%d) erreicht – gebe auf.",
                            MAX_EMPTY_RETRIES,
                        )
                        self._failed_translation_cache.put(original_text, True)
                        self._record_error()
                        return None
                    time.sleep(CONTENT_RETRY_DELAY)
                    continue

                if not self._is_valid_translation(original_text, translated_text):
                    empty_or_invalid_attempts += 1
                    if empty_or_invalid_attempts > MAX_EMPTY_RETRIES:
                        log_debug(
                            "translate",
                            "Übersetzung auch nach %d Wiederholungen ungültig – gebe auf.",
                            MAX_EMPTY_RETRIES,
                        )
                        self._failed_translation_cache.put(original_text, True)
                        self._record_error()
                        return None
                    time.sleep(CONTENT_RETRY_DELAY)
                    continue

                result = TranslationResult(
                    original=original_text,
                    translated=translated_text.strip(),
                    source_lang=source_lang,
                    target_lang=target,
                )

                self._record_success()

                with self._lock:
                    self._cache_manager.cache_translation(result)
                    self._last_translations.append(original_text)

                if DEBUG_LEVEL >= 2:
                    log_debug(
                        "translate",
                        f"Übersetzung erfolgreich: {len(translated_text)} Zeichen",
                    )
                return result

            except Exception as e:
                last_exception = e
                is_network_error = False
                if isinstance(e, (ConnectionError, TimeoutError)):
                    is_network_error = True
                elif self._requests is not None:
                    req_exceptions = self._requests.exceptions
                    if isinstance(
                        e, (req_exceptions.Timeout, req_exceptions.ConnectionError)
                    ):
                        is_network_error = True

                if not is_network_error:
                    self._record_error()
                if attempt < self._max_retries:
                    delay = (
                        NETWORK_BACKOFF_BASE * (2**attempt)
                        if is_network_error
                        else CONTENT_RETRY_DELAY
                    )
                    time.sleep(delay)

        self._failed_translation_cache.put(original_text, True)
        self._record_error()
        if last_exception:
            logger.warning(
                f"Übersetzung fehlgeschlagen nach {self._max_retries + 1} Versuchen: {last_exception}"
            )
        return None

    # ------------------------------------------------------------------
    # Hilfsmethoden
    # ------------------------------------------------------------------
    def _get_prompts_for_language(self, target_lang: str) -> Dict[str, str]:
        """Liefert die Prompt‑Vorlagen passend zur Zielsprache.

        Für Deutsch werden spezielle deutsche Prompts verwendet; für alle
        anderen Sprachen das englische Standard‑Set.  Weitere Sprachen
        können durch Hinzufügen weiterer ``_prompts_XX``‑Attribute
        unterstützt werden.
        """
        if target_lang.lower() in ("de", "deu", "deutsch", "german"):
            return self._prompts_de
        return self._prompts_en

    def _safe_ollama_call(
        self,
        engine: BaseTranslationEngine,
        prompt: str,
        system_prompt: str,
        stage: str,
    ) -> Optional[str]:
        """Führt einen Ollama‑Aufruf mit Timeout und Fehlerbehandlung durch.

        Unterstützt sowohl die alte API
        (``_call_ollama_with_timeout_retry``) als auch die neue API
        (``_call_ollama_with_retry``) der Basis‑Engine.

        Args:
            engine: Die Basis‑Engine, die den Ollama‑Aufruf ausführt.
            prompt: Der formatierte Benutzer‑Prompt.
            system_prompt: Der System‑Prompt für die aktuelle Stufe.
            stage: Beschreibung der aktuellen Stufe (für Logging).

        Returns:
            Die bereinigte Antwort des Modells oder ``None`` bei Fehler.
        """
        full_prompt = f"System: {system_prompt}\n\n{prompt}"

        if DEBUG_LEVEL >= 3:
            log_debug(
                "reflection",
                "Calling Ollama for %s (len=%d)",
                stage,
                len(full_prompt),
            )

        try:
            # Alte API (OllamaTranslationEngine)
            if hasattr(engine, "_call_ollama_with_timeout_retry"):
                result = engine._call_ollama_with_timeout_retry(
                    full_prompt,
                    cancel_event=self.cancel_event,
                )
            # Neue API (OllamaSummarizer)
            elif hasattr(engine, "_call_ollama_with_retry"):
                result = engine._call_ollama_with_retry(
                    prompt=full_prompt,
                    text="",  # der gesamte Prompt steckt bereits in full_prompt
                    temperature=0.0,  # Reflexion arbeitet zuverlässig mit Temperatur 0
                    cancel_event=self.cancel_event,
                )
            else:
                logger.error(
                    "ReflectionEngine: base_engine besitzt keine gültige "
                    "Ollama‑Methode"
                )
                return None

            if result and result.strip():
                cleaned = result.strip()
                # Falls das Modell versehentlich "System:" voranstellt
                if cleaned.lower().startswith("system:"):
                    cleaned = cleaned.split("\n", 1)[-1].strip()
                return cleaned

            logger.warning("ReflectionEngine: %s returned empty response", stage)
        except Exception as exc:
            logger.error(
                "ReflectionEngine: %s API call failed: %s",
                stage,
                exc,
                exc_info=True,
            )
        return None

    def dispose(self) -> None:
        """Gibt die Ressourcen der Basis‑Engine frei.

        Die Methode ist idempotent und thread‑sicher.  Nach dem Aufruf
        ist die Instanz nicht mehr verwendbar.
        """
        with self._lock:
            if self.base_engine is not None:
                try:
                    self.base_engine.dispose()
                except Exception as exc:
                    logger.warning(
                        "ReflectionEngine: Error during base_engine.dispose(): %s",
                        exc,
                    )
                finally:
                    self.base_engine = None


class ArgosTranslateEngine(BaseCachedTranslationEngine):
    """
    Übersetzungs‑Engine mit argos‑translate (offline, OpenNMT).

    Unterstützt sowohl die neue API (source.get_translation(target))
    als auch die ältere API (target.get_translator(source)).  Bei
    fehlenden Sprachpaketen wird automatisch versucht, diese aus
    dem Internet nachzuladen.
    """

    __slots__ = (
        "_translators",
        "_package_lock",
        "_disabled",
        "_disable_reason",
        "_installed_languages_cache",
        "_installed_languages_cache_time",
        "_installed_languages_cache_ttl",
    )

    _ARGOS_LANG_MAP = {
        "zh-cn": "zh",
        "zh-tw": "zh",
        "fil": "tl",
        "ht": "ht",
    }

    # Wie lange der Cache für installierte Sprachen gültig ist (Sekunden)
    _INSTALLED_LANGUAGES_CACHE_TTL = 300

    # Maximale Installationsversuche pro Paket
    _PACKAGE_INSTALL_MAX_ATTEMPTS = 3

    # Timeout für den Download eines Pakets (Sekunden)
    _PACKAGE_DOWNLOAD_TIMEOUT = 120

    def _normalize_argos_code(self, lang_code: str) -> str:
        """Wandelt ISO‑Code in argos‑internen Code um."""
        if lang_code == "auto":
            return "auto"
        normalized = lang_code.lower().replace("_", "-")
        return self._ARGOS_LANG_MAP.get(normalized, normalized)

    def __init__(
        self,
        target_lang: str = "de",
        settings: Optional["AdvancedSettings"] = None,
        cache_manager: Optional[CacheManager] = None,
    ):
        super().__init__(
            target_lang,
            settings,
            max_retries=3,
            retry_delay_base=1.0,
            retry_delay_max=5.0,
            cache_manager=cache_manager,
            max_errors=10,
            disable_duration=60.0,
        )
        self._translators: Dict[str, Any] = {}
        self._package_lock = threading.RLock()
        self._disabled = False
        self._disable_reason = ""
        self._installed_languages_cache: Optional[List[Any]] = None
        self._installed_languages_cache_time = 0.0
        self._installed_languages_cache_ttl = self._INSTALLED_LANGUAGES_CACHE_TTL

        # ── 1. Prüfen, ob argostranslate installiert ist ──────────────
        if not importlib.util.find_spec("argostranslate"):
            self._disabled = True
            self._disable_reason = "argostranslate nicht installiert"
            logger.warning("⚠️ ArgosTranslateEngine deaktiviert: %s", self._disable_reason)
            return

        # ── 2. Versuche, argostranslate zu importieren und zu initialisieren ──
        try:
            from argostranslate import translate
            _ = translate.get_installed_languages
        except ImportError as e:
            self._disabled = True
            self._disable_reason = f"Import fehlgeschlagen: {e}"
            logger.warning("⚠️ ArgosTranslateEngine deaktiviert: %s", self._disable_reason)
            return
        except Exception as e:
            # Fängt auch Pydantic‑Inkompatibilitäten ab (z. B. pydantic-core Version)
            self._disabled = True
            self._disable_reason = f"Initialisierung fehlgeschlagen: {e}"
            logger.warning("⚠️ ArgosTranslateEngine deaktiviert: %s", self._disable_reason)
            return

        # ── 3. Zielsprache normalisieren ──────────────────────────────────
        norm_target = self._normalize_argos_code(self.default_target_lang)
        if norm_target != self.default_target_lang:
            log_debug(
                "translate",
                f"Argos: Zielcode normalisiert: {self.default_target_lang} -> {norm_target}",
            )
            self.default_target_lang = norm_target
        log_debug("translate", "ArgosTranslateEngine initialisiert (lazy)")

        # ★ OPTIMIERUNG: Asynchrones Vorabladen des Sprachpakets
        # (damit die GUI nicht blockiert und Timeouts beim ersten Übersetzungsversuch vermieden werden)
        if not self._disabled:
            def _preload_translator() -> None:
                try:
                    logger.info("⏳ Argos: Lade Übersetzungsmodell im Hintergrund vor ...")
                    self._load_translator(self.default_target_lang)
                except Exception as e:
                    logger.warning(f"Argos-Vorabladen fehlgeschlagen: {e}")

            threading.Thread(target=_preload_translator, daemon=True, name="ArgosPreload").start()

    def is_functional(self) -> bool:
        return False if self._disabled else super().is_functional()

    def set_target_language(self, target_lang: str) -> None:
        if self._disabled:
            logger.warning(
                "ArgosTranslateEngine ist deaktiviert – set_target_language ignoriert"
            )
            return

        norm_target = self._normalize_argos_code(target_lang)
        if norm_target != target_lang:
            log_debug(
                "translate",
                f"Argos: Zielcode normalisiert: {target_lang} -> {norm_target}",
            )
        if norm_target not in SUPPORTED_LANGUAGES and norm_target != "auto":
            logger.warning(f"Unbekannter Sprachcode '{norm_target}', verwende 'en'")
            norm_target = "en"
        super().set_target_language(norm_target)

        with self._lock:
            self._translators.clear()
            self._invalidate_installed_languages_cache()

    # ── Cache für installierte Sprachen ────────────────────────────
    def _get_installed_languages(self) -> List[Any]:
        """Gibt installierte Sprachen zurück, mit TTL‑Cache."""
        now = time.time()
        if (
            self._installed_languages_cache is not None
            and (now - self._installed_languages_cache_time)
            < self._installed_languages_cache_ttl
        ):
            return self._installed_languages_cache
        try:
            from argostranslate import translate

            installed = translate.get_installed_languages()
            self._installed_languages_cache = installed
            self._installed_languages_cache_time = now
            return installed
        except Exception:
            return []

    def _invalidate_installed_languages_cache(self) -> None:
        self._installed_languages_cache = None
        self._installed_languages_cache_time = 0.0

    # ── Unterbrechbarer Schlaf (für Download‑Wiederholungen) ──────────
    def _interruptible_sleep(self, seconds: float, interval: float = 0.5) -> None:
        """
        Schläft für `seconds` Sekunden, unterbricht aber bei jedem Intervall
        und prüft, ob der Engine ein Shutdown oder ein Stop‑Event signalisiert wurde.
        """
        if seconds <= 0:
            return
        # Da wir keinen globalen Stop‑Event haben, verwenden wir nur einen einfachen Sleep.
        # In einer erweiterten Version könnte man ein Event von außen übergeben.
        time.sleep(seconds)

    # ── Übersetzer laden ───────────────────────────────────────────
    def _load_translator(self, target_lang: str) -> Optional[Any]:
        """
        Lädt oder installiert den argos-Übersetzer für *target_lang*.
        Verwendet bevorzugt die neue API `source.get_translation(target)`.
        """
        if self._disabled:
            return None

        with self._package_lock:
            if target_lang in self._translators:
                return self._translators[target_lang]

            try:
                from argostranslate import package, translate

                installed_languages = self._get_installed_languages()

                # Zielsprache finden
                target_lang_obj = None
                for lang in installed_languages:
                    if lang.code == target_lang:
                        target_lang_obj = lang
                        break

                # Fehlendes Sprachpaket nachinstallieren
                if target_lang_obj is None:
                    log_debug(
                        "translate",
                        f"Argos: Sprachpaket für '{target_lang}' nicht installiert – versuche Download",
                    )
                    # ★ OPTIMIERUNG: Benutzer-sichtbarer Hinweis
                    logger.info(f"📦 Lade argos-Übersetzungsmodell für '{target_lang}' herunter (ca. 300 MB) …")

                    available_packages = package.get_available_packages()
                    # Pakete, die in die Zielsprache übersetzen
                    matching_packages = [
                        p for p in available_packages if p.to_code == target_lang
                    ]
                    if not matching_packages:
                        logger.warning(
                            "⚠️ Kein argos-Paket für Zielsprache '%s' verfügbar",
                            target_lang,
                        )
                        return None

                    # Bevorzuge Paket, das von Englisch (en) übersetzt
                    en_pkg = None
                    other_pkg = None
                    for pkg in matching_packages:
                        if pkg.from_code == "en":
                            en_pkg = pkg
                            break
                        elif other_pkg is None:
                            other_pkg = pkg
                    selected_pkg = en_pkg or other_pkg

                    logger.info("📦 Installiere argos-Paket: %s", selected_pkg)
                    success = False
                    last_exception = None

                    for attempt in range(1, self._PACKAGE_INSTALL_MAX_ATTEMPTS + 1):
                        try:
                            # Timeout-geschützter Download mit Abbruchmöglichkeit
                            dl_path = selected_pkg.download()
                            package.install_from_path(dl_path)
                            logger.info(
                                "✅ argos-Paket für %s installiert", target_lang
                            )
                            success = True
                            break
                        except Exception as e:
                            last_exception = e
                            if attempt < self._PACKAGE_INSTALL_MAX_ATTEMPTS:
                                wait = min(30, 2 ** (attempt - 1))
                                logger.warning(
                                    "⚠️ Download fehlgeschlagen (Versuch %d/%d): %s. "
                                    "Nächster Versuch in %ds",
                                    attempt,
                                    self._PACKAGE_INSTALL_MAX_ATTEMPTS,
                                    e,
                                    wait,
                                )
                                self._interruptible_sleep(wait)
                            else:
                                logger.error(
                                    "❌ Installation nach %d Versuchen fehlgeschlagen: %s",
                                    self._PACKAGE_INSTALL_MAX_ATTEMPTS,
                                    last_exception,
                                )
                    if not success:
                        return None

                    # Cache invalidieren und neu laden
                    self._invalidate_installed_languages_cache()
                    translate.load_installed_languages()
                    installed_languages = self._get_installed_languages()
                    for lang in installed_languages:
                        if lang.code == target_lang:
                            target_lang_obj = lang
                            break

                # Übersetzer finden (bevorzugt von Englisch)
                source_candidates = []
                for lang in installed_languages:
                    if lang.code == "en":
                        source_candidates.insert(0, lang)
                    else:
                        source_candidates.append(lang)

                translator = None
                used_source = None
                for source_lang_obj in source_candidates:
                    try:
                        # Neue API bevorzugen
                        translation_obj = source_lang_obj.get_translation(
                            target_lang_obj
                        )
                        if translation_obj is not None:
                            translator = translation_obj
                            used_source = source_lang_obj.code
                            break
                    except AttributeError:
                        # Alte API als Fallback
                        try:
                            translator = target_lang_obj.get_translator(source_lang_obj)
                            used_source = source_lang_obj.code
                            break
                        except AttributeError:
                            continue
                    except Exception as e:
                        log_debug(
                            "translate",
                            "Kein Übersetzer von %s nach %s: %s",
                            source_lang_obj.code,
                            target_lang,
                            e,
                        )
                        continue

                if translator:
                    self._translators[target_lang] = translator
                    log_debug(
                        "translate",
                        "Argos: Übersetzer von %s nach %s geladen",
                        used_source,
                        target_lang,
                    )
                    return translator
                else:
                    logger.warning(
                        "⚠️ argos: Kein Übersetzer von einer installierten Sprache nach '%s'",
                        target_lang,
                    )
                    return None

            except Exception as e:
                logger.warning(
                    "⚠️ Fehler beim Laden des argos-Übersetzers: %s", e, exc_info=True
                )
                return None

    def _load_specific_translator(self, from_lang: str, to_lang: str) -> Optional[Any]:
        """Lädt einen Übersetzer von einer bestimmten Quellsprache."""
        if self._disabled:
            return None

        norm_from = self._normalize_argos_code(from_lang)
        norm_to = self._normalize_argos_code(to_lang)

        # Cache‑Schlüssel
        key = f"{norm_from}_{norm_to}"
        if key in self._translators:
            return self._translators[key]

        try:
            installed_languages = self._get_installed_languages()
            from_lang_obj = None
            to_lang_obj = None
            for lang in installed_languages:
                if lang.code == norm_from:
                    from_lang_obj = lang
                if lang.code == norm_to:
                    to_lang_obj = lang

            if from_lang_obj and to_lang_obj:
                # Neue API
                try:
                    translation = from_lang_obj.get_translation(to_lang_obj)
                    if translation:
                        self._translators[key] = translation
                        log_debug(
                            "translate",
                            "Spezifischer Übersetzer %s geladen (neue API)",
                            key,
                        )
                        return translation
                except AttributeError:
                    pass
                # Alte API
                try:
                    translator = from_lang_obj.get_translator(to_lang_obj)
                    if translator:
                        self._translators[key] = translator
                        log_debug(
                            "translate",
                            "Spezifischer Übersetzer %s geladen (alte API)",
                            key,
                        )
                        return translator
                except AttributeError:
                    pass
        except Exception as e:
            log_debug("translate", "Fehler in _load_specific_translator: %s", e)
        return None

    def _call_translation_api(
        self, text: str, source_lang: str, target_lang: str
    ) -> Optional[str]:
        """Führt die Übersetzung mit argos durch."""
        if self._disabled:
            return None

        norm_source = self._normalize_argos_code(source_lang)
        norm_target = self._normalize_argos_code(target_lang)

        translator = self._translators.get(norm_target)
        if translator is None:
            translator = self._load_translator(norm_target)
            if translator is None:
                self._record_error()
                return None

        effective_translator = translator
        if norm_source != "auto" and norm_source != "en":
            specific = self._load_specific_translator(norm_source, norm_target)
            if specific:
                effective_translator = specific

        try:
            # Beide API‑Varianten unterstützen
            if hasattr(effective_translator, "translate"):
                translated = effective_translator.translate(text)
            elif callable(effective_translator):
                translated = effective_translator(text)
            else:
                raise RuntimeError("Unbekanntes Übersetzer-Objekt")
            return translated.strip() if translated else None
        except Exception as e:
            log_debug("translate", "Argos translation error: %s", e)
            raise

    def dispose(self) -> None:
        super().dispose()
        with self._lock:
            self._translators.clear()
            self._invalidate_installed_languages_cache()


TranscriptionCallback = Callable[[TranscriptionResult], None]
TranslationCallback = Callable[[TranslationResult], None]
InfoCallback = Callable[[str], None]
ErrorCallback = Callable[[str], None]
FinishedCallback = Callable[[], None]


class DummyTranslationEngine(BaseTranslationEngine):
    """
    Platzhalter‑Engine, wenn keine echte Übersetzungs‑Engine verfügbar ist.
    """

    def __init__(
        self,
        target_lang: str = "de",
        settings: Optional["AdvancedSettings"] = None,
        cache_manager: Optional[CacheManager] = None,
    ):
        self.target_lang = target_lang
        self.settings = settings or AdvancedSettings()
        self._cache_manager = cache_manager
        self._lock = threading.RLock()
        self._last_translations: Deque[str] = deque(maxlen=5)
        self.last_detected_language = "auto"

    def translate_text(
        self, text: str, source_lang: str = "auto"
    ) -> Optional[TranslationResult]:
        """Gibt einen Platzhalter zurück."""
        return TranslationResult(
            original=text,
            translated="[Übersetzung nicht verfügbar]",
            source_lang=source_lang,
            target_lang=self.target_lang,
        )

    def set_target_language(self, target_lang: str) -> None:
        """Setzt die Zielsprache (wird nur gespeichert)."""
        self.target_lang = target_lang

    def dispose(self) -> None:
        """Nichts zu tun."""


class AudioEnhancer:
    MAX_COMPARE_LEN: int = 150
    MAX_LEN_RATIO_DEVIATION: float = 0.5
    PUNCTUATION = str.maketrans("", "", ".,!?;:")
    MIN_RMS_FOR_ENHANCEMENT: float = 0.005
    TARGET_RMS_FOR_GAIN: float = 0.02
    MAX_GAIN_FACTOR: float = 1.5
    HIGH_RMS_THRESHOLD: float = 0.3
    HIGH_RMS_TARGET: float = 0.3
    CLIPPING_LIMIT: float = 0.99
    EPSILON: float = 1e-6
    NOISEREDUCE_CONFIDENCE_THRESHOLD: float = 0.3
    NOISEREDUCE_RMS_THRESHOLD: float = 0.003
    NOISEREDUCE_MIN_LENGTH: int = 32000
    HIGHPASS_CUTOFF_FREQ: int = 80

    __slots__ = (
        "config",
        "settings",
        "_np",
        "_scipy_signal",
        "_noisereduce_available",
        "_noisereduce",
        "_fuzz",
        "_difflib",
        "_debug",
    )

    def __init__(self, config: Config, settings: "AdvancedSettings") -> None:
        self.config = config
        self.settings = settings
        self._debug = logger.isEnabledFor(logging.DEBUG)
        self._np = None
        self._scipy_signal = None
        self._noisereduce_available = False
        self._noisereduce = None
        self._fuzz = None
        self._difflib = None
        self._load_modules()

    def enhance_audio(
        self,
        audio_data: bytes,
        last_confidence: float,
        noisereduce_counter: int,
        is_start: bool = False,
    ) -> bytes:
        """
        Optimierte Audiovorverarbeitung mit adaptiver Rauschunterdrückung,
        dynamischer Verstärkung und optionalem Hochpassfilter.
        """
        # -- 1. Schneller Rückweg, wenn Enhancement nicht aktiviert ist ----
        if not self.config.AUDIO_ENHANCEMENT_ENABLED:
            if self._debug and DEBUG_LEVEL >= 4:
                log_debug("enhance", "AUDIO_ENHANCEMENT_ENABLED=False – überspringe")
            return audio_data

        # -- 2. Sicherstellen, dass numpy verfügbar ist --------------------
        if self._np is None:
            self._load_modules()
            if self._np is None:
                if self._debug:
                    log_debug(
                        "enhance", "numpy nicht verfügbar – Enhancement deaktiviert"
                    )
                return audio_data

        # -- 3. Mindestlänge prüfen -----------------------------------------
        if len(audio_data) < Config.AUDIO_ENHANCEMENT_MIN_LENGTH:
            log_debug(
                "enhance", "Audio zu kurz (%d Bytes) – überspringe", len(audio_data)
            )
            return audio_data

        # -- 4. In float32 konvertieren und Grundzustand prüfen -------------
        try:
            audio_np = self._bytes_to_float32(audio_data)
            original_length = len(audio_data)

            # Früherkennung von defekten Daten
            if self._np.isnan(audio_np).any() or self._np.isinf(audio_np).any():
                log_debug("enhance", "NaN/Inf im Eingangssignal – gebe Original zurück")
                return audio_data

            # -- 5. RMS bestimmen (minimaler positiver Wert) -----------------
            rms = float(self._np.sqrt(self._np.mean(audio_np**2)))
            if rms < self.EPSILON:
                rms = self.EPSILON

            if DEBUG_LEVEL >= 4:
                log_debug(
                    "enhance",
                    "Eingabe: len=%d, rms=%.6f, conf=%.2f, start=%s",
                    len(audio_data),
                    rms,
                    last_confidence,
                    is_start,
                )

            # -- 6. Start‑Boost für extrem leise Anfänge --------------------
            if is_start and rms < self.START_BOOST_RMS_THRESHOLD:
                boost = min(self.START_BOOST_GAIN, self.TARGET_RMS_FOR_GAIN / rms)
                audio_np *= boost
                audio_np = self._np.clip(
                    audio_np, -self.CLIPPING_LIMIT, self.CLIPPING_LIMIT
                )
                audio_np -= self._np.mean(audio_np)
                if DEBUG_LEVEL >= 3:
                    log_debug("enhance", "Start‑Boost angewendet: Faktor %.2f", boost)

            # -- 7. Dynamische Verstärkung (nur bei leisen Signalen) ---------
            if rms < self.MIN_RMS_FOR_ENHANCEMENT:
                desired_gain = self.TARGET_RMS_FOR_GAIN / rms
                gain = min(self.MAX_GAIN_FACTOR, desired_gain)
            else:
                gain = 1.0
            audio_np *= gain
            audio_np = self._np.clip(
                audio_np, -self.CLIPPING_LIMIT, self.CLIPPING_LIMIT
            )
            audio_np -= self._np.mean(audio_np)

            if DEBUG_LEVEL >= 4:
                new_rms = float(self._np.sqrt(self._np.mean(audio_np**2)))
                log_debug(
                    "enhance",
                    "Gain angewendet: Faktor %.2f, rms %.6f → %.6f",
                    gain,
                    rms,
                    new_rms,
                )

            # -- 8. Rauschunterdrückung (optional) --------------------------
            if self._should_apply_noisereduce(
                last_confidence, rms, len(audio_np), noisereduce_counter
            ):
                audio_np = self._apply_noisereduce(audio_np)

            # -- 9. Hochpassfilter (konfigurierbar, Standard aktiv) ---------
            #     Das Attribut enable_highpass kann in den AdvancedSettings
            #     fehlen – wir verwenden dann den sicheren Default True.
            enable_hp = getattr(self.settings, "enable_highpass", None)
            if enable_hp is None:
                enable_hp = True  # Standardwert, weil die Einstellung fehlt
                if self._debug:
                    log_debug(
                        "enhance",
                        "enable_highpass nicht in Settings gefunden – verwende Standard (aktiv)",
                    )
            if enable_hp:
                audio_np = self._apply_highpass(audio_np, enabled=True)
            elif self._debug and DEBUG_LEVEL >= 4:
                log_debug(
                    "enhance", "Hochpassfilter deaktiviert (enable_highpass=False)"
                )

            # -- 10. Rückkonvertierung zu Bytes (exakt gleiche Länge) -------
            enhanced = self._float32_to_bytes(audio_np, original_length=original_length)

            if DEBUG_LEVEL >= 3:
                final_rms = float(self._np.sqrt(self._np.mean(audio_np**2)))
                log_debug(
                    "enhance",
                    "Ausgabe: len=%d, rms=%.6f (war %.6f)",
                    len(enhanced),
                    final_rms,
                    rms,
                )

            return enhanced

        except Exception as exc:
            logger.warning(
                "Audio‑Enhancement fehlgeschlagen: %s – Originaldaten werden verwendet.",
                exc,
                exc_info=DEBUG_LEVEL >= 3,
            )
            return audio_data

    def _apply_start_boost(self, audio_np: Any, rms: float) -> Any:
        """
        Verstärkt sehr leise Signale am Anfang eines Streams prozentual
        stärker, damit die Spracherkennung auch leise Einsprengsel
        (z. B. ein chinesisches Wort vor einem deutschen Satz) erfassen
        kann.
        """
        if rms <= 0:
            return audio_np

        boost_factor = min(self.START_BOOST_GAIN, self.TARGET_RMS / rms)
        boosted = audio_np * boost_factor
        if DEBUG_LEVEL >= 3:
            log_debug(
                "enhance",
                "Start‑Boost applied: factor=%.2f (rms %.6f → target %.3f)",
                boost_factor,
                rms,
                self.TARGET_RMS,
            )
        return boosted

    START_BOOST_RMS_THRESHOLD: float = 0.05
    START_BOOST_GAIN: float = 3.0

    def is_duplicate(
        self,
        current_text: str,
        last_text: str,
        recent_texts: Deque[str],
        confidence: float = None,
        last_confidence: float = 0.0,
    ) -> bool:
        """
        Prüft, ob der aktuelle Text ein Duplikat eines kürzlich transkribierten Textes ist.
        """
        if not self.settings.enable_duplicate_check:
            return False

        current_text = current_text.strip()
        if not current_text or len(current_text) < self.config.MIN_TEXT_LENGTH:
            return True
        if current_text == last_text:
            return True
        curr_norm = self._normalize_text(current_text)
        last_norm = self._normalize_text(last_text)
        if curr_norm == last_norm:
            return True
        curr_short = curr_norm[: self.MAX_COMPARE_LEN]
        compare_texts = [last_norm] + list(recent_texts)
        similarity_threshold = self.settings.duplicate_similarity_threshold

        for prev_norm in compare_texts:
            if not prev_norm:
                continue
            prev_short = prev_norm[: self.MAX_COMPARE_LEN]
            len_curr = len(curr_short)
            len_prev = len(prev_short)
            if len_curr > 0 and len_prev > 0:
                ratio = max(len_curr, len_prev) / min(len_curr, len_prev)
                if ratio > 1.0 + self.MAX_LEN_RATIO_DEVIATION:
                    continue
            sim = self._similarity(curr_short, prev_short)
            if sim > similarity_threshold:
                if self._debug:
                    log_debug(
                        "duplicate",
                        f"{sim:.2%} match: '{curr_short[:30]}' ≈ '{prev_short[:30]}'",
                    )
                return True

        words = current_text.lower().split()
        if len(words) > 3:
            unique_ratio = len(set(words)) / len(words)
            if unique_ratio < self.config.MIN_UNIQUE_WORDS_RATIO:
                if self._debug:
                    log_debug(
                        "duplicate",
                        f"Geringe Wortvielfalt: {unique_ratio:.2%} < {self.config.MIN_UNIQUE_WORDS_RATIO:.2%}",
                    )
                return True
        return False

    def _load_modules(self) -> None:
        if NUMPY_AVAILABLE:
            self._np = FastLazyLoader.load("numpy")
        if SCIPY_AVAILABLE:
            self._scipy_signal = FastLazyLoader.load("scipy.signal")
        try:
            import noisereduce as nr

            self._noisereduce_available = True
            self._noisereduce = nr
        except ImportError:
            self._noisereduce_available = False
        try:
            from rapidfuzz import fuzz

            self._fuzz = fuzz
        except ImportError:
            import difflib

            self._difflib = difflib

    def _bytes_to_float32(self, audio_data: bytes):
        np = self._np
        return np.frombuffer(audio_data, dtype=np.int16).astype(np.float32) / 32768.0

    def _float32_to_bytes(self, audio_np, original_length: int) -> bytes:
        np = self._np
        audio_np = np.clip(audio_np, -self.CLIPPING_LIMIT, self.CLIPPING_LIMIT)
        enhanced = (audio_np * 32767).astype(np.int16).tobytes()
        return enhanced if len(enhanced) == original_length else audio_np.tobytes()

    def _normalize_text(self, text: str) -> str:
        return text.translate(self.PUNCTUATION).strip().lower()

    def _similarity(self, a: str, b: str) -> float:
        if self._fuzz is not None:
            return self._fuzz.ratio(a, b) / 100.0
        if self._difflib is not None:
            return self._difflib.SequenceMatcher(None, a, b).ratio()
        return 0.0

    def _apply_gain(self, audio_np, rms: Optional[float] = None):
        np = self._np
        if rms is None:
            rms = float(np.sqrt(np.mean(audio_np**2)))
        gain = 1.0
        if rms < self.EPSILON:
            gain = self.MAX_GAIN_FACTOR
        elif rms < self.MIN_RMS_FOR_ENHANCEMENT:
            gain = min(
                self.MAX_GAIN_FACTOR, self.TARGET_RMS_FOR_GAIN / max(rms, self.EPSILON)
            )
        elif rms > self.HIGH_RMS_THRESHOLD:
            gain = self.HIGH_RMS_TARGET / rms
        audio_np *= gain
        audio_np -= np.mean(audio_np)
        return audio_np

    def _should_apply_noisereduce(
        self, last_confidence: float, rms: float, length: int, counter: int
    ) -> bool:
        if not self.settings.enable_noise_reduction:
            return False
        if not self._noisereduce_available:
            return False
        if self._noisereduce is None:
            return False
        if last_confidence > self.NOISEREDUCE_CONFIDENCE_THRESHOLD:
            return False
        if rms > self.NOISEREDUCE_RMS_THRESHOLD:
            return False
        if length < self.NOISEREDUCE_MIN_LENGTH:
            return False
        return counter % 10 == 0

    def _apply_noisereduce(self, audio_np):
        try:
            if self._noisereduce is None:
                return audio_np
            audio_np = self._noisereduce.reduce_noise(
                y=audio_np, sr=self.config.SAMPLE_RATE, prop_decrease=0.6
            )
            if self._debug:
                logger.debug("🔇 noisereduce angewendet")
        except Exception as e:
            logger.warning(f"⚠️ noisereduce fehlgeschlagen: {e}")
        return audio_np

    def _apply_highpass(self, audio_np, enabled: bool = True):
        """
        Wendet einen Butterworth-Hochpassfilter auf das Audiosignal an.

        Parameter
        ----------
        audio_np : numpy.ndarray
            1D‑Array mit float32‑Werten im Bereich [-1, 1].
        enabled : bool
            Wenn ``False``, wird das Signal unverändert zurückgegeben.
            Dadurch kann der Aufrufer die Filterung z. B. über eine
            Benutzereinstellung steuern.

        Rückgabe
        -------
        numpy.ndarray
            Gefiltertes Signal oder das Original, falls die Filterung
            nicht durchgeführt werden kann oder deaktiviert ist.

        Hinweise
        --------
        * Die Grenzfrequenz wird über ``HIGHPASS_CUTOFF_FREQ`` (80 Hz)
          und die Samplerate des ``Config``‑Objekts bestimmt.
        * Das Filter ist ein Butterworth‑Filter 2. Ordnung.
        * Es wird ``scipy.signal.filtfilt`` verwendet, um Phasenverzerrungen
          zu vermeiden.
        * Arrays mit weniger als 100 Samples werden nicht gefiltert.
        * Wenn ``scipy`` oder ``numpy`` nicht geladen werden können,
          wird das Original zurückgegeben.
        """
        # --- 1. Schneller Rückweg, wenn deaktiviert oder Module fehlen ---
        if not enabled:
            if self._debug and DEBUG_LEVEL >= 4:
                log_debug("audio", "Hochpassfilter deaktiviert (enabled=False)")
            return audio_np

        if self._scipy_signal is None:
            if self._debug:
                log_debug("audio", "Hochpassfilter nicht verfügbar (scipy fehlt)")
            return audio_np

        if self._np is None:
            if self._debug:
                log_debug("audio", "Hochpassfilter nicht verfügbar (numpy fehlt)")
            return audio_np

        # --- 2. Mindestlänge prüfen ---------------------------------------
        MIN_SAMPLES_FOR_FILTER = 100
        if len(audio_np) < MIN_SAMPLES_FOR_FILTER:
            if self._debug and DEBUG_LEVEL >= 4:
                log_debug(
                    "audio",
                    "Signal zu kurz für Hochpass (%d < %d) – überspringe",
                    len(audio_np),
                    MIN_SAMPLES_FOR_FILTER,
                )
            return audio_np

        # --- 3. Parameter berechnen und validieren ------------------------
        try:
            nyquist = self.config.SAMPLE_RATE / 2.0
            cutoff_normalized = self.HIGHPASS_CUTOFF_FREQ / nyquist

            if not (0.0 < cutoff_normalized < 1.0):
                if self._debug and DEBUG_LEVEL >= 3:
                    log_debug(
                        "audio",
                        "Hochpass: normalisierte Grenzfrequenz %.4f außerhalb (0,1) – überspringe",
                        cutoff_normalized,
                    )
                return audio_np

            # --- 4. NaN / Inf frühzeitig erkennen -------------------------
            if self._np.isnan(audio_np).any() or self._np.isinf(audio_np).any():
                if self._debug:
                    log_debug(
                        "audio", "Hochpass: NaN/Inf im Signal erkannt – überspringe"
                    )
                return audio_np

            # --- 5. Filterkoeffizienten berechnen -------------------------
            b, a = self._scipy_signal.butter(2, cutoff_normalized, btype="high")

            # --- 6. Filter anwenden ----------------------------------------
            filtered = self._scipy_signal.filtfilt(b, a, audio_np)

            # --- 7. Ergebnis validieren -----------------------------------
            if self._np.isnan(filtered).any() or self._np.isinf(filtered).any():
                if self._debug:
                    log_debug(
                        "audio", "Hochpass: Ergebnis enthält NaN/Inf – Original zurück"
                    )
                return audio_np

            if self._debug and DEBUG_LEVEL >= 4:
                log_debug(
                    "audio",
                    "Hochpassfilter angewendet (fc=%.1f Hz, Ordnung=2)",
                    self.HIGHPASS_CUTOFF_FREQ,
                )

            return filtered

        except Exception as exc:
            if self._debug:
                log_debug(
                    "audio",
                    "Hochpassfilter fehlgeschlagen: %s – verwende ungefiltertes Signal",
                    exc,
                )
            return audio_np


class TranscriptionEngine:
    """
    Optimierte Transkriptions-Engine mit automatischer Hardware-Erkennung,
    intelligenter Fallback-Strategie und maximaler Kompatibilität für:
    """

