    RESPONSE_CACHE_MAXSIZE = 50  # Max. Anzahl zwischengespeicherter Antworten
    MODEL_FETCH_TTL = 120.0  # 2 Minuten
    MAX_CHUNKS = 200  # Maximale Anzahl von Chunks, um Überlastung zu vermeiden
