    def __init__(self, parent: tk.Widget, text: str, gui_ref: Any) -> None:
        """
        Initialisiert den SummarizeDialog vollständig und thread‑sicher.

        Erweiterungen gegenüber der Basisversion:
        - Detaillierte Debug‑Ausgaben für jede Initialisierungsphase
        - Robuste Fehlerbehandlung mit Fallbacks
        - Optimierte Cache‑ und Lock‑Strukturen
        - Vorbereitung für Video‑spezifische Zusammenfassungen
        - Lazy Loading für teure Operationen (Modell‑Liste, NLTK)
        - Periodischer Backup‑Mechanismus für ungespeicherte Zusammenfassungen
        - Drag‑&‑Drop für Transkriptionsdateien
        - Asynchroner NLTK‑Download (verhindert GUI‑Blockade)
        - Korrekte TTL-Konstante für Antwort-Cache

        Args:
            parent: Das übergeordnete Tkinter‑Widget (normalerweise das Hauptfenster).
            text: Der zu analysierende Text (Transkription) oder leerer String.
            gui_ref: Referenz auf die Haupt‑GUI (für Zugriff auf Einstellungen und Event‑Bus).
        """
        # ──────────────────────────────────────────────────────────────────
        # 1. Debug‑Initialisierung
        # ──────────────────────────────────────────────────────────────────
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS
        if _debug:
            log_debug("summarize", "SummarizeDialog.__init__: START")

        # ──────────────────────────────────────────────────────────────────
        # 2. Grundlegende Attribute
        # ──────────────────────────────────────────────────────────────────
        self.text = text
        self.gui = gui_ref
        self.stream_title = self._extract_stream_title()
        self._request_cancel = threading.Event()
        if _debug:
            log_debug(
                "summarize",
                f"  Textlänge: {len(text)} Zeichen, Stream-Titel: {self.stream_title[:50] if self.stream_title else 'keiner'}",
            )

        # ──────────────────────────────────────────────────────────────────
        # 3. OllamaSummarizer‑Klasse ermitteln
        # ──────────────────────────────────────────────────────────────────
        self._ollama_class = globals().get("OllamaSummarizer")
        if self._ollama_class is None and _debug:
            log_debug("summarize", "  Warnung: OllamaSummarizer-Klasse nicht gefunden")

        # ──────────────────────────────────────────────────────────────────
        # 4. Einstellungen aus AdvancedSettings lesen
        # ──────────────────────────────────────────────────────────────────
        adv = gui_ref.advanced_settings
        self.model = getattr(adv, "summarize_model", "llama3.1:8b")
        self.temperature = getattr(adv, "summarize_temperature", 0.1)
        self.strategy = getattr(adv, "summary_strategy", "Schnell (parallel)")
        self.language = getattr(adv, "summary_language", "Deutsch")
        self.style = getattr(adv, "summary_style", "Kompakt (3‑5 Sätze)")
        self.use_title_context = getattr(adv, "summary_use_title", False)
        self.max_chunk_tokens = getattr(adv, "summary_max_chunk_tokens", 2000)
        self.use_structured_output = getattr(adv, "summary_structured", False)
        self._user_edited_prompt = False
        self._retry_attempt = 0
        if _debug:
            log_debug(
                "summarize",
                f"  Einstellungen geladen: Modell={self.model}, Sprache={self.language}, Stil={self.style}",
            )

        # ──────────────────────────────────────────────────────────────────
        # 5. Profilverwaltung
        # ──────────────────────────────────────────────────────────────────
        self._profiles: Dict[str, Dict[str, Any]] = {}
        self._load_profiles()
        if _debug:
            log_debug("summarize", f"  {len(self._profiles)} Profil(e) geladen")

        # ──────────────────────────────────────────────────────────────────
        # 6. Thread‑Sicherheit & Zustand
        # ──────────────────────────────────────────────────────────────────
        self._state_lock = threading.RLock()
        self._summary_state: Dict[str, Any] = {
            "full_summary": "",
            "parts": [],
        }
        self._destroyed = False
        self._chunk_results: List[Optional[str]] = []
        self._chunks_total = 0
        self._chunks_processed = 0
        self._chunks_lock = threading.RLock()
        self._last_progress_update = 0.0
        self._progress_update_interval = 0.5
        if _debug:
            log_debug("summarize", "  Zustandsvariablen initialisiert")

        # ──────────────────────────────────────────────────────────────────
        # 7. Antwort‑Cache (LRU, mit TTL)
        # ──────────────────────────────────────────────────────────────────
        self.CACHE_TTL = 3600
        self._response_cache = self._build_lru_cache(maxsize=self.RESPONSE_CACHE_MAXSIZE)
        self._cache_lock = threading.RLock()
        if _debug:
            log_debug(
                "summarize",
                f"  Antwort‑Cache (LRU) mit max. {self.RESPONSE_CACHE_MAXSIZE} Einträgen, TTL={self.CACHE_TTL}s",
            )

        # ──────────────────────────────────────────────────────────────────
        # 8. Token‑Cache (LRU)
        # ──────────────────────────────────────────────────────────────────
        self._token_cache = self._build_lru_cache(500)
        if _debug:
            log_debug("summarize", "  Token‑Cache (LRU) mit 500 Einträgen")

        # ──────────────────────────────────────────────────────────────────
        # 9. tiktoken (optional)
        # ──────────────────────────────────────────────────────────────────
        self._tiktoken = None
        try:
            import tiktoken
            self._tiktoken = tiktoken
            if _debug:
                log_debug("summarize", "  tiktoken erfolgreich importiert")
        except ImportError:
            if _debug:
                log_debug("summarize", "  tiktoken nicht verfügbar – verwende Heuristik")

        # ──────────────────────────────────────────────────────────────────
        # 10. Modell‑Kontext‑Limit (lazy)
        # ──────────────────────────────────────────────────────────────────
        self._model_context_limit: Optional[int] = None

        # ──────────────────────────────────────────────────────────────────
        # 11. Backup‑Mechanismus
        # ──────────────────────────────────────────────────────────────────
        self._backup_file = os.path.join(tempfile.gettempdir(), "dragon_summary_backup.txt")
        self._backup_timer: Optional[str] = None
        if _debug:
            log_debug("summarize", f"  Backup‑Datei: {self._backup_file}")

        # ──────────────────────────────────────────────────────────────────
        # 12. Benutzerdefinierte Vorlagen
        # ──────────────────────────────────────────────────────────────────
        self._user_templates: Dict[str, Dict[str, Any]] = {}
        self._load_user_templates()
        self._build_template_list()
        if _debug:
            log_debug("summarize", f"  {len(self._user_templates)} benutzerdefinierte Vorlagen geladen")

        # ──────────────────────────────────────────────────────────────────
        # 13. Blacklist‑Patterns
        # ──────────────────────────────────────────────────────────────────
        self._blacklist_patterns: List[re.Pattern] = []
        self._prepare_blacklist_patterns()
        if _debug:
            log_debug("summarize", f"  {len(self._blacklist_patterns)} Blacklist‑Patterns vorbereitet")

        # ──────────────────────────────────────────────────────────────────
        # 14. NLTK (asynchroner Download)
        # ──────────────────────────────────────────────────────────────────
        self._nltk_available = False
        self._nltk_initialized = False
        try:
            import nltk
            self._nltk = nltk
            self._nltk_available = True

            def _download_nltk():
                try:
                    self._nltk.data.find("tokenizers/punkt_tab")
                except LookupError:
                    if _debug:
                        log_debug("summarize", "  NLTK punkt_tab nicht gefunden – starte Hintergrund‑Download")
                    self._nltk.download("punkt_tab", quiet=True)
                self._nltk_initialized = True
                if _debug:
                    log_debug("summarize", "  NLTK punkt_tab bereit")

            threading.Thread(target=_download_nltk, daemon=True, name="NLTKDownloader").start()
            if _debug:
                log_debug("summarize", "  NLTK asynchroner Download gestartet")
        except ImportError:
            if _debug:
                log_debug("summarize", "  NLTK nicht verfügbar – verwende reguläre Ausdrücke für Satzteilung")

        # ──────────────────────────────────────────────────────────────────
        # 15. Zusammenfassungs‑Verlauf (persistent)
        # ──────────────────────────────────────────────────────────────────
        self._history: List[Dict[str, Any]] = []
        self._history_file = PlatformUtils.get_platform_config_dir() / "summarize_history.json"
        self._load_history()
        if _debug:
            log_debug("summarize", f"  {len(self._history)} Historie‑Einträge geladen")

        # ──────────────────────────────────────────────────────────────────
        # 16. Modell‑Liste (vom Ollama‑Server)
        # ──────────────────────────────────────────────────────────────────
        self._available_models: List[str] = []
        self._model_fetch_in_progress = False
        self._model_fetch_timestamp = 0.0

        # ──────────────────────────────────────────────────────────────────
        # 17. Ollama‑Instanz und Nutzungszähler
        # ──────────────────────────────────────────────────────────────────
        self._ollama_instance = None
        self._ollama_usage_lock = threading.RLock()
        self._ollama_usage_count = 0
        self._ollama_available = self._ollama_class is not None
        if _debug:
            log_debug("summarize", f"  OllamaSummarizer verfügbar: {self._ollama_available}")

        # ──────────────────────────────────────────────────────────────────
        # 18. GUI aufbauen (BaseDialog)
        # ──────────────────────────────────────────────────────────────────
        if _debug:
            log_debug("summarize", "  Rufe BaseDialog.__init__ auf...")
        super().__init__(
            parent,
            "Zusammenfassung mit Ollama",
            width=1100,
            height=740,
            modal=True,
            resizable=True,
        )
        if _debug:
            log_debug("summarize", "  BaseDialog.__init__ abgeschlossen")

        # ──────────────────────────────────────────────────────────────────
        # 19. Tastenkürzel und Backup‑Wiederherstellung
        # ──────────────────────────────────────────────────────────────────
        self._bind_shortcuts()
        self._check_backup()
        if _debug:
            log_debug("summarize", "  Tastenkürzel gebunden, Backup geprüft")

        # ──────────────────────────────────────────────────────────────────
        # 20. Debounce‑ID für Token‑Update und Prompt‑Reset
        # ──────────────────────────────────────────────────────────────────
        self._token_debounce_id: Optional[str] = None
        self._reset_to_default_prompt()
        if _debug:
            log_debug("summarize", "  Standard‑Prompt zurückgesetzt")

        # ──────────────────────────────────────────────────────────────────
        # 21. Drag‑&‑Drop für Transkriptionsdateien
        # ──────────────────────────────────────────────────────────────────
        self._dnd_available = False
        try:
            if importlib.util.find_spec("tkinterdnd2") is not None:
                import tkinterdnd2  # noqa: F401
                self.dialog.drop_target_register("DND_Files")
                self.dialog.dnd_bind("<<Drop>>", self._on_drop)
                self._dnd_available = True
                if _debug:
                    log_debug("summarize", "  Drag&Drop aktiviert (tkinterdnd2)")
            else:
                raise ImportError("tkinterdnd2 not found")
        except ImportError:
            if _debug:
                log_debug("summarize", "  tkinterdnd2 nicht installiert – Drag&Drop deaktiviert")
        except Exception as e:
            if _debug:
                log_debug("summarize", f"  Drag&Drop Konfiguration fehlgeschlagen: {e}")

        # ──────────────────────────────────────────────────────────────────
        # 22. Periodisches Backup starten
        # ──────────────────────────────────────────────────────────────────
        self._start_periodic_backup()
        if _debug:
            log_debug("summarize", "  Periodischer Backup‑Timer gestartet")

        # ──────────────────────────────────────────────────────────────────
        # 23. Fokus auf Prompt‑Textfeld setzen
        # ──────────────────────────────────────────────────────────────────
        if hasattr(self, "prompt_text") and self.prompt_text.winfo_exists():
            self.prompt_text.focus_set()
            if _debug:
                log_debug("summarize", "  Fokus auf Prompt‑Textfeld gesetzt")

        # ──────────────────────────────────────────────────────────────────
        # 24. Verfügbare Modelle asynchron abrufen
        # ──────────────────────────────────────────────────────────────────
        self._fetch_available_models(force=False)
        if _debug:
            log_debug("summarize", "  Asynchrone Modell‑Liste angefordert")

        # ──────────────────────────────────────────────────────────────────
        # 25. UI deaktivieren, wenn OllamaSummarizer fehlt
        # ──────────────────────────────────────────────────────────────────
        if not self._ollama_available:
            if hasattr(self, "summarize_btn") and self.summarize_btn.winfo_exists():
                self.summarize_btn.config(state="disabled")
            if hasattr(self, "test_btn") and self.test_btn.winfo_exists():
                self.test_btn.config(state="disabled")
            if hasattr(self, "status_label") and self.status_label.winfo_exists():
                self.status_label.config(text="❌ OllamaSummarizer nicht verfügbar")
            if _debug:
                log_debug("summarize", "  UI deaktiviert (OllamaSummarizer fehlt)")

        # ──────────────────────────────────────────────────────────────────
        # 26. Abschließendes Debug‑Log
        # ──────────────────────────────────────────────────────────────────
        if _debug:
            log_debug("summarize", "SummarizeDialog.__init__ FINISHED")

    @staticmethod
    def _build_lru_cache(maxsize: int = 500):
        """
        Erzeugt einen thread‑sicheren LRU‑Cache mit RLock.
        Verwendet OrderedDict und Move‑to‑End‑Strategie.
        """
        from collections import OrderedDict

        class _LRU:
            def __init__(self, maxsize):
                self.maxsize = maxsize
                self._data = OrderedDict()
                self._lock = threading.RLock()

            def get(self, key):
                with self._lock:
                    if key in self._data:
                        self._data.move_to_end(key)
                        return self._data[key]
                    return None

            def put(self, key, value):
                with self._lock:
                    if key in self._data:
                        del self._data[key]
                    self._data[key] = value
                    if len(self._data) > self.maxsize:
                        self._data.popitem(last=False)

            def remove(self, key):
                with self._lock:
                    if key in self._data:
                        del self._data[key]

            def clear(self):
                with self._lock:
                    self._data.clear()

            def __contains__(self, key):
                with self._lock:
                    return key in self._data

        return _LRU(maxsize)

    @staticmethod
    def _get_ollama_class():
        return globals().get("OllamaSummarizer")

    def _is_ollama_available(self) -> bool:
        cls = self._get_ollama_class()
        return cls is not None

    def _extract_stream_title(self) -> str:
        info = getattr(self.gui, "current_stream_info", None)
        return info.title if info and info.title else ""

    def _prepare_blacklist_patterns(self) -> None:
        blacklist = getattr(self.gui.advanced_settings, "blacklist", [])
        mode = getattr(self.gui.advanced_settings, "blacklist_mode", "word")
        for phrase in blacklist:
            if not phrase:
                continue
            try:
                if mode == "word":
                    pat = re.compile(r"\b" + re.escape(phrase) + r"\b", re.IGNORECASE)
                else:
                    pat = re.compile(re.escape(phrase), re.IGNORECASE)
                self._blacklist_patterns.append(pat)
            except re.error as e:
                log_debug("summarize", f"Ungültiges Blacklist-Muster '{phrase}': {e}")

    def _apply_blacklist(self, text: str) -> str:
        for pat in self._blacklist_patterns:
            text = pat.sub("", text)
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

    def _estimate_tokens(self, t: str) -> int:
        """
        Schätzt die Token‑Anzahl für den Text *t*.
        Verwendet den einmalig importierten tiktoken‑Cache.
        """
        if not isinstance(t, str):
            try:
                t = str(t)
            except Exception:
                return 1
        if not t:
            return 1

        cache = getattr(self, "_token_cache", None)
        cache_key = f"{self.model}||{hashlib.sha256(t.encode('utf-8', errors='ignore')).hexdigest()[:16]}"
        if cache is not None:
            cached = cache.get(cache_key)
            if cached is not None:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "summarize", "_estimate_tokens: Cache‑HIT → %d Tokens", cached
                    )
                return cached

        tokens = None
        if self._tiktoken is not None:
            for enc_name in ("o200k_base", "cl100k_base", "p50k_base", "r50k_base"):
                try:
                    enc = self._tiktoken.get_encoding(enc_name)
                    tokens = len(enc.encode(t))
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "summarize",
                            "_estimate_tokens: tiktoken '%s' → %d Tokens",
                            enc_name,
                            tokens,
                        )
                    break
                except Exception:
                    continue

        if tokens is None:
            tokens = max(1, len(t) // 3)
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize", "_estimate_tokens: Heuristik → %d Tokens", tokens
                )

        if cache is not None:
            try:
                cache.put(cache_key, tokens)
            except Exception:
                pass

        return tokens

    def _get_model_context_limit(self) -> int:
        """
        Ermittelt das Kontext‑Token‑Limit des aktuellen Ollama‑Modells.
        """
        if self._model_context_limit is not None:
            return self._model_context_limit

        FALLBACK_LIMITS: Dict[str, int] = {
            "llama3.1:8b": 128000,
            "qwen2.5:7b": 128000,
            "glm4:9b": 128000,
            "llama3.1:70b": 128000,
            "llama3.1:405b": 128000,
            "qwen2.5:14b": 128000,
            "qwen2.5:32b": 128000,
            "deepseek-r1:7b": 128000,
            "deepseek-r1:14b": 128000,
            "phi4:14b": 128000,
            "mistral-nemo:12b": 128000,
            "gemma3:12b": 8192,
            "gemma3:27b": 8192,
            "llama3:8b": 8192,
            "llama3:70b": 8192,
            "mistral": 8192,
            "codellama": 16384,
            "tinyllama": 2048,
            "orca-mini": 2048,
        }

        fallback = FALLBACK_LIMITS.get(self.model, 4096)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "summarize",
                "_get_model_context_limit: Verwende Fallback‑Limit %d für Modell '%s'.",
                fallback,
                self.model,
            )

        self._model_context_limit = fallback
        return fallback

    def _truncate_text_to_fit(
        self,
        text: str,
        max_tokens: int,
        *,
        add_notice: bool = True,
    ) -> str:
        """
        Kürzt *text* so, dass er zusammen mit dem Prompt ins Kontextfenster passt.
        """
        if not isinstance(text, str):
            try:
                text = str(text)
            except Exception:
                return ""

        if max_tokens <= 0:
            return text

        current_tokens = self._estimate_tokens(text)
        if current_tokens <= max_tokens:
            return text

        if DEBUG_LEVEL >= 3:
            log_debug(
                "summarize",
                "_truncate_text_to_fit: Kürze Text von %d auf max. %d Tokens",
                current_tokens,
                max_tokens,
            )

        ratio = max_tokens / current_tokens
        approx_len = int(len(text) * ratio)

        trunc_pos = approx_len
        while trunc_pos > 0 and trunc_pos < len(text):
            if text[trunc_pos] in ".!?。！？":
                if trunc_pos + 1 >= len(text) or text[trunc_pos + 1] in " \n":
                    break
            trunc_pos -= 1

        if trunc_pos == 0:
            trunc_pos = approx_len

        truncated = text[: trunc_pos + 1].strip()

        original_len = len(text)
        if original_len > 0 and len(truncated) < original_len * 0.1:
            logger.warning(
                "_truncate_text_to_fit: Text wurde auf %d%% der Originallänge gekürzt.",
                int(len(truncated) / original_len * 100),
            )

        if add_notice:
            truncated += (
                "\n\n[Text wurde automatisch gekürzt, um das Kontextlimit einzuhalten.]"
            )

        return truncated

    def _split_sentences(self, text: str) -> List[str]:
        """
        Zerlegt einen Text in eine Liste von Sätzen.

        Verwendet eine mehrstufige, robuste Strategie:
        1. NLTK (wenn installiert und bereits initialisiert) für präzise linguistische Satzaufteilung.
        2. Falls NLTK noch nicht initialisiert ist (asynchroner Download läuft), wird die globale
           `split_sentences`-Funktion als sofortiger Fallback verwendet.
        3. Bei fehlendem NLTK oder Fehlern wird ebenfalls auf `split_sentences` zurückgegriffen.
        4. Als letzte Reserve dient eine einfache regex-basierte Aufteilung.

        Die Initialisierung von NLTK (`punkt_tab`) erfolgt asynchron im Hintergrund,
        sodass der Dialog nicht blockiert wird. Solange der Download läuft, wird
        der Fallback verwendet – nach Abschluss wird automatisch die präzisere
        NLTK-Variante genutzt.

        Args:
            text: Der zu zerlegende Text (kann auch None oder leer sein).

        Returns:
            Liste der Sätze (ohne abschließende Leerzeichen). Bei leerer Eingabe
            oder Fehlern wird eine leere Liste zurückgegeben.
        """
        # ── 1. Eingabe validieren und normalisieren ──────────────────────────
        if not text or not isinstance(text, str):
            return []
        clean = text.strip()
        if not clean:
            return []

        # ── 2. Versuch 1: NLTK (wenn verfügbar und initialisiert) ───────────
        if self._nltk_available:
            # Prüfen, ob der asynchrone Download bereits abgeschlossen ist
            if getattr(self, "_nltk_initialized", False):
                try:
                    # NLTK's sent_tokenize ist die genaueste Methode
                    sentences = self._nltk.sent_tokenize(clean)
                    if sentences:
                        if DEBUG_LEVEL >= 4:
                            log_debug(
                                "summarize", f"NLTK: {len(sentences)} Sätze erkannt"
                            )
                        return sentences
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            f"NLTK sent_tokenize fehlgeschlagen: {e} – verwende Fallback",
                        )
            else:
                # NLTK ist verfügbar, aber der Download läuft noch – kurz warten?
                # Um die GUI nicht zu blockieren, verwenden wir sofort den Fallback
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "summarize", "NLTK wird noch initialisiert – verwende Fallback"
                    )
                # Fallthrough zum Fallback

        # ── 3. Versuch 2: Globale `split_sentences`-Funktion (aus dem Hauptmodul) ──
        try:
            # Die Funktion ist im globalen Namensraum definiert (siehe Modulanfang)
            _split_func = globals().get("split_sentences")
            if _split_func is not None:
                result = _split_func(clean)
                if result:
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "summarize", f"split_sentences: {len(result)} Sätze erkannt"
                        )
                    return result
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", f"globale split_sentences fehlgeschlagen: {e}")

        # ── 4. Versuch 3: Einfache regex-basierte Aufteilung (Fallback) ──────
        #     Der Lookbehind prüft ein einzelnes Satzendzeichen, daher in Python erlaubt.
        try:
            parts = re.split(r"(?<=[.!?。！？])[ \n]+", clean)
            sentences = [s.strip() for s in parts if s.strip()]
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "summarize", f"Regex-Fallback: {len(sentences)} Sätze erkannt"
                )
            return sentences
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", f"Regex-Split fehlgeschlagen: {e}")
            # Letzte Rettung: gesamten Text als einen Satz betrachten
            return [clean] if clean else []

    def _split_into_chunks(self, text: str, max_tokens: int) -> List[str]:
        """
        Teilt einen Text in Chunks auf, wobei jeder Chunk maximal
        *max_tokens* Tokens beanspruchen darf.
        Überlange Einzelsätze werden automatisch gekürzt.
        """
        if not text or max_tokens <= 0:
            return []

        sents = self._split_sentences(text)
        if not sents:
            return [text]

        chunks: List[str] = []
        current_chunk: List[str] = []
        current_tokens = 0

        for s in sents:
            t = self._estimate_tokens(s)
            # Einzelsatz zu groß → sofort kürzen
            if t > max_tokens:
                if current_chunk:
                    chunks.append(" ".join(current_chunk))
                    current_chunk = []
                    current_tokens = 0
                truncated = self._truncate_text_to_fit(s, max_tokens, add_notice=True)
                if truncated:
                    chunks.append(truncated)
                continue

            if current_tokens + t <= max_tokens:
                current_chunk.append(s)
                current_tokens += t
            else:
                if current_chunk:
                    chunks.append(" ".join(current_chunk))
                current_chunk = [s]
                current_tokens = t

        if current_chunk:
            chunks.append(" ".join(current_chunk))

        # Begrenzung der Chunk-Anzahl, um Überlastung des Ollama-Servers zu vermeiden
        if len(chunks) > self.MAX_CHUNKS:
            chunks = chunks[: self.MAX_CHUNKS]

        return chunks if chunks else [text]

    def _cache_key(self, prompt: str) -> str:
        """
        Erzeugt einen eindeutigen Schlüssel für den Antwort‑Cache.
        """
        model = str(self.model) if self.model else "unknown"
        prompt = str(prompt) if prompt else ""
        text = str(self.text) if hasattr(self, "text") and self.text else ""

        raw = f"{model}|{prompt}|{text}"
        return hashlib.sha256(raw.encode("utf-8", errors="ignore")).hexdigest()

    def _get_cached(self, prompt: str) -> Optional[str]:
        key = self._cache_key(prompt)
        entry = self._response_cache.get(key)
        if entry:
            res, ts = entry
            if time.time() - ts < self._cache_ttl:
                log_debug("summarize", "Cache-HIT")
                return res
            else:
                self._response_cache.remove(key)
                log_debug("summarize", "Cache-Eintrag abgelaufen, entfernt")
        return None

    def _cache_set(self, prompt: str, res: str) -> None:
        key = self._cache_key(prompt)
        self._response_cache.put(key, (res, time.time()))
        log_debug("summarize", f"Cache set for {key[:16]}…")

    def _get_full_summary(self) -> str:
        with self._state_lock:
            return self._summary_state["full_summary"]

    def _set_full_summary(self, s: str) -> None:
        with self._state_lock:
            self._summary_state["full_summary"] = s

    def _append_summary_part(self, part: str) -> None:
        with self._state_lock:
            self._summary_state["parts"].append(part)

    def _clear_summary_parts(self) -> None:
        with self._state_lock:
            self._summary_state["parts"].clear()

    def _get_summary_parts(self) -> List[str]:
        with self._state_lock:
            return list(self._summary_state["parts"])

    def _apply_blacklist_to_summary(self) -> None:
        """
        Wendet die konfigurierte Blacklist auf die aktuelle Zusammenfassung an.
        """
        summary = self._get_full_summary()
        if not summary:
            return

        filter_func = getattr(self.gui, "_filter_blacklist_text", None)
        if filter_func is None:
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", "Blacklist-Filter nicht verfügbar – überspringe")
            return

        try:
            filtered = filter_func(summary, "unknown")
        except Exception as e:
            log_debug("summarize", f"Blacklist filter error: {e}")
            return

        if filtered is not None and filtered != summary:
            self._set_full_summary(filtered)
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self._safe_after(
                    0,
                    lambda: (
                        self.summary_text.delete("1.0", "end"),
                        self.summary_text.insert("1.0", filtered),
                    ),
                )

    def _check_backup(self) -> None:
        if not os.path.exists(self._backup_file):
            return
        try:
            if time.time() - os.path.getmtime(self._backup_file) > 3600:
                return
        except OSError:
            return
        if DarkMessageBox.askyesno(
            "Zusammenfassung wiederherstellen?",
            "Es wurde eine nicht gespeicherte Zusammenfassung gefunden. Wiederherstellen?",
            parent=self.dialog,
        ):
            try:
                with open(self._backup_file, "r", encoding="utf-8") as f:
                    saved = f.read()
                self._set_full_summary(saved)
                self.dialog.after(100, self._restore_backup)
            except Exception as e:
                log_debug("summarize", f"Backup restore error: {e}")

    def _restore_backup(self) -> None:
        if self._destroyed or not self.dialog.winfo_exists():
            return
        try:
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self.summary_text.delete("1.0", "end")
                self.summary_text.insert("1.0", self._get_full_summary())
        except Exception as e:
            log_debug("summarize", f"Backup restore UI error: {e}")

    def _save_backup(self) -> None:
        s = self._get_full_summary()
        if not s:
            return
        try:
            with open(self._backup_file, "w", encoding="utf-8") as f:
                f.write(s)
        except Exception as e:
            log_debug("summarize", f"Backup save error: {e}")

    def _load_profiles(self) -> None:
        path = PlatformUtils.get_platform_config_dir() / "summarize_profiles.json"
        if path.exists():
            try:
                with open(path, "r", encoding="utf-8") as f:
                    self._profiles = json.load(f)
            except Exception as e:
                log_debug("summarize", f"Profile konnten nicht geladen werden: {e}")
                self._profiles = {}

    def _save_profiles(self) -> None:
        path = PlatformUtils.get_platform_config_dir() / "summarize_profiles.json"
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(self._profiles, f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"Could not save profiles: {e}")

    def _save_current_profile(self) -> None:
        name = simpledialog.askstring(
            "Profil speichern", "Name des Profils:", parent=self.dialog
        )
        if not name:
            return
        profile = {
            "model": self.model,
            "temperature": self.temperature,
            "strategy": self.strategy,
            "language": self.language,
            "style": self.style,
            "use_title_context": self.use_title_context,
            "max_chunk_tokens": self.max_chunk_tokens,
            "use_structured_output": self.use_structured_output,
        }
        self._profiles[name] = profile
        self._save_profiles()
        self._update_profile_menu()
        self.status_label.config(text=f"✅ Profil '{name}' gespeichert")

    def _load_profile(self, name: str) -> None:
        profile = self._profiles.get(name)
        if not profile:
            self.status_label.config(text=f"❌ Profil '{name}' nicht gefunden")
            return
        self.model = profile["model"]
        self.model_var.set(self.model)
        self._token_cache.clear()
        self._model_context_limit = None
        self.temperature = profile["temperature"]
        self.temp_var.set(self.temperature)
        self.strategy = profile["strategy"]
        self.strategy_var.set(self.strategy)
        self.language = profile["language"]
        self.lang_var.set(self.language)
        self.style = profile["style"]
        self.style_var.set(self.style)
        self.use_title_context = profile.get("use_title_context", False)
        self.title_var.set(self.use_title_context)
        self.max_chunk_tokens = profile.get("max_chunk_tokens", 2000)
        self.use_structured_output = profile.get("use_structured_output", False)
        self.structured_var.set(self.use_structured_output)
        self._user_edited_prompt = False
        self._reset_to_default_prompt()
        self.status_label.config(text=f"✅ Profil '{name}' geladen")

    def _update_profile_menu(self) -> None:
        if not hasattr(self, "profile_menu") or self.profile_menu is None:
            return
        self.profile_menu.delete(0, "end")
        for name in sorted(self._profiles.keys()):
            self.profile_menu.add_command(
                label=name, command=lambda n=name: self._load_profile(n)
            )
        if self._profiles:
            self.profile_menu.add_separator()
        self.profile_menu.add_command(
            label="➕ Neues Profil speichern", command=self._save_current_profile
        )
        if self._profiles:
            self.profile_menu.add_command(
                label="🗑️ Profil löschen", command=self._delete_profile
            )

    def _delete_profile(self) -> None:
        names = sorted(self._profiles.keys())
        if not names:
            return
        name = simpledialog.askstring(
            "Profil löschen",
            f"Welches Profil löschen?\n{', '.join(names)}",
            parent=self.dialog,
        )
        if name and name in self._profiles:
            del self._profiles[name]
            self._save_profiles()
            self._update_profile_menu()
            self.status_label.config(text=f"🗑️ Profil '{name}' gelöscht")

    def _load_user_templates(self) -> None:
        path = PlatformUtils.get_platform_config_dir() / self.TEMPLATES_FILENAME
        if path.exists():
            try:
                with open(path, "r", encoding="utf-8") as f:
                    self._user_templates = json.load(f)
            except Exception as e:
                log_debug("summarize", f"Vorlagen-Datei beschädigt: {e}")
                self._user_templates = {}
        else:
            self._user_templates = {}
        for k, v in list(self._user_templates.items()):
            if isinstance(v, str):
                self._user_templates[k] = {"text": v, "category": ""}
            elif not isinstance(v, dict):
                del self._user_templates[k]

    def _save_user_templates(self) -> None:
        path = PlatformUtils.get_platform_config_dir() / self.TEMPLATES_FILENAME
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(self._user_templates, f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"Could not save templates: {e}")

    def _build_template_list(self) -> None:
        predefined = list(self.TEMPLATES.keys())
        user = sorted(self._user_templates.keys())
        combined = predefined[:]
        for name in user:
            if name not in combined:
                combined.append(name)
        self._template_names = combined

    def _get_template_prompt(self, name: str) -> str:
        if name in self._user_templates:
            entry = self._user_templates[name]
            return entry["text"] if isinstance(entry, dict) else entry
        return self.TEMPLATES.get(name, "")

    def _get_template_category(self, name: str) -> str:
        if name in self._user_templates:
            entry = self._user_templates[name]
            return entry.get("category", "") if isinstance(entry, dict) else ""
        return ""

    def _save_current_as_template(self) -> None:
        if not hasattr(self, "prompt_text") or not self.prompt_text.winfo_exists():
            return
        cur = self.prompt_text.get("1.0", "end-1c").strip()
        if not cur:
            self.status_label.config(text="❌ Prompt ist leer")
            return
        name = self.template_var.get().strip()
        if not name or (name in self.TEMPLATES and name not in self._user_templates):
            name = simpledialog.askstring(
                "Vorlage speichern", "Name:", parent=self.dialog
            )
        if not name:
            return
        cat = (
            simpledialog.askstring("Kategorie", "(optional):", parent=self.dialog) or ""
        )
        self._user_templates[name] = {"text": cur, "category": cat}
        self._save_user_templates()
        self._build_template_list()
        self.template_combo["values"] = self._template_names
        self.template_var.set(name)
        self.status_label.config(text=f"✅ Vorlage '{name}' gespeichert")

    def _delete_current_template(self) -> None:
        name = self.template_var.get().strip()
        if not name or name not in self._user_templates:
            self.status_label.config(text="❌ Nur eigene Vorlagen löschbar")
            return
        if DarkMessageBox.askyesno(
            "Löschen", f"'{name}' wirklich löschen?", parent=self.dialog
        ):
            del self._user_templates[name]
            self._save_user_templates()
            self._build_template_list()
            self.template_combo["values"] = self._template_names
            self.template_var.set("")
            self.status_label.config(text=f"🗑️ '{name}' gelöscht")

    def _load_template(self) -> None:
        name = self.template_var.get().strip()
        if not name:
            return
        prompt = self._get_template_prompt(name)
        if not prompt:
            self.status_label.config(text=f"❌ '{name}' nicht gefunden")
            return
        if not hasattr(self, "prompt_text") or not self.prompt_text.winfo_exists():
            return
        self.prompt_text.delete("1.0", "end")
        self.prompt_text.insert("1.0", prompt)
        self._user_edited_prompt = True
        self._update_preview()
        self.status_label.config(text=f"✅ '{name}' geladen")

    def _on_drop(self, event) -> None:
        if not self._dnd_available:
            return
        try:
            files = self.dialog.tk.splitlist(event.data)
        except Exception:
            data = getattr(event, "data", "")
            files = [data.strip("{}")] if data else []
        if not files:
            return
        path = files[0]
        if not os.path.isfile(path):
            self.status_label.config(text="❌ Keine gültige Datei")
            return
        if not path.lower().endswith(".txt"):
            self.status_label.config(text="❌ Nur .txt erlaubt")
            return
        self._load_transcript_from_file(path)

    def _load_transcript_from_file(self, path: str) -> None:
        content = None
        for enc in ("utf-8", "latin-1", "cp1252"):
            try:
                with open(path, "r", encoding=enc) as f:
                    content = f.read()
                break
            except (UnicodeDecodeError, UnicodeError):
                continue
            except Exception as e:
                DarkMessageBox.showerror("Fehler", str(e), parent=self.dialog)
                return
        if content is None:
            DarkMessageBox.showerror(
                "Fehler", "Keine lesbaren Textdaten", parent=self.dialog
            )
            return
        title, text = self._parse_transcript_content(content)
        if not text:
            self.status_label.config(text="❌ Kein Transkriptionstext")
            return
        self._apply_loaded_transcript(title, text)

    def _load_saved_transcript(self) -> None:
        path = filedialog.askopenfilename(
            title="Transkription laden",
            filetypes=[("Textdateien", "*.txt"), ("Alle", "*.*")],
        )
        if not path:
            return
        self._load_transcript_from_file(path)

    @staticmethod
    def _parse_transcript_content(content: str) -> Tuple[str, str]:
        title = ""
        text = content.strip()
        if "=== STREAM INFORMATION ===" in content:
            parts = re.split(r"=== (?:TRANSCRIPT|TRANSLATION) ===", content, maxsplit=1)
            info = parts[0]
            m = re.search(r"Title:\s*(.+)", info)
            if m:
                title = m.group(1).strip()
            if len(parts) > 1:
                text = parts[1].strip()
        return title, text

    def _apply_loaded_transcript(self, title: str, text: str) -> None:
        if title:
            self.stream_title = title
            self.title_var.set(True)
            self.use_title_context = True
        else:
            self.stream_title = ""
            self.use_title_context = False
        self.text = text
        self._user_edited_prompt = False
        self._update_preview()
        self.status_label.config(
            text=f"✅ Geladen ({len(text):,} Zeichen)"
            + (f" – {title[:60]}…" if title else "")
        )

    def _set_temperature_preset(self, temp: float) -> None:
        self.temperature = temp
        self.temp_var.set(temp)

    def _update_preview(self) -> None:
        if self._user_edited_prompt and hasattr(self, "prompt_text"):
            effective = self.prompt_text.get("1.0", "end-1c")
        else:
            base = self.SUMMARY_LANGUAGE_PROMPTS.get(
                self.language, self.SUMMARY_LANGUAGE_PROMPTS["Deutsch"]
            )
            style = self.TEMPLATES.get(
                self.style, self.TEMPLATES["Kompakt (3-5 Sätze)"]
            )
            if self.use_title_context and self.stream_title:
                base = f"Titel: {self.stream_title}\n\n{base}"
            effective = f"{base}\n\n{style}"
        if hasattr(self, "preview_text") and self.preview_text.winfo_exists():
            self.preview_text.config(state="normal")
            self.preview_text.delete("1.0", "end")
            self.preview_text.insert("1.0", effective)
            self.preview_text.config(state="disabled")
        self._schedule_token_update()

    def _schedule_token_update(self) -> None:
        if self._token_debounce_id is not None:
            self.dialog.after_cancel(self._token_debounce_id)
        self._token_debounce_id = self.dialog.after(300, self._do_token_update)

    def _do_token_update(self) -> None:
        self._token_debounce_id = None
        if not hasattr(self, "preview_text") or not self.preview_text.winfo_exists():
            return
        effective = self.preview_text.get("1.0", "end-1c")
        total_text = effective + "\n\n" + self.text
        tokens = self._estimate_tokens(total_text)
        limit = self._get_model_context_limit()
        self._update_context_bar(tokens, limit)
        if hasattr(self, "token_label"):
            if tokens <= limit * 0.8:
                col = CURRENT_THEME.SUCCESS
            elif tokens <= limit:
                col = CURRENT_THEME.WARNING
            else:
                col = CURRENT_THEME.ERROR
            self.token_label.config(text=f"📊 Token: {tokens}/{limit}", fg=col)

    def _on_prompt_changed(self, event=None) -> None:
        self._user_edited_prompt = True
        self._update_preview()
        if hasattr(self, "reset_prompt_btn"):
            self.reset_prompt_btn.config(state="normal", bg=CURRENT_THEME.WARNING)

    def _reset_to_default_prompt(self) -> None:
        self._user_edited_prompt = False
        self._update_preview()
        effective = self.preview_text.get("1.0", "end-1c")
        if hasattr(self, "prompt_text") and self.prompt_text.winfo_exists():
            self.prompt_text.delete("1.0", "end")
            self.prompt_text.insert("1.0", effective)
        if hasattr(self, "reset_prompt_btn"):
            self.reset_prompt_btn.config(state="disabled", bg=CURRENT_THEME.BG_TERTIARY)

    def _on_setting_changed(self, event=None) -> None:
        """Synchronisiert alle Einstellungen aus der GUI mit den Instanzvariablen."""
        lang = self.lang_var.get()
        if lang in self.SUPPORTED_SUMMARY_LANGUAGES:
            self.language = lang
        else:
            self.language = "Deutsch"
            self.lang_var.set("Deutsch")
        style = self.style_var.get()
        if style in self.TEMPLATES:
            self.style = style
        else:
            self.style = "Kompakt (3-5 Sätze)"
            self.style_var.set(self.style)
        self.use_title_context = self.title_var.get()
        self.use_structured_output = self.structured_var.get()
        self._user_edited_prompt = False
        self._reset_to_default_prompt()

    def _update_context_bar(self, tokens: int, limit: int) -> None:
        if not hasattr(self, "context_bar") or self.context_bar is None:
            return
        pct = min(1.0, tokens / max(limit, 1))
        if pct <= 0.5:
            color = "#238636"
        elif pct <= 0.8:
            color = "#d29922"
        elif pct <= 1.0:
            color = "#f85149"
        else:
            color = "#ff00ff"
        self.context_bar.config(width=int(pct * 200), bg=color)
        if hasattr(self, "context_label"):
            self.context_label.config(text=f"{tokens} / {limit} Tokens ({pct:.0%})")

    def _update_readability_metrics(self, text: str) -> None:
        if not hasattr(self, "metrics_label") or not text:
            return
        sentences = self._split_sentences(text)
        words = text.split()
        wc = len(words)
        sc = max(1, len(sentences))
        avg = wc / sc
        syllables = sum(self._count_syllables(w) for w in words)
        flesch = max(0, 180 - avg - (syllables * 60 / max(1, wc)))
        rt = max(1, wc // 200)

        # Interpretation des Flesch‑Index
        if flesch >= 60:
            level = "sehr leicht"
        elif flesch >= 50:
            level = "leicht"
        elif flesch >= 30:
            level = "mittelschwer"
        elif flesch >= 0:
            level = "schwer"
        else:
            level = "sehr schwer"

        msg = (
            f"📊 {wc} Wörter | {sc} Sätze | ⌀ {avg:.1f} W/Satz | "
            f"📖 Flesch: {flesch:.0f} ({level}) | ⏱️ ~{rt}m"
        )
        self.metrics_label.config(text=msg)

    def _clear_history(self) -> None:
        """Löscht den gesamten Zusammenfassungsverlauf."""
        if not self._history:
            return
        if DarkMessageBox.askyesno(
            "Verlauf löschen",
            "Möchten Sie den gesamten Verlauf wirklich löschen?",
            parent=self.dialog,
        ):
            self._history.clear()
            self._save_history()
            self._update_history_combobox()
            self.status_label.config(text="🗑️ Verlauf gelöscht")

    @staticmethod
    def _count_syllables(word: str) -> int:
        word = word.lower()
        cnt = 0
        vowels = "aeiouyäöü"
        prev = False
        for ch in word:
            is_v = ch in vowels
            if is_v and not prev:
                cnt += 1
            prev = is_v
        return max(1, cnt)

    def _auto_regenerate(
        self,
        summary: str,
        prompt: str,
        temperature: float,
        min_word_gain: float = 1.2,
        max_attempts: int = 1,
    ) -> Optional[str]:
        """
        Versucht, eine zu kurze oder qualitativ unzureichende Zusammenfassung
        durch einen zweiten, kreativeren Durchlauf mit höherer Temperatur zu
        verbessern.

        **Ultimative Optimierungen (v7.0 – vollständig überarbeitet):**
        - Behebt den mypy‑Fehler „Too few arguments“ durch dynamische Prüfung der
          Methodensignatur (verwendet `inspect.signature`).
        - Unterstützt sowohl Methoden mit zwei Parametern `(prompt, temperature)`
          als auch solche mit nur einem Parameter `(prompt)`.  Dadurch maximale
          Kompatibilität mit verschiedenen Summarizer‑Implementierungen.
        - Dynamische Erzeugung der Temperaturliste basierend auf `max_attempts`.
        - Zusätzliche Heuristik: Wenn die ursprüngliche Zusammenfassung bereits
          mehr als 50 Wörter umfasst, wird ein Auto‑Regenerate übersprungen.
        - Prüfung auf Existenz der Summarizer‑Methoden (`_summarize_refine` /
          `_summarize_map_reduce`).  Bei Fehlen wird `None` zurückgegeben.
        - Verbesserte Fehlerbehandlung mit detaillierten Debug‑Ausgaben.
        - Verwendung von `self._request_cancel` für vorzeitigen Abbruch.
        - Schutz vor negativen oder zu kleinen `min_word_gain`-Werten.
        - Ausführliches Logging auf verschiedenen DEBUG‑Levels.

        Args:
            summary: Die ursprüngliche Zusammenfassung (als String).
            prompt: Der ursprüngliche Prompt (wird unverändert weitergereicht).
            temperature: Die ursprünglich verwendete Temperatur (wird ignoriert).
            min_word_gain: Minimaler Faktor der Wortanzahl, um die neue
                           Zusammenfassung zu akzeptieren (1.2 = 20% mehr Wörter).
            max_attempts: Maximale Anzahl zusätzlicher Versuche (1, 2 oder 3).

        Returns:
            Verbesserte Zusammenfassung oder None, wenn keine Verbesserung erreicht wurde.
        """
        # ──────────────────────────────────────────────────────────────────────────
        # 0. Parameter normalisieren und Frühabbruch
        # ──────────────────────────────────────────────────────────────────────────
        if max_attempts <= 0:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate deaktiviert (max_attempts=%d)",
                    max_attempts,
                )
            return None

        if not summary or not summary.strip():
            if DEBUG_LEVEL >= 3:
                log_debug("summarize", "Auto‑Regenerate übersprungen: summary ist leer")
            return None

        # min_word_gain normalisieren (mindestens 1.0)
        effective_min_gain = max(1.0, min_word_gain)

        # ──────────────────────────────────────────────────────────────────────────
        # 1. Grundlegende Textmetriken
        # ──────────────────────────────────────────────────────────────────────────
        original_words = len(summary.split())
        original_chars = len(summary)
        total_text_words = len(self.text.split()) if self.text else 0

        # ──────────────────────────────────────────────────────────────────────────
        # 2. Heuristik: Ist die Zusammenfassung bereits ausführlich genug?
        # ──────────────────────────────────────────────────────────────────────────
        if original_words >= 50:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Zusammenfassung bereits lang (%d Wörter)",
                    original_words,
                )
            return None

        if total_text_words > 0 and original_words / total_text_words > 0.1:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Zusammenfassung bereits ausführlich "
                    "(%.1f%% des Originals, %d Wörter)",
                    (original_words / total_text_words) * 100,
                    original_words,
                )
            return None

        is_too_short = original_words < 20
        is_text_short = total_text_words < 100
        if not is_too_short and not is_text_short:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate übersprungen: Keine Verbesserung nötig "
                    "(original_words=%d, text_words=%d)",
                    original_words,
                    total_text_words,
                )
            return None

        if DEBUG_LEVEL >= 2:
            log_debug(
                "summarize",
                "Auto‑Regenerate gestartet (original: %d Wörter, %d Zeichen, "
                "Textlänge: %d Wörter, min_gain=%.2f, max_attempts=%d)",
                original_words,
                original_chars,
                total_text_words,
                effective_min_gain,
                max_attempts,
            )

        # ──────────────────────────────────────────────────────────────────────────
        # 3. Verfügbare Summarizer‑Methoden ermitteln
        # ──────────────────────────────────────────────────────────────────────────
        refine_method = getattr(self, "_summarize_refine", None)
        mapreduce_method = getattr(self, "_summarize_map_reduce", None)

        if refine_method is None and mapreduce_method is None:
            logger.error(
                "_auto_regenerate: Weder _summarize_refine noch _summarize_map_reduce verfügbar"
            )
            return None

        # Methode gemäß Strategie auswählen (wie in start_summarize)
        if self.strategy == "Genau (schrittweise)":
            target_method = (
                refine_method if refine_method is not None else mapreduce_method
            )
        else:
            target_method = (
                mapreduce_method if mapreduce_method is not None else refine_method
            )

        if target_method is None:
            logger.error(
                "_auto_regenerate: Keine geeignete Summarizer‑Methode gefunden"
            )
            return None

        # ──────────────────────────────────────────────────────────────────────────
        # 4. Signatur der Zielmethode analysieren (um mypy‑Fehler zu vermeiden)
        # ──────────────────────────────────────────────────────────────────────────
        import inspect

        sig = inspect.signature(target_method)
        params = list(sig.parameters.keys())
        supports_temperature = "temperature" in params

        # ──────────────────────────────────────────────────────────────────────────
        # 5. Temperaturen für die verschiedenen Versuche (steigende Kreativität)
        # ──────────────────────────────────────────────────────────────────────────
        temperatures = []
        if max_attempts >= 1:
            temperatures.append(0.7)
        if max_attempts >= 2:
            temperatures.append(0.8)
        if max_attempts >= 3:
            temperatures.append(0.9)
        temperatures = temperatures[:max_attempts]

        if not temperatures:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize", "Keine Temperaturen für max_attempts=%d", max_attempts
                )
            return None

        # ──────────────────────────────────────────────────────────────────────────
        # 6. Wiederholungsschleife mit verschiedenen Temperaturen
        # ──────────────────────────────────────────────────────────────────────────
        best_result = None
        best_word_count = original_words

        for attempt, current_temp in enumerate(temperatures, start=1):
            if self._request_cancel.is_set():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "Auto‑Regenerate abgebrochen (cancel_event) bei Versuch %d",
                        attempt,
                    )
                break

            if DEBUG_LEVEL >= 3:
                log_debug(
                    "summarize",
                    "Auto‑Regenerate Versuch %d/%d mit Temperatur %.1f",
                    attempt,
                    len(temperatures),
                    current_temp,
                )

            try:
                # ── Aufruf der Methode mit korrekter Argumentzahl ──
                if supports_temperature:
                    regenerated = target_method(prompt, temperature=current_temp)
                else:
                    # Methode erwartet nur ein Argument (prompt)
                    regenerated = target_method(prompt)

                # Validierung des Ergebnisses
                if not regenerated or not isinstance(regenerated, str):
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  Versuch %d lieferte leere oder ungültige Antwort",
                            attempt,
                        )
                    continue

                regenerated = regenerated.strip()
                if not regenerated:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  Versuch %d lieferte leere Antwort (nach strip)",
                            attempt,
                        )
                    continue

                new_word_count = len(regenerated.split())
                gain_ratio = new_word_count / max(original_words, 1)

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "  Versuch %d: %d Wörter (Gewinnfaktor %.2f)",
                        attempt,
                        new_word_count,
                        gain_ratio,
                    )

                # Akzeptieren, wenn der Gewinnfaktor überschritten wird
                if gain_ratio >= effective_min_gain:
                    best_result = regenerated
                    best_word_count = new_word_count
                    if DEBUG_LEVEL >= 2:
                        log_debug(
                            "summarize",
                            "  ✅ Verbesserung akzeptiert (%.1f → %d Wörter, Faktor %.2f >= %.2f)",
                            original_words,
                            new_word_count,
                            gain_ratio,
                            effective_min_gain,
                        )
                    break
                elif new_word_count > best_word_count:
                    # Falls nicht ausreichend, aber besser als vorher, merken
                    best_result = regenerated
                    best_word_count = new_word_count
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "summarize",
                            "  ⏺ Zwischenergebnis gespeichert (%d Wörter, bisher best: %d)",
                            new_word_count,
                            best_word_count,
                        )
                else:
                    if DEBUG_LEVEL >= 4:
                        log_debug(
                            "summarize",
                            "  Versuch %d lieferte keine Verbesserung (%d <= %d Wörter)",
                            attempt,
                            new_word_count,
                            best_word_count,
                        )

            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize",
                        "  ❌ Auto‑Regenerate Versuch %d fehlgeschlagen: %s",
                        attempt,
                        str(e)[:100],
                    )
                # Bei Fehlern nicht abbrechen, sondern nächsten Versuch versuchen
                continue

        # ──────────────────────────────────────────────────────────────────────────
        # 7. Ergebnisbewertung und Rückgabe
        # ──────────────────────────────────────────────────────────────────────────
        if best_result and best_word_count > original_words:
            improvement_percent = int(
                (best_word_count / max(original_words, 1) - 1) * 100
            )
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "summarize",
                    "✅ Auto‑Regenerate erfolgreich: %d → %d Wörter (Verbesserung um %d%%)",
                    original_words,
                    best_word_count,
                    improvement_percent,
                )
            return best_result

        if DEBUG_LEVEL >= 3:
            log_debug(
                "summarize",
                "❌ Auto‑Regenerate keine Verbesserung (bester Versuch: %d Wörter, original: %d)",
                best_word_count,
                original_words,
            )
        return None

    @contextmanager
    def _ollama_usage(
        self, timeout: Optional[float] = None
    ) -> Generator[Any, None, None]:
        """
        Kontextmanager für die Nutzung des OllamaSummarizers.

        Erhöht den Nutzungszähler bei Eintritt und dekrementiert ihn beim Verlassen.
        Stellt sicher, dass die Ressource auch bei Exceptions freigegeben wird.

        Verbesserungen gegenüber der Originalversion:
        - Unterstützung für ein optionales Timeout (wartet auf Freigabe des Zählers)
        - Detaillierte Debug‑Ausgaben bei Eintritt und Austritt
        - Robustere Fehlerbehandlung (falls `_get_ollama_summarizer` fehlschlägt)
        - Explizite Typannotation (Generator)
        - Möglichkeit, bei Timeout eine Exception auszulösen (optional)

        Args:
            timeout: Maximale Wartezeit in Sekunden auf die Freigabe des
                     Nutzungszählers (0 = sofort, None = unbegrenzt).
                     Das Warten ist nur sinnvoll, wenn der Zähler bereits
                     einen Maximalwert erreicht hat – was im aktuellen Design
                     nicht der Fall ist, da keine Begrenzung existiert.
                     Daher wird dieser Parameter derzeit nicht verwendet, ist
                     aber für zukünftige Erweiterungen vorbereitet.

        Yields:
            Die `OllamaSummarizer`-Instanz (bereits initialisiert und bereit).

        Raises:
            RuntimeError: Wenn der OllamaSummarizer nicht verfügbar ist oder
                          die Initialisierung fehlschlägt.
            TimeoutError: Wenn `timeout` angegeben ist und die Akquise des
                          Nutzungszählers fehlschlägt (nicht implementiert).
        """
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS

        if _debug:
            log_debug(
                "summarize",
                "_ollama_usage: Eintritt, aktuelle Nutzerzahl = %d",
                self._ollama_usage_count,
            )

        # ── 1. Summarizer-Instanz beschaffen (kann eine Exception werfen) ──
        try:
            summarizer = self._get_ollama_summarizer()
        except Exception as e:
            if _debug:
                log_exception(
                    "summarize",
                    "_get_ollama_summarizer fehlgeschlagen",
                    e,
                    level="error",
                )
            raise RuntimeError(
                f"Konnte OllamaSummarizer nicht bereitstellen: {e}"
            ) from e

        # ── 2. Kontext betreten (Zähler wurde bereits in _get_ollama_summarizer erhöht)
        #    Da der Zähler bereits inkrementiert ist, müssen wir hier nichts zusätzlich tun.
        #    Der finally-Block wird die Freigabe übernehmen.

        try:
            if _debug:
                log_debug(
                    "summarize",
                    "_ollama_usage: Gebe Summarizer aus (Nutzer = %d)",
                    self._ollama_usage_count,
                )
            yield summarizer
        finally:
            # ── 3. Freigabe (Zähler dekrementieren und ggf. Instanz verwerfen)
            self._ollama_usage_release()
            if _debug:
                log_debug(
                    "summarize",
                    "_ollama_usage: Verlassen, neue Nutzerzahl = %d",
                    self._ollama_usage_count,
                )

    def _get_ollama_summarizer(self) -> Any:
        """
        Gibt die **eine** `OllamaSummarizer`‑Instanz zurück und registriert
        eine Nutzung, indem der interne Zähler erhöht wird.

        Verbesserungen gegenüber der Originalversion:
        - Video‑spezifischer System‑Prompt für authentische Video‑Zusammenfassungen
        - Übernahme von Timeout, Keep‑Alive und Fallback‑Hosts aus den Einstellungen
        - Begrenzung der parallelen Anfragen auf maximal 10 (schont den Server)
        - Health‑Check für gecachte Instanz (Server‑Erreichbarkeit)
        - Detaillierte Debug‑Ausgaben für jede Phase
        - Robuste Fehlerbehandlung mit aussagekräftigen Meldungen
        - Automatische Bereinigung defekter Instanzen

        Returns:
            Die (einzige) `OllamaSummarizer`‑Instanz.

        Raises:
            RuntimeError: Wenn OllamaSummarizer nicht verfügbar ist, der Server nicht
                          erreichbar ist oder die Initialisierung fehlschlägt.
        """
        _debug = DEBUG_LEVEL >= 3 or "summarize" in DEBUG_COMPONENTS

        with self._ollama_usage_lock:
            # ──────────────────────────────────────────────────────────────
            # 1. Prüfen, ob bereits eine Instanz existiert und noch gültig ist
            # ──────────────────────────────────────────────────────────────
            if self._ollama_instance is not None:
                try:
                    # Health‑Check: Ist der Server noch erreichbar?
                    if hasattr(self._ollama_instance, "is_server_reachable"):
                        reachable = self._ollama_instance.is_server_reachable()
                        if not reachable:
                            if _debug:
                                log_debug(
                                    "summarize",
                                    "Gecachte Ollama‑Instanz nicht erreichbar – erstelle neue",
                                )
                            self._ollama_instance = None
                    # Fallback: keine öffentliche Methode – wir vertrauen der Instanz
                except Exception as e:
                    if _debug:
                        log_debug(
                            "summarize",
                            f"Health‑Check der gecachten Instanz fehlgeschlagen: {e} – erstelle neue",
                        )
                    self._ollama_instance = None

            # ──────────────────────────────────────────────────────────────
            # 2. Neue Instanz erstellen (falls nötig)
            # ──────────────────────────────────────────────────────────────
            if self._ollama_instance is None:
                cls = self._ollama_class
                if cls is None:
                    raise RuntimeError(
                        "OllamaSummarizer ist nicht verfügbar. "
                        "Stellen Sie sicher, dass das Modul geladen ist."
                    )

                # ── Einstellungen aus AdvancedSettings auslesen ──
                adv = self.gui.advanced_settings
                host = getattr(adv, "ollama_host", "http://localhost:11434")
                timeout = getattr(adv, "ollama_timeout", 90)
                keep_alive = getattr(adv, "ollama_keep_alive", 300)
                fallback_hosts = getattr(adv, "ollama_fallback_hosts", [])

                # Max. parallele Anfragen – begrenzt auf 10, mindestens 2
                max_parallel = max(2, min(10, self.max_parallel_requests * 2))

                # ── Video‑spezifischer System‑Prompt ──
                system_prompt = (
                    f"Du bist ein hilfreicher Assistent, der Video-Transkriptionen analysiert. "
                    f"Deine Aufgabe ist es, den Inhalt eines Video-Clips auf {self.language} "
                    f"so zusammenzufassen, als würdest du einem Freund das Video beschreiben. "
                    f"Verwende Formulierungen wie 'Das Video zeigt...', 'In diesem Clip wird erklärt...', "
                    f"'Der Sprecher sagt...'. Vermeide Bezüge auf 'Text' oder 'dieser Text'. "
                    f"Antworte ausschließlich auf {self.language} und ohne Zeichen aus anderen Schriftsystemen."
                )

                if _debug:
                    log_debug(
                        "summarize",
                        "Erstelle neue OllamaSummarizer‑Instanz mit: "
                        "model=%s, host=%s, timeout=%d, keep_alive=%d, max_parallel=%d",
                        self.model,
                        host,
                        timeout,
                        keep_alive,
                        max_parallel,
                    )

                # ── Instanz erzeugen (mit Fehlerbehandlung) ──
                try:
                    self._ollama_instance = cls(
                        self.gui,
                        model=self.model,
                        host=host,
                        timeout=timeout,
                        cache_manager=None,
                        system_prompt=system_prompt,
                        max_parallel_requests=max_parallel,
                        keep_alive=keep_alive,
                        fallback_hosts=fallback_hosts,
                    )
                except Exception as e:
                    raise RuntimeError(
                        f"Konnte OllamaSummarizer nicht initialisieren: {e}\n"
                        f"Prüfen Sie, ob Ollama läuft und unter {host} erreichbar ist.\n"
                        f"Tipp: Führen Sie 'ollama serve' in einem Terminal aus."
                    ) from e

                if _debug:
                    log_debug(
                        "summarize",
                        "✅ Neue OllamaSummarizer‑Instanz erstellt (usage_count=%d)",
                        self._ollama_usage_count,
                    )

            # ──────────────────────────────────────────────────────────────
            # 3. Nutzungszähler erhöhen und Instanz zurückgeben
            # ──────────────────────────────────────────────────────────────
            self._ollama_usage_count += 1
            if _debug and DEBUG_LEVEL >= 4:
                log_debug(
                    "summarize",
                    "_ollama_usage_count erhöht → %d",
                    self._ollama_usage_count,
                )
            return self._ollama_instance

    def _ollama_usage_release(self) -> None:
        """
        Dekrementiert den internen Nutzungszähler des `OllamaSummarizer`.
        Benachrichtigt wartende Threads nur, wenn der Zähler auf 0 fällt –
        der Timeout in close() verhindert dauerhaftes Blockieren.
        """
        with self._ollama_usage_lock:
            if self._ollama_usage_count > 0:
                self._ollama_usage_count -= 1
            else:
                self._ollama_usage_count = 0

    def _reset_ollama_instance(self) -> None:
        """
        Entlädt und verwirft die aktuelle OllamaSummarizer‑Instanz sofort.
        """
        with self._ollama_usage_lock:
            if self._ollama_instance is not None:
                try:
                    self._ollama_instance.stop()
                except Exception:
                    pass
                try:
                    self._ollama_instance.dispose()
                except Exception:
                    pass
                finally:
                    self._ollama_instance = None
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "summarize", "OllamaSummarizer‑Instanz zurückgesetzt (reset)"
                    )

    def _summarize_chunk(
        self,
        chunk: str,
        prompt: str,
        temperature: Optional[float] = None,
    ) -> Optional[str]:
        """
        Fasst einen einzelnen Text‑Chunk mit dem Ollama‑Modell zusammen.
        """
        temp = temperature if temperature is not None else self.temperature
        with self._ollama_usage() as summarizer:
            return summarizer.summarize_sync(chunk, prompt, temp)

    def _process_chunk(
        self, idx: int, chunk: str, prompt: str, temperature: Optional[float] = None
    ) -> None:
        if self._request_cancel.is_set():
            return
        try:
            res = self._summarize_chunk(chunk, prompt, temperature)
        except Exception as e:
            log_debug("summarize", f"Chunk {idx} Fehler: {e}")
            res = None
        with self._chunks_lock:
            self._chunk_results[idx] = res
            self._chunks_processed += 1
            now = time.time()
            if now - self._last_progress_update >= self._progress_update_interval:
                pct = (self._chunks_processed / self._chunks_total) * 100
                self._safe_after(0, lambda: self.progress_var.set(pct))
                self._safe_after(
                    0,
                    lambda: self.progress_label.config(
                        text=f"Chunk {self._chunks_processed}/{self._chunks_total}"
                    ),
                )
                self._last_progress_update = now

    def _summarize_map_reduce(
        self,
        prompt: str,
        temperature: Optional[float] = None,
        *,
        abort_event: Optional[threading.Event] = None,
    ) -> Optional[str]:
        """
        Map‑Reduce‑basierte Zusammenfassung für große Texte.

        Jeder Chunk wird parallel an den Ollama‑Server gesendet, die Ergebnisse
        werden gesammelt und in einem zweiten Schritt zu einer Gesamt‑
        zusammenfassung synthetisiert.

        Verbesserungen:
        - Expliziter Executor‑Shutdown mit ``cancel_futures=True`` (wenn verfügbar),
          damit bei einem Abbruch keine Worker mehr blockieren.
        - Synthese‑Prompt wird bei Bedarf gekürzt, um das Kontextlimit des
          Modells nicht zu überschreiten.
        - Zusätzlicher Logging‑Hinweis bei fehlgeschlagenen Chunks.
        - Abbruch‑Event wird vor jedem Future‑Zugriff geprüft.
        """
        temp = temperature if temperature is not None else self.temperature
        effective_abort = abort_event or self._request_cancel
        limit = self._get_model_context_limit()
        max_tok = min(self.max_chunk_tokens, int(limit * 0.6))
        chunks = self._split_into_chunks(self.text, max_tok)
        if len(chunks) <= 1:
            return self._summarize_chunk(
                chunks[0] if chunks else self.text, prompt, temp
            )

        self._chunks_total = len(chunks)
        self._chunk_results = [None] * len(chunks)
        self._chunks_processed = 0
        self._safe_after(0, lambda: self.progress_var.set(0))
        self._safe_after(0, lambda: self.progress_label.config(text="0%"))

        # Explizit verwalteter Executor, um sicheren Shutdown zu gewährleisten.
        executor = ThreadPoolExecutor(max_workers=self.max_parallel_requests)
        try:
            future_to_idx = {
                executor.submit(self._process_chunk, idx, chunk, prompt, temp): idx
                for idx, chunk in enumerate(chunks)
            }

            for future in as_completed(future_to_idx):
                if effective_abort.is_set():
                    # Alle noch ausstehenden Futures abbrechen.
                    for f in future_to_idx:
                        if not f.done():
                            f.cancel()
                    break

                try:
                    future.result()
                except Exception as exc:
                    idx = future_to_idx[future]
                    log_debug(
                        "summarize",
                        "Chunk %d endgültig fehlgeschlagen: %s",
                        idx,
                        exc,
                        exc_info=DEBUG_LEVEL >= 3,
                    )
                    # Hinweis für den Benutzer (einmalig, nicht bei jedem Fehler)
                    if not hasattr(self, "_chunk_error_shown"):
                        self._chunk_error_shown = True
                        self._safe_after(
                            0,
                            lambda: self.status_label.config(
                                text="⚠️ Einige Chunks fehlgeschlagen – Zusammenfassung evtl. unvollständig"
                            ),
                        )
        finally:
            # Sauberes Herunterfahren: keine neuen Tasks annehmen, laufende ggf. abbrechen.
            try:
                # Python 3.9+ unterstützt cancel_futures.
                safe_shutdown_executor(executor, wait=False, cancel_futures=True)
            except TypeError:
                # Fallback für ältere Python‑Versionen.
                executor.shutdown(wait=False)

        # Nur erfolgreich zusammengefasste Chunks verwenden.
        valid = [r for r in self._chunk_results if r]
        if not valid:
            return None

        combined = "\n\n".join(valid)

        # Synthese‑Prompt zusammenbauen und sicherstellen, dass er ins Kontextfenster passt.
        synthesis_prompt = (
            "Fasse die folgenden Teilzusammenfassungen zu einer einzigen, "
            "kohärenten Gesamtzusammenfassung zusammen.\n\n"
        )
        # Maximal erlaubte Token für den Synthese‑Aufruf: Kontextlimit abzüglich Prompt‑Overhead.
        max_synthesis_tokens = limit - self._estimate_tokens(synthesis_prompt) - 500
        truncated_combined = self._truncate_text_to_fit(
            combined, max_synthesis_tokens, add_notice=True
        )

        return self._summarize_chunk(truncated_combined, synthesis_prompt, temp)

    def _summarize_refine(
        self, prompt: str, temperature: Optional[float] = None
    ) -> Optional[str]:
        limit = self._get_model_context_limit()
        max_tok = min(self.max_chunk_tokens, int(limit * 0.6))
        chunks = self._split_into_chunks(self.text, max_tok)
        if not chunks:
            return None
        cur = None
        total = len(chunks)
        for i, ch in enumerate(chunks):
            if self._request_cancel.is_set():
                return cur
            p = (
                f"Fasse zusammen:\n{ch}"
                if i == 0
                else (
                    f"Erste Zusammenfassung:\n{cur}\n\nVerfeinere mit:\n{ch}\n\nGib NUR die verfeinerte Zusammenfassung zurück."
                )
            )
            cur = self._summarize_chunk(ch, p, temperature)
            if not cur:
                return None
            step = i + 1
            self._safe_after(
                0, lambda s=step: self.status_label.config(text=f"Refine {s}/{total}")
            )
        return cur

    def start_summarize(self) -> None:
        if self._destroyed:
            return
        if not self._ollama_available:
            self.status_label.config(text="❌ OllamaSummarizer nicht verfügbar")
            return

        # ── Server‑Erreichbarkeit prüfen ──────────────────────────
        try:
            with self._ollama_usage() as summarizer:
                if not summarizer.is_server_reachable():
                    if self._retry_attempt < 3:
                        self._retry_attempt += 1
                        if DarkMessageBox.askyesno(
                            "Server nicht erreichbar - Wiederholen?",
                            "Ollama-Server nicht erreichbar. Bitte starten Sie Ollama.",
                            parent=self.dialog,
                        ):
                            self.start_summarize()
                        else:
                            self._retry_attempt = 0
                    else:
                        DarkMessageBox.showerror(
                            "Server nicht erreichbar",
                            "Maximale Wiederholungen erreicht.",
                            parent=self.dialog,
                        )
                        self._retry_attempt = 0
                    return
        except Exception as e:
            if self._retry_attempt < 3:
                self._retry_attempt += 1
                if DarkMessageBox.askyesno(
                    "Serverfehler - Wiederholen?", str(e), parent=self.dialog
                ):
                    self.start_summarize()
                else:
                    self._retry_attempt = 0
            else:
                DarkMessageBox.showerror(
                    "Serverfehler",
                    "Maximale Wiederholungen erreicht.",
                    parent=self.dialog,
                )
                self._retry_attempt = 0
            return

        self._retry_attempt = 0

        # ── UI für den Start vorbereiten ──────────────────────────
        self._set_ui_enabled(False)
        self._clear_summary_parts()
        self._set_full_summary("")
        if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
            self._safe_after(0, lambda: self.summary_text.delete("1.0", "end"))
            self._safe_after(
                0,
                lambda: self.summary_text.insert(
                    "1.0", "[Zusammenfassung wird erstellt...]"
                ),
            )
        self._request_cancel.clear()
        self._safe_after(0, lambda: self.progress_var.set(0))
        self._safe_after(0, lambda: self.progress_label.config(text="0%"))
        self._last_progress_update = time.time()

        effective_prompt = self.preview_text.get("1.0", "end-1c")
        use_structured = self.structured_var.get()
        strategy = self.strategy_var.get()
        temperature = self.temperature

        # ── Token‑Limit‑Prüfung ───────────────────────────────────
        prompt_tokens = self._estimate_tokens(effective_prompt)
        limit = self._get_model_context_limit()
        max_text_tokens = limit - prompt_tokens - 500
        original_text = self.text
        if max_text_tokens > 0:
            truncated_text = self._truncate_text_to_fit(
                self.text, max_text_tokens, add_notice=True
            )
            if truncated_text != self.text:
                self.text = truncated_text
                self._safe_after(
                    0,
                    lambda: self.status_label.config(
                        text="⚠️ Text wurde gekürzt, um ins Kontextfenster zu passen"
                    ),
                )
        else:
            self._safe_after(
                0,
                lambda: self.status_label.config(
                    text="❌ Prompt bereits zu lang – bitte Prompt kürzen"
                ),
            )
            self._reset_ui()
            return

        # ── Cache prüfen ──────────────────────────────────────────
        cached = self._get_cached(effective_prompt)
        if cached:
            self._set_full_summary(cached)
            self._apply_blacklist_to_summary()
            self._save_backup()
            self._update_readability_metrics(cached)
            self._add_to_history(cached)
            self.text = original_text
            self._safe_after(0, self._reset_ui)
            return

        # ── Hintergrund‑Worker starten ────────────────────────────
        def worker() -> None:
            """Führt die eigentliche Zusammenfassung aus und aktualisiert die GUI."""
            try:
                meth = (
                    self._summarize_refine
                    if strategy == "Genau (schrittweise)"
                    else self._summarize_map_reduce
                )
                result = meth(effective_prompt, temperature)
                if result and not self._request_cancel.is_set():
                    # Automatische Nachbesserung (mit eigenem Cancel‑Check)
                    regen = self._auto_regenerate(result, effective_prompt, temperature)
                    if regen:
                        result = regen
                    if use_structured:
                        result = json.dumps(
                            {
                                "summary": result,
                                "model": self.model,
                                "temperature": temperature,
                                "timestamp": datetime.now().isoformat(),
                            },
                            indent=2,
                            ensure_ascii=False,
                        )
                    self._set_full_summary(result)
                    self._apply_blacklist_to_summary()
                    self._cache_set(effective_prompt, result)
                    self._save_backup()
                    self._update_readability_metrics(result)
                    self._add_to_history(result)
                    self._safe_after(0, lambda: self.progress_var.set(100))
                    self._safe_after(0, lambda: self.progress_label.config(text="100%"))
                    self._safe_after(
                        0,
                        lambda: self.status_label.config(
                            text="✅ Zusammenfassung erstellt"
                        ),
                    )
                elif not self._request_cancel.is_set():
                    self._safe_after(
                        0,
                        lambda: self.status_label.config(
                            text="❌ Zusammenfassung fehlgeschlagen"
                        ),
                    )
            except Exception as e:
                err = str(e)[:80]
                log_debug("summarize", f"Worker Fehler: {e}", exc_info=True)
                self._safe_after(
                    0, lambda msg=err: self.status_label.config(text=f"❌ {msg}")
                )
            finally:
                # Text ggf. wiederherstellen
                if self.text != original_text:
                    self.text = original_text
                # UI in jedem Fall zurücksetzen (über _safe_after, um Widget‑Zerstörung abzufangen)
                self._safe_after(0, self._reset_ui)

        threading.Thread(
            target=worker, daemon=True, name=f"SummarizeWorker-{int(time.time())}"
        ).start()

    def _set_ui_enabled(self, enabled: bool) -> None:
        self.summarize_btn.config(state="normal" if enabled else "disabled")
        self.cancel_btn.config(state="disabled" if enabled else "normal")
        for b in (self.copy_btn, self.save_btn, self.translate_btn):
            if b:
                b.config(state="disabled")

    def _reset_ui(self) -> None:
        self.summarize_btn.config(state="normal", text="🚀 Zusammenfassen")
        self.cancel_btn.config(state="disabled")
        has = bool(self._get_full_summary())
        for b in (self.copy_btn, self.save_btn, self.translate_btn):
            if b:
                b.config(state="normal" if has else "disabled")
        if has and hasattr(self, "summary_text"):
            self.summary_text.delete("1.0", "end")
            self.summary_text.insert("1.0", self._get_full_summary())
        self.status_label.config(text="✅ Bereit")
        self.progress_var.set(0)
        self.progress_label.config(text="0%")

    def cancel_request(self) -> None:
        """
        Bricht eine laufende Zusammenfassung ab, sichert die bisherigen
        Teilergebnisse und setzt die UI zurück.
        Setzt den Nutzungszähler explizit auf 0, damit close() nicht blockiert.
        """
        self._request_cancel.set()

        with self._ollama_usage_lock:
            inst = self._ollama_instance
            if inst is not None:
                try:
                    inst.stop()
                except Exception as e:
                    log_debug("summarize", f"Fehler beim Stoppen von Ollama: {e}")
            # Alle Nutzungen als beendet markieren – der Kontextmanager wurde
            # nicht ordentlich beendet, also manuell zurücksetzen.
            self._ollama_usage_count = 0
            # notify_all wurde entfernt (nicht benötigt)

        parts = self._get_summary_parts()
        if parts:
            self._set_full_summary("".join(parts))
            self._apply_blacklist_to_summary()
            self._save_backup()

        self._safe_after(0, self._reset_ui)

    def _retry_summarize(self) -> None:
        self.start_summarize()

    def copy_summary(self) -> None:
        s = self._get_full_summary()
        if not s:
            return
        self.dialog.clipboard_clear()
        self.dialog.clipboard_append(s)
        self.status_label.config(text="✅ Kopiert")

    def save_summary(self) -> None:
        s = self._get_full_summary()
        if not s:
            return
        fn = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text", "*.txt"), ("JSON", "*.json")],
        )
        if not fn:
            return
        try:
            if fn.endswith(".json"):
                with open(fn, "w", encoding="utf-8") as f:
                    json.dump(
                        {
                            "summary": s,
                            "model": self.model,
                            "timestamp": datetime.now().isoformat(),
                        },
                        f,
                        indent=2,
                        ensure_ascii=False,
                    )
            else:
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(s)
            self.status_label.config(text=f"💾 {os.path.basename(fn)}")
        except Exception as e:
            self.status_label.config(text=f"❌ {e}")
            log_debug("summarize", f"Save error: {e}")

    def translate_summary(self) -> None:
        s = self._get_full_summary()
        if not s:
            return
        engine = getattr(self.gui, "translation_engine", None)
        if not engine or not engine.is_functional():
            self.status_label.config(text="⚠️ Übersetzung nicht verfügbar")
            return
        TranslationDialog(self.dialog, engine, self.gui, initial_text=s)

    def test_model(self) -> None:
        model = self.model_var.get().strip()
        if not model:
            self.status_label.config(text="❌ Kein Modell")
            return
        self.status_label.config(text="⏳ Teste …")

        def worker():
            try:
                with self._ollama_usage() as summarizer:
                    if not summarizer.is_server_reachable():
                        self._safe_after(
                            0,
                            lambda: self.status_label.config(
                                text="❌ Server nicht erreichbar"
                            ),
                        )
                        return
                    res = summarizer.summarize_sync(
                        "Antworte mit 'OK'.", "Antworte mit 'OK'.", 0.0
                    )
                    preview = (res or "")[:50] + ("…" if len(res or "") > 50 else "")
                    if "OK" in preview:
                        self._safe_after(
                            0, lambda: self.status_label.config(text="✅ Modell OK")
                        )
                    else:
                        self._safe_after(
                            0,
                            lambda p=preview: self.status_label.config(
                                text=f"⚠️ Antwort: {p}"
                            ),
                        )
            except Exception as e:
                err = str(e)[:80]
                log_debug("summarize", f"Test-model Fehler: {e}")
                self._safe_after(
                    0, lambda msg=err: self.status_label.config(text=f"❌ {msg}")
                )

        threading.Thread(target=worker, daemon=True).start()

    def _export_menu(self) -> None:
        menu = tk.Menu(self.dialog, tearoff=0)
        menu.add_command(
            label="Text (.txt)", command=lambda: self._export_summary("txt")
        )
        menu.add_command(
            label="JSON (.json)", command=lambda: self._export_summary("json")
        )
        if importlib.util.find_spec("docx"):
            menu.add_command(
                label="DOCX (.docx)", command=lambda: self._export_summary("docx")
            )
        if importlib.util.find_spec("reportlab"):
            menu.add_command(
                label="PDF (.pdf)", command=lambda: self._export_summary("pdf")
            )
        menu.add_command(
            label="Markdown (.md)", command=lambda: self._export_summary("md")
        )
        menu.add_command(
            label="HTML (.html)", command=lambda: self._export_summary("html")
        )
        menu.post(
            self.export_btn.winfo_rootx(),
            self.export_btn.winfo_rooty() + self.export_btn.winfo_height(),
        )

    def _export_summary(self, fmt: str) -> None:
        s = self._get_full_summary()
        if not s:
            DarkMessageBox.showwarning(
                "Keine Zusammenfassung", "Nichts zu exportieren."
            )
            return
        fn = filedialog.asksaveasfilename(
            defaultextension=f".{fmt}",
            filetypes=[(f"{fmt.upper()}", f"*.{fmt}")],
        )
        if not fn:
            return
        try:
            if fmt == "txt":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(s)
            elif fmt == "json":
                with open(fn, "w", encoding="utf-8") as f:
                    json.dump(
                        {
                            "summary": s,
                            "model": self.model,
                            "ts": datetime.now().isoformat(),
                        },
                        f,
                        indent=2,
                        ensure_ascii=False,
                    )
            elif fmt == "docx":
                from docx import Document

                doc = Document()
                doc.add_heading("Zusammenfassung", 0)
                doc.add_paragraph(s)
                doc.save(fn)
            elif fmt == "pdf":
                from reportlab.lib.pagesizes import A4
                from reportlab.lib.styles import getSampleStyleSheet
                from reportlab.platypus import Paragraph, SimpleDocTemplate

                doc = SimpleDocTemplate(fn, pagesize=A4)
                styles = getSampleStyleSheet()
                story = [Paragraph(s.replace("\n", "<br/>"), styles["Normal"])]
                doc.build(story)
            elif fmt == "md":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(f"# Zusammenfassung\n\n{s}")
            elif fmt == "html":
                with open(fn, "w", encoding="utf-8") as f:
                    f.write(f"<html><body><pre>{s}</pre></body></html>")
            self.status_label.config(text=f"✅ {os.path.basename(fn)}")
        except Exception as e:
            DarkMessageBox.showerror("Export fehlgeschlagen", str(e))
            log_debug("summarize", f"Export error: {e}")

    def _load_history(self) -> None:
        """Lädt den Zusammenfassungsverlauf aus der JSON‑Datei und begrenzt
        die In‑Memory‑Liste sofort auf ``_MAX_HISTORY_ENTRIES`` Einträge."""
        if self._history_file.exists():
            try:
                with open(self._history_file, "r", encoding="utf-8") as f:
                    self._history = json.load(f)
                # Nach dem Laden die Liste auf die Maximalgröße kürzen
                if len(self._history) > self._MAX_HISTORY_ENTRIES:
                    self._history = self._history[: self._MAX_HISTORY_ENTRIES]
                log_debug(
                    "summarize",
                    f"{len(self._history)} History-Einträge geladen (max. {self._MAX_HISTORY_ENTRIES})",
                )
            except Exception as e:
                log_debug("summarize", f"History-Datei beschädigt: {e}")
                self._history = []
        else:
            self._history = []

    def _save_history(self) -> None:
        """Speichert die letzten 50 Einträge des Verlaufs persistent."""
        try:
            self._history_file.parent.mkdir(parents=True, exist_ok=True)
            with open(self._history_file, "w", encoding="utf-8") as f:
                json.dump(self._history[:50], f, indent=2, ensure_ascii=False)
        except Exception as e:
            log_debug("summarize", f"History save error: {e}")

    def _add_to_history(self, summary: str) -> None:
        """Fügt eine Zusammenfassung dem Verlauf hinzu, speichert und
        begrenzt die In‑Memory‑Liste auf ``_MAX_HISTORY_ENTRIES``."""
        entry = {
            "ts": datetime.now().isoformat(),
            "model": self.model,
            "temperature": self.temperature,
            "language": self.language,
            "summary": summary,
            "source_title": self.stream_title,
            "source_length": len(self.text),
        }
        self._history.insert(0, entry)

        # In‑Memory‑Begrenzung (die Datei speichert ohnehin nur 50)
        if len(self._history) > self._MAX_HISTORY_ENTRIES:
            self._history = self._history[: self._MAX_HISTORY_ENTRIES]

        self._save_history()
        self._update_history_combobox()

    def _update_history_combobox(self) -> None:
        if not hasattr(self, "history_combo"):
            return
        values = []
        for e in self._history[:20]:
            title = e.get("source_title", "")[:30]
            s_len = e.get("source_length", 0)
            values.append(f"{e['ts'][:19]} | {title} | {s_len} Zeichen")
        self.history_combo["values"] = values
        if values:
            self.history_combo.current(0)

    def _on_history_selected(self, event=None) -> None:
        idx = self.history_combo.current()
        if 0 <= idx < len(self._history):
            entry = self._history[idx]
            self._set_full_summary(entry["summary"])
            if hasattr(self, "summary_text") and self.summary_text.winfo_exists():
                self.summary_text.delete("1.0", "end")
                self.summary_text.insert("1.0", entry["summary"])
                self._update_readability_metrics(entry["summary"])
            self.status_label.config(text=f"📜 Verlauf: {entry['ts'][:19]}")

    def _fetch_available_models(self, force: bool = False) -> None:
        now = time.time()
        if (
            not force
            and self._available_models
            and (now - self._model_fetch_timestamp) < self.MODEL_FETCH_TTL
        ):
            self._update_model_list(self._available_models)
            return
        if self._model_fetch_in_progress:
            return
        self._model_fetch_in_progress = True
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="⏳ Lade Modelle...")

        def worker():
            try:
                import requests as _requests
            except ImportError:
                self._safe_after(0, lambda: self._clear_model_status())
                self._model_fetch_in_progress = False
                return
            try:
                host = self.gui.advanced_settings.ollama_host.rstrip("/")
                resp = _requests.get(f"{host}/api/tags", timeout=5)
                if resp.status_code == 200:
                    data = resp.json()
                    models = [m["name"] for m in data.get("models", [])]
                    if models:
                        self._available_models = models
                        self._model_fetch_timestamp = time.time()
                        self._safe_after(0, lambda m=models: self._update_model_list(m))
                else:
                    log_debug(
                        "summarize",
                        f"Ollama‑Server antwortet mit HTTP {resp.status_code}",
                    )
            except Exception as e:
                log_debug("summarize", f"Modell‑Liste konnte nicht geladen werden: {e}")
            finally:
                self._safe_after(0, lambda: self._clear_model_status())
                self._model_fetch_in_progress = False

        threading.Thread(target=worker, daemon=True).start()

    def _clear_model_status(self) -> None:
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="")

    def _update_model_list(self, models: List[str]) -> None:
        if not hasattr(self, "model_combo"):
            return
        self.model_combo["values"] = models
        if self.model in models:
            self.model_var.set(self.model)
        elif models:
            self.model_var.set(models[0])
        if hasattr(self, "model_status_label") and self.model_status_label is not None:
            self.model_status_label.config(text="✅")

    @property
    def max_parallel_requests(self) -> int:
        return getattr(self.gui.advanced_settings, "summary_max_parallel_requests", 2)

    def _safe_after(
        self, delay: int, func: Callable, *args: Any, **kwargs: Any
    ) -> None:
        if self._destroyed or not self.dialog.winfo_exists():
            return
        self.dialog.after(delay, func, *args, **kwargs)

    def _is_destroyed(self) -> bool:
        return self._destroyed

    def _set_destroyed(self) -> None:
        self._destroyed = True

    def _bind_shortcuts(self) -> None:
        self.dialog.bind("<Control-s>", lambda e: self.save_summary())
        self.dialog.bind("<Escape>", lambda e: self.close())

    def _start_periodic_backup(self) -> None:
        """Startet den periodischen Backup‑Timer, falls der Dialog noch existiert."""
        if self._destroyed or not self.dialog or not self.dialog.winfo_exists():
            return

        def backup_worker():
            if self._destroyed or not self.dialog.winfo_exists():
                return
            if self._get_full_summary():
                self._save_backup()
            self._backup_timer = self.dialog.after(30000, backup_worker)

        self._backup_timer = self.dialog.after(30000, backup_worker)

    def _apply_combobox_font_to_dropdowns(self) -> None:
        """
        Setzt die Schriftart aller Combobox‑Dropdown‑Listen UND des
        sichtbaren Texteingabefelds auf Fonts.SMALL.
        """
        self.main.update_idletasks()
        for child in self.main.children.values():
            self._fix_combobox_recursive(child)

    def _fix_combobox_recursive(self, widget: tk.Widget) -> None:
        """Rekursiv alle Comboboxen finden und deren Schrift setzen."""
        if isinstance(widget, ttk.Combobox):
            # 1. Korrektur der dauerhaft sichtbaren Texteingabe
            try:
                widget.configure(font=Fonts.SMALL)
            except Exception:
                pass

            # 2. Korrektur der Dropdown‑Listbox beim Öffnen
            def _apply_font(event: tk.Event) -> None:
                try:
                    popdown = (
                        widget.tk.call(widget._w, "popdown")
                        if hasattr(widget, "_w")
                        else None
                    )
                    if popdown:
                        widget.tk.call(popdown, "configure", "-font", Fonts.SMALL)
                except Exception:
                    pass

            widget.bind("<Map>", _apply_font, add="+")
            return

        # Kinder des Widgets durchsuchen
        for child in widget.winfo_children():
            self._fix_combobox_recursive(child)

    def build_ui(self) -> None:
        """
        Endgültige, professionelle Oberfläche für den SummarizeDialog.

        **Schriftgrößen:**  Sämtliche Combobox‑Listboxen werden auf
        ``Fonts.SMALL`` gesetzt, damit sie zur restlichen Typografie passen.
        Die Combobox‑Breiten wurden für mehrsprachige Einträge leicht erhöht
        (``width=16``), um auch bei längeren Wörtern wie in der französischen
        oder spanischen Lokalisierung nicht abzuschneiden.

        **Prompt‑Test‑Ergebnis:**  Die Höhe beträgt ``height=4``, sodass auch
        etwas längere Antworten ohne sofortiges Scrollen lesbar sind.

        **Workflow:**  Die Bedienelemente sind in einem natürlichen
        Arbeitsablauf angeordnet: Einstellungen → Prompt → Starten →
        Ergebnis prüfen → Exportieren / Schließen.
        """
        # Nur die Zusammenfassung (Zeile 4) darf vertikal wachsen.
        self.main.grid_rowconfigure(4, weight=1)
