    def __init__(self, parent: tk.Tk, gui_ref: Any) -> None:
        """Initialisiert den InstallDependencyDialog vollständig und threadsicher."""
        self.gui = gui_ref
        self._stop_event = threading.Event()
        self._current_process: Optional[subprocess.Popen] = None
        self._process_lock = threading.RLock()
        self.in_venv = hasattr(sys, "real_prefix") or (
            hasattr(sys, "base_prefix") and sys.base_prefix != sys.prefix
        )
        self.platform = SYSTEM.lower()
        self.pkg_manager = self._detect_package_manager()
        self._closed = False
        self._active_threads: List[threading.Thread] = []
        self._active_threads_lock = threading.Lock()
        self._update_running = False
        self._vlc_installed = self._is_vlc_installed()
        self._tool_installed_cache: Dict[str, bool] = {}
        self.package_labels: List[Tuple[str, tk.Label]] = []
        self._prev_available: Dict[str, bool] = {}
        self._last_stderr: str = ""
        self._player_cache: Optional[List[Tuple[str, List[str]]]] = None
        self._player_cache_lock = threading.RLock()
        self._executor: Optional[ThreadPoolExecutor] = None
        self._executor_shutdown = False
        self._progress_callback: Optional[Callable[[int, str], None]] = None
        self._progress_timer: Optional[threading.Timer] = None

        # ── Basis‑Dialog initialisieren (erstellt das Fenster) ──────────────
        super().__init__(
            parent,
            "🐉 Abhängigkeiten installieren / aktualisieren",
            width=960,
            height=820,
            modal=True,
        )

        # ── Zusätzliche Initialisierungen nach dem Erstellen des Dialogs ────
        self._init_executor()
        self._bind_shortcuts()

        if DEBUG_LEVEL >= 3:
            log_debug(
                "install_dlg", "InstallDependencyDialog vollständig initialisiert"
            )

    def _check_pydantic_compatibility(
        self,
    ) -> Tuple[bool, Optional[str], Optional[str]]:
        """
        Prüft, ob pydantic und pydantic-core kompatibel sind.
        Verwendet importlib.metadata, um die installierten Versionen zu lesen.
        Gibt zurück: (is_compatible, pydantic_version, pydantic_core_version)
        """
        # ── 1. Versuche importlib.metadata (Python 3.8+) ────────────────
        try:
            from importlib.metadata import version as pkg_version

            try:
                pydantic_ver = pkg_version("pydantic")
            except Exception:
                pydantic_ver = None
            try:
                core_ver = pkg_version("pydantic-core")
            except Exception:
                core_ver = None
        except ImportError:
            # ── 2. Fallback: pkg_resources (veraltet, aber kompatibel) ──
            try:
                import pkg_resources

                pydantic_ver = pkg_resources.get_distribution("pydantic").version
                core_ver = pkg_resources.get_distribution("pydantic-core").version
            except Exception:
                return False, None, None

        # ── 3. Fehlen mindestens eines Pakets? ──────────────────────────
        if not pydantic_ver or not core_ver:
            return False, pydantic_ver, core_ver

        # ── 4. Build-Metadaten entfernen (z.B. "+cu118") ────────────────
        pydantic_base = pydantic_ver.split("+")[0]
        core_base = core_ver.split("+")[0]

        # ── 5. NUR die HAUPTVERSION (Major) vergleichen ────────────────
        pydantic_major = pydantic_base.split(".")[0]
        core_major = core_base.split(".")[0]

        if pydantic_major != core_major:
            return False, pydantic_ver, core_ver

        return True, pydantic_ver, core_ver

    def _repair_pydantic_compatibility(
        self,
        cancel_event: Optional[threading.Event] = None,
    ) -> bool:
        """
        Führt eine Aktualisierung von pydantic und pydantic-core durch,
        um die Kompatibilität wiederherzustellen.
        Gibt True bei Erfolg zurück, False bei Fehlschlag oder Abbruch.
        """
        # ── 1. Prüfung vor dem Update ──────────────────────────────────────
        self._append_output("\n🔧 Repariere Pydantic-Kompatibilität...\n")
        compatible, pv, cv = self._check_pydantic_compatibility()
        if compatible:
            self._append_output("✅ Bereits kompatibel.\n")
            return True

        if pv and cv:
            self._append_output(
                f"   Gefundene Versionen: pydantic={pv}, pydantic-core={cv}\n"
            )
        else:
            self._append_output("   Mindestens eines der Pakete fehlt.\n")

        # ── 2. Vorbereitung des pip-Befehls ────────────────────────────────
        python_exe = sys.executable
        supports_break = self._pip_supports_break_system()
        cmd_base = [python_exe, "-m", "pip", "install", "--upgrade"]

        # Optionen für venv vs. systemweit
        use_user = False
        use_break = False
        if not self.in_venv:
            if supports_break:
                use_break = True
            else:
                use_user = True

        # ── 3. Erster Versuch (mit --user oder --break-system-packages) ──
        cmd = cmd_base.copy()
        if use_break:
            cmd.append("--break-system-packages")
        elif use_user:
            cmd.append("--user")
        cmd += ["pydantic", "pydantic-core"]

        self._append_output(f"📦 Führe aus: {' '.join(cmd)}\n")

        # ── 4. Ausführung mit Wiederholungen bei temporären Fehlern ──────
        max_attempts = 2
        last_error = None

        for attempt in range(1, max_attempts + 1):
            if cancel_event and cancel_event.is_set():
                self._append_output("⏹️ Abbruch durch Benutzer.\n")
                return False

            success = self._run_subprocess(
                cmd,
                description=f"Pydantic-Update (Versuch {attempt}/{max_attempts})",
                timeout=120,
                stream_output=True,
                cancel_event=cancel_event,
            )

            if success:
                # Nach erfolgreichem Update nochmal prüfen
                compatible_after, pv_after, cv_after = (
                    self._check_pydantic_compatibility()
                )
                if compatible_after:
                    self._append_output(
                        "✅ Pydantic-Kompatibilität wiederhergestellt.\n"
                    )
                    self._append_output(
                        f"   Neue Versionen: pydantic={pv_after}, pydantic-core={cv_after}\n"
                    )
                    FastLazyLoader.clear_cache("pydantic")
                    FastLazyLoader.clear_cache("pydantic_core")
                    return True
                else:
                    self._append_output(
                        f"⚠️ Update schien erfolgreich, aber Kompatibilität bleibt: "
                        f"pydantic={pv_after}, core={cv_after}\n"
                    )
                    FastLazyLoader.clear_cache("pydantic")
                    FastLazyLoader.clear_cache("pydantic_core")
                    return False

            # Fehler beim Versuch
            last_error = (
                self._last_stderr
                if hasattr(self, "_last_stderr")
                else "Unbekannter Fehler"
            )
            if attempt < max_attempts:
                wait = 2.0 * attempt
                self._append_output(
                    f"   Fehler bei Versuch {attempt}: {last_error[:100]}...\n"
                )
                self._append_output(f"   Warte {wait:.1f}s vor nächstem Versuch...\n")
                if cancel_event and cancel_event.wait(wait):
                    self._append_output("⏹️ Abbruch während Wartezeit.\n")
                    return False

        # ── 5. Fallback: ohne spezielle Flags ──────────────────────────
        self._append_output(
            "❌ Reparatur fehlgeschlagen. Versuche alternativen Befehl ohne "
            "'--user'/'--break-system-packages'...\n"
        )
        fallback_cmd = [
            python_exe,
            "-m",
            "pip",
            "install",
            "--upgrade",
            "pydantic",
            "pydantic-core",
        ]
        self._append_output(f"📦 Führe aus: {' '.join(fallback_cmd)}\n")

        if cancel_event and cancel_event.is_set():
            self._append_output("⏹️ Abbruch durch Benutzer.\n")
            return False

        # Fallback mit verlängertem Timeout
        success_fallback = self._run_subprocess(
            fallback_cmd,
            description="Pydantic-Update (Fallback)",
            timeout=180,
            stream_output=True,
            cancel_event=cancel_event,
        )

        if success_fallback:
            compatible_after2, _, _ = self._check_pydantic_compatibility()
            if compatible_after2:
                self._append_output(
                    "✅ Pydantic-Kompatibilität mit Fallback-Befehl wiederhergestellt.\n"
                )
                FastLazyLoader.clear_cache("pydantic")
                FastLazyLoader.clear_cache("pydantic_core")
                return True
            else:
                self._append_output(
                    "⚠️ Fallback-Update schien erfolgreich, aber Kompatibilität bleibt.\n"
                )
                FastLazyLoader.clear_cache("pydantic")
                FastLazyLoader.clear_cache("pydantic_core")
                return False
        else:
            self._append_output(
                "❌ Auch Fallback fehlgeschlagen. Bitte manuell ausführen:\n"
            )
            cmd_manual = " ".join(cmd_base) + " pydantic pydantic-core"
            self._append_output(f"   {cmd_manual}\n")
            if hasattr(self, "_last_stderr"):
                self._append_output(f"   Fehlerdetails: {self._last_stderr[:200]}\n")
            return False

    def _check_pydantic_and_update_ui(self) -> None:
        """
        Prüft die Pydantic‑Kompatibilität und fügt bei Bedarf einen
        Reparatur‑Button in die Steuerleiste ein.
        """
        try:
            compatible, pv, cv = self._check_pydantic_compatibility()
        except Exception as e:
            logger.warning("Pydantic‑Kompatibilitätsprüfung fehlgeschlagen: %s", e)
            return

        if compatible:
            # Alles in Ordnung – keinen Button benötigt
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dlg",
                    "Pydantic‑Kompatibilität OK (pydantic=%s, core=%s)",
                    pv,
                    cv,
                )
            return

        # ── Inkompatibilität: Warnung ausgeben und Button hinzufügen ──────
        if pv and cv:
            warn_text = f"⚠️ Pydantic inkompatibel: pydantic={pv}, pydantic-core={cv}"
        else:
            warn_text = "⚠️ Pydantic oder pydantic-core nicht gefunden"
        self._append_output(f"\n{warn_text}\n")
        self._append_output(
            "   Klicken Sie auf '🔧 Pydantic reparieren', um das Problem zu beheben.\n"
        )

        # ── Button in der Steuerleiste (falls noch nicht vorhanden) ──────
        if not hasattr(self, "_pydantic_repair_btn"):
            # Erstelle einen separaten Frame für den Reparatur-Button
            repair_frame = tk.Frame(
                self.scrollable_frame, bg=self.gui.current_theme.BG_PRIMARY
            )
            repair_frame.pack(fill="x", pady=5)
            self._pydantic_repair_btn = tk.Button(
                repair_frame,
                text="🔧 Pydantic reparieren",
                command=self._repair_pydantic_compatibility,
                bg=self.gui.current_theme.WARNING,
                fg=self.gui.current_theme.TEXT_PRIMARY,
                font=Fonts.BUTTON,
                padx=10,
                cursor="hand2",
                activebackground=self.gui.current_theme.BG_HOVER,
                activeforeground=self.gui.current_theme.TEXT_ACCENT,
            )
            self._pydantic_repair_btn.pack(side="left", padx=5)
            ToolTip(
                self._pydantic_repair_btn,
                "Aktualisiert pydantic und pydantic-core auf kompatible Versionen.",
            )
        else:
            # Button bereits vorhanden – sicherstellen, dass er sichtbar ist
            try:
                self._pydantic_repair_btn.pack(side="left", padx=5)
            except Exception:
                pass

    # ── Hilfsmethode 2: _pip_supports_break_system ──────────────────────
    def _pip_supports_break_system(self) -> bool:
        """Prüft, ob die installierte pip-Version --break-system-packages unterstützt."""
        try:
            result = subprocess.run(
                [sys.executable, "-m", "pip", "--version"],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            if result.returncode == 0:
                version_str = result.stdout.split()[1] if result.stdout else "0"
                version = tuple(int(x) for x in version_str.split(".")[:2])
                return version >= (23, 0)
        except Exception:
            pass
        return False

    # ── Hilfsmethode 3: _run_subprocess_with_details ─────────────────────
    def _run_subprocess_with_details(
        self,
        cmd: List[str],
        description: str,
        timeout: int = 120,
        env: Optional[Dict[str, str]] = None,
        cancel_event: Optional[threading.Event] = None,
    ) -> Tuple[bool, str, str]:
        """
        Führt einen Subprozess aus und gibt (success, stdout, stderr) zurück.
        """
        if cancel_event and cancel_event.is_set():
            return False, "", "Abgebrochen durch Benutzer"

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=timeout,
                env=env or os.environ.copy(),
                check=False,
            )
            stdout = result.stdout.strip()
            stderr = result.stderr.strip()
            success = result.returncode == 0

            if success:
                self._append_output(f"✅ {description} erfolgreich\n")
            else:
                self._append_output(
                    f"❌ {description} fehlgeschlagen (Exit {result.returncode})\n"
                )
                if stderr:
                    self._append_output(f"   Fehler: {stderr[:200]}\n")

            return success, stdout, stderr

        except subprocess.TimeoutExpired:
            self._append_output(f"⏰ {description} Timeout nach {timeout}s\n")
            return False, "", f"Timeout nach {timeout}s"
        except Exception as e:
            self._append_output(f"❌ {description} unerwarteter Fehler: {e}\n")
            return False, "", str(e)

    # ─────────────────────────────────────────────────────────────────────
    # Hilfsmethoden für die Initialisierung
    # ─────────────────────────────────────────────────────────────────────
    def _init_executor(self) -> None:
        """Erstellt einen ThreadPoolExecutor für Hintergrundaufgaben."""
        if self._executor is None:
            cpu_count = os.cpu_count() or 2
            workers = max(1, cpu_count // 2)
            self._executor = ThreadPoolExecutor(
                max_workers=workers,
                thread_name_prefix="InstallDlgWorker",
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dlg", f"Executor mit {workers} Worker(s) initialisiert"
                )

    def _bind_shortcuts(self) -> None:
        """Bindet Tastenkürzel für den Dialog."""
        if self.dialog is None:
            return
        self.dialog.bind("<Escape>", lambda e: self.close())
        self.dialog.bind("<Control-c>", lambda e: self.cancel_installation())
        self.dialog.bind("<Control-w>", lambda e: self.close())

    @staticmethod
    def _detect_package_manager() -> str:
        """Erkennt den bevorzugten systemeigenen Paketmanager."""
        if IS_WINDOWS:
            return "winget" if shutil.which("winget") else "manual"
        if IS_MACOS:
            return "brew" if shutil.which("brew") else "manual"
        for manager, binary in [
            ("apt", "apt-get"),
            ("dnf", "dnf"),
            ("yum", "yum"),
            ("pacman", "pacman"),
            ("zypper", "zypper"),
            ("apk", "apk"),
        ]:
            if shutil.which(binary):
                return manager
        return "manual"

    def update_critical_packages(self) -> None:
        """
        Startet die Aktualisierung der kritischen Python‑Pakete in einem
        Hintergrund‑Thread, nachdem zuvor die pip‑Version ermittelt und
        die Benutzeroberfläche vorbereitet wurde.

        Verbesserungen (v4.3.2+):
        - Übergabe des `supports_break_system`‑Arguments an den Worker‑Thread,
          damit die Methode `_update_critical_worker` den Wert korrekt erhält.
        - Sicherheitsabfrage, ob der Dialog noch existiert, bevor UI‑Elemente
          manipuliert werden.
        - Verhindert doppelte Ausführung durch das Flag `_update_running`.
        - Detaillierte Fehlerbehandlung und Logging.
        - Stellt sicher, dass der Cancel‑Button während des Updates aktiviert wird.
        - Ermittelt `supports_break_system` dynamisch direkt vor dem Thread‑Start.
        - **NEU:** Nach Abschluss des Worker-Threads wird die Pydantic‑Kompatibilität
          automatisch geprüft und ggf. repariert (im Worker selbst bereits enthalten,
          aber hier wird zusätzlich die UI aktualisiert).
        """
        # ── 1. Grundlegende Gültigkeitsprüfungen ─────────────────────────
        try:
            if self._closed or not self.dialog.winfo_exists():
                return
        except tk.TclError:
            return

        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return

        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "Update kritischer Pakete gestartet")

        # ── 2. UI‑Elemente deaktivieren ─────────────────────────────────
        self._update_running = True

        if (
            hasattr(self, "update_critical_btn")
            and self.update_critical_btn is not None
            and self.update_critical_btn.winfo_exists()
        ):
            try:
                self.update_critical_btn.config(
                    state="disabled", text="⏳ Aktualisiere..."
                )
            except tk.TclError:
                pass

        self._enable_ui(False)

        if (
            hasattr(self, "cancel_btn")
            and self.cancel_btn is not None
            and self.cancel_btn.winfo_exists()
        ):
            try:
                self.cancel_btn.config(state="normal")
            except tk.TclError:
                pass

        # ── 3. Ausgabe der Paketliste ────────────────────────────────────
        self._append_output("\n⚠️ KRITISCHE PAKETE AKTUALISIEREN\n")
        for pkg in self.CRITICAL_PYTHON_PACKAGES:
            self._append_output(f"  • {pkg}\n")
        self._append_output("\n")

        # ── 4. `supports_break_system` dynamisch ermitteln ───────────────
        supports_break_system = False
        try:
            result = subprocess.run(
                [sys.executable, "-m", "pip", "--version"],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            if result.returncode == 0:
                pip_version_str = result.stdout.split()[1] if result.stdout else "0"
                pip_version = tuple(int(x) for x in pip_version_str.split(".")[:2])
                supports_break_system = pip_version >= (23, 0)
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "install",
                        f"pip version {pip_version_str}, supports_break_system={supports_break_system}",
                    )
        except Exception as e:
            logger.warning(
                f"Konnte pip‑Version nicht ermitteln: {e} – verwende supports_break_system=False"
            )

        # ── 5. Hintergrund‑Thread starten (mit korrektem Argument) ────────
        thread = threading.Thread(
            target=self._update_critical_worker,
            args=(supports_break_system,),
            daemon=True,
            name="InstallDependency-CriticalUpdateWorker",
        )

        try:
            with self._active_threads_lock:
                self._active_threads.append(thread)
            thread.start()
            if DEBUG_LEVEL >= 3:
                log_debug("install_dlg", "Kritischer Update‑Thread gestartet")
        except RuntimeError as exc:
            logger.error(
                "Kritischer Update-Thread konnte nicht gestartet werden: %s", exc
            )
            self._append_output(f"❌ Fehler beim Starten des Updates: {exc}\n")
            self._update_running = False
            self._enable_ui(True)
            if hasattr(self, "cancel_btn") and self.cancel_btn is not None:
                try:
                    self.cancel_btn.config(state="disabled")
                except tk.TclError:
                    pass
            return

        # ── 6. Warten auf das Ende des Worker-Threads (nicht blockierend) ──
        #    Das Ende wird durch die Worker-Methode selbst signalisiert.
        #    Hier wird nur der Status für den Benutzer aktualisiert, falls nötig.
        def _monitor_completion() -> None:
            """Wartet auf das Ende des Worker-Threads und aktualisiert die UI."""
            thread.join(timeout=0.0)  # Nicht blockieren, nur prüfen
            # Der Worker setzt selbst _update_running = False und aktiviert die UI.
            # Wir müssen hier nur sicherstellen, dass die UI nach einem unerwarteten
            # Ende des Threads wieder freigegeben wird.
            if thread.is_alive():
                # Nach einer Sekunde erneut prüfen (rekursiver Timer)
                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(1000, _monitor_completion)
            else:
                # Thread beendet – UI ist bereits im Worker freigegeben
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "install_dlg",
                        "Kritischer Update-Thread beendet, UI bereits zurückgesetzt",
                    )
                # Zusätzlich die Pydantic‑Reparatur im Hauptthread überprüfen (falls nötig)
                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(100, self._refresh_package_status)

        # Starte den Monitor nur, wenn der Thread gestartet wurde
        if self.dialog and self.dialog.winfo_exists():
            self.dialog.after(100, _monitor_completion)

        if DEBUG_LEVEL >= 3:
            log_debug(
                "install_dlg",
                "update_critical_packages abgeschlossen (Thread läuft im Hintergrund)",
            )

    @classmethod
    def _is_vlc_installed(cls) -> bool:
        """Prüft, ob VLC Media Player installiert ist."""
        cache_attr = "_vlc_installed_cache"
        cached = getattr(cls, cache_attr, None)
        if isinstance(cached, bool):
            return cached
        try:
            if shutil.which("vlc"):
                setattr(cls, cache_attr, True)
                return True
        except Exception:
            pass
        if IS_WINDOWS:
            typical_paths = [
                os.path.expandvars(r"%ProgramFiles%\VideoLAN\VLC\vlc.exe"),
                os.path.expandvars(r"%ProgramFiles(x86)%\VideoLAN\VLC\vlc.exe"),
                r"C:\Program Files\VideoLAN\VLC\vlc.exe",
                r"C:\Program Files (x86)\VideoLAN\VLC\vlc.exe",
            ]
            for path in typical_paths:
                if os.path.isfile(path):
                    setattr(cls, cache_attr, True)
                    return True
        setattr(cls, cache_attr, False)
        return False

    @staticmethod
    def _is_admin() -> bool:
        """
        Prüft, ob das Programm mit Administratorrechten (Windows) / root (Linux/macOS) läuft.

        Diese optimierte Version verwendet:
        - Caching des Ergebnisses, um wiederholte, teure Systemaufrufe zu vermeiden.
        - Plattformspezifische Implementierungen mit robusten Fallbacks.
        - Detaillierte Debug‑Ausgaben bei Bedarf.
        - Unter Unix zusätzliche Prüfung, ob sudo verwendet wurde (über Umgebungsvariablen).
        - Unter Windows eine alternative Abfrage über ctypes.windll.shell32.IsUserAnAdmin.

        Returns:
            True, wenn das Programm erhöhte Privilegien besitzt, sonst False.
        """
        # ── Cache (Klassenvariable) ─────────────────────────────────────────
        if not hasattr(InstallDependencyDialog, "_admin_cache"):
            InstallDependencyDialog._admin_cache = None

        if InstallDependencyDialog._admin_cache is not None:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "install_dlg",
                    f"_is_admin: Cache‑Treffer: {InstallDependencyDialog._admin_cache}",
                )
            return InstallDependencyDialog._admin_cache

        is_admin = False

        try:
            if IS_WINDOWS:
                # ── Windows: IsUserAnAdmin (Shell32) ───────────────────────
                try:
                    import ctypes

                    is_admin = ctypes.windll.shell32.IsUserAnAdmin() != 0
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "install_dlg",
                            f"Windows Admin Check: {is_admin} (via IsUserAnAdmin)",
                        )
                except (ImportError, AttributeError):
                    # Fallback: Prüfe, ob der Prozess mit erhöhten Token läuft
                    try:
                        import ctypes
                        import ctypes.wintypes

                        OpenProcessToken = ctypes.windll.advapi32.OpenProcessToken
                        GetTokenInformation = ctypes.windll.advapi32.GetTokenInformation
                        TOKEN_QUERY = 0x0008
                        TOKEN_ELEVATION = 20
                        TokenElevation = ctypes.c_ulong()

                        h_process = ctypes.windll.kernel32.GetCurrentProcess()
                        h_token = ctypes.wintypes.HANDLE()
                        if OpenProcessToken(
                            h_process, TOKEN_QUERY, ctypes.byref(h_token)
                        ):
                            size = ctypes.c_ulong(4)
                            if GetTokenInformation(
                                h_token,
                                TOKEN_ELEVATION,
                                ctypes.byref(TokenElevation),
                                size,
                                ctypes.byref(size),
                            ):
                                is_admin = TokenElevation.value != 0
                            ctypes.windll.kernel32.CloseHandle(h_token)
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "install_dlg",
                                f"Windows Admin Check (Fallback): {is_admin}",
                            )
                    except Exception as fallback_e:
                        logger.warning(
                            f"Konnte Admin‑Rechte nicht prüfen: {fallback_e}"
                        )
                        is_admin = False
            else:
                # ── Unix / Linux / macOS: effektive Benutzer-ID prüfen ──────
                try:
                    is_admin = os.geteuid() == 0
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "install_dlg", f"Unix Admin Check (euid=0): {is_admin}"
                        )

                    # Zusätzliche Prüfung: Falls nicht root, aber sudo ausgeführt?
                    # sudo setzt oft SUDO_USER oder SUDO_UID
                    if not is_admin and (
                        "SUDO_USER" in os.environ or "SUDO_UID" in os.environ
                    ):
                        # Der Benutzer hat sudo verwendet, aber das Skript läuft nicht mit root?
                        # Eigentlich sollte euid=0 sein, wenn sudo funktioniert.
                        # Trotzdem warnen.
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "install_dlg",
                                "SUDO_USER gefunden, aber euid != 0 – möglicherweise fehlerhafte sudo‑Konfiguration",
                            )
                except AttributeError:
                    # Fallback: Versuche os.getuid()
                    try:
                        is_admin = os.getuid() == 0
                        if DEBUG_LEVEL >= 3:
                            log_debug(
                                "install_dlg", f"Unix Admin Check (uid=0): {is_admin}"
                            )
                    except AttributeError:
                        logger.warning(
                            "Keine Möglichkeit, Admin‑Rechte unter Unix zu prüfen"
                        )
                        is_admin = False

        except Exception as e:
            logger.error(
                f"Fehler bei der Admin‑Prüfung: {e}", exc_info=DEBUG_LEVEL >= 3
            )
            is_admin = False

        # ── Ergebnis cachen ────────────────────────────────────────────────
        InstallDependencyDialog._admin_cache = is_admin
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", f"_is_admin: Ergebnis {is_admin} gecacht")

        return is_admin

    # ------------------------------------------------------------------
    # UI‑Aufbau
    # ------------------------------------------------------------------
    def build_ui(self) -> None:
        """
        Baut die Benutzeroberfläche des Installationsdialogs auf.
        Enthält jetzt eine automatische Pydantic‑Kompatibilitätsprüfung und
        einen Reparatur‑Button für den Fall einer Inkompatibilität.
        """
        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui gestartet")

        # ── 1. Theme sicher ermitteln ──────────────────────────────────────
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dlg", "CURRENT_THEME nicht verfügbar – verwende DarkTheme"
                )

        # ── 2. Hauptcontainer (scrollbar) ──────────────────────────────────
        canvas = tk.Canvas(self.main, bg=theme.BG_PRIMARY, highlightthickness=0)
        scrollbar = tk.Scrollbar(self.main, orient="vertical", command=canvas.yview)
        self.scrollable_frame = tk.Frame(canvas, bg=theme.BG_PRIMARY)

        self.scrollable_frame.bind(
            "<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )
        canvas.create_window((0, 0), window=self.scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        # ── 3. Einheitliche Mausrad‑Unterstützung (alle Plattformen) ──────
        def _on_mousewheel(event):
            """
            Behandelt das Mausrad plattformunabhängig.
            Windows/Mac: event.delta
            Linux: event.num (4 = hoch, 5 = runter)
            """
            try:
                if hasattr(event, "delta") and event.delta:
                    # Windows / macOS
                    scroll = int(-1 * (event.delta / 120))
                elif hasattr(event, "num"):
                    # Linux (X11)
                    if event.num == 4:
                        scroll = -1
                    elif event.num == 5:
                        scroll = 1
                    else:
                        scroll = 0
                else:
                    scroll = 0
                if scroll:
                    canvas.yview_scroll(scroll, "units")
            except Exception:
                pass
            return "break"

        # Bindings für alle relevanten Widgets (Canvas + innerer Frame)
        for widget in (canvas, self.scrollable_frame):
            widget.bind("<MouseWheel>", _on_mousewheel, add="+")
            widget.bind("<Button-4>", _on_mousewheel, add="+")
            widget.bind("<Button-5>", _on_mousewheel, add="+")

        # ── 4. Abschnitte aufbauen ──────────────────────────────────────────
        try:
            self._build_system_packages_section()
            self._build_python_packages_section()
            self._build_piper_voices_section()
            self._build_update_section()
            self._build_output_section()
            self._build_control_buttons()
        except Exception as e:
            logger.exception("Fehler beim Aufbau der UI‑Abschnitte: %s", e)
            # Fehler als Label anzeigen, damit der Dialog nicht leer bleibt
            error_label = tk.Label(
                self.scrollable_frame,
                text="⚠️ Fehler beim Laden der Oberfläche. Bitte Log prüfen.",
                bg=theme.BG_PRIMARY,
                fg=theme.ERROR,
                font=("Segoe UI", 10, "bold"),
            )
            error_label.pack(pady=20)

        # ── 5. Pydantic‑Kompatibilität prüfen und ggf. Button einblenden ──
        self._check_pydantic_and_update_ui()

        # ── 6. Status der Pakete aktualisieren ─────────────────────────────
        self._refresh_package_status()

        # ── 7. Layout finalisieren ─────────────────────────────────────────
        self.scrollable_frame.update_idletasks()
        canvas.configure(scrollregion=canvas.bbox("all"))

        if DEBUG_LEVEL >= 3:
            log_debug("install_dlg", "build_ui abgeschlossen")

    def _build_system_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        sys_frame = tk.LabelFrame(
            self.scrollable_frame,
            text="🖥️ Systempakete (externe Tools)",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_PRIMARY,
            font=(
                Fonts.SUBTITLE
                if hasattr(Fonts, "SUBTITLE")
                else ("Segoe UI", 10, "bold")
            ),
            padx=10,
            pady=5,
        )
        sys_frame.pack(fill="x", pady=5, padx=5)

        self.sys_vars: Dict[str, tk.BooleanVar] = {}
        for pkg_name, pkg_data in self.SYSTEM_PACKAGES.items():
            installed = self._is_tool_installed(pkg_name)
            if installed:
                tk.Label(
                    sys_frame,
                    text=f"✅ {pkg_name} (bereits installiert)",
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                ).pack(fill="x", pady=1)
                continue

            if not (
                self.pkg_manager in pkg_data
                or "pip" in pkg_data
                or "fallback" in pkg_data
            ):
                tk.Label(
                    sys_frame,
                    text=f"⚠️ {pkg_name} (nicht unterstützt auf diesem System)",
                    bg=theme.BG_SECONDARY,
                    fg=theme.WARNING,
                    anchor="w",
                ).pack(fill="x", pady=1)
                continue

            is_critical = pkg_name in self.CRITICAL_SYSTEM_PACKAGES
            var = tk.BooleanVar(value=is_critical)
            cb = tk.Checkbutton(
                sys_frame,
                text=f"{pkg_name} {'⚠️ kritisch' if is_critical else '(optional)'}",
                variable=var,
                bg=theme.BG_SECONDARY,
                fg=theme.TEXT_PRIMARY,
                selectcolor=theme.BG_TERTIARY,
                activebackground=theme.BG_HOVER,
                anchor="w",
            )
            cb.pack(fill="x", pady=1)
            self.sys_vars[pkg_name] = var
            tip = f"Installiert {pkg_name} über {self.pkg_manager or 'Fallback'}"
            if is_critical:
                tip += "\n(⚠️ Für den Betrieb zwingend erforderlich)"
            ToolTip(cb, tip)

        if not self.in_venv and not self._is_admin():
            tk.Label(
                sys_frame,
                text="⚠️  Sie installieren Pakete systemweit (kein venv).\n"
                "   Tipp: Verwenden Sie eine virtuelle Umgebung für mehr Sicherheit.",
                bg=theme.BG_SECONDARY,
                fg=theme.WARNING,
                font=Fonts.SMALL if hasattr(Fonts, "SMALL") else ("Segoe UI", 7),
                justify="left",
            ).pack(fill="x", pady=5)

        if IS_WINDOWS and self.pkg_manager == "winget" and not self._is_admin():
            tk.Button(
                sys_frame,
                text="🛡️ Als Administrator neu starten",
                command=self._restart_as_admin,
                bg=theme.WARNING,
                fg=theme.TEXT_PRIMARY,
                font=Fonts.BUTTON if hasattr(Fonts, "BUTTON") else ("Segoe UI", 9),
                padx=10,
                pady=5,
                cursor="hand2",
                activebackground=theme.DRAGON_GREEN,
            ).pack(pady=(5, 0))

    def _build_python_packages_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        py_frame = tk.LabelFrame(
            self.scrollable_frame,
            text="🐍 Python-Pakete (pip)",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_PRIMARY,
            font=(
                Fonts.SUBTITLE
                if hasattr(Fonts, "SUBTITLE")
                else ("Segoe UI", 10, "bold")
            ),
            padx=10,
            pady=5,
        )
        py_frame.pack(fill="x", pady=5, padx=5)

        left_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        left_col.pack(side="left", fill="both", expand=True, padx=5)
        right_col = tk.Frame(py_frame, bg=theme.BG_SECONDARY)
        right_col.pack(side="right", fill="both", expand=True, padx=5)

        self.py_vars: Dict[str, tk.BooleanVar] = {}
        self.package_labels.clear()
        half = len(self.PYTHON_PACKAGES) // 2
        for i, (pkg_name, display_text, check_func) in enumerate(self.PYTHON_PACKAGES):
            if pkg_name == "pywin32" and not IS_WINDOWS:
                continue
            target = left_col if i < half else right_col
            if not check_func():
                is_critical = pkg_name in self.CRITICAL_PYTHON_PACKAGES
                var = tk.BooleanVar(value=is_critical)
                cb = tk.Checkbutton(
                    target,
                    text=f"{display_text} {'⚠️' if is_critical else ''}",
                    variable=var,
                    bg=theme.BG_SECONDARY,
                    fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY,
                    activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.pack(fill="x", pady=1)
                self.py_vars[pkg_name] = var
                tip = f"Installiert {pkg_name} mit pip"
                if is_critical:
                    tip += "\n(⚠️ Für den Betrieb zwingend erforderlich)"
                ToolTip(cb, tip)
            else:
                lbl = tk.Label(
                    target,
                    text=f"✅ {display_text}",
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                )
                lbl.pack(fill="x", pady=1)
                self.package_labels.append((pkg_name, lbl))

    def _build_piper_voices_section(self) -> None:
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        voice_frame = tk.LabelFrame(
            self.scrollable_frame,
            text="🎤 Piper-Stimmen (hochwertige TTS)",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_PRIMARY,
            font=(
                Fonts.SUBTITLE
                if hasattr(Fonts, "SUBTITLE")
                else ("Segoe UI", 10, "bold")
            ),
            padx=10,
            pady=5,
        )
        voice_frame.pack(fill="x", pady=5, padx=5)

        info_label = tk.Label(
            voice_frame,
            text="💡 Fehlt eine Sprache? Sie können Stimmen manuell von Hugging Face herunterladen.\n"
            "   ℹ️ Bewegen Sie die Maus über diesen Text für eine Anleitung.",
            bg=theme.BG_SECONDARY,
            fg=theme.TEXT_SECONDARY,
            font=Fonts.SMALL if hasattr(Fonts, "SMALL") else ("Segoe UI", 7),
            justify="left",
        )
        info_label.pack(anchor="w", pady=(0, 5))

        tooltip_path = None
        try:
            if hasattr(TTSManager, "get_piper_cache_dir"):
                tooltip_path = TTSManager.get_piper_cache_dir()
            else:
                tooltip_path = os.path.join(
                    os.path.expanduser("~"),
                    ".cache" if not IS_WINDOWS else "AppData\\Roaming",
                    "piper",
                )
        except Exception:
            tooltip_path = os.path.join(os.path.expanduser("~"), "piper_models")
        manual_steps = (
            "Manuelle Installation:\n"
            "1. Besuchen Sie: https://huggingface.co/rhasspy/piper-voices\n"
            "2. Navigieren Sie zu Sprache / Sprecher / Qualität.\n"
            "3. Laden Sie .onnx und .onnx.json herunter.\n"
            "4. Speichern Sie beide Dateien in:\n"
            f"   {tooltip_path}\n"
            "Nach einem Neustart wird die Stimme erkannt."
        )
        ToolTip(info_label, manual_steps)

        voice_buttons_frame = tk.Frame(voice_frame, bg=theme.BG_SECONDARY)
        voice_buttons_frame.pack(fill="x")

        self.voice_vars: Dict[str, tk.BooleanVar] = {}
        cache_dir = TTSManager.get_piper_cache_dir()
        os.makedirs(cache_dir, exist_ok=True)

        row, col = 0, 0
        for voice_name, display_name in self.PIPER_VOICES.items():
            model_path = os.path.join(cache_dir, f"{voice_name}.onnx")
            json_path = os.path.join(cache_dir, f"{voice_name}.onnx.json")
            fully_installed = (
                os.path.exists(model_path)
                and os.path.getsize(model_path) > 0
                and os.path.exists(json_path)
                and os.path.getsize(json_path) > 0
            )

            if not fully_installed:
                var = tk.BooleanVar(value=False)
                cb = tk.Checkbutton(
                    voice_buttons_frame,
                    text=display_name,
                    variable=var,
                    bg=theme.BG_SECONDARY,
                    fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY,
                    activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.grid(row=row, column=col, sticky="w", padx=10, pady=2)
                self.voice_vars[voice_name] = var
                if os.path.exists(model_path) and os.path.getsize(model_path) > 0:
                    ToolTip(
                        cb,
                        "✅ Modell vorhanden, aber Konfigurationsdatei fehlt – wird nachgeladen",
                    )
                else:
                    ToolTip(cb, f"Lädt {voice_name} herunter (ca. 50-200 MB)")
            else:
                tk.Label(
                    voice_buttons_frame,
                    text=f"✅ {display_name}",
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                ).grid(row=row, column=col, sticky="w", padx=10, pady=2)
            col += 1
            if col > 2:
                col = 0
                row += 1

