    def _add_label_value(
        self, parent: tk.Widget, label: str, value: str, row: int
    ) -> None:
        """Fügt ein Label mit einem statischen Wert hinzu."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        tk.Label(
            parent,
            text=value,
            relief="sunken",
            width=15,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=1, sticky="w", pady=5, padx=5)

    def _add_labeled_spinbox(
        self,
        parent: tk.Widget,
        label: str,
        var: tk.Variable,
        from_val: float,
        to_val: float,
        row: int,
        tooltip: str,
    ) -> None:
        """Fügt eine beschriftete Spinbox hinzu und registriert sie für die Validierung."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        spin = tk.Spinbox(
            parent,
            from_=from_val,
            to=to_val,
            textvariable=var,
            width=self.SPINBOX_WIDTH,
            bg=self.gui.current_theme.BG_TERTIARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
            buttonbackground=self.gui.current_theme.BG_TERTIARY,
        )
        spin.grid(row=row, column=1, sticky="w", pady=5, padx=5)
        ToolTip(spin, tooltip)
        self._spinbox_vars[spin] = var

    def _add_labeled_scale(
        self,
        parent: tk.Widget,
        label: str,
        var: tk.DoubleVar,
        from_val: float,
        to_val: float,
        resolution: float,
        row: int,
        tooltip: str,
    ) -> None:
        """Fügt eine beschriftete ttk.Scale hinzu."""
        tk.Label(
            parent,
            text=label,
            anchor="w",
            bg=self.gui.current_theme.BG_SECONDARY,
            fg=self.gui.current_theme.TEXT_PRIMARY,
        ).grid(row=row, column=0, sticky="w", pady=5)
        scale, lbl = self._add_ttk_scale(parent, var, from_val, to_val, resolution)
        scale.grid(row=row, column=1, sticky="ew", pady=5, padx=5)
        lbl.grid(row=row, column=2, padx=5)
        ToolTip(scale, tooltip)

    def _add_ttk_scale(
        self,
        parent: tk.Widget,
        var: tk.DoubleVar,
        from_val: float,
        to_val: float,
        resolution: float,
    ):
        """
        Erstellt eine ttk.Scale mit zugehörigem Wertelabel.
        """
        try:
            theme = self.gui.current_theme
        except Exception:
            theme = DarkTheme()
        try:
            scale = ttk.Scale(
                parent,
                from_=from_val,
                to=to_val,
                variable=var,
                orient=tk.HORIZONTAL,
                length=self.SCALE_LENGTH,
            )
        except Exception as e:
            logger.error(f"Unerwarteter Fehler beim Erstellen der Scale: {e}")
            scale = tk.Label(parent, text="⚠️", bg="red", fg="white")

        try:
            value_label = tk.Label(
                parent,
                textvariable=var,
                width=5,
                bg=theme.BG_SECONDARY,
                fg=theme.TEXT_PRIMARY,
            )
        except Exception as e:
            logger.warning(f"Fehler beim Erstellen des Wertelabels: {e}")
            value_label = tk.Label(
                parent, text="?", bg=theme.BG_PRIMARY, fg=theme.TEXT_PRIMARY
            )

        def update_label(*args):
            try:
                current = var.get()
                value_label.config(text=f"{current:.2f}")
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("scale", f"update_label Fehler: {e}")

        try:
            var.trace_add("write", update_label)
        except Exception as e:
            logger.warning(f"trace_add für var fehlgeschlagen: {e}")

        return scale, value_label

