        def open_install_dialog_and_refresh():
            """Öffnet den Installationsdialog und aktualisiert die Statusanzeige,
            sobald der Dialog geschlossen wird – **ohne** den Hauptthread zu blockieren.
            """
            dlg = InstallDependencyDialog(self.dialog, self.gui)

            # Registriere Callback für das Schließen des Dialogs
            def _on_dialog_closed():
                self._on_packages_installed()
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "packages_tab", "Paket‑Status nach Installation aktualisiert"
                    )

            # Protokolliere Fenster‑Schließen (über 'X')
            dlg.dialog.protocol(
                "WM_DELETE_WINDOW", lambda: (dlg.close(), _on_dialog_closed())
            )
            # Überschreibe die close‑Methode, damit auch der "Schließen"‑Button den Refresh auslöst
            original_close = dlg.close

            def _close_and_refresh():
                original_close()
                _on_dialog_closed()

            dlg.close = _close_and_refresh

