    def _setup_callbacks(self) -> None:
        """Platzhalter für zusätzliche Callbacks (z. B. für Plugins)."""

    def _setup_validation_styles(self) -> None:
        """Erstellt ttk‑Styles für Validierungsfehler."""
        style = ttk.Style()
        style.configure("Danger.TSpinbox", fieldbackground="#ffcccc")
        style.configure("Danger.TEntry", fieldbackground="#ffcccc")
        style.configure("Danger.TCombobox", fieldbackground="#ffcccc")

    def _bind_validation_recursive(self, widget: tk.Widget) -> None:
        """
        Bindet Validierungsfunktionen an alle numerischen Widgets im Widget-Baum.
        """
        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return

        try:
            if isinstance(widget, (tk.Spinbox, tk.Entry, ttk.Entry)):
                var = self._spinbox_vars.get(widget)
                if var is not None and isinstance(var, (tk.DoubleVar, tk.IntVar)):
                    min_val, max_val = self._get_spinbox_range(widget)
                    is_int = isinstance(var, tk.IntVar)

                    def _on_focus_in(event, w=widget, v=var):
                        try:
                            w._saved_value = v.get()
                        except Exception:
                            pass

                    widget.bind("<FocusIn>", _on_focus_in, add="+")

                    def _on_focus_out(
                        event, w=widget, v=var, mn=min_val, mx=max_val, ii=is_int
                    ):
                        self._validate_numeric_input(w, v, mn, mx, ii)

                    widget.bind("<FocusOut>", _on_focus_out, add="+")
        except tk.TclError:
            pass
        except Exception as e:
            logger.warning(f"Fehler beim Binden der Validierung für {widget}: {e}")
        try:
            for child in widget.winfo_children():
                self._bind_validation_recursive(child)
        except tk.TclError:
            pass

    def _get_spinbox_range(self, spin: tk.Spinbox) -> Tuple[float, float]:
        """Ermittelt den gültigen Bereich einer Spinbox."""
        try:
            from_val = float(spin.cget("from"))
            to_val = float(spin.cget("to"))
            return from_val, to_val
        except Exception:
            return -float("inf"), float("inf")

    def _validate_numeric_input(
        self,
        widget: tk.Widget,
        var: tk.Variable,
        min_val: float,
        max_val: float,
        is_int: bool = False,
    ) -> bool:
        """
        Validiert eine numerische Eingabe und stellt bei Fehlern den letzten gültigen Wert wieder her.
        """
        try:
            raw = var.get()
        except tk.TclError:
            self._show_validation_error(widget, "Wert kann nicht gelesen werden")
            self.dialog.bell()
            return False

        saved = getattr(widget, "_saved_value", None)
        try:
            value = int(raw) if is_int else float(raw)
        except (ValueError, TypeError, OverflowError):
            if saved is not None:
                try:
                    var.set(saved)
                except tk.TclError:
                    pass
                self._clear_validation_error(widget)
            else:
                self._show_validation_error(widget, "Ungültige Zahl")
            self.dialog.bell()
            return False

        if not (min_val <= value <= max_val):
            if saved is not None:
                try:
                    var.set(saved)
                except tk.TclError:
                    pass
                self._clear_validation_error(widget)
            else:
                self._show_validation_error(
                    widget, f"Wert muss zwischen {min_val} und {max_val} liegen"
                )
            self.dialog.bell()
            return False

        self._clear_validation_error(widget)
        return True

    def _validate_suppress_tokens(self, value: str) -> bool:
        """
        Validiert das Format des Feldes ``suppress_tokens``.
        """
        if value is None:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_tokens: value ist None → gültig (-1)",
                )
            return True

        if not isinstance(value, str):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: value ist kein String (Typ {type(value).__name__}) → ungültig",
                )
            return False

        stripped = value.strip()
        if not stripped:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate", "_validate_suppress_tokens: leerer String → gültig (-1)"
                )
            return True

        if stripped == "-1":
            if DEBUG_LEVEL >= 4:
                log_debug("validate", "_validate_suppress_tokens: '-1' → gültig")
            return True
        parts = [p.strip() for p in stripped.split(",")]
        if "" in parts:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: leere Elemente in '{stripped}' → ungültig",
                )
            return False
        try:
            tokens = [int(part) for part in parts]
        except (ValueError, OverflowError) as e:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: Konvertierungsfehler '{stripped}' → {e}",
                )
            return False
        if any(t < 0 for t in tokens):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: negative Werte in '{stripped}' → ungültig",
                )
            return False
        if DEBUG_LEVEL >= 4:
            log_debug(
                "validate",
                f"_validate_suppress_tokens: '{stripped}' → {len(tokens)} Token(s), gültig",
            )
        return True

    def _validate_suppress_field(self) -> None:
        """
        Validiert das »Suppress Tokens«‑Eingabefeld bei Fokusverlust und
        markiert es bei ungültigen Eingaben rot.  Die Methode ist robust
        gegen den Fall, dass das zugehörige Widget (noch) nicht existiert
        (Lazy Loading des Tabs »Erweitert & System«).

        Verbesserungen (v2.0):
        - Prüft den gültigen Bereich der Token‑IDs (0‑50256) für Whisper.
        - Bietet detaillierte Fehlermeldungen bei Bereichsüberschreitungen.
        - Verwendet eine zentrale Konstante für die maximale Token‑ID.
        - Behandelt leere Felder und den Spezialfall '-1' korrekt.
        - Thread‑sicher und defensiv gegen fehlende Widgets.
        """
        # ── 1. Konstante für maximalen Token‑ID‑Bereich ─────────────────────
        WHISPER_MAX_TOKEN_ID = 50256  # Standard‑Token‑Vokabular von Whisper

        widget = getattr(self, "suppress_entry", None)
        if widget is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: suppress_entry widget nicht vorhanden – Abbruch",
                )
            return

        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        "_validate_suppress_field: suppress_entry widget existiert nicht mehr – Abbruch",
                    )
                return
        except (tk.TclError, AttributeError):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: TclError/AttributeError bei winfo_exists – Abbruch",
                )
            return

        try:
            tokens_str = self.suppress_tokens_var.get().strip()
        except tk.TclError:
            logger.warning("_validate_suppress_field: suppress_tokens_var nicht lesbar")
            return

        # ── 2. Leeres Feld → gültig (bedeutet -1) ──────────────────────────
        if not tokens_str:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_field: leeres Feld → als -1 interpretiert, gültig",
                )
            return

        # ── 3. Validierung durchführen ──────────────────────────────────────
        is_valid, error_msg = self._validate_suppress_tokens(
            tokens_str,
            min_token=0,
            max_token=WHISPER_MAX_TOKEN_ID,
        )

        if is_valid:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_field: gültig – '%s'",
                    tokens_str[:60],
                )
        else:
            # ── 4. Fehlermeldung zusammenbauen ──────────────────────────────
            if error_msg:
                msg = f"Ungültige Eingabe: {error_msg}\n\n"
            else:
                msg = "Ungültiges Format.\n\n"
            msg += (
                "Erwartet wird eine kommagetrennte Liste von Token‑IDs "
                "im Bereich 0‑50256.\n"
                "Beispiele: -1  oder  1,2,3  oder  10-20,100\n"
                "Hinweis: -1 bedeutet Standard‑Unterdrückung (empfohlen)."
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: ungültig – '%s' → %s",
                    tokens_str[:60],
                    error_msg,
                )
            self._show_validation_error(widget, msg)

    def _validate_suppress_tokens(
        self,
        token_str: str,
        min_token: int = 0,
        max_token: int = 50256,
    ) -> Tuple[bool, str]:
        """
        Validiert einen kommagetrennten String von Token‑IDs und optionalen Bereichen.

        Verbesserungen (v2.0):
        - Prüft, ob jede einzelne Token‑ID im gültigen Bereich [min_token, max_token] liegt.
        - Unterstützt Bereiche (z.B. "10-20") und einzelne IDs.
        - Liefert eine aussagekräftige Fehlermeldung bei ungültigen Werten.
        - Erkennt und meldet Duplikate (optional – hier ignoriert).
        - Robust gegen führende/trailende Leerzeichen und leere Elemente.
        - Berücksichtigt den Spezialfall "-1" (Standardunterdrückung) als gültig.

        Args:
            token_str: Der zu validierende String (z.B. "1,2,3" oder "10-20").
            min_token: Minimal erlaubte Token‑ID (inklusive).
            max_token: Maximal erlaubte Token‑ID (inklusive).

        Returns:
            Tuple[bool, str]: (is_valid, error_message)
        """
        # ── 1. Leerer String oder "-1" → sofort gültig ──────────────────────
        if not token_str or token_str.strip() == "-1":
            return True, ""

        # ── 2. String in einzelne Teile zerlegen ─────────────────────────────
        parts = [p.strip() for p in token_str.split(",") if p.strip()]
        if not parts:
            return False, "Keine Token‑IDs angegeben."

        # ── 3. Hilfsfunktion für Bereichsvalidierung ─────────────────────────
        def validate_token_id(value: int) -> Tuple[bool, str]:
            if value < min_token:
                return False, f"Token {value} ist kleiner als {min_token}."
            if value > max_token:
                return False, f"Token {value} ist größer als {max_token}."
            return True, ""

        # ── 4. Jedes Teil validieren ──────────────────────────────────────────
        for part in parts:
            # 4a. Bereich (z.B. "10-20")
            if "-" in part and not part.startswith("-"):
                try:
                    start_str, end_str = part.split("-", 1)
                    start = int(start_str.strip())
                    end = int(end_str.strip())
                except ValueError:
                    return False, f"Ungültiger Bereich: '{part}' – keine ganzen Zahlen."

                if start < min_token or start > max_token:
                    return (
                        False,
                        f"Startwert {start} außerhalb des gültigen Bereichs [{min_token}, {max_token}].",
                    )
                if end < min_token or end > max_token:
                    return (
                        False,
                        f"Endwert {end} außerhalb des gültigen Bereichs [{min_token}, {max_token}].",
                    )
                if start > end:
                    return False, f"Startwert {start} ist größer als Endwert {end}."

                # Optional: Prüfen, ob der Bereich zu groß ist (> 10000 Elemente)
                if end - start > 10000:
                    return (
                        False,
                        f"Bereich '{part}' umfasst über 10000 Token – zu groß.",
                    )

            # 4b. Einzelne ID
            else:
                try:
                    token_id = int(part)
                except ValueError:
                    return False, f"Ungültige Token‑ID: '{part}' – keine ganze Zahl."

                valid, msg = validate_token_id(token_id)
                if not valid:
                    return False, msg

        # ── 5. Alle Prüfungen bestanden ──────────────────────────────────────
        return True, ""

    def _validate_proxy_url(self, url: str) -> bool:
        """Prüft, ob die Proxy‑URL ein gültiges Schema und netloc hat."""
        if not url:
            return False
        try:
            parsed = urllib.parse.urlparse(url)
            return parsed.scheme in ("http", "https", "socks4", "socks5") and bool(
                parsed.netloc
            )
        except Exception:
            return False

    def _validate_proxy_field(self) -> None:
        """Validiert die Proxy‑URL bei Fokusverlust und markiert das Feld bei
        ungültigen Eingaben rot.  Die Methode ist robust gegen den Fall,
        dass das zugehörige Widget (noch) nicht existiert (Lazy Loading
        des Tabs »Erweitert & System«)."""
        widget = getattr(self, "proxy_entry", None)
        if widget is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: proxy_entry widget nicht vorhanden – Abbruch",
                )
            return
        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        "_validate_proxy_field: proxy_entry widget existiert nicht mehr – Abbruch",
                    )
                return
        except (tk.TclError, AttributeError):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: TclError/AttributeError bei winfo_exists – Abbruch",
                )
            return
        try:
            proxy_enabled = self.proxy_enabled_var.get()
        except tk.TclError:
            logger.warning("_validate_proxy_field: proxy_enabled_var nicht lesbar")
            return
        try:
            url = self.proxy_var.get().strip()
        except tk.TclError:
            logger.warning("_validate_proxy_field: proxy_var nicht lesbar")
            return
        if not proxy_enabled or not url:
            self._clear_validation_error(widget)
            return
        is_valid = self._validate_proxy_url(url)
        if is_valid:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_proxy_field: gültig – '%s'",
                    url[:60],
                )
        else:
            try:
                parsed = urllib.parse.urlparse(url)
                if not parsed.scheme:
                    msg = (
                        "Ungültiges URL‑Schema. Erlaubt sind:\n"
                        "http, https, socks4, socks5."
                    )
                elif not parsed.netloc:
                    msg = (
                        "Proxy‑Adresse enthält keinen Hostnamen.\n"
                        "Beispiel: socks5://127.0.0.1:18080"
                    )
                else:
                    msg = (
                        "Proxy‑URL ist ungültig. Bitte Format prüfen.\n"
                        "Beispiel: socks5://127.0.0.1:18080"
                    )
            except Exception:
                msg = "Proxy‑URL ist ungültig. Bitte Format prüfen."
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: ungültig – '%s'",
                    url[:60],
                )
            self._show_validation_error(widget, msg)

    def _show_validation_error(
        self,
        widget: tk.Widget,
        message: str,
        play_bell: bool = True,
    ) -> None:
        """
        Markiert ein Widget visuell als fehlerhaft und speichert die
        zugehörige Fehlermeldung im internen ``_validation_errors``‑Dictionary.
        """
        self._validation_errors[widget] = message

        if DEBUG_LEVEL >= 4:
            log_debug(
                "validate",
                f"_show_validation_error: widget={widget!r}, "
                f"msg='{message}', bell={play_bell}",
            )

        if play_bell:
            try:
                if hasattr(self, "dialog") and self.dialog.winfo_exists():
                    self.dialog.bell()
                else:
                    widget.bell()
            except (tk.TclError, AttributeError):
                pass
            except Exception as e:
                logger.warning(f"_show_validation_error: bell() fehlgeschlagen: {e}")

        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        f"Widget {widget!r} existiert nicht mehr – "
                        "überspringe visuelle Markierung",
                    )
                return
        except tk.TclError:
            return

        ERROR_BG = "#ffcccc"

        try:
            if isinstance(widget, tk.Spinbox):
                widget.config(bg=ERROR_BG)

            elif isinstance(widget, ttk.Entry):
                widget.configure(style="Danger.TEntry")

            elif isinstance(widget, ttk.Combobox):
                style = ttk.Style()
                style.configure("Danger.TCombobox", fieldbackground=ERROR_BG)
                widget.configure(style="Danger.TCombobox")

            elif isinstance(widget, tk.Entry):
                widget.config(bg=ERROR_BG)

            elif isinstance(widget, tk.Text):
                widget.config(bg=ERROR_BG)

            else:
                try:
                    widget.config(bg=ERROR_BG)
                except tk.TclError:
                    pass

        except tk.TclError:
            pass
        except Exception as e:
            logger.warning(
                f"_show_validation_error: Fehler bei visueller Markierung "
                f"von {widget}: {e}"
            )
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "validate",
                    "show_validation_error visual mark failed",
                    e,
                    level="debug",
                )

    def _clear_validation_error(self, widget: tk.Widget) -> None:
        """
        Entfernt die visuelle Fehlermarkierung von einem Widget und löscht
        den zugehörigen Eintrag aus dem internen ``_validation_errors``‑Dictionary.
        """
        if widget in self._validation_errors:
            removed_msg = self._validation_errors.pop(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    f"_clear_validation_error: Fehler für {widget!r} "
                    f"entfernt (Meldung='{removed_msg}')",
                )
        else:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    f"_clear_validation_error für {widget!r} aufgerufen, "
                    "aber kein Fehlereintrag vorhanden",
                )

        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return

        try:
            theme = self.gui.current_theme
            normal_bg = getattr(theme, "BG_TERTIARY", "#f0f0f0")
            input_bg = getattr(
                theme, "INPUT_BG", getattr(theme, "BG_TERTIARY", "#f0f0f0")
            )
        except Exception:
            normal_bg = "#f0f0f0"
            input_bg = "#f0f0f0"

        try:
            if isinstance(widget, tk.Spinbox):
                widget.config(bg=normal_bg)

            elif isinstance(widget, ttk.Entry):
                widget.state(["!invalid"])
                widget.configure(style="TEntry")

            elif isinstance(widget, ttk.Combobox):
                widget.configure(style="Dark.TCombobox")

            elif isinstance(widget, tk.Entry):
                widget.config(bg=input_bg)

            elif isinstance(widget, tk.Text):
                widget.config(bg=input_bg)

            else:
                try:
                    widget.config(bg=input_bg)
                except tk.TclError:
                    pass

        except tk.TclError:
            pass
        except Exception as e:
            logger.warning(
                f"_clear_validation_error: Fehler bei visueller "
                f"Zurücksetzung von {widget}: {e}"
            )
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "validate",
                    "clear_validation_error visual reset failed",
                    e,
                    level="debug",
                )

    def _on_search_changed(self) -> None:
        """
        Reagiert auf Änderungen im Suchfeld.  Durchsucht zuerst die bereits
        geladenen Tabs und anschließend den Index der noch nicht geladenen
        Tabs.
        """
        raw = self._search_text.get()
        term = raw.strip().lower() if raw else ""

        if not term:
            if DEBUG_LEVEL >= 4:
                log_debug("search", "_on_search_changed: kein Suchtext – Abbruch")
            return

        if DEBUG_LEVEL >= 3:
            log_debug("search", f"_on_search_changed: term='{term}'")

        try:
            tab_ids = self.notebook.tabs()
        except tk.TclError:
            if DEBUG_LEVEL >= 3:
                log_debug("search", "  notebook.tabs() fehlgeschlagen – Abbruch")
            return

        for tab_id in tab_ids:
            try:
                tab_widget = self.notebook.nametowidget(tab_id)
            except tk.TclError:
                continue

            if self._widget_contains_text(tab_widget, term):
                tab_idx = self.notebook.index(tab_id)
                self.notebook.select(tab_idx)
                self._flash_tab(tab_idx)
                self._highlight_search_widget(tab_widget, term)
                if DEBUG_LEVEL >= 3:
                    tab_text = self.notebook.tab(tab_id, "text")
                    log_debug("search", f"  Treffer in geladenem Tab '{tab_text}'")
                return

        idx = getattr(self, "_search_index", None)
        if idx is None:
            if DEBUG_LEVEL >= 3:
                log_debug("search", "  Kein _search_index vorhanden – Ende")
            return

        for tab_name, texts in idx.items():
            if tab_name in self._loaded_tabs:
                continue

            if any(term in t.lower() for t in texts):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "search",
                        f"  Index-Treffer für Tab '{tab_name}' – löse Lazy Load aus",
                    )

                tab_widget = self._get_tab_widget_by_name(tab_name)
                if tab_widget is None:
                    continue

                try:
                    pos = self.notebook.index(tab_widget)
                except tk.TclError:
                    continue

                self.notebook.select(pos)
                self._flash_tab(pos)

                def _highlight_after_load(tab=tab_widget, t=term):
                    self._highlight_search_widget(tab, t)

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(50, _highlight_after_load)

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(100, self._on_search_changed)

                return

        if DEBUG_LEVEL >= 3:
            log_debug("search", "  Kein Treffer im Index")

    def _add_to_search_index(self, tab_name: str, texts: List[str]) -> None:
        """
        Fügt dem internen Suchindex statische Texte für ein Tab hinzu.
        """
        if not tab_name:
            logger.warning("_add_to_search_index: leerer tab_name – ignoriert")
            return
        if not texts:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "search", f"_add_to_search_index: '{tab_name}' – leere Textliste"
                )
            return

        if tab_name in self._loaded_tabs:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search",
                    f"_add_to_search_index: Tab '{tab_name}' bereits geladen – "
                    "Indexeintrag wird nicht mehr benötigt",
                )
            return

        idx: Dict[str, List[str]] = getattr(self, "_search_index", None)
        if idx is None:
            self._search_index = {}
            idx = self._search_index
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search", "_add_to_search_index: _search_index neu initialisiert"
                )

        normalized = [t.strip().lower() for t in texts if t and t.strip()]
        if not normalized:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "search",
                    f"_add_to_search_index: '{tab_name}' – keine gültigen Texte nach Normalisierung",
                )
            return

        if tab_name not in idx:
            idx[tab_name] = []
        before = len(idx[tab_name])
        idx[tab_name].extend(normalized)
        after = len(idx[tab_name])

        if DEBUG_LEVEL >= 3:
            log_debug(
                "search",
                f"_add_to_search_index: '{tab_name}' +{after - before} Begriffe → {after} insgesamt",
            )

    def _get_tab_widget_by_name(self, name: str) -> Optional[tk.Widget]:
        """Liefert das zu einem internen Tab‑Namen gehörende Frame-Widget."""
        try:
            return getattr(self, f"tab_{name}")
        except AttributeError:
            if DEBUG_LEVEL >= 3:
                log_debug("search", f"  Kein Widget für Tab '{name}'")
            return None

    def _widget_contains_text(self, widget: tk.Widget, term: str) -> bool:
        """Rekursiv prüfen, ob ein Widget oder seine Kinder den Suchbegriff enthalten."""
        if isinstance(widget, (tk.Label, tk.Checkbutton, tk.Radiobutton, tk.Button)):
            if term in widget.cget("text").lower():
                return True
        elif isinstance(widget, (tk.Entry, ttk.Entry, tk.Spinbox, ttk.Combobox)):
            try:
                if term in widget.get().lower():
                    return True
            except tk.TclError:
                pass
        for child in widget.winfo_children():
            if self._widget_contains_text(child, term):
                return True
        return False

    def _flash_tab(self, tab_idx: int) -> None:
        """Hebt das ausgewählte Tab kurz hervor."""
        style = ttk.Style()
        style.configure("Flash.TNotebook.Tab", background="#ffff99")
        self.notebook.tab(tab_idx, style="Flash.TNotebook.Tab")
        self.dialog.after(
            300, lambda: self.notebook.tab(tab_idx, style="TNotebook.Tab")
        )

    def _show_advanced_search(self) -> None:
        """
        Öffnet einen Hinweis‑Dialog, der die Bedienung der Suche erklärt.
        Der aktuelle Suchtext (falls vorhanden) wird in die Meldung
        übernommen, sodass der Anwender ihn nicht erneut eintippen muss.
        """
        term = self._search_text.get().strip()
        info = (
            "Geben Sie einen Suchbegriff ein und drücken Sie die Eingabetaste.\n"
            "Alle Labels, Tooltips und Eingabefelder werden durchsucht.\n"
            "Bei einem Treffer wird das entsprechende Tab geöffnet und das\n"
            "erste passende Widget kurz hervorgehoben.\n\n"
            "Tipp: Verwenden Sie die Suche, um schnell zu einer bestimmten\n"
            "Einstellung zu springen (z. B. 'Proxy', 'VAD', 'Beam Size')."
        )
        if term:
            info = f"Aktuelle Suche: »{term}«\n\n{info}"

        try:
            DarkMessageBox.showinfo(
                "Erweiterte Suche",
                info,
                parent=self.dialog,
                timeout=30,
            )
        except Exception as e:
            logger.warning(
                "_show_advanced_search: Dialog konnte nicht geöffnet werden – %s\n%s",
                e,
                info,
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search",
                    f"_show_advanced_search: Fallback auf Log-Ausgabe wegen {e}",
                )

    def _highlight_search_widget(self, parent_widget: tk.Widget, term: str) -> None:
        """
        Sucht rekursiv (iterativ) im Widget‑Baum ab *parent_widget* nach
        einem Steuerelement, dessen sichtbarer Text den Suchbegriff
        *term* enthält, und hebt das erste gefundene Widget kurz optisch
        hervor (gelber Hintergrund), um dem Benutzer die Navigation zu
        erleichtern.
        """
        term_lower = term.lower()
        stack: List[tk.Widget] = [parent_widget]

        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue

            text = ""
            try:
                if isinstance(
                    widget, (tk.Label, tk.Checkbutton, tk.Radiobutton, tk.Button)
                ):
                    text = widget.cget("text")
                elif isinstance(
                    widget, (tk.Entry, ttk.Entry, tk.Spinbox, ttk.Combobox)
                ):
                    text = widget.get()
                elif isinstance(widget, tk.Text):
                    try:
                        text = widget.get("1.0", "2.0")
                    except tk.TclError:
                        pass
            except tk.TclError:
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "search",
                        f"Fehler beim Auslesen von {type(widget).__name__}: {e}",
                    )

            if text and term_lower in text.lower():
                original_bg = ""
                try:
                    original_bg = widget.cget("bg")
                except tk.TclError:
                    pass

                try:
                    widget.config(bg="#ffff99")
                except tk.TclError:
                    return

                def restore():
                    try:
                        if widget.winfo_exists():
                            widget.config(bg=original_bg)
                    except tk.TclError:
                        pass
                    except Exception as e:
                        if DEBUG_LEVEL >= 4:
                            log_debug(
                                "search", f"Fehler beim Zurücksetzen der Farbe: {e}"
                            )

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(800, restore)
                else:
                    restore()

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "search",
                        f"Widget {type(widget).__name__} hervorgehoben "
                        f"für Begriff '{term}'",
                    )
                return

            try:
                stack.extend(widget.winfo_children())
            except tk.TclError:
                pass

    def delete_current_profile(self) -> None:
        """Löscht das aktuell ausgewählte benutzerdefinierte Profil."""
        name = self.profile_var.get()
        if name not in self.custom_profiles:
            DarkMessageBox.showwarning(
                "Löschen nicht möglich",
                "Nur eigene Profile können gelöscht werden.",
                self.parent,
            )
            return
        if DarkMessageBox.askyesno(
            "Profil löschen",
            f"Möchten Sie das Profil '{name}' wirklich löschen?",
            parent=self.dialog,
        ):
            path = PlatformUtils.get_platform_config_dir() / "profiles" / f"{name}.json"
            try:
                path.unlink()
            except OSError:
                pass
            if name in self.custom_profiles:
                del self.custom_profiles[name]
            self.profile_list.remove(name)
            self.profile_combo["values"] = self.profile_list
            self.profile_var.set("")
            DarkMessageBox.showinfo(
                "Gelöscht", f"Profil '{name}' wurde gelöscht.", self.parent
            )

    def _on_theme_selected(self, event: Optional[tk.Event] = None) -> None:
        """
        Wendet das ausgewählte Theme sofort als Live‑Vorschau an – inklusive
        aller bereits geladenen Tabs, aller offenen Nebendialoge und sämtlicher
        Canvas‑Hintergründe.  Um Flackern zu vermeiden, wird das Fenster
        während der Aktualisierung kurz versteckt und erst nach Abschluss
        aller Änderungen wieder eingeblendet.

        Vollständig optimierte Version mit:
        - Expliziter Rückgabe `-> None` (behebt mypy‑Fehler).
        - Defensiver Prüfung der Widget‑Existenz.
        - Robuster Theme‑Ermittlung (GUI, globale Variable, Fallback).
        - Anwendung des Themes auf alle geladenen Tabs (via `_loaded_tabs`).
        - Aktualisierung offener Dialoge (über `gui._open_dialogs`).
        - Korrektur der Canvas‑Hintergründe in scrollbaren Bereichen.
        - Verwendung von `_safe_after` für asynchrone Updates (optional).
        - Detaillierten Debug‑Ausgaben bei `DEBUG_LEVEL >= 3`.
        - Vermeidung von `return` ohne Wert – jetzt explizit `return` oder `None`.

        Args:
            event: Optionales Tkinter‑Event (wird ignoriert).
        """
        # ── 1. Grundlegende Prüfungen ─────────────────────────────────────
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            if DEBUG_LEVEL >= 3:
                log_debug("settings", "_on_theme_selected: dialog nicht verfügbar")
            return

        new_theme = self.theme_var.get()
        if not new_theme:
            if DEBUG_LEVEL >= 3:
                log_debug("settings", "_on_theme_selected: theme_var ist leer")
            return

        gui = getattr(self, "gui", None)
        if gui is not None and hasattr(gui, "settings"):
            try:
                if gui.settings.theme == new_theme:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "settings",
                            f"Theme '{new_theme}' bereits aktiv – nichts zu tun",
                        )
                    return
            except Exception:
                pass

        if DEBUG_LEVEL >= 2:
            log_debug("settings", f"_on_theme_selected: applying theme '{new_theme}'")

        # Fenster kurz verstecken, um Flackern zu minimieren
        try:
            self.dialog.withdraw()
        except tk.TclError:
            pass

        # ── 2. Theme global über die GUI‑Instanz setzen ───────────────────
        theme_applied = False
        if gui is not None and hasattr(gui, "_apply_theme"):
            try:
                gui._apply_theme(new_theme)
                theme_applied = True
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "settings", f"gui._apply_theme('{new_theme}') erfolgreich"
                    )
            except Exception as e:
                logger.warning(
                    "_on_theme_selected: gui._apply_theme('%s') fehlgeschlagen: %s",
                    new_theme,
                    e,
                )
                if DEBUG_LEVEL >= 3:
                    log_exception(
                        "settings", "gui._apply_theme failed", e, level="debug"
                    )

        # ── 3. Fallback: Nur den Dialog selbst aktualisieren ──────────────
        if not theme_applied:
            logger.warning(
                "GUI._apply_theme nicht verfügbar – Theme wird nur im Dialog gesetzt."
            )
            theme_map = {
                "dark": DarkTheme,
                "light": LightTheme,
                "pastel": PastelTheme,
                "highcontrast": HighContrastTheme,
                "dracula": DraculaTheme,
                "nord": NordTheme,
                "solarized": SolarizedDarkTheme,
                "gruvbox": GruvboxDarkTheme,
                "onedark": OneDarkTheme,
                "monokai": MonokaiTheme,
                "a11y-dark": A11yDarkTheme,
                "catppuccin": CatppuccinMochaTheme,
                "tokyonight": TokyoNightTheme,
            }
            theme_class = theme_map.get(new_theme, DarkTheme)
            try:
                if gui is not None:
                    gui.current_theme = theme_class()
                else:
                    # Ohne GUI-Referenz bleibt der Dialog bei DarkTheme
                    pass
            except Exception as e:
                logger.error("Fehler beim Setzen des Fallback‑Themes: %s", e)

        # ── 4. Aktives Theme‑Objekt bestimmen ────────────────────────────
        try:
            theme = gui.current_theme if gui is not None else DarkTheme()
        except Exception:
            theme = DarkTheme()

        # ── 5. Dialog‑Hintergrund setzen ─────────────────────────────────
        try:
            self.dialog.configure(bg=theme.BG_PRIMARY)
        except (tk.TclError, RuntimeError):
            pass

        # ── 6. ttk‑Styles aktualisieren ─────────────────────────────────
        try:
            self._setup_ttk_styles()
        except Exception as e:
            logger.warning("Fehler beim Aktualisieren der ttk-Styles: %s", e)

        # ── 7. Widget‑Baum rekursiv aktualisieren ───────────────────────
        try:
            PlatformUtils.apply_theme_to_widget_tree(self.dialog, theme)
        except Exception as e:
            logger.warning("Fehler beim Anwenden des Themes auf den Widget-Baum: %s", e)

        # ── 8. Bereits geladene Tabs (Lazy Loading) aktualisieren ────────
        if hasattr(self, "_loaded_tabs"):
            for tab_name in self._loaded_tabs:
                tab_attr = f"tab_{tab_name}"
                tab = getattr(self, tab_attr, None)
                if tab is None or not tab.winfo_exists():
                    continue
                try:
                    PlatformUtils.apply_theme_to_widget_tree(tab, theme)
                    tab.configure(bg=theme.BG_PRIMARY)
                except (tk.TclError, RuntimeError):
                    pass

        # ── 9. Offene Nebendialoge ebenfalls aktualisieren ───────────────
        if gui is not None and hasattr(gui, "_open_dialogs"):
            for dlg in gui._open_dialogs[:]:
                try:
                    if dlg is None or not dlg.winfo_exists():
                        continue
                    if hasattr(dlg, "apply_theme") and callable(dlg.apply_theme):
                        dlg.apply_theme()
                    elif isinstance(dlg, tk.Toplevel):
                        dlg.configure(bg=theme.BG_PRIMARY)
                        # Auch die Kinder des Dialogs aktualisieren
                        PlatformUtils.apply_theme_to_widget_tree(dlg, theme)
                except (tk.TclError, RuntimeError):
                    pass

        # ── 10. Spezielle Widgets im Dialog aktualisieren ────────────────
        special_widgets = [
            "profile_combo",
            "search_entry",
            "ollama_combo",
            "ollama_refresh_label",
            "tts_voice_combo",
            "suppress_entry",
            "proxy_entry",
        ]
        for name in special_widgets:
            widget = getattr(self, name, None)
            if widget is None or not widget.winfo_exists():
                continue
            try:
                if isinstance(widget, tk.Entry):
                    widget.config(
                        bg=getattr(theme, "INPUT_BG", theme.BG_TERTIARY),
                        fg=theme.TEXT_PRIMARY,
                        insertbackground=theme.TEXT_PRIMARY,
                    )
                elif isinstance(widget, tk.Label):
                    widget.config(bg=theme.BG_PRIMARY, fg=theme.TEXT_PRIMARY)
                elif isinstance(widget, tk.Button):
                    widget.config(bg=theme.BG_TERTIARY, fg=theme.TEXT_PRIMARY)
                elif isinstance(widget, ttk.Combobox):
                    # Combobox wird bereits über ttk‑Styles behandelt
                    pass
            except (tk.TclError, RuntimeError):
                pass
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("settings", f"_on_theme_selected: Fehler bei {name}: {e}")

        # ── 11. Canvas‑Hintergründe in scrollbaren Bereichen korrigieren ──
        for canvas in getattr(self, "_scrollable_canvases", []):
            try:
                if canvas.winfo_exists():
                    canvas.configure(bg=theme.BG_PRIMARY)
            except (tk.TclError, RuntimeError):
                pass

        # ── 12. Grafikausgabe erzwingen ─────────────────────────────────
        try:
            self.dialog.update_idletasks()
        except tk.TclError:
            pass

        # ── 13. Fenster wieder einblenden ───────────────────────────────
        try:
            self.dialog.deiconify()
        except tk.TclError:
            pass

        if DEBUG_LEVEL >= 3:
            log_debug(
                "settings",
                "Theme '%s' vollständig auf Dialog und geladene Tabs angewendet",
                new_theme,
            )

        # Explizites return None (optional, aber für mypy-Klarheit)
        return None

    def apply_theme(self) -> None:
        """Wird vom Hauptfenster bei globalen Theme‑Wechseln aufgerufen."""
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            return
        self._on_theme_selected()

    def _load_current_settings(self) -> None:
        """
        Lädt **alle** aktuellen Werte aus ``self.gui.advanced_settings``
        und ``self.gui.settings`` in die Dialog‑Variablen.

        Die Zuordnung ist exakt dieselbe wie in ``AdvancedSettings.to_dict()``,
        sodass keine Inkonsistenzen zwischen Speichern und Laden entstehen.
        """

        if DEBUG_LEVEL >= 3:
            log_debug(
                "settings", "_load_current_settings: Lade Einstellungen in Dialog"
            )

        adv = self.gui.advanced_settings
        app = self.gui.settings

        # ------------------------------------------------------------------
        # 1. Audio & VAD
        # ------------------------------------------------------------------
        self.chunk_var.set(self._get_safe(adv, "chunk_duration", 15.0))
        self.vad_filter_var.set(self._get_safe(adv, "vad_filter", False))
        self.vad_threshold_var.set(self._get_safe(adv, "vad_threshold", 0.25))
        self.vad_min_speech_var.set(
            self._get_safe(adv, "vad_min_speech_duration_ms", 225)
        )
        self.vad_min_silence_var.set(
            self._get_safe(adv, "vad_min_silence_duration_ms", 80)
        )

        # ------------------------------------------------------------------
        # 2. Modell & Inferenz
        # ------------------------------------------------------------------
        self.beam_var.set(self._get_safe(adv, "beam_size", 10))
        self.temp_var.set(self._get_safe(adv, "temperature", 0.0))
        self.gpu_var.set(self._get_safe(adv, "gpu_acceleration", True))
        self.cpu_threads_var.set(self._get_safe(adv, "cpu_threads", 0))
        self.hotwords_var.set(self._get_safe(adv, "hotwords", ""))

        # ------------------------------------------------------------------
        # 3. Übersetzung & TTS
        # ------------------------------------------------------------------
        self.engine_var.set(self._get_safe(adv, "translation_engine", "google"))
        self.ollama_model_var.set(self._get_safe(adv, "ollama_model", "llama3.1:8b"))
        self.ollama_host_var.set(
            self._get_safe(adv, "ollama_host", "http://localhost:11434")
        )
        self.reflection_var.set(self._get_safe(adv, "enable_reflection", False))
        self.tts_engine_var.set(self._get_safe(adv, "tts_engine", "piper"))
        self.tts_voice_var.set(
            self._get_safe(adv, "tts_voice", "de_DE-thorsten-medium")
        )
        self.tts_length_scale_var.set(
            self._piper_speed_to_gui(self._get_safe(adv, "tts_length_scale", 0.9))
        )
        self.tts_sentence_silence_var.set(
            self._get_safe(adv, "tts_sentence_silence", 0.1)
        )
        self.tts_convert_to_sink_var.set(
            self._get_safe(adv, "tts_convert_to_sink", True)
        )

        # ------------------------------------------------------------------
        # 4. GUI & Anzeige
        # ------------------------------------------------------------------
        self.trans_lines_var.set(self._get_safe(adv, "transcript_max_lines", 800))
        self.transl_lines_var.set(self._get_safe(adv, "translation_max_lines", 600))
        self.theme_var.set(app.theme)
        self.auto_save_var.set(app.auto_save_on_completion)

        # ------------------------------------------------------------------
        # 5. Erweitert & System
        # ------------------------------------------------------------------
        self.cache_var.set(self._get_safe(adv, "max_cache_size", 200))
        self.plugin_var.set(app.enable_plugins)
        self.cookies_var.set(app.use_browser_cookies)
        self.cookies_browser_var.set(app.cookies_browser)
        self.asian_var.set(self._get_safe(adv, "asian_mode", False))
        self.precision_var.set(self._get_safe(adv, "precision_mode", False))
        self.adaptive_chunk_var.set(self._get_safe(adv, "adaptive_chunk", False))
        self.live_from_start_var.set(self._get_safe(adv, "live_from_start", False))
        self.download_inactivity_var.set(
            self._get_safe(adv, "download_inactivity_timeout", 30.0)
        )
        self.proxy_enabled_var.set(self._get_safe(adv, "proxy_enabled", False))
        self.proxy_var.set(self._get_safe(adv, "proxy_url", ""))
        self.max_mem_var.set(self._get_safe(adv, "max_memory_mb", 1024))
        self.auto_save_interval_var.set(self._get_safe(adv, "auto_save_interval", 300))
        self.optimize_var.set(self._get_safe(adv, "optimize_translations", False))
        self.sentiment_var.set(self._get_safe(adv, "enable_sentiment_analysis", False))
        self.diarize_var.set(self._get_safe(adv, "enable_speaker_diarization", False))
        self.audio_enhancement_var.set(
            self._get_safe(adv, "enable_audio_enhancement", False)
        )

        # Whisper‑Anti‑Halluzination
        self.no_speech_var.set(self._get_safe(adv, "no_speech_threshold", 0.6))
        self.log_prob_var.set(self._get_safe(adv, "log_prob_threshold", -1.0))
        self.comp_ratio_var.set(self._get_safe(adv, "compression_ratio_threshold", 2.4))
        self.patience_var.set(self._get_safe(adv, "patience", 1.0))
        self.condition_prev_var.set(
            self._get_safe(adv, "condition_on_previous_text", True)
        )
        self.length_penalty_var.set(0.0)  # Wurde entfernt, nur Platzhalter
        self.best_of_var.set(self._get_safe(adv, "best_of", 5))
        self.suppress_tokens_var.set(self._get_safe(adv, "suppress_tokens", "-1"))
        self.profile_var_audio.set(
            self._get_safe(adv, "audio_profile", "transcription")
        )

        # Transkriptions‑Filter
        self.min_conf_var.set(self._get_safe(adv, "min_confidence", 0.1))
        self.dup_thresh_var.set(
            self._get_safe(adv, "duplicate_similarity_threshold", 0.98)
        )
        self.low_words_var.set(self._get_safe(adv, "adaptive_chunk_low_words", 3))
        self.high_words_var.set(self._get_safe(adv, "adaptive_chunk_high_words", 10))
        self.blacklist_mode_var.set(self._get_safe(adv, "blacklist_mode", "word"))

        # Zusammenfassung
        self.summarize_temperature_var.set(
            self._get_safe(adv, "summarize_temperature", 0.1)
        )
        self.summarize_model_var.set(
            self._get_safe(adv, "summarize_model", "qwen2.5:7b")
        )

        # Satzpufferung
        self.sentence_interval_var.set(
            self._get_safe(adv, "sentence_flush_interval", 3.0)
        )
        self.sentence_words_var.set(
            self._get_safe(adv, "sentence_flush_word_threshold", 30)
        )

        # Sonstiges
        self.vram_idle_var.set(self._get_safe(adv, "vram_idle_timeout_seconds", 180))
        self.min_lang_conf_var.set(self._get_safe(adv, "min_language_confidence", 0.2))

        fallback_code = self._get_safe(adv, "fallback_source_language", "de")
        try:
            fallback_name = SUPPORTED_LANGUAGES.get(fallback_code, "Deutsch")
        except NameError:
            fallback_name = {"de": "Deutsch", "en": "Englisch"}.get(
                fallback_code, "Deutsch"
            )
        self.fallback_lang_var.set(fallback_name)

        self.auto_tts_transcript_var.set(
            self._get_safe(adv, "auto_tts_transcript", False)
        )
        self.auto_tts_translation_var.set(
            self._get_safe(adv, "auto_tts_translation", False)
        )

        # Blacklist & erlaubte Verzeichnisse
        if hasattr(self, "allowed_dirs_text") and self.allowed_dirs_text is not None:
            self._safe_set_text(self.allowed_dirs_text, adv, "allowed_dirs")
        else:
            self._pending_allowed_dirs = getattr(adv, "allowed_dirs", [])[:]

        if hasattr(self, "blacklist_text") and self.blacklist_text is not None:
            self._safe_set_text(self.blacklist_text, adv, "blacklist")
        else:
            self._pending_blacklist = getattr(adv, "blacklist", [])[:]

        if DEBUG_LEVEL >= 3:
            log_debug("settings", "_load_current_settings: Alle Werte geladen")

    # ------------------------------------------------------------------
    # Hilfsfunktionen (innerhalb der Klasse)
    # ------------------------------------------------------------------
    @staticmethod
    def _get_safe(obj: Any, attr: str, default: Any) -> Any:
        """Liefert den Wert eines Attributs oder einen Standardwert."""
        return getattr(obj, attr, default)

    def _safe_set_text(self, widget: tk.Widget, obj: Any, attr: str) -> None:
        """Schreibt eine Liste sicher in ein ScrolledText‑Widget."""
        if widget is None or not widget.winfo_exists():
            return
        try:
            items = getattr(obj, attr, [])
            if not isinstance(items, list):
                items = []
        except Exception:
            items = []

        widget.delete("1.0", "end")
        if items:
            widget.insert("1.0", "\n".join(str(item) for item in items))

    def apply_settings(self) -> None:
        """
        Übernimmt die aktuellen Werte des Dialogs in die Einstellungsobjekte
        und speichert sie persistent. Die GUI bleibt geöffnet.

        Optimierungen (v2):
        - Zentralisierte Listen für `safe_set`-Aufrufe, Reduzierung von Redundanz.
        - Erweiterte Synchronisation von Cookies mit StreamManager, StreamInfoExtractor und YtDlpHelper.
        - Verbesserte Fehlerbehandlung und Logging.
        - Typsichere Behandlung von Optionen.
        """
        # ── 1. Grundlegende Prüfungen ──────────────────────────────────────
        if not hasattr(self, "gui") or self.gui is None:
            logger.error("apply_settings: Keine GUI‑Referenz vorhanden")
            return
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            logger.error("apply_settings: Dialogfenster existiert nicht mehr")
            return

        # ── 2. Validierungsfehler prüfen ──────────────────────────────────
        self._validation_errors = {
            w: msg for w, msg in self._validation_errors.items() if w.winfo_exists()
        }
        if self._validation_errors:
            DarkMessageBox.showerror(
                "Ungültige Eingaben",
                "Einige Felder enthalten ungültige Werte.\n"
                "Bitte korrigieren Sie die rot markierten Felder.",
                self.parent,
            )
            log_debug(
                "settings",
                "apply_settings: %d Validierungsfehler verhindern Apply",
                len(self._validation_errors),
            )
            return

        # ── 3. Proxy-Validierung ──────────────────────────────────────────
        proxy_enabled = self.proxy_enabled_var.get()
        proxy_url = self.proxy_var.get().strip()
        proxy_widget = getattr(self, "proxy_entry", None)
        if proxy_enabled and proxy_url:
            if not self._validate_proxy_url(proxy_url):
                if proxy_widget is not None and proxy_widget.winfo_exists():
                    self._show_validation_error(
                        proxy_widget, "Ungültige Proxy‑URL (Schema oder Host fehlt)"
                    )
                DarkMessageBox.showerror(
                    "Ungültige Eingabe",
                    "Die Proxy‑URL ist ungültig.\n"
                    "Bitte korrigieren Sie sie im Tab 'Erweitert & System'.",
                    self.parent,
                )
                log_debug("settings", "Ungültige Proxy‑URL verhindert Apply")
                return
            if proxy_widget is not None and proxy_widget.winfo_exists():
                self._clear_validation_error(proxy_widget)
        else:
            if proxy_widget is not None and proxy_widget.winfo_exists():
                self._clear_validation_error(proxy_widget)

        # ── 4. Suppress-Tokens-Validierung ──────────────────────────────
        tokens_str = self.suppress_tokens_var.get().strip()
        suppress_widget = getattr(self, "suppress_entry", None)
        if not self._validate_suppress_tokens(tokens_str):
            if suppress_widget is not None and suppress_widget.winfo_exists():
                self._show_validation_error(
                    suppress_widget,
                    "Kommagetrennte Liste positiver Integer erwartet (oder -1)",
                )
            DarkMessageBox.showerror(
                "Ungültige Eingabe",
                "Das Feld 'Suppress Tokens' enthält ungültige Werte.\n"
                "Bitte korrigieren Sie es im Tab 'Erweitert & System'.",
                self.parent,
            )
            log_debug("settings", "Ungültige suppress_tokens verhindern Apply")
            return
        if suppress_widget is not None and suppress_widget.winfo_exists():
            self._clear_validation_error(suppress_widget)

        # ── 5. AdvancedSettings-Objekt holen und Mode-Overrides zurücksetzen ──
        adv = self.gui.advanced_settings
        try:
            adv.restore_mode_overrides()
            log_debug("settings", "restore_mode_overrides() ausgeführt")
        except Exception as e:
            logger.warning(f"restore_mode_overrides fehlgeschlagen: {e}")

        # ── 6. Zentrale Hilfsfunktion für sicheres Setzen ──────────────────
        def safe_set(obj: Any, attr: str, value: Any) -> None:
            """Setzt ein Attribut nur, wenn es existiert. Fehlt es, wird eine
            Debug‑Meldung ausgegeben."""
            if not hasattr(obj, attr):
                log_debug(
                    "settings",
                    f"Kann Attribut '{attr}' nicht setzen – fehlt in {type(obj).__name__}",
                )
                return
            try:
                old = getattr(obj, attr)
                setattr(obj, attr, value)
                if DEBUG_LEVEL >= 3 and old != value:
                    log_debug("settings", f"  {attr}: {old!r} → {value!r}")
            except Exception as e:
                logger.warning(f"Fehler beim Setzen von {attr}: {e}")

        # ── 7. Attribut-Liste für AdvancedSettings ────────────────────────
        # Alle Werte, die aus den GUI-Variablen in adv übernommen werden sollen.
        # Jeder Eintrag ist ein Tuple (attr_name, value)
        adv_attrs = [
            ("chunk_duration", self.chunk_var.get()),
            ("audio_profile", self.profile_var_audio.get()),
            ("vad_filter", self.vad_filter_var.get()),
            ("vad_threshold", self.vad_threshold_var.get()),
            ("vad_min_speech_duration_ms", self.vad_min_speech_var.get()),
            ("vad_min_silence_duration_ms", self.vad_min_silence_var.get()),
            ("beam_size", self.beam_var.get()),
            ("temperature", self.temp_var.get()),
            ("gpu_acceleration", self.gpu_var.get()),
            ("cpu_threads", self.cpu_threads_var.get()),
            ("hotwords", self.hotwords_var.get().strip()),
            ("translation_engine", self.engine_var.get()),
            ("ollama_model", self.ollama_model_var.get().strip()),
            ("ollama_host", self.ollama_host_var.get().strip()),
            ("enable_reflection", self.reflection_var.get()),
            ("tts_engine", self.tts_engine_var.get()),
            ("tts_voice", self.tts_voice_var.get()),
            ("tts_length_scale", self._gui_speed_to_piper(self.tts_length_scale_var.get())),
            ("tts_sentence_silence", self.tts_sentence_silence_var.get()),
            ("tts_convert_to_sink", self.tts_convert_to_sink_var.get()),
            ("transcript_max_lines", self.trans_lines_var.get()),
            ("translation_max_lines", self.transl_lines_var.get()),
            ("asian_mode", self.asian_var.get()),
            ("precision_mode", self.precision_var.get()),
            ("adaptive_chunk", self.adaptive_chunk_var.get()),
            ("live_from_start", self.live_from_start_var.get()),
            ("download_inactivity_timeout", self.download_inactivity_var.get()),
            ("proxy_enabled", proxy_enabled),
            ("proxy_url", proxy_url),
            ("max_memory_mb", self.max_mem_var.get()),
            ("auto_save_interval", self.auto_save_interval_var.get()),
            ("optimize_translations", self.optimize_var.get()),
            ("enable_sentiment_analysis", self.sentiment_var.get()),
            ("enable_speaker_diarization", self.diarize_var.get()),
            ("no_speech_threshold", self.no_speech_var.get()),
            ("log_prob_threshold", self.log_prob_var.get()),
            ("compression_ratio_threshold", self.comp_ratio_var.get()),
            ("patience", self.patience_var.get()),
            ("condition_on_previous_text", self.condition_prev_var.get()),
            ("length_penalty", self.length_penalty_var.get()),
            ("best_of", self.best_of_var.get()),
            ("suppress_tokens", tokens_str),
            ("min_confidence", self.min_conf_var.get()),
            ("duplicate_similarity_threshold", self.dup_thresh_var.get()),
            ("adaptive_chunk_low_words", self.low_words_var.get()),
            ("adaptive_chunk_high_words", self.high_words_var.get()),
            ("blacklist_mode", self.blacklist_mode_var.get()),
            ("summarize_temperature", self.summarize_temperature_var.get()),
            ("summarize_model", self.summarize_model_var.get().strip()),
            ("sentence_flush_interval", self.sentence_interval_var.get()),
            ("sentence_flush_word_threshold", self.sentence_words_var.get()),
            ("enable_audio_enhancement", self.audio_enhancement_var.get()),
            ("vram_idle_timeout_seconds", self.vram_idle_var.get()),
            ("min_language_confidence", self.min_lang_conf_var.get()),
            ("auto_tts_transcript", self.auto_tts_transcript_var.get()),
            ("auto_tts_translation", self.auto_tts_translation_var.get()),
        ]

        # Fallback-Sprache separat behandeln (Code → Name)
        fallback_name = self.fallback_lang_var.get()
        try:
            fallback_code = DISPLAY_NAME_TO_CODE.get(fallback_name, "de")
        except NameError:
            fallback_code = {"Deutsch": "de", "Englisch": "en"}.get(fallback_name, "de")
        adv_attrs.append(("fallback_source_language", fallback_code))

        # Alle Attribute in adv setzen
        for attr, value in adv_attrs:
            safe_set(adv, attr, value)

        # ── 8. Mode-Overrides erneut anwenden (nachdem alle Werte gesetzt sind) ──
        try:
            adv._apply_mode_overrides()
            log_debug("settings", "_apply_mode_overrides() ausgeführt")
        except Exception as e:
            logger.warning(f"_apply_mode_overrides fehlgeschlagen: {e}")

        # ── 9. Verzeichnis- und Blacklist-Listen setzen ────────────────────
        if hasattr(self, "allowed_dirs_text") and self.allowed_dirs_text is not None:
            try:
                adv.allowed_dirs = [
                    line.strip()
                    for line in self.allowed_dirs_text.get("1.0", "end-1c").split("\n")
                    if line.strip()
                ]
            except tk.TclError:
                adv.allowed_dirs = self._pending_allowed_dirs or []
        elif self._pending_allowed_dirs is not None:
            adv.allowed_dirs = self._pending_allowed_dirs
        else:
            adv.allowed_dirs = []

        if hasattr(self, "blacklist_text") and self.blacklist_text is not None:
            try:
                adv.blacklist = [
                    line.strip()
                    for line in self.blacklist_text.get("1.0", "end-1c").split("\n")
                    if line.strip()
                ]
            except tk.TclError:
                adv.blacklist = self._pending_blacklist or []
        elif self._pending_blacklist is not None:
            adv.blacklist = self._pending_blacklist
        else:
            adv.blacklist = []

        # ── 10. AppSettings aktualisieren ──────────────────────────────────
        self.gui.settings.theme = self.theme_var.get()
        self.gui.settings.auto_save_on_completion = self.auto_save_var.get()
        self.gui.settings.enable_plugins = self.plugin_var.get()
        self.gui.settings.use_browser_cookies = self.cookies_var.get()
        self.gui.settings.cookies_browser = self.cookies_browser_var.get()

        # ── 11. AdvancedSettings als JSON persistieren ──────────────────────
        try:
            data = asdict(adv)
        except Exception as e:
            DarkMessageBox.showerror(
                "Fehler", f"Konnte Einstellungen nicht serialisieren:\n{e}", self.parent
            )
            logger.exception("asdict für AdvancedSettings fehlgeschlagen")
            return

        data.pop("config", None)
        data.pop("_chunk_duration", None)
        data["chunk_duration"] = adv.chunk_duration
        data["_version"] = 2

        config_dir = PlatformUtils.get_platform_config_dir()
        try:
            config_dir.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            DarkMessageBox.showerror(
                "Fehler",
                f"Konfigurationsverzeichnis nicht erstellbar:\n{e}",
                self.parent,
            )
            return

        file_path = config_dir / "dragon_advanced_settings.json"
        temp_path = file_path.with_suffix(".tmp")
        try:
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
        except Exception as e:
            DarkMessageBox.showerror(
                "Fehler",
                f"Schreiben der Einstellungen fehlgeschlagen:\n{e}",
                self.parent,
            )
            return

        if file_path.exists():
            try:
                shutil.copy2(file_path, file_path.with_suffix(".json.bak"))
            except Exception as e:
                logger.warning(f"Backup der Einstellungen fehlgeschlagen: {e}")

        try:
            os.replace(temp_path, file_path)
        except (OSError, PermissionError) as e:
            DarkMessageBox.showerror(
                "Fehler", f"Konnte Einstellungsdatei nicht ersetzen:\n{e}", self.parent
            )
            return

        if hasattr(AdvancedSettings, "invalidate_cache"):
            AdvancedSettings.invalidate_cache()

        try:
            self.gui.settings.save_to_file()
        except Exception as e:
            logger.warning(f"Speichern der AppSettings fehlgeschlagen: {e}")

        log_debug("settings", "Einstellungen erfolgreich gespeichert (Version 2)")

        # ── 12. Theme anwenden ─────────────────────────────────────────────
        if hasattr(self.gui, "_apply_theme"):
            try:
                self.gui._apply_theme(self.gui.settings.theme)
            except Exception as e:
                logger.warning(f"apply_theme fehlgeschlagen: {e}")

        # ── 13. StreamManager synchronisieren (Cookies & Proxy) ───────────
        if hasattr(self.gui, "stream_manager") and self.gui.stream_manager is not None:
            try:
                sm = self.gui.stream_manager
                # Cookies
                sm.use_browser_cookies = self.gui.settings.use_browser_cookies
                sm.cookies_browser = self.gui.settings.cookies_browser
                # Proxy
                sm.set_proxy(adv.proxy_url, adv.proxy_enabled)
                log_debug(
                    "settings",
                    "StreamManager synchronisiert: cookies=%s, browser=%s, proxy=%s",
                    sm.use_browser_cookies,
                    sm.cookies_browser,
                    adv.proxy_url if adv.proxy_enabled else "deaktiviert",
                )
            except Exception as e:
                logger.warning(f"StreamManager-Synchronisation fehlgeschlagen: {e}")

        # ── 14. StreamInfoExtractor synchronisieren (Cookies) ─────────────
        if hasattr(self.gui, "stream_info_extractor") and self.gui.stream_info_extractor is not None:
            try:
                sie = self.gui.stream_info_extractor
                sie.use_browser_cookies = self.gui.settings.use_browser_cookies
                sie.cookies_browser = self.gui.settings.cookies_browser
                log_debug(
                    "settings",
                    "StreamInfoExtractor synchronisiert: cookies=%s, browser=%s",
                    sie.use_browser_cookies,
                    sie.cookies_browser,
                )
            except Exception as e:
                logger.warning(f"StreamInfoExtractor-Synchronisation fehlgeschlagen: {e}")

        # ── 15. YtDlpHelper-Konfiguration aktualisieren (falls verfügbar) ──
        try:
            from .ytdlp_helper import YtDlpHelper
            YtDlpHelper.set_config(
                use_cookies=self.gui.settings.use_browser_cookies,
                cookies_browser=self.gui.settings.cookies_browser,
                proxy=adv.proxy_url if adv.proxy_enabled else "",
                proxy_enabled=adv.proxy_enabled,
            )
            log_debug("settings", "YtDlpHelper-Konfiguration aktualisiert")
        except ImportError:
            log_debug("settings", "YtDlpHelper nicht importierbar – überspringe")
        except Exception as e:
            logger.warning(f"YtDlpHelper-Synchronisation fehlgeschlagen: {e}")

        # ── 16. Transkriptions-Engine: GPU-Acceleration setzen ─────────────
        if hasattr(self.gui, "transcription_engine") and self.gui.transcription_engine is not None:
            try:
                self.gui.transcription_engine.set_gpu_acceleration(adv.gpu_acceleration)
            except Exception as e:
                logger.warning(f"TranscriptionEngine GPU-Sync fehlgeschlagen: {e}")

        # ── 17. TTS-Manager synchronisieren ──────────────────────────────
        if hasattr(self.gui, "tts_manager") and self.gui.tts_manager is not None:
            try:
                tts = self.gui.tts_manager
                tts.set_engine(adv.tts_engine)
                tts.set_voice(adv.tts_voice)
                tts.length_scale = adv.tts_length_scale
                tts.sentence_silence = adv.tts_sentence_silence
                log_debug("settings", "TTS-Manager synchronisiert")
            except Exception as e:
                logger.warning(f"TTS-Manager-Synchronisation fehlgeschlagen: {e}")

        # ── 18. Auto‑TTS mit dem AudioProcessor synchronisieren ────────────
        try:
            if hasattr(self.gui, "_sync_auto_tts_to_processor"):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "settings",
                        "apply_settings: synchronisiere Auto‑TTS mit AudioProcessor",
                    )
                self.gui._sync_auto_tts_to_processor()
            else:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "settings",
                        "apply_settings: _sync_auto_tts_to_processor nicht verfügbar",
                    )
        except Exception as exc:
            logger.warning(
                "apply_settings: Auto‑TTS‑Synchronisation fehlgeschlagen: %s", exc
            )
            if DEBUG_LEVEL >= 3:
                log_exception("settings", "Auto‑TTS sync exception", exc, level="debug")

        # ── 19. Abschluss ──────────────────────────────────────────────────
        self.gui.update_status("✅ Settings applied")
        log_debug("settings", "apply_settings() abgeschlossen")

    def save_settings(self) -> None:
        """
        Speichert die aktuellen Einstellungen des Dialogs persistent,
        synchronisiert die Auto‑TTS‑Flags mit dem laufenden AudioProcessor,
        **aktualisiert die GUI‑Referenz der AdvancedSettings** und schließt
        das Fenster.

        Die Methode ist vollständig defensiv: Jeder Schritt ist gegen
        Ausnahmen geschützt und der Dialog wird unter **allen** Umständen
        geschlossen.  Die Aktualisierung der GUI‑Instanz (Schritt 2)
        behebt das Problem, dass nach einem Speichern die Haupt‑GUI
        weiterhin mit veralteten Einstellungen arbeitet.
        """
        if DEBUG_LEVEL >= 3:
            log_debug("settings", "save_settings() aufgerufen")

        # ═══════════════════════════════════════════════════════════════
        # 1. Einstellungen aus dem Dialog in die internen Objekte
        #    übernehmen und persistent speichern (Datei + Seiteneffekte)
        # ═══════════════════════════════════════════════════════════════
        try:
            self.apply_settings()
            if DEBUG_LEVEL >= 3:
                log_debug("settings", "apply_settings() erfolgreich ausgeführt")
        except Exception as exc:
            logger.exception("save_settings: apply_settings() fehlgeschlagen: %s", exc)
            if DEBUG_LEVEL >= 3:
                log_exception("settings", "apply_settings failed", exc, level="error")
            # Trotz Fehler den Dialog schließen
            self._safe_destroy()
            return

        # ═══════════════════════════════════════════════════════════════
        # 2. GUI‑Referenz der AdvancedSettings aktualisieren  (← GEÄNDERT)
        #    Damit das Hauptfenster immer mit der zuletzt gespeicherten
        #    Konfiguration arbeitet, selbst wenn der AudioProcessor
        #    nicht läuft (z. B. bei der manuellen Übersetzung).
        #    Kein load_from_file() mehr, um zusätzliche Instanzen zu vermeiden.
        # ═══════════════════════════════════════════════════════════════
        try:
            gui = getattr(self, "gui", None)
            if gui is not None:
                # Cache invalidieren, um die frische Datei zu lesen
                try:
                    AdvancedSettings.invalidate_cache()
                except Exception as exc:
                    logger.warning(
                        "save_settings: invalidate_cache fehlgeschlagen: %s", exc
                    )
                    if DEBUG_LEVEL >= 3:
                        log_exception(
                            "settings", "invalidate_cache error", exc, level="debug"
                        )
                # Keine neue Instanz laden; die apply_settings hat bereits
                # gui.advanced_settings aktualisiert. Die Werte sind in gui.advanced_settings
                # bereits synchron mit der Datei.
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "settings",
                        "GUI‑Instanz der AdvancedSettings bereits aktuell "
                        "(auto_tts_translation=%s)",
                        gui.advanced_settings.auto_tts_translation,
                    )
            else:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "settings", "Keine GUI‑Referenz – Aktualisierung übersprungen"
                    )
        except Exception as exc:
            logger.warning(
                "save_settings: Aktualisierung der GUI‑AdvancedSettings "
                "fehlgeschlagen: %s",
                exc,
            )
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "settings",
                    "GUI AdvancedSettings update failed",
                    exc,
                    level="warning",
                )

        # ═══════════════════════════════════════════════════════════════
        # 3. Auto‑TTS‑Synchronisation mit dem AudioProcessor
        #    Stellt sicher, dass die Checkboxen im Hauptfenster und die
        #    internen Flags des AudioProcessors sofort übereinstimmen.
        # ═══════════════════════════════════════════════════════════════
        try:
            gui = getattr(self, "gui", None)
            if gui is not None and hasattr(gui, "_sync_auto_tts_to_processor"):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "settings",
                        "save_settings: synchronisiere Auto‑TTS mit AudioProcessor",
                    )
                gui._sync_auto_tts_to_processor()
            else:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "settings",
                        "save_settings: _sync_auto_tts_to_processor nicht verfügbar",
                    )
        except Exception as exc:
            logger.warning(
                "save_settings: Auto‑TTS‑Synchronisation fehlgeschlagen: %s", exc
            )
            if DEBUG_LEVEL >= 3:
                log_exception("settings", "Auto‑TTS sync exception", exc, level="debug")

        # ═══════════════════════════════════════════════════════════════
        # 4. Dialog garantiert schließen
        # ═══════════════════════════════════════════════════════════════
        self._safe_destroy()

        if DEBUG_LEVEL >= 3:
            log_debug("settings", "save_settings() abgeschlossen, Dialog geschlossen")

    def _safe_destroy(self) -> None:
        """
        Zerstört das Dialogfenster und fängt alle Tkinter‑Fehler ab.
        Wird als Fallback verwendet, um den Dialog unter allen Umständen
        zu schließen.
        """
        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.destroy()
        except (tk.TclError, RuntimeError) as exc:
            if DEBUG_LEVEL >= 3:
                log_debug("settings", "Fehler beim Schließen des Dialogs: %s", exc)
        except Exception as exc:
            logger.warning("Unerwarteter Fehler beim Schließen des Dialogs: %s", exc)

