    def save_to_file(self, filename: str = "dragon_advanced_settings.json") -> None:
        """
        Speichert die aktuellen Einstellungen atomar in eine JSON‑Datei.
        Verwendet explizite ``to_dict()`` Methode statt ``dataclasses.asdict()``.
        """
        start_time = time.perf_counter()
        config_dir = None
        file_path = None
        temp_path = None
        backup_path = None
        success = False

        try:
            config_dir = PlatformUtils.get_platform_config_dir()
            config_dir.mkdir(parents=True, exist_ok=True)
            file_path = config_dir / filename
            temp_path = file_path.with_suffix(".tmp")
            if file_path.exists():
                backup_path = file_path.with_suffix(".json.bak")

            data = self.to_dict()

            if DEBUG_LEVEL >= 3:
                log_debug("settings", f"Writing settings to temp file: {temp_path}")

            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2, ensure_ascii=False)

            if backup_path is not None and file_path.exists():
                try:
                    shutil.copy2(file_path, backup_path)
                    if DEBUG_LEVEL >= 3:
                        log_debug("settings", f"Backup created: {backup_path}")
                except Exception as be:
                    logger.warning(f"Konnte kein Backup erstellen: {be}")

            try:
                os.replace(temp_path, file_path)
            except AttributeError:
                if IS_WINDOWS:
                    os.replace(temp_path, file_path)
                else:
                    shutil.move(str(temp_path), str(file_path))
            except FileNotFoundError:
                config_dir.mkdir(parents=True, exist_ok=True)
                os.replace(temp_path, file_path)

            self.invalidate_cache(filename)

            success = True
            duration_ms = (time.perf_counter() - start_time) * 1000
            logger.info(
                f"💾 Settings saved to {file_path} ({duration_ms:.1f} ms, Config Type: {self.config_type})"
            )
            if DEBUG_LEVEL >= 3:
                log_debug("settings", "Settings saved successfully, cache invalidated")

        except PermissionError as e:
            logger.error(f"❌ Keine Berechtigung zum Speichern: {e}")
        except json.JSONDecodeError as e:
            logger.error(f"❌ JSON-Fehler beim Serialisieren: {e}")
        except OSError as e:
            logger.error(f"❌ OS-Fehler beim Speichern: {e}")
        except Exception as e:
            logger.error(f"❌ Unerwarteter Fehler beim Speichern: {e}")
        finally:
            if temp_path is not None and temp_path.exists() and not success:
                try:
                    temp_path.unlink()
                    if DEBUG_LEVEL >= 3:
                        log_debug("settings", f"Temp file removed: {temp_path}")
                except Exception:
                    pass

    def validate(self) -> List[str]:
        issues = []
        if not (1 <= self.beam_size <= 20):
            issues.append(f"beam_size {self.beam_size} außerhalb 1-20")
        if not (0.0 <= self.temperature <= 2.0):
            issues.append(f"temperature {self.temperature} außerhalb 0.0-2.0")
        if not (100 <= self.max_memory_mb <= 16384):
            issues.append(f"max_memory_mb {self.max_memory_mb} außerhalb 100-16384")
        if self.config_type not in ("default", "realtime", "high_accuracy", "youtube"):
            issues.append(f"Ungültiger config_type '{self.config_type}'")
        if self.config:
            min_dur = self.config.MIN_CHUNK_DURATION
            max_dur = self.config.MAX_CHUNK_DURATION
            if not (min_dur <= self.chunk_duration <= max_dur):
                issues.append(
                    f"chunk_duration {self.chunk_duration}s außerhalb [{min_dur}, {max_dur}]"
                )
        else:
            min_dur = ConfigDefaults.MIN_CHUNK_DURATION
            max_dur = ConfigDefaults.MAX_CHUNK_DURATION
            if not (min_dur <= self.chunk_duration <= max_dur):
                issues.append(
                    f"chunk_duration {self.chunk_duration}s außerhalb [{min_dur}, {max_dur}] (config missing)"
                )
        if not (100 <= self.transcript_max_lines <= 5000):
            issues.append(
                f"transcript_max_lines {self.transcript_max_lines} außerhalb 100-5000"
            )
        if not (100 <= self.translation_max_lines <= 5000):
            issues.append(
                f"translation_max_lines {self.translation_max_lines} außerhalb 100-5000"
            )
        if self.translation_engine not in ("google", "ollama", "argos"):
            issues.append(f"translation_engine '{self.translation_engine}' ungültig")
        if not (0.5 <= self.duplicate_similarity_threshold <= 1.0):
            issues.append(
                f"duplicate_similarity_threshold {self.duplicate_similarity_threshold} außerhalb 0.5-1.0"
            )
        if not (0.0 <= self.min_confidence <= 1.0):
            issues.append(f"min_confidence {self.min_confidence} außerhalb 0.0-1.0")
        if not (0.0 <= self.vad_threshold <= 1.0):
            issues.append(f"vad_threshold {self.vad_threshold} außerhalb 0.0-1.0")
        if self.vad_min_speech_duration_ms < 0:
            issues.append("vad_min_speech_duration_ms negativ")
        if self.vad_min_silence_duration_ms < 0:
            issues.append("vad_min_silence_duration_ms negativ")
        if self.blacklist_mode not in ("word", "substring"):
            issues.append(f"blacklist_mode '{self.blacklist_mode}' ungültig")
        if self.tts_engine not in ("piper", "pyttsx3"):
            issues.append(f"tts_engine '{self.tts_engine}' ungültig")
        if not (1 <= self.best_of <= 20):
            issues.append(f"best_of {self.best_of} außerhalb 1-20")
        if not (0.0 <= self.patience <= 2.0):
            issues.append(f"patience {self.patience} außerhalb 0.0-2.0")
        if not (0.0 <= self.no_speech_threshold <= 1.0):
            issues.append(
                f"no_speech_threshold {self.no_speech_threshold} außerhalb 0.0-1.0"
            )
        if not (-5.0 <= self.log_prob_threshold <= 0.0):
            issues.append(
                f"log_prob_threshold {self.log_prob_threshold} außerhalb -5.0-0.0"
            )
        if not (1.0 <= self.compression_ratio_threshold <= 5.0):
            issues.append(
                f"compression_ratio_threshold {self.compression_ratio_threshold} außerhalb 1.0-5.0"
            )
        if self.proxy_url and not any(
            self.proxy_url.startswith(s)
            for s in ("http://", "https://", "socks4://", "socks5://")
        ):
            issues.append(f"proxy_url '{self.proxy_url}' ungültiges Schema")
        if not (0.0 <= self.summarize_temperature <= 1.0):
            issues.append(
                f"summarize_temperature {self.summarize_temperature} außerhalb 0.0-1.0"
            )
        if not self.summarize_model or not isinstance(self.summarize_model, str):
            issues.append("summarize_model ungültig")
        if not (0.5 <= self.sentence_flush_interval <= 10.0):
            issues.append(
                f"sentence_flush_interval {self.sentence_flush_interval} außerhalb 0.5-10.0"
            )
        if not (5 <= self.sentence_flush_word_threshold <= 100):
            issues.append(
                f"sentence_flush_word_threshold {self.sentence_flush_word_threshold} außerhalb 5-100"
            )
        if not (10 <= self.download_inactivity_timeout <= 600):
            issues.append(
                f"download_inactivity_timeout {self.download_inactivity_timeout} außerhalb 10-600"
            )
        return issues

    def repair(self) -> List[str]:
        """
        Repariert inkonsistente oder fehlende Felder der AdvancedSettings‑Instanz.
        Verwendet die Dataclass‑Definition, um nur initialisierbare Felder zu überprüfen,
        und ergänzt spezifische, bekannte Reparaturen – **ohne** eine neue Instanz
        zu erzeugen.
        """
        repairs: List[str] = []

        default_values: Dict[str, Any] = {}
        for f in fields(AdvancedSettings):
            if not f.init:
                continue
            if f.default is not dataclasses.MISSING:
                default_values[f.name] = f.default
            elif f.default_factory is not dataclasses.MISSING:
                try:
                    default_values[f.name] = f.default_factory()
                except Exception:
                    default_values[f.name] = None
            else:
                default_values[f.name] = None

        for f in fields(AdvancedSettings):
            if not f.init:
                continue

            field_name = f.name
            current_val = getattr(self, field_name, None)

            # 2a. Fehlendes Attribut oder None → auf Default setzen
            if current_val is None and field_name in default_values:
                setattr(self, field_name, default_values[field_name])
                repairs.append(f"Repaired missing/invalid field '{field_name}'")

            # 2b. Wertebereichsprüfungen für bestimmte Felder
            if field_name == "beam_size":
                if not isinstance(current_val, int) or current_val < 1 or current_val > 20:
                    setattr(self, field_name, 10)
                    repairs.append("Beam size reset to 10")
            elif field_name == "temperature":
                if not isinstance(current_val, (int, float)) or current_val < 0.0 or current_val > 2.0:
                    setattr(self, field_name, 0.0)
                    repairs.append("Temperature reset to 0.0")
            elif field_name == "vad_threshold":
                if not isinstance(current_val, (int, float)) or current_val < 0.0 or current_val > 1.0:
                    setattr(self, field_name, 0.2)
                    repairs.append("VAD threshold reset to 0.2")
            elif field_name == "min_confidence":
                if not isinstance(current_val, (int, float)) or current_val < 0.0 or current_val > 1.0:
                    setattr(self, field_name, 0.1)
                    repairs.append("Min confidence reset to 0.1")
            elif field_name == "duplicate_similarity_threshold":
                if not isinstance(current_val, (int, float)) or current_val < 0.5 or current_val > 1.0:
                    setattr(self, field_name, 0.98)
                    repairs.append("Duplicate threshold reset to 0.98")
            elif field_name == "max_memory_mb":
                if not isinstance(current_val, int) or current_val < 100 or current_val > 16384:
                    setattr(self, field_name, 1024)
                    repairs.append("Max memory reset to 1024 MB")
            elif field_name == "vram_idle_timeout_seconds":
                if not isinstance(current_val, int) or current_val < 0:
                    setattr(self, field_name, 180)
                    repairs.append("VRAM idle timeout reset to 180s")
            elif field_name == "auto_save_interval":
                if not isinstance(current_val, int) or current_val < 0:
                    setattr(self, field_name, 300)
                    repairs.append("Auto‑save interval reset to 300s")
            elif field_name == "translation_engine":
                valid_engines = {"google", "ollama", "argos"}
                if current_val not in valid_engines:
                    setattr(self, field_name, "google")
                    repairs.append("Translation engine reset to 'google'")
            elif field_name == "tts_engine":
                valid_engines = {"piper", "pyttsx3", "espeak"}
                if current_val not in valid_engines:
                    setattr(self, field_name, "piper")
                    repairs.append("TTS engine reset to 'piper'")
            elif field_name == "target_language":
                if current_val not in SUPPORTED_LANGUAGES:
                    setattr(self, field_name, "de")
                    repairs.append("Target language reset to 'de'")
            elif field_name == "blacklist_mode":
                if current_val not in ("word", "substring"):
                    setattr(self, field_name, "word")
                    repairs.append("Blacklist mode reset to 'word'")
            elif field_name == "audio_profile":
                valid_profiles = {"transcription", "realtime", "noisy", "podcast", "music"}
                if current_val not in valid_profiles:
                    setattr(self, field_name, "transcription")
                    repairs.append("Audio profile reset to 'transcription'")
            elif field_name == "chunk_duration" and hasattr(self, "_chunk_duration"):
                # Wird separat behandelt, siehe unten
                pass
            elif field_name == "hotwords" and not isinstance(current_val, str):
                setattr(self, field_name, "")
                repairs.append("Hotwords reset to empty string")
            elif field_name == "proxy_url" and not isinstance(current_val, str):
                setattr(self, field_name, "")
                repairs.append("Proxy URL reset to empty string")
            elif field_name == "ollama_host" and not isinstance(current_val, str):
                setattr(self, field_name, "http://localhost:11434")
                repairs.append("Ollama host reset to default")
            elif field_name == "ollama_model" and not isinstance(current_val, str):
                setattr(self, field_name, "llama3.1:8b")
                repairs.append("Ollama model reset to default")
            elif field_name in ("enable_sentiment_analysis", "enable_speaker_diarization",
                                "optimize_translations", "vad_filter", "gpu_acceleration",
                                "adaptive_chunk", "asian_mode", "precision_mode",
                                "enable_reflection", "auto_tts_transcript",
                                "auto_tts_translation", "proxy_enabled", "live_from_start"):
                if not isinstance(current_val, bool):
                    setattr(self, field_name, False)
                    repairs.append(f"{field_name} reset to False")
            elif field_name in ("transcription_workers", "translation_workers", "cpu_threads"):
                if not isinstance(current_val, int) or current_val < 0:
                    setattr(self, field_name, 0 if field_name == "cpu_threads" else 4)
                    repairs.append(f"{field_name} reset to default")

        if hasattr(self, "ollama_model") and self.ollama_model == "llama3":
            self.ollama_model = "llama3.1:8b"
            repairs.append("Updated ollama_model from 'llama3' to 'llama3.1:8b'")

        if not hasattr(self, "config") or self.config is None:
            self._recreate_config()
            repairs.append("Recreated config")

        self._apply_mode_overrides()

        if hasattr(self, "_chunk_duration"):
            self.chunk_duration = self._chunk_duration
            if hasattr(self, "config") and self.config is not None:
                if abs(self.config.CHUNK_DURATION - self._chunk_duration) > 0.001:
                    repairs.append(f"Synchronized chunk duration to {self._chunk_duration:.1f}s")

        try:
            from importlib.metadata import version
            pydantic_ver = version("pydantic")
            core_ver = version("pydantic-core")
            # Entferne Build‑Metadaten (z.B. "+cu118")
            pydantic_base = pydantic_ver.split("+")[0]
            core_base = core_ver.split("+")[0]
            # Major‑Versionen vergleichen
            pydantic_major = pydantic_base.split(".")[0]
            core_major = core_base.split(".")[0]

            if pydantic_major != core_major:
                repairs.append(
                    f"Pydantic‑Inkompatibilität: pydantic={pydantic_ver}, core={core_ver} → "
                    "versuche Reparatur"
                )

                # ── Automatisches Downgrade auf kompatible Version ──
                import subprocess
                import sys
                target_pydantic = "2.46.4"
                target_core = "2.46.4"

                cmd = [
                    sys.executable, "-m", "pip", "install",
                    f"pydantic=={target_pydantic}",
                    f"pydantic-core=={target_core}",
                    "--upgrade"
                ]

                in_venv = hasattr(sys, "real_prefix") or (
                    hasattr(sys, "base_prefix") and sys.base_prefix != sys.prefix
                )
                if not in_venv:
                    if self._pip_supports_break_system():
                        cmd.append("--break-system-packages")
                    else:
                        cmd.append("--user")

                try:
                    subprocess.run(cmd, check=True, timeout=120)
                    repairs.append("✅ Pydantic‑Pakete erfolgreich aktualisiert")
                    # Cache leeren
                    FastLazyLoader.clear_cache("pydantic")
                    FastLazyLoader.clear_cache("pydantic_core")
                    # Prüfe erneut
                    new_core = version("pydantic-core")
                    if new_core.startswith(target_core):
                        repairs.append("✅ Pydantic‑Kompatibilität wiederhergestellt")
                    else:
                        repairs.append(
                            "⚠️ Automatische Reparatur teilweise fehlgeschlagen – "
                            "wechsle zu Google‑Engine"
                        )
                        self.translation_engine = "google"
                except subprocess.CalledProcessError as e:
                    repairs.append(f"❌ pip‑Update fehlgeschlagen (Exit {e.returncode}) – "
                                   "wechsle zu Google‑Engine")
                    self.translation_engine = "google"
                except subprocess.TimeoutExpired:
                    repairs.append("⏰ pip‑Update Zeitüberschreitung – "
                                   "wechsle zu Google‑Engine")
                    self.translation_engine = "google"
                except Exception as e:
                    repairs.append(f"❌ Pydantic‑Reparatur fehlgeschlagen: {e} – "
                                   "wechsle zu Google‑Engine")
                    self.translation_engine = "google"

        except ImportError:
            pass
        except Exception as e:
            repairs.append(f"⚠️ Pydantic‑Prüfung fehlgeschlagen: {e}")

        if not hasattr(self, "_original_values") or not isinstance(
            self._original_values, dict
        ):
            self._original_values = {}
            repairs.append("Initialized _original_values")

        if not hasattr(self, "_mode_overrides_applied"):
            self._mode_overrides_applied = False
            repairs.append("Initialized _mode_overrides_applied")

        if repairs:
            logger.info(f"✅ AdvancedSettings repairs: {', '.join(repairs)}")
            self.save_to_file()
        else:
            logger.info("✅ No repairs needed – all fields valid")

        return repairs

    def _pip_supports_break_system(self) -> bool:
        """Prüft, ob die installierte pip‑Version --break-system-packages unterstützt."""
        try:
            import subprocess
            result = subprocess.run(
                [sys.executable, "-m", "pip", "--version"],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            if result.returncode == 0:
                version_str = result.stdout.split()[1] if result.stdout else "0"
                version_parts = tuple(int(x) for x in version_str.split(".")[:2])
                return version_parts >= (23, 0)
        except Exception:
            pass
        return False

    def set_config_type(self, config_type: str) -> bool:
        if config_type == self.config_type:
            return True
        if config_type not in ("default", "realtime", "high_accuracy", "youtube"):
            logger.warning(f"⚠️ Ungültiger config_type '{config_type}'")
            return False

        old_type = self.config_type
        old_chunk = self.chunk_duration

        self.config_type = config_type
        self._recreate_config()
        self.chunk_duration = old_chunk
        self._apply_mode_overrides()

        logger.info(
            f"🔄 Config type geändert: {old_type} → {config_type}, neue CHUNK_DURATION: {self.config.CHUNK_DURATION}s"
        )

        try:
            event_bus = AppContext().event_bus
            if event_bus:
                event_bus.emit(
                    "config_changed",
                    {
                        "config_type": config_type,
                        "old_type": old_type,
                        "chunk_duration": self.chunk_duration,
                        "sample_rate": self.config.SAMPLE_RATE,
                        "channels": self.config.CHANNELS,
                        "bytes_per_second": self.config.BYTES_PER_SECOND,
                    },
                )
                log_debug("settings", f"Sent config_changed event for {config_type}")
        except Exception as e:
            logger.warning(f"Konnte config_changed Event nicht senden: {e}")

        return True

    def get_audio_filter(
        self, language: Optional[str] = None, profile: Optional[str] = None
    ) -> str:
        return self.config.get_audio_filter(language, profile or self.audio_profile)

    def get_youtube_headers(self, is_manifest: bool = False) -> Dict[str, str]:
        return self.config.get_youtube_headers(is_manifest)

    def get_platform_config(self, platform: Optional[str] = None) -> Dict[str, Any]:
        return self.config.get_platform_config(platform)

