def _safe_print(*args: Any, **kwargs: Any) -> None:
    """Gibt Text auf der Konsole aus und fängt UnicodeEncodeError ab."""
    file = kwargs.get("file", sys.stdout)
    encoding = getattr(file, "encoding", None) or "utf-8"
    try:
        print(*args, **kwargs)
        return
    except UnicodeEncodeError:
        pass
    try:
        safe_args = []
        for arg in args:
            if isinstance(arg, str):
                safe_args.append(
                    arg.encode(encoding, errors="replace").decode(encoding)
                )
            else:
                safe_args.append(arg)
        print(*safe_args, **kwargs)
        return
    except UnicodeEncodeError:
        pass
    try:
        ascii_args = []
        for arg in args:
            if isinstance(arg, str):
                ascii_args.append(arg.encode("ascii", errors="replace").decode("ascii"))
            else:
                ascii_args.append(arg)
        print(*ascii_args, **kwargs)
    except Exception:
        print(*(repr(a) for a in args), **kwargs)


def _print_welcome(debug_level: int, quiet: bool) -> None:
    if quiet or debug_level == 0:
        return
    use_emoji = _can_use_emoji(debug_level)
    title = (
        "🐉 DRAGON WHISPERER READY" if use_emoji else "*** DRAGON WHISPERER READY ***"
    )
    if debug_level >= 3:
        _log_debug_welcome_info(debug_level, use_emoji, quiet)
    _safe_print("\n" + "=" * 50)
    _safe_print(title)
    _safe_print("=" * 50)
    _safe_print(f"Platform: {_get_platform_string()}")
    _safe_print(f"Python: {sys.version.split()[0]}")
    _safe_print(f"Working Dir: {os.getcwd()}")
    _safe_print("Model: (wird beim Start geladen)")
    _safe_print("=" * 50 + "\n")


def _can_use_emoji(debug_level: int) -> bool:
    if not sys.stdout.isatty():
        if debug_level >= 4:
            log_debug("welcome", "Emojis deaktiviert: stdout ist kein TTY")
        return False
    if IS_WINDOWS:
        if not _is_windows_terminal(debug_level):
            if debug_level >= 4:
                log_debug("welcome", "Windows: Kein modernes Terminal → ASCII")
            return False
    encoding = sys.stdout.encoding or "unknown"
    if encoding.lower() not in ("utf-8", "utf8"):
        if debug_level >= 4:
            log_debug("welcome", f"Kodierung {encoding} nicht UTF‑8 → ASCII")
        return False
    term = os.environ.get("TERM", "").lower()
    if term in ("dumb", "unknown", ""):
        if debug_level >= 4:
            log_debug("welcome", f"TERM={term} → Emojis deaktiviert")
        return False
    try:
        sys.stdout.write("\U0001f409")
        sys.stdout.write("\n")
        sys.stdout.flush()
        return True
    except (UnicodeEncodeError, UnicodeError):
        if debug_level >= 4:
            log_debug("welcome", "UnicodeEncodeError beim Emoji‑Test → ASCII")
        return False
    except Exception as e:
        if debug_level >= 4:
            log_debug("welcome", f"Unerwarteter Fehler beim Emoji‑Test: {e}")
        return False
    finally:
        try:
            sys.stdout.write("\r\033[K")
        except Exception:
            pass

