# ────────────────────────────────────────────────────────────────────────────────
# 1. Terminal‑ und Plattform‑Erkennung
# ────────────────────────────────────────────────────────────────────────────────


def _is_windows_terminal(debug_level: int = 0) -> bool:
    """Erkennt zuverlässig moderne Windows‑Terminals (Unterstützung für Emojis) – mit Cache."""
    global _is_windows_terminal_cache
    if _is_windows_terminal_cache is not None:
        return _is_windows_terminal_cache

    if not sys.platform.startswith("win"):
        _is_windows_terminal_cache = False
        return False

    if os.environ.get("WT_SESSION"):
        if debug_level >= 4:
            log_debug("welcome", "Windows Terminal erkannt (WT_SESSION)")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("TERM_PROGRAM") == "vscode":
        if debug_level >= 4:
            log_debug("welcome", "VS Code Terminal erkannt (TERM_PROGRAM=vscode)")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("ConEmuPID"):
        if debug_level >= 4:
            log_debug("welcome", "ConEmu/Cmder erkannt (ConEmuPID)")
        _is_windows_terminal_cache = True
        return True

    ps_module_path = os.environ.get("PSModulePath", "")
    if "powershell" in ps_module_path.lower():
        if debug_level >= 4:
            log_debug("welcome", "PowerShell erkannt → Emojis möglich")
        _is_windows_terminal_cache = True
        return True

    if os.environ.get("TERM", "").lower() in ("xterm", "xterm-256color", "cygwin"):
        if shutil.which("mintty"):
            if debug_level >= 4:
                log_debug("welcome", "Mintty (Git Bash) erkannt")
            _is_windows_terminal_cache = True
            return True

    if os.environ.get("TERM", "").endswith("256color"):
        if debug_level >= 4:
            log_debug("welcome", "TERM mit 256 Farben → Emojis wahrscheinlich")
        _is_windows_terminal_cache = True
        return True

    if debug_level >= 4:
        log_debug(
            "welcome",
            "Altes CMD oder nicht unterstütztes Terminal → Emojis deaktiviert",
        )
    _is_windows_terminal_cache = False
    return False


def _get_platform_string() -> str:
    """Erzeugt einen lesbaren Plattform‑String mit Architektur und Container‑Info (gecached)."""
    global _platform_string_cache
    if _platform_string_cache is not None:
        return _platform_string_cache

    import platform

    base = platform.system()
    arch = "ARM" if platform.machine().lower() in ("arm64", "aarch64") else "x86"
    info = f"{base} {arch}"
    container = _get_container_type()
    if container != "none":
        info += f" ({container.upper()})"
    _platform_string_cache = info
    return info


def _get_container_type() -> str:
    """Ermittelt den Containertyp (docker, wsl, flatpak, snap) – mit Cache."""
    global _container_type_cache
    if _container_type_cache is not None:
        return _container_type_cache

    import platform

    if os.path.exists("/.dockerenv"):
        _container_type_cache = "docker"
        return "docker"
    try:
        with open("/proc/1/cgroup", "r") as f:
            if any("docker" in line for line in f):
                _container_type_cache = "docker"
                return "docker"
            if any("lxc" in line for line in f):
                _container_type_cache = "lxc"
                return "lxc"
    except Exception:
        pass
    if (
        "WSL_DISTRO_NAME" in os.environ
        or "microsoft" in platform.uname().release.lower()
    ):
        _container_type_cache = "wsl"
        return "wsl"
    if "FLATPAK_ID" in os.environ or "FLATPAK_SANDBOX_DIR" in os.environ:
        _container_type_cache = "flatpak"
        return "flatpak"
    if "SNAP" in os.environ or "SNAP_NAME" in os.environ:
        _container_type_cache = "snap"
        return "snap"
    _container_type_cache = "none"
    return "none"


def extract_debug_info(args: argparse.Namespace) -> Tuple[int, List[str]]:
    """
    Extrahiert Debug-Level und -Komponenten aus den akkumulierten --debug-Argumenten.
    """
    debug_level: int = 0
    debug_components: List[str] = []
    all_components_requested: bool = False
    raw_items: List[str] = []

    if hasattr(args, "debug") and args.debug:
        if isinstance(args.debug, list):
            raw_items = args.debug
        elif isinstance(args.debug, str):
            raw_items = [args.debug]
        else:
            raw_items = [str(args.debug)]

    if hasattr(args, "debug_level") and args.debug_level is not None:
        try:
            debug_level = max(debug_level, int(args.debug_level))
        except (ValueError, TypeError):
            pass

    for item in raw_items:
        if not item or not isinstance(item, str):
            continue

        item = item.strip()
        if not item:
            continue

        # ── 3a. Sonderfall: 'all' ──────────────────────────────────────
        if item.lower() == "all":
            all_components_requested = True
            debug_level = max(debug_level, 3)  # 'all' erzwingt Level 3
            continue

        # ── 3b. Reine Zahl (Debug-Level) ──────────────────────────────
        if item.isdigit():
            try:
                level = int(item)
                debug_level = max(debug_level, level)
            except ValueError:
                pass
            continue

        # ── 3c. Gemischter String wie "3,transcribe,translate" ─────────
        if "," in item:
            parts = [p.strip() for p in item.split(",") if p.strip()]
            for part in parts:
                if part.isdigit():
                    try:
                        debug_level = max(debug_level, int(part))
                    except ValueError:
                        pass
                elif part.lower() == "all":
                    all_components_requested = True
                    debug_level = max(debug_level, 3)
                else:
                    debug_components.append(part.lower())
            continue

        # ── 3d. Einzelne Komponente ──────────────────────────────────────
        debug_components.append(item.lower())

    env_debug = os.environ.get("DRAGON_DEBUG", "").strip()
    if env_debug:
        env_parts = [p.strip() for p in env_debug.split(",") if p.strip()]
        for part in env_parts:
            if part.isdigit():
                try:
                    debug_level = max(debug_level, int(part))
                except ValueError:
                    pass
            elif part.lower() == "all":
                all_components_requested = True
                debug_level = max(debug_level, 3)
            else:
                debug_components.append(part.lower())

    if all_components_requested:
        debug_components.extend(ALL_DEBUG_COMPONENTS)

    debug_components = sorted(set(debug_components))

    if debug_components:
        unknown = [
            c for c in debug_components if c not in ALL_DEBUG_COMPONENTS and c != "all"
        ]
        if unknown:
            try:
                logger = logging.getLogger("dragon")
                logger.warning(
                    f"⚠️ Unbekannte Debug-Komponente(n): {', '.join(unknown)}"
                )
                logger.info(
                    f"   Verfügbare Komponenten: {', '.join(ALL_DEBUG_COMPONENTS[:10])}..."
                )
            except Exception:
                print(f"⚠️ Unbekannte Debug-Komponente(n): {', '.join(unknown)}")

    if hasattr(args, "quiet") and args.quiet:
        debug_level = 0
        debug_components = []

    try:
        logger = logging.getLogger("dragon")
        logger.debug(
            "Debug-Konfiguration extrahiert: level=%d, components=%d (%s)",
            debug_level,
            len(debug_components),
            ", ".join(debug_components[:5])
            + ("..." if len(debug_components) > 5 else ""),
        )
    except Exception:
        pass

    return debug_level, debug_components


def _write_crash_report(exception: BaseException, traceback_str: str) -> None:
    """Schreibt einen ausführlichen Crash‑Report in eine Log‑Datei (erweitert)."""
    if isinstance(exception, (KeyboardInterrupt, SystemExit)):
        return

    try:
        config_dir = PlatformUtils.get_platform_config_dir()
        config_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        config_dir = Path(tempfile.gettempdir()) / "dragon_crashes"

    timestamp = time.strftime("%Y%m%d_%H%M%S")
    crash_file = config_dir / f"crash_{timestamp}.log"
    json_file = config_dir / f"crash_{timestamp}.json"

    system_info = {
        "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        "exception_type": type(exception).__name__,
        "exception_message": str(exception),
        "traceback": traceback_str[:200000],
        "platform": sys.platform,
        "python_version": sys.version,
        "python_executable": sys.executable,
        "cpu_count": os.cpu_count(),
        "working_directory": os.getcwd(),
        "command_line": sys.argv,
        "environment": {
            k: v
            for k, v in os.environ.items()
            if not any(s in k.lower() for s in ("key", "token", "secret", "password"))
        },
    }

    try:
        import psutil

        mem = psutil.virtual_memory()
        system_info["memory_total_gb"] = mem.total / (1024**3)
        system_info["memory_available_gb"] = mem.available / (1024**3)
        disk = psutil.disk_usage(str(config_dir))
        system_info["disk_free_gb"] = disk.free / (1024**3)
        system_info["cpu_percent"] = psutil.cpu_percent(interval=0.1)
    except ImportError:
        pass

    try:
        with open(crash_file, "w", encoding="utf-8") as f:
            f.write("=" * 80 + "\n")
            f.write("DRAGON WHISPERER CRASH REPORT\n")
            f.write(f"Time: {system_info['time']}\n")
            f.write(
                f"Exception: {system_info['exception_type']}: {system_info['exception_message']}\n"
            )
            f.write("=" * 80 + "\n\n")
            f.write("TRACEBACK:\n")
            f.write(traceback_str)
            f.write("\n\n" + "=" * 80 + "\n")
            f.write("SYSTEM INFORMATION:\n")
            for key, value in system_info.items():
                if key in ("traceback", "exception_type", "exception_message"):
                    continue
                if isinstance(value, dict):
                    f.write(f"\n{key}:\n")
                    for k, v in value.items():
                        f.write(f"  {k}: {v}\n")
                else:
                    f.write(f"{key}: {value}\n")
        logger.info("📄 Crash report saved to %s", crash_file)
    except Exception as e:
        logger.warning("Could not write crash report: %s", e)

    try:
        with open(json_file, "w", encoding="utf-8") as f:
            json.dump(system_info, f, indent=2, default=str, ensure_ascii=False)
        logger.debug("📄 JSON crash report saved to %s", json_file)
    except Exception:
        pass


def _global_crash_handler(
    exc_type: type, exc_value: BaseException, exc_tb: Any, debug_level: int
) -> None:
    """Globaler Exception‑Handler, der einen Crash‑Report erstellt und loggt."""
    tb_str = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
    if not issubclass(exc_type, KeyboardInterrupt):
        _write_crash_report(exc_value, tb_str)
        if debug_level >= 1:
            logger.critical("Unhandled exception:\n%s", tb_str)
    sys.__excepthook__(exc_type, exc_value, exc_tb)


def _log_debug_welcome_info(debug_level: int, use_emoji: bool, quiet: bool) -> None:
    """Protokolliert detaillierte System‑ und Debug‑Informationen bei Debug‑Level >= 3."""
    if debug_level < 3:
        return

    import platform

    log_debug("welcome", "=" * 60)
    log_debug("welcome", "🐉 DEBUG: _print_welcome - Detaillierte Diagnose")
    log_debug("welcome", "=" * 60)

    log_debug("welcome", f"Debug-Level        : {debug_level}")
    log_debug("welcome", f"Quiet-Modus        : {quiet}")
    log_debug("welcome", f"Emoji aktiviert    : {use_emoji}")
    log_debug("welcome", f"stdout.isatty()    : {sys.stdout.isatty()}")
    log_debug("welcome", f"stdout.encoding    : {sys.stdout.encoding or 'UNKNOWN'}")
    log_debug("welcome", f"stdin.encoding     : {sys.stdin.encoding or 'UNKNOWN'}")
    log_debug("welcome", f"stderr.encoding    : {sys.stderr.encoding or 'UNKNOWN'}")

    env_vars = (
        "TERM",
        "LANG",
        "WT_SESSION",
        "COLORTERM",
        "PYTHONIOENCODING",
        "TERM_PROGRAM",
        "ConEmuPID",
        "WSL_DISTRO_NAME",
    )
    for var in env_vars:
        value = os.environ.get(var, "nicht gesetzt")
        log_debug("welcome", f"${var:20} : {value}")

    log_debug("welcome", f"SYSTEM             : {platform.system()}")
    log_debug("welcome", f"IS_WINDOWS         : {sys.platform.startswith('win')}")
    log_debug("welcome", f"IS_MACOS           : {sys.platform == 'darwin'}")
    log_debug("welcome", f"IS_LINUX           : {sys.platform.startswith('linux')}")
    log_debug(
        "welcome",
        f"IS_ARM             : {platform.machine().lower() in ('arm64', 'aarch64')}",
    )
    log_debug(
        "welcome",
        f"IS_X86             : {platform.machine().lower() in ('x86_64', 'amd64')}",
    )
    log_debug("welcome", f"platform.uname()   : {platform.uname()}")
    log_debug("welcome", f"Python-Version     : {sys.version}")
    log_debug("welcome", f"Python-Executable  : {sys.executable}")

    enc_info = _get_encoding_info()
    for key, value in enc_info.items():
        log_debug("welcome", f"encoding_{key:20} : {value or 'UNKNOWN'}")

    log_debug("welcome", "-" * 60)
    log_debug("welcome", "Emoji-Entscheidung im Detail:")

    if not sys.stdout.isatty():
        log_debug("welcome", "  ❌ stdout ist kein TTY → Emojis deaktiviert")
    elif sys.platform.startswith("win") and not _is_windows_terminal(debug_level):
        log_debug(
            "welcome", "  ❌ Windows: Kein modernes Terminal → Emojis deaktiviert"
        )
    elif (sys.stdout.encoding or "unknown").lower() not in ("utf-8", "utf8"):
        log_debug(
            "welcome",
            f"  ❌ Kodierung {sys.stdout.encoding} nicht UTF-8 → Emojis deaktiviert",
        )
    elif os.environ.get("TERM", "").lower() in ("dumb", "unknown", ""):
        log_debug(
            "welcome",
            f"  ❌ TERM={os.environ.get('TERM', 'nicht gesetzt')} → Emojis deaktiviert",
        )
    else:
        log_debug("welcome", "  ✅ Alle Prüfungen bestanden → Emojis aktiviert")

    log_debug("welcome", "=" * 60)


def _get_encoding_info() -> Dict[str, Optional[str]]:
    """Sammelt alle relevanten Kodierungsinformationen des Systems."""
    import locale

    return {
        "stdin_encoding": sys.stdin.encoding,
        "stdout_encoding": sys.stdout.encoding,
        "stderr_encoding": sys.stderr.encoding,
        "locale_preferred": locale.getpreferredencoding(),
        "filesystem_encoding": sys.getfilesystemencoding(),
        "default_encoding": sys.getdefaultencoding(),
    }


def _show_critical_error(message: str) -> None:
    if sys.platform.startswith("win") and not sys.stdin.isatty():
        try:
            import ctypes

            short_msg = message[:200] + "..." if len(message) > 200 else message
            ctypes.windll.user32.MessageBoxW(
                0,
                f"Dragon Whisperer - Critical Error\n\n{short_msg}",
                "Critical Error",
                0x10,
            )
        except Exception:
            pass
    else:
        print(f"\n💥 {message}")


def _setup_early_environment() -> None:
    """Setzt frühzeitig Umgebungsvariablen für maximale Kompatibilität und Stabilität."""
    os.environ.setdefault("LOKY_PURGE", "1")
    os.environ.setdefault(
        "JOBLIB_START_METHOD", "fork" if not sys.platform.startswith("win") else "spawn"
    )
    if "LOKY_MAX_WORKERS" not in os.environ:
        cpu_count = os.cpu_count() or 2
        os.environ["LOKY_MAX_WORKERS"] = str(max(1, cpu_count // 2))
    os.environ.setdefault("PYDANTIC_IGNORE_CORE_MISMATCH", "1")
    os.environ.setdefault("PYTHONUNBUFFERED", "1")
    if sys.platform.startswith("win"):
        os.environ.setdefault("PYTHONLEGACYWINDOWSSTDIO", "1")


def _validate_and_repair_environment(debug_level: int) -> List[str]:
    """Führt Umgebungsvalidierungen und -reparaturen durch (Temp‑Verzeichnis, Konfiguration)."""
    repairs = []
    config_dir = PlatformUtils.get_platform_config_dir()
    adv_file = config_dir / "dragon_advanced_settings.json"
    if adv_file.exists() and adv_file.stat().st_size == 0:
        try:
            adv_file.unlink()
            repairs.append("Leere AdvancedSettings‑Datei gelöscht")
        except Exception:
            pass
    try:
        test_file = tempfile.NamedTemporaryFile(delete=False)
        test_file.close()
        os.unlink(test_file.name)
    except (PermissionError, OSError):
        user_temp = Path.home() / ".cache" / "dragon_temp"
        user_temp.mkdir(parents=True, exist_ok=True)
        tempfile.tempdir = str(user_temp)
        repairs.append(f"Temp‑Verzeichnis auf {user_temp} umgestellt")
    if sys.platform.startswith("win") and os.environ.get("PYTHONIOENCODING") != "utf-8":
        os.environ["PYTHONIOENCODING"] = "utf-8"
        repairs.append("PYTHONIOENCODING auf utf-8 gesetzt")
    return repairs


def _check_gpu_health() -> Tuple[bool, str]:
    """Prüft die GPU‑Verfügbarkeit und den freien VRAM."""
    if not TORCH_AVAILABLE:
        return False, "PyTorch nicht installiert"
    try:
        import torch

        if not torch.cuda.is_available():
            return False, "Keine CUDA‑fähige GPU gefunden"
        free, total = torch.cuda.mem_get_info()
        free_gb = free / (1024**3)
        if free_gb < 0.5:
            return False, f"VRAM fast voll ({free_gb:.1f} GB frei)"
        device_name = torch.cuda.get_device_name(0)
        return True, f"✅ {device_name}, {free_gb:.1f} GB frei"
    except Exception as e:
        return False, f"GPU‑Fehler: {e}"


def _repair_configuration() -> List[str]:
    """Setzt eine beschädigte Konfiguration zurück und erstellt eine neue."""
    repairs = []
    config_dir = PlatformUtils.get_platform_config_dir()
    adv_file = config_dir / "dragon_advanced_settings.json"
    if adv_file.exists():
        backup = adv_file.with_suffix(".json.broken")
        try:
            shutil.move(str(adv_file), str(backup))
            repairs.append(f"Defekte Konfiguration nach {backup.name} verschoben")
        except Exception:
            pass
    AdvancedSettings.invalidate_cache()
    repairs.append("Neue Standardkonfiguration wird erstellt")
    return repairs


# ────────────────────────────────────────────────────────────────────────────────
# 5. Garantierte Bereinigung (deadlock‑frei, mit Timeout)
# ────────────────────────────────────────────────────────────────────────────────


def _perform_guaranteed_cleanup(
    timeout: float = 10.0,
    gui: Optional["DragonWhispererGUI"] = None,
) -> None:
    """
    Führt eine garantierte Ressourcenbereinigung mit Gesamt‑Timeout durch.
    - Idempotent (wird nur einmal ausgeführt).
    - Bereinigt alle Executors (global, AudioProcessor, Übersetzung, Timeout).
    - Terminiert alle Subprozesse (FFmpeg, yt‑dlp, VLC) inkl. Kindprozesse.
    - Bricht alle aktiven Futures ab und schließt offene Pipes.
    - Thread‑Joining mit kurzen Timeouts; verbleibende Threads werden als Daemon markiert.
    - Löscht temporäre Dateien (falls gui übergeben wurde).
    - Bei Gesamt‑Timeout wird zuerst `sys.exit(0)` versucht, um atexit‑Handler auszuführen;
      erst im Notfall wird `os._exit(0)` erzwungen.
    """
    if hasattr(_perform_guaranteed_cleanup, "_in_progress"):
        logger.debug("🔄 Bereinigung bereits aktiv – überspringe.")
        return
    _perform_guaranteed_cleanup._in_progress = True

    start = time.monotonic()
    logger.info("🧹 Starte garantierte Bereinigung (Timeout %.1fs)", timeout)
    step_times: Dict[str, float] = {}

    def _step(step_name: str, action: Callable[[], None]) -> None:
        """Führt einen Schritt aus, misst die Zeit und protokolliert Fortschritt."""
        if time.monotonic() - start >= timeout:
            logger.warning(
                "⏰ Gesamt‑Timeout überschritten – breche Schritt '%s' ab.", step_name
            )
            return
        logger.debug("  ▶️ Schritt '%s' beginnt ...", step_name)
        t0 = time.monotonic()
        try:
            action()
        except Exception as e:
            logger.warning("⚠️ Schritt '%s' fehlgeschlagen: %s", step_name, e)
        finally:
            elapsed_ms = (time.monotonic() - t0) * 1000
            step_times[step_name] = elapsed_ms
            logger.debug("  ✅ Schritt '%s' beendet in %.2f ms", step_name, elapsed_ms)

    # ─── 1. Loky‑Cleanup (inkl. resource_tracker) ──────────────────────────
    def _loky_cleanup():
        logger.debug("  ▶️ Loky‑Cleanup: Starte resource_tracker‑Stopp ...")
        try:
            import multiprocessing.resource_tracker as rt

            if hasattr(rt, "_resource_tracker") and hasattr(
                rt._resource_tracker, "stop"
            ):
                rt._resource_tracker.stop()
                logger.debug("  ✅ Resource‑Tracker gestoppt")
        except Exception as e:
            logger.debug("  ⚠️ Resource‑Tracker‑Stopp fehlgeschlagen: %s", e)

        logger.debug("  ▶️ Loky‑Cleanup: Versuche Executor‑Shutdown ...")
        try:
            from loky import get_reusable_executor

            executor = get_reusable_executor()
            if executor is not None:
                shutdown_done = threading.Event()

                def _shutdown():
                    try:
                        safe_shutdown_executor(
                            executor, wait=False, cancel_futures=True
                        )
                    except Exception:
                        pass
                    finally:
                        shutdown_done.set()

                threading.Thread(target=_shutdown, daemon=True).start()
                if not shutdown_done.wait(timeout=3.0):
                    logger.warning("⏰ Loky‑Shutdown Timeout – setze Referenz auf None")
                    try:
                        import loky

                        loky._reusable_executor = None
                    except Exception:
                        pass
                else:
                    logger.debug("✅ Loky‑Executor heruntergefahren")
            else:
                logger.debug("ℹ️ Kein Loky‑Executor vorhanden")
        except ImportError:
            logger.debug("ℹ️ Loky nicht installiert – überspringe")
        except Exception as e:
            logger.debug("⚠️ Loky‑Cleanup Fehler: %s", e)

    _step("loky_cleanup", _loky_cleanup)

    # ─── 2. Executors sammeln und Futures abbrechen ──────────────────────
    executors: List[Tuple[str, Any]] = []
    global _EXECUTOR
    if _EXECUTOR is not None:
        executors.append(("global", _EXECUTOR))
        _EXECUTOR = None

    if gui is not None:
        ap = getattr(gui, "audio_processor", None)
        if ap is not None:
            for name, attr in [
                ("transcription", "_transcription_executor"),
                ("translation", "_translation_executor"),
                ("timeout", "_transcribe_timeout_executor"),
            ]:
                exec_obj = getattr(ap, attr, None)
                if exec_obj is not None:
                    executors.append((f"audio_processor.{name}", exec_obj))
                    setattr(ap, attr, None)
        transl_exec = getattr(gui, "translation_executor", None)
        if transl_exec is not None:
            executors.append(("gui_translation", transl_exec))
            gui.translation_executor = None

    def _cancel_futures():
        for name, exec_obj in executors:
            for futures_attr in ("_futures", "_active_futures", "_pending_work_items"):
                if hasattr(exec_obj, futures_attr):
                    try:
                        container = getattr(exec_obj, futures_attr)
                        if isinstance(container, dict):
                            items = list(container.keys())
                            for f in items:
                                if not f.done():
                                    f.cancel()
                            container.clear()
                            if items:
                                logger.debug(
                                    "  → %d Future(s) aus '%s' abgebrochen",
                                    len(items),
                                    name,
                                )
                        elif isinstance(container, (list, set)):
                            items = list(container)
                            for f in items:
                                if not f.done():
                                    f.cancel()
                            container.clear()
                            if items:
                                logger.debug(
                                    "  → %d Future(s) aus '%s' abgebrochen",
                                    len(items),
                                    name,
                                )
                    except Exception:
                        pass

    _step("cancel_futures", _cancel_futures)

    # ─── 3. Executors herunterfahren (asynchron + synchron mit Timeout) ──
    def _shutdown_executors():
        for name, exec_obj in executors:
            logger.debug("  ▶️ Shutdown Executor '%s' ...", name)
            # Erst asynchron (gibt sofort zurück)
            try:
                safe_shutdown_executor(exec_obj, wait=False, cancel_futures=True)
                logger.debug(
                    "    → shutdown(wait=False, cancel_futures=True) aufgerufen"
                )
            except TypeError:
                try:
                    exec_obj.shutdown(wait=False)
                    logger.debug("    → shutdown(wait=False) (Fallback)")
                except Exception as e:
                    logger.warning("    → shutdown(wait=False) fehlgeschlagen: %s", e)
            except Exception as e:
                logger.warning("    → shutdown(wait=False) fehlgeschlagen: %s", e)

            # Dann synchron mit kurzem Timeout
            try:
                exec_obj.shutdown(wait=True, timeout=1.5)
                logger.debug("    → shutdown(wait=True, timeout=1.5s) erfolgreich")
            except TypeError:
                try:
                    exec_obj.shutdown(wait=True)
                    logger.debug("    → shutdown(wait=True) (Fallback)")
                except Exception as e:
                    logger.warning("    → shutdown(wait=True) fehlgeschlagen: %s", e)
            except Exception as e:
                logger.warning(
                    "    → shutdown(wait=True, timeout) fehlgeschlagen: %s", e
                )

    _step("shutdown_executors", _shutdown_executors)

    def _kill_subprocesses():
        if gui is not None:
            fm = getattr(gui, "ffmpeg_manager", None)
            if fm is not None:
                try:
                    fm.kill_all_streams()
                    logger.debug("✅ FFmpeg‑Streams getötet")
                except Exception as e:
                    logger.warning("⚠️ FFmpeg‑Kill fehlgeschlagen: %s", e)
            ap = getattr(gui, "audio_processor", None)
            if ap is not None and hasattr(ap, "_safe_stop_ffmpeg"):
                try:
                    ap._safe_stop_ffmpeg()
                    logger.debug("✅ AudioProcessor‑FFmpeg gestoppt")
                except Exception as e:
                    logger.warning("⚠️ AudioProcessor‑Stop fehlgeschlagen: %s", e)

        # Alle verbleibenden Kinderprozesse (auch ohne GUI) terminieren
        try:
            import psutil

            current = psutil.Process()
            children = current.children(recursive=True)
            for child in children:
                try:
                    child.terminate()
                    try:
                        child.wait(timeout=0.5)
                    except psutil.TimeoutExpired:
                        child.kill()
                        child.wait(timeout=0.3)
                except psutil.NoSuchProcess:
                    pass
            if children:
                logger.debug("✅ %d Subprozesse terminiert", len(children))
        except ImportError:
            pass
        except Exception as e:
            logger.warning("⚠️ Subprozess‑Cleanup fehlgeschlagen: %s", e)

    _step("kill_subprocesses", _kill_subprocesses)

    # ─── 5. Temporäre Dateien löschen (falls gui vorhanden) ──────────────
    def _cleanup_temp_files():
        if gui is None:
            return
        temp_files = getattr(gui, "_temp_files", None)
        if not temp_files:
            return
        deleted = 0
        for f in list(temp_files):
            try:
                if os.path.exists(f):
                    os.unlink(f)
                    deleted += 1
            except Exception:
                pass
        temp_files.clear()
        if deleted:
            logger.debug("✅ %d temporäre Dateien gelöscht", deleted)

    _step("cleanup_temp_files", _cleanup_temp_files)

    # ─── 6. Threads sauber beenden (priorisiert, mit kurzem Timeout) ─────
    def _join_threads():
        main_thread = threading.main_thread()
        remaining = timeout - (time.monotonic() - start)
        if remaining <= 0:
            logger.warning(
                "⏰ Keine Zeit mehr für Thread‑Joins – markiere alle als Daemon"
            )
            for t in threading.enumerate():
                if t is not main_thread and t.is_alive():
                    try:
                        t.daemon = True
                    except RuntimeError:
                        pass
            return

        priority_groups = ["loky", "ProcessPool", "Transcribe", "Translate", "FFmpeg"]
        thread_groups: Dict[str, List[threading.Thread]] = {}
        for t in threading.enumerate():
            if t is main_thread or not t.is_alive():
                continue
            prefix = t.name.split("-")[0] if "-" in t.name else t.name
            group = next(
                (g for g in priority_groups if g.lower() in prefix.lower()), "other"
            )
            thread_groups.setdefault(group, []).append(t)

        if not thread_groups:
            return

        sorted_groups = sorted(
            thread_groups.keys(),
            key=lambda g: (
                priority_groups.index(g) if g in priority_groups else 999,
                g,
            ),
        )

        for group_name in sorted_groups:
            threads = thread_groups[group_name]
            if remaining <= 0:
                break
            per_thread_timeout = min(0.3, remaining / max(1, len(threads)))
            for t in threads:
                if not t.is_alive():
                    continue
                t.join(timeout=per_thread_timeout)
                if t.is_alive():
                    try:
                        t.daemon = True
                        logger.debug("  → Thread '%s' als Daemon markiert", t.name)
                    except RuntimeError:
                        pass
                remaining = timeout - (time.monotonic() - start)
                if remaining <= 0:
                    break

    _step("join_threads", _join_threads)
    _step("gc_collect", lambda: gc.collect())

    def _emit_shutdown_event():
        if gui is not None:
            event_bus = getattr(gui, "event_bus", None)
            if event_bus is not None:
                try:
                    event_bus.emit("shutdown_completed", {"timeout": timeout})
                    logger.debug("✅ Shutdown‑Event gesendet")
                except Exception:
                    pass

    _step("emit_shutdown_event", _emit_shutdown_event)

    elapsed = time.monotonic() - start
    if elapsed >= timeout:
        logger.critical(
            "⏰ Bereinigungs‑Timeout (%.1fs) überschritten – Schritt‑Zeiten: %s",
            timeout,
            ", ".join(f"{k}={v:.1f}ms" for k, v in step_times.items()),
        )
        for t in threading.enumerate():
            if t is not threading.main_thread() and t.is_alive():
                try:
                    t.daemon = True
                except RuntimeError:
                    pass
        try:
            sys.exit(0)
        except SystemExit:
            raise
        except Exception:
            os._exit(0)
    else:
        logger.info(
            "✅ Garantierte Bereinigung abgeschlossen in %.2f ms\n"
            "   Schritt‑Zeiten: %s",
            elapsed * 1000,
            ", ".join(f"{k}={v:.1f}ms" for k, v in step_times.items()),
        )

    _perform_guaranteed_cleanup._in_progress = False

def _perform_loky_cleanup() -> None:
    """
    ULTIMATIVE, GARANTIERTE BEREINIGUNG DES LOKY‑REUSABLE‑EXECUTORS.
    Behebt Semaphore‑Leaks, die bei der Debug‑Ausgabe als
    "leaked semaphore objects" erscheinen.
    """
    import warnings

    warnings.filterwarnings(
        "ignore", category=UserWarning, module="multiprocessing.resource_tracker"
    )

    # ── Hilfsfunktion für gründliche Bereinigung eines Executors ──
    def _cleanup_executor(executor, name="executor"):
        if executor is None:
            return
        try:
            # 1. Ausstehende Futures abbrechen
            if hasattr(executor, "_pending_work_items"):
                pending = list(executor._pending_work_items.keys())
                for future in pending:
                    future.cancel()
                executor._pending_work_items.clear()
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "loky",
                        f"{len(pending)} ausstehende Futures abgebrochen ({name})",
                    )

            # 2. ★★★ INTERNEN THREADPOOLEXECUTOR HERUNTERFAHREN ★★★
            if hasattr(executor, "_executor") and executor._executor is not None:
                inner = executor._executor
                try:
                    safe_shutdown_executor(inner, wait=False, cancel_futures=True)
                except Exception:
                    inner.shutdown(wait=False)
                # Threads des inneren Executors als Daemon markieren
                if hasattr(inner, "_threads"):
                    for t in list(inner._threads):
                        if t.is_alive():
                            try:
                                t.daemon = True
                            except RuntimeError:
                                pass
                    inner._threads.clear()
                executor._executor = None
                if DEBUG_LEVEL >= 4:
                    log_debug("loky", f"Inneren Executor bereinigt ({name})")

            # 3. Executor selbst herunterfahren
            try:
                safe_shutdown_executor(executor, wait=False, cancel_futures=True)
            except Exception:
                executor.shutdown(wait=False)
            if hasattr(executor, "_stop"):
                try:
                    executor._stop()
                except Exception:
                    pass

            # 4. Interne Threads als Daemon markieren
            if hasattr(executor, "_threads"):
                for t in list(executor._threads):
                    if t.is_alive():
                        try:
                            t.daemon = True
                        except RuntimeError:
                            pass
                executor._threads.clear()

            if hasattr(executor, "_executor"):
                executor._executor = None
            if hasattr(executor, "_shutdown"):
                executor._shutdown = True

            if DEBUG_LEVEL >= 3:
                log_debug("loky", f"Executor {name} bereinigt")
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("loky", f"Fehler bei Bereinigung von {name}: {e}")

    executor = None
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
    except ImportError:
        pass
    except Exception as e:
        if DEBUG_LEVEL >= 3:
            log_debug("loky", f"get_reusable_executor() fehlgeschlagen: {e}")

    if executor is not None:
        _cleanup_executor(executor, "reusable")

    try:
        import loky

        if hasattr(loky, "_reusable_executor"):
            executor2 = loky._reusable_executor
            if executor2 is not None and executor2 is not executor:
                _cleanup_executor(executor2, "direct")
            loky._reusable_executor = None
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "loky._reusable_executor auf None gesetzt")
    except Exception:
        pass

    loky_threads = [
        t for t in threading.enumerate() if t.name.startswith("loky") and t.is_alive()
    ]
    if loky_threads:
        if DEBUG_LEVEL >= 3:
            log_debug("loky", f"Beende {len(loky_threads)} loky-Thread(s)...")
        for t in loky_threads:
            try:
                t.join(timeout=0.5)
                if t.is_alive():
                    t.daemon = True
                    if DEBUG_LEVEL >= 4:
                        log_debug("loky", f"Thread '{t.name}' als Daemon markiert")
            except RuntimeError:
                pass

    try:
        import joblib

        if (
            hasattr(joblib, "_parallel_backend")
            and joblib._parallel_backend is not None
        ):
            backend = joblib._parallel_backend
            if hasattr(backend, "terminate"):
                try:
                    backend.terminate()
                except Exception:
                    pass
            elif hasattr(backend, "shutdown"):
                try:
                    backend.shutdown()
                except Exception:
                    pass
            joblib._parallel_backend = None
            if DEBUG_LEVEL >= 3:
                log_debug("loky", "joblib parallel backend bereinigt")
    except ImportError:
        pass
    except Exception as e:
        if DEBUG_LEVEL >= 3:
            log_debug("loky", f"joblib-Cleanup fehlgeschlagen: {e}")

    try:
        import multiprocessing

        active = multiprocessing.active_children()
        if active:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "loky", f"Terminiere {len(active)} Multiprocessing‑Prozesse..."
                )
            for p in active:
                try:
                    p.terminate()
                    p.join(timeout=1.0)
                except Exception:
                    pass
    except Exception:
        pass

    for _ in range(3):
        gc.collect()
    if DEBUG_LEVEL >= 3:
        log_debug("loky", "Garbage Collection (3x) durchgeführt")

    main_thread = threading.main_thread()
    for t in threading.enumerate():
        if t is not main_thread and not t.daemon and t.is_alive():
            try:
                t.daemon = True
                if DEBUG_LEVEL >= 4:
                    log_debug("loky", f"Thread '{t.name}' als Daemon markiert")
            except RuntimeError:
                pass

    if DEBUG_LEVEL >= 2:
        log_debug("loky", "✅ Loky-Cleanup abgeschlossen (Semaphore‑Leak behoben)")


@dataclass
class StartupConfig:
    debug_level: int = 0
    debug_components: List[str] = field(default_factory=list)
    quiet: bool = False
    headless: bool = False
    url: Optional[str] = None
    profile: Optional[str] = None
    model: Optional[str] = None
    language: Optional[str] = None
    benchmark: bool = False
    safe_mode: bool = False
    repair_config: bool = False
    check_gpu: bool = False
    crash_report: bool = True
    startup_timeout: float = 30.0
    shutdown_timeout: float = 15.0


def _run_benchmark() -> None:
    """Misst die Startzeiten der kritischen Initialisierungsphasen und gibt sie als JSON aus."""
    timings = {}
    start_total = time.perf_counter()

    start = time.perf_counter()
    _setup_early_environment()
    timings["early_env"] = time.perf_counter() - start

    start = time.perf_counter()
    args = parse_arguments()
    timings["parse_args"] = time.perf_counter() - start

    start = time.perf_counter()
    debug_level, _ = extract_debug_info(args)
    timings["debug_extract"] = time.perf_counter() - start

    start = time.perf_counter()
    configure_logging(debug_level, [], False)
    timings["logging"] = time.perf_counter() - start

    start = time.perf_counter()
    apply()
    timings["monkeypatch"] = time.perf_counter() - start

    start = time.perf_counter()
    setup_platform_environment(debug_level)
    timings["platform"] = time.perf_counter() - start

    start = time.perf_counter()
    _validate_and_repair_environment(debug_level)
    timings["repair"] = time.perf_counter() - start

    start = time.perf_counter()
    if GUI_AVAILABLE:
        app = DragonWhispererGUI()
        timings["gui_init"] = time.perf_counter() - start
        app.root.destroy()
    else:
        timings["gui_init"] = 0.0

    timings["total"] = time.perf_counter() - start_total
    print(json.dumps(timings, indent=2))


def _run_headless(args: argparse.Namespace, startup_config: StartupConfig) -> int:
    """Führt das Programm im Headless‑Modus (ohne GUI) aus."""
    logger.info("🐉 Starting in headless mode...")
    if not args.url:
        print("Error: --headless requires --url to specify a stream.", file=sys.stderr)
        return 1

    try:
        PlatformUtils.check_platform_dependencies()
    except RuntimeError as e:
        print(f"❌ Fehlende Abhängigkeiten: {e}", file=sys.stderr)
        return 1

    app_settings = AppSettings.load_from_file()
    adv_settings = AdvancedSettings.load_from_file()

    if args.model and args.model in Config.WHISPER_MODELS:
        app_settings.default_model = args.model
    if args.language and args.language in SUPPORTED_LANGUAGES:
        app_settings.default_language = args.language

    ffmpeg_manager = FFmpegManager(adv_settings.config, settings=adv_settings)
    stream_manager = StreamManager(
        enable_debug=(startup_config.debug_level >= 1),
        use_browser_cookies=app_settings.use_browser_cookies,
        proxy=adv_settings.proxy_url,
        proxy_enabled=adv_settings.proxy_enabled,
    )

    if WHISPER_AVAILABLE:
        transcription_engine = TranscriptionEngine(adv_settings)
        if (
            transcription_engine.load_model(app_settings.default_model, set_active=True)
            is None
        ):
            logger.error("❌ Failed to load model")
            return 1
    else:
        transcription_engine = DummyTranscriptionEngine(adv_settings)

    if adv_settings.translation_engine == "ollama" and OLLAMA_AVAILABLE:
        translation_engine = OllamaTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
            model=adv_settings.ollama_model,
            host=adv_settings.ollama_host,
        )
    elif adv_settings.translation_engine == "argos" and ARGOS_AVAILABLE:
        translation_engine = ArgosTranslateEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
    elif TRANSLATOR_AVAILABLE:
        translation_engine = GoogleTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )
    else:
        translation_engine = DummyTranslationEngine(
            target_lang=app_settings.default_language,
            settings=adv_settings,
        )

    processor = AudioProcessor(
        None, ffmpeg_manager, adv_settings, stream_manager=stream_manager
    )
    processor.set_engines(
        transcription_engine=transcription_engine,
        translation_engine=translation_engine,
    )

    def info_cb(msg: str) -> None:
        logger.info(msg)

    def error_cb(msg: str) -> None:
        logger.error(msg)

    def trans_cb(res: TranscriptionResult) -> None:
        if res and res.text:
            print(f"[{time.strftime('%H:%M:%S')}] {res.text}")

    def transl_cb(res: TranslationResult) -> None:
        if res and res.translated:
            print(f"[{time.strftime('%H:%M:%S')}] → {res.translated}")

    def finished_cb() -> None:
        logger.info("Processing finished.")

    processor.start_processing(
        url=args.url,
        transcription_callback=trans_cb,
        translation_callback=transl_cb,
        info_callback=info_cb,
        error_callback=error_cb,
        finished_callback=finished_cb,
    )

    try:
        while processor.is_processing() and not processor.is_stop_requested():
            time.sleep(0.5)
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
        processor.stop_processing(wait=True)
    finally:
        processor.dispose()
        transcription_engine.dispose()
        translation_engine.dispose()
        ffmpeg_manager.dispose()
        stream_manager.dispose()

    return 0


def _run_gui_with_fallbacks(
    startup_config: StartupConfig,
) -> Optional["DragonWhispererGUI"]:
    """Startet die GUI mit mehrstufigen Fallbacks bei fehlenden Abhängigkeiten."""
    if not GUI_AVAILABLE:
        logger.warning("Tkinter nicht verfügbar – wechsle in Headless‑Modus")
        if startup_config.url:
            args = argparse.Namespace(
                url=startup_config.url,
                headless=True,
                quiet=startup_config.quiet,
                debug=(
                    str(startup_config.debug_level)
                    if startup_config.debug_level
                    else "0"
                ),
                model=startup_config.model,
                language=startup_config.language,
                profile=startup_config.profile,
                version=False,
                sysinfo=False,
                check=False,
                test=False,
                help=False,
                benchmark=False,
                repair_config=False,
                check_gpu=False,
                safe_mode=startup_config.safe_mode,
            )
            _run_headless(args, startup_config)
            return None
        else:
            _show_critical_error(
                "Tkinter ist nicht installiert und keine URL für Headless‑Modus angegeben.\n"
                "Installieren Sie Tkinter (z.B. sudo apt install python3-tk) oder nutzen Sie --url."
            )
            return None

    logger.info("🐉 Dragon Whisperer starting...")
    logger.debug("🔍 Checking dependencies...")

    dependency_issue = False
    try:
        PlatformUtils.check_platform_dependencies()
    except RuntimeError as e:
        dependency_issue = True
        logger.warning(
            "Einige kritische Abhängigkeiten fehlen, aber die GUI kann "
            "trotzdem gestartet werden. Nach der Installation der "
            "Komponenten steht der volle Funktionsumfang zur Verfügung.\n%s",
            e,
        )

    app: Optional["DragonWhispererGUI"] = None
    try:
        app = DragonWhispererGUI()
    except Exception as e:
        logger.exception("❌ GUI‑Initialisierung fehlgeschlagen: %s", e)
        _show_critical_error(
            f"Die Benutzeroberfläche konnte nicht gestartet werden:\n{e}"
        )
        return None

    if startup_config.profile:
        _load_profile(app, startup_config.profile, startup_config.debug_level)

    if startup_config.url:
        _set_url_async(app, startup_config.url)

    if dependency_issue:
        _schedule_install_dialog(app)

    if startup_config.debug_level >= 1 and not startup_config.quiet:
        _print_welcome(startup_config.debug_level, startup_config.quiet)
    if startup_config.debug_level >= 3:
        _log_debug_welcome_info(startup_config.debug_level, True, startup_config.quiet)

    def _delayed_health_check(*args: Any) -> None:
        if app is None or app.is_shutting_down():
            return
        if not startup_config.safe_mode:
            health_issues = _post_startup_health_check(app)
            if health_issues:
                logger.warning(
                    "⚠️ Health‑Check Probleme:\n  • " + "\n  • ".join(health_issues)
                )
                if startup_config.debug_level >= 1:
                    app.update_status(
                        "⚠️ Einige Funktionen eingeschränkt – Details im Log"
                    )

    if app.event_bus is not None:
        app.event_bus.subscribe_once("model_load_finished", _delayed_health_check)

    exit_code = 0
    try:
        logger.info("🚀 Starting main loop...")
        app.run()
        logger.info("✅ Application closed normally")
    except KeyboardInterrupt:
        logger.info("\n🛑 Interrupted by user (KeyboardInterrupt)")
        exit_code = 130
    except SystemExit as e:
        logger.info(
            "SystemExit mit Code %d empfangen", e.code if hasattr(e, "code") else 0
        )
        exit_code = e.code if isinstance(e.code, int) else 0
    except Exception as e:
        logger.exception("💥 Unexpected error in GUI main loop: %s", e)
        if startup_config.debug_level >= 2:
            traceback.print_exc()
        exit_code = 2
    finally:
        if app is not None:
            try:
                if hasattr(app, "_cleanup_resources"):
                    app._cleanup_resources(emergency=False)
                elif hasattr(app, "dispose"):
                    app.dispose()
                else:
                    if hasattr(app, "root") and app.root.winfo_exists():
                        app.root.destroy()
                logger.debug("✅ GUI-Ressourcen freigegeben")
            except Exception as e:
                logger.warning("Fehler bei GUI‑Ressourcenbereinigung: %s", e)

        _perform_loky_cleanup()
        gc.collect()
        logger.debug("✅ Systemweite Bereinigung abgeschlossen")

    if exit_code == 0 and app is not None and not app.is_shutting_down():
        return app
    return None


def _load_profile(
    app: "DragonWhispererGUI", profile_name: str, debug_level: int
) -> None:
    """Lädt ein benutzerdefiniertes Profil aus dem Profilverzeichnis."""
    try:
        profile_path = (
            PlatformUtils.get_platform_config_dir()
            / "profiles"
            / f"{profile_name}.json"
        )
        if profile_path.exists():
            with open(profile_path, "r", encoding="utf-8") as f:
                profile_data = json.load(f)
            for key, value in profile_data.items():
                if hasattr(app.advanced_settings, key):
                    setattr(app.advanced_settings, key, value)
            logger.info("✅ Profile '%s' loaded", profile_name)
        else:
            logger.warning("⚠️ Profile '%s' not found", profile_name)
    except Exception as e:
        logger.warning("⚠️ Failed to load profile: %s", e)


def _set_url_async(app: "DragonWhispererGUI", url: str) -> None:
    """Setzt die URL asynchron im Hauptthread der GUI."""

    def _set_url():
        if hasattr(app, "url_entry") and app.url_entry.winfo_exists():
            app.url_entry.delete(0, "end")
            app.url_entry.insert(0, url)
            logger.info("📌 URL from command line: %s", url)
        else:
            logger.warning("URL-Eingabefeld nicht verfügbar – URL nicht gesetzt")

    if hasattr(app, "_safe_after"):
        app._safe_after(500, _set_url)
    else:
        app.root.after_idle(_set_url)


def _schedule_install_dialog(app: "DragonWhispererGUI") -> None:
    """Plant das Öffnen des Installationsdialogs nach einer Verzögerung."""

    def _open_installer():
        if hasattr(app, "show_install_dialog") and not app.is_shutting_down():
            app.show_install_dialog()

    if hasattr(app, "_safe_after"):
        app._safe_after(1500, _open_installer)
    else:
        app.root.after(1500, _open_installer)


def _post_startup_health_check(app: "DragonWhispererGUI") -> List[str]:
    """Führt einen schnellen Gesundheitscheck der Engines und Tools durch."""
    issues = []
    if hasattr(app, "transcription_engine") and app.transcription_engine:
        try:
            if not app.transcription_engine.test_model_functionality(timeout=10):
                issues.append("Transkriptionsmodell reagiert nicht")
        except Exception as e:
            issues.append(f"Transkriptionstest fehlgeschlagen: {e}")
    if hasattr(app, "translation_engine") and app.translation_engine:
        try:
            test_result = app.translation_engine.translate_text("Hello", "en")
            if not test_result or not test_result.translated:
                issues.append("Übersetzungs‑Engine liefert leere Antwort")
        except Exception as e:
            issues.append(f"Übersetzungstest fehlgeschlagen: {e}")
    if shutil.which("ffmpeg") is None:
        issues.append("FFmpeg nicht im PATH – Livestreams nicht möglich")
    if shutil.which("yt-dlp") is None:
        issues.append("yt-dlp nicht im PATH – YouTube‑Streams eingeschränkt")
    return issues


def _cleanup_gui(
    app: Optional["DragonWhispererGUI"], startup_config: StartupConfig
) -> None:
    """Führt die GUI‑Ressourcenbereinigung durch, falls die GUI initialisiert wurde."""
    if app is not None:
        try:
            if hasattr(app, "_cleanup_resources"):
                app._cleanup_resources(emergency=False)
            elif hasattr(app, "dispose"):
                app.dispose()
            else:
                if hasattr(app, "root") and app.root.winfo_exists():
                    app.root.destroy()
        except Exception as e:
            logger.warning("Fehler bei GUI‑Ressourcenbereinigung: %s", e)
    _perform_loky_cleanup()
    gc.collect()


def _print_version() -> None:
    """Gibt die Versionsinformationen aus."""
    print("🐉 Dragon Whisperer v6.0 (optimized)")
    print(f"Platform: {SYSTEM} {'ARM' if IS_ARM else 'x86'}")
    print(f"Python: {sys.version.split()[0]}")
    try:
        import subprocess

        git_hash = subprocess.check_output(
            ["git", "rev-parse", "--short", "HEAD"],
            stderr=subprocess.DEVNULL,
            text=True,
        ).strip()
        print(f"Git commit: {git_hash}")
    except Exception:
        pass


def _print_detailed_help() -> None:
    """Zeigt eine ausführliche Hilfe mit allen Optionen und Beispielen an."""
    help_text = """
🐉 DRAGON WHISPERER - ULTIMATE STREAM TRANSCRIPTION & TRANSLATION

Usage:
  python dragon_whisperer.py [options]

Options:
  --quiet, -q            Suppress all non‑error output.
  --debug[=N]            Enable debug output. N can be 1‑3 (higher = more detail)
                         or a comma‑separated list of components, e.g.
                         --debug=ytdlp,network,vad
  --check                Run system compatibility check and exit.
  --test                 Run internal unit tests and exit.
  --version, -v          Show version information and exit.
  --sysinfo              Print detailed system information (for bug reports).
  --headless             Run without GUI (requires --url).
  --url URL              Start processing the given URL immediately.
  --model MODEL          Whisper model to use (e.g. 'large-v3', 'medium').
  --language LANG        Target language for translation (e.g. 'de', 'en').
  --profile NAME         Load a custom settings profile from the profiles folder.
  --benchmark            Measure startup times and exit.
  --repair-config        Reset broken configuration to defaults.
  --check-gpu            Check GPU availability and VRAM, then exit.
  --safe-mode            Disable non‑essential features (no health‑check, no auto‑updates).

Environment Variables:
  LOKY_PURGE=1           (set automatically) – reduces semaphore leaks.
  JOBLIB_START_METHOD    (set automatically) – fork (Unix) / spawn (Windows).
  PYDANTIC_IGNORE_CORE_MISMATCH=1 – suppress Pydantic version warnings.

Examples:
  Normal start:          python dragon_whisperer.py
  Debug level 2:         python dragon_whisperer.py --debug=2
  Component debug:       python dragon_whisperer.py --debug=vad,ffmpeg
  Headless mode:         python dragon_whisperer.py --headless --url "https://..."
  Load profile:          python dragon_whisperer.py --profile my_streaming_profile

For more information, see the documentation or visit https://github.com/.../dragon-whisperer
"""
    print(help_text)


def parse_arguments() -> argparse.Namespace:
    """Ultimativ optimierter Kommandozeilen‑Parser mit --debug=all Unterstützung."""
    parser = argparse.ArgumentParser(
        description="🐉 Dragon Whisperer - Livestream Transcription & Translation",
        epilog="For more information, visit: https://github.com/your-repo/dragon-whisperer",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    parser.add_argument(
        "-q", "--quiet", action="store_true", help="Suppress all output except errors"
    )
    parser.add_argument(
        "--debug",
        action="append",
        help=(
            "Enable debug output. Can be a number (0-5) or a comma-separated "
            "list of components. Use 'all' for all components. Can be repeated."
        ),
    )
    parser.add_argument(
        "--check", action="store_true", help="Run system compatibility check and exit"
    )
    parser.add_argument(
        "--test", action="store_true", help="Run internal unit tests and exit"
    )
    parser.add_argument(
        "--version", "-v", action="store_true", help="Show version information and exit"
    )
    parser.add_argument(
        "--sysinfo",
        action="store_true",
        help="Print detailed system information and exit",
    )
    parser.add_argument(
        "--headless",
        action="store_true",
        help="Run in headless mode (no GUI, console output only)",
    )
    parser.add_argument(
        "--url", metavar="URL", help="Start processing the given URL immediately"
    )
    parser.add_argument(
        "--profile", metavar="NAME", help="Load a custom settings profile"
    )
    parser.add_argument(
        "--model", help="Whisper model to use (e.g. 'large-v3', 'medium')"
    )
    parser.add_argument(
        "--language", help="Target language for translation (e.g. 'de', 'en')"
    )
    parser.add_argument(
        "--benchmark", action="store_true", help="Measure startup times and exit"
    )
    parser.add_argument(
        "--repair-config",
        action="store_true",
        help="Reset broken configuration to defaults",
    )
    parser.add_argument(
        "--check-gpu",
        action="store_true",
        help="Check GPU availability and VRAM, then exit",
    )
    parser.add_argument(
        "--safe-mode", action="store_true", help="Disable non‑essential features"
    )
    return parser.parse_args()


def main() -> int:
    """Hauptprogramm – ultimativ optimiert mit allen Verbesserungen."""
    _setup_early_environment()
    args = parse_arguments()
    global DEBUG_LEVEL, DEBUG_COMPONENTS, QUIET_MODE

    debug_level, debug_components = extract_debug_info(args)
    DEBUG_LEVEL = debug_level
    DEBUG_COMPONENTS = debug_components
    QUIET_MODE = args.quiet
    startup_config = StartupConfig(
        debug_level=DEBUG_LEVEL,
        debug_components=DEBUG_COMPONENTS,
        quiet=QUIET_MODE,
        headless=args.headless,
        url=args.url,
        profile=args.profile,
        model=args.model,
        language=args.language,
        benchmark=args.benchmark,
        safe_mode=args.safe_mode,
        repair_config=args.repair_config,
        check_gpu=args.check_gpu,
        crash_report=True,
        startup_timeout=30.0,
        shutdown_timeout=15.0,
    )

    sys.excepthook = lambda t, v, tb: _global_crash_handler(t, v, tb, DEBUG_LEVEL)

    if args.version:
        _print_version()
        return 0
    if args.sysinfo:
        _log_debug_welcome_info(DEBUG_LEVEL, True, QUIET_MODE)
        return 0
    if args.check_gpu:
        ok, msg = _check_gpu_health()
        print(f"GPU Health: {msg}")
        return 0 if ok else 1
    if args.benchmark:
        _run_benchmark()
        return 0
    if args.repair_config:
        repairs = _repair_configuration()
        print("Repairs performed:", ", ".join(repairs) if repairs else "None")
        return 0
    if args.check:
        try:
            PlatformUtils.check_platform_dependencies()
            return 0
        except RuntimeError:
            return 1
    if args.test:
        return run_tests()

    configure_logging(DEBUG_LEVEL, DEBUG_COMPONENTS, QUIET_MODE)
    apply()

    PlatformUtils.setup_platform_environment()

    repairs = _validate_and_repair_environment(DEBUG_LEVEL)
    if repairs and DEBUG_LEVEL >= 1:
        logger.info("🔧 Umgebungsreparaturen: %s", ", ".join(repairs))

    import atexit

    def _cleanup_loky_atexit() -> None:
        try:
            from loky import get_reusable_executor

            executor = get_reusable_executor()
            if executor is not None:
                safe_shutdown_executor(executor, wait=True, cancel_futures=True)
        except ImportError:
            pass
        except Exception:
            pass

    if not hasattr(sys, "_loky_cleanup_registered"):
        atexit.register(_cleanup_loky_atexit)
        sys._loky_cleanup_registered = True

    exit_code = 0
    gui_instance: Optional["DragonWhispererGUI"] = None

    try:
        if args.headless or args.url:
            exit_code = _run_headless(args, startup_config)
        else:
            gui_instance = _run_gui_with_fallbacks(startup_config)
    except KeyboardInterrupt:
        logger.info("\n🛑 Programm durch Benutzer unterbrochen")
        exit_code = 130
    except SystemExit as e:
        exit_code = e.code if isinstance(e.code, int) else 0
    except Exception as e:
        logger.exception("💥 Schwerer Fehler: %s", e)
        exit_code = 2
    finally:
        _perform_guaranteed_cleanup(
            timeout=startup_config.shutdown_timeout, gui=gui_instance
        )
        try:
            from loky import get_reusable_executor

            executor = get_reusable_executor()
            if executor is not None:
                safe_shutdown_executor(executor, wait=True, cancel_futures=True)
        except ImportError:
            pass
        except Exception as e:
            if DEBUG_LEVEL >= 1:
                logger.warning(f"⚠️ Finaler Loky‑Cleanup fehlgeschlagen: {e}")
        logger.debug("Finale Bereinigung abgeschlossen.")
    return exit_code


def _force_loky_cleanup_atexit() -> None:
    """Ultimative Notfall-Bereinigung des loky-Executors beim Programmende."""
    try:
        from loky import get_reusable_executor

        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
            if DEBUG_LEVEL >= 1:
                print("🧹 Loky-Executor via atexit bereinigt.")
    except ImportError:
        pass
    except Exception as e:
        if DEBUG_LEVEL >= 1:
            print(f"⚠️ Loky-atexit-Cleanup fehlgeschlagen: {e}")

atexit.register(_force_loky_cleanup_atexit)


def _debug_active_executors():
    import sys
    import threading

    for mod_name, mod in sys.modules.items():
        if hasattr(mod, "_reusable_executor"):
            print(f"Found executor in {mod_name}: {mod._reusable_executor}")
    for t in threading.enumerate():
        if "loky" in t.name or "joblib" in t.name:
            print(f"Active thread: {t.name} (daemon={t.daemon})")

atexit.register(_perform_loky_cleanup)

if __name__ == "__main__":
    try:
        if "__file__" in globals():
            script_dir = os.path.dirname(os.path.abspath(__file__))
            if os.getcwd() != script_dir:
                os.chdir(script_dir)
                if DEBUG_LEVEL >= 1:
                    print(f"📁 Working directory set to: {script_dir}")
    except Exception:
        pass
    ret = main()
    try:
        from loky import get_reusable_executor
        executor = get_reusable_executor()
        if executor is not None:
            safe_shutdown_executor(executor, wait=True, cancel_futures=True)
    except ImportError:
        pass
    except Exception as e:
        if DEBUG_LEVEL >= 1:
            print(f"⚠️ Loky-Cleanup fehlgeschlagen: {e}")
    sys.exit(ret)
